CREATE PROCEDURE "informix".sp_ca_detallearchivosxmlprocesados(pUsuario CHAR(8), pIdFuncion CHAR(10), pNumCliente CHAR(20),
pIdEstatus CHAR(1), pFechaInicio DATE, pFechaFin DATE, pNumOficio CHAR(60), pNumExpediente CHAR(60), pIdAutoridad CHAR(2),
pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(100) AS nombre_oficio,
			CHAR(60) AS num_oficio,
			CHAR(60) AS num_expediente,
			CHAR(60) AS solicitud_siara,
			INTEGER AS folio, 
			CHAR(4) AS anio_oficio,
			CHAR(2) AS id_area, 
			CHAR(30) AS desc_area,
			CHAR(25) AS fecha_publicacion,
			CHAR(2) AS dias_plazo,
			CHAR(60) AS nombre_autoridad,
			CHAR(60) AS referencia,
			INTEGER AS id_persona_ps,
			CHAR(30) AS caracter_ps,
			CHAR(10) AS des_tipo_persona_ps,
			CHAR(150) AS nombre_ps,
			CHAR(26) AS ap_paterno_ps,
			CHAR(26) AS ap_materno_ps,
			CHAR(15) AS rfc_ps,
			CHAR(50) AS entidad,
			CHAR(20) AS cuenta,
			CHAR(20) AS num_cliente,
			CHAR(1) AS id_estatus,
			CHAR(35) AS desc_estatus;
				
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cNombre_oficio CHAR(100);
	DEFINE cNum_oficio CHAR(60);
	DEFINE cNum_expediente CHAR(60);
	DEFINE cSolicitud_siara CHAR(60);
	DEFINE iFolio INTEGER;
	DEFINE cAnio_oficio CHAR(4);
	DEFINE cId_area CHAR(2);
	DEFINE cDesc_area CHAR(30);
	DEFINE cFecha_publicacion CHAR(25);
	DEFINE cDias_plazo CHAR(2);
	DEFINE cNombre_autoridad CHAR(60);
	DEFINE cReferencia CHAR(60);
	DEFINE iId_persona_ps INTEGER;
	DEFINE cCaracter_ps CHAR(30);
	DEFINE cDes_tipo_persona_ps CHAR(10);
	DEFINE cNombre_ps CHAR(150);
	DEFINE cAp_paterno_ps CHAR(26);
	DEFINE cAp_materno_ps CHAR(26);
	DEFINE cRfc_ps CHAR(15);
	DEFINE cEntidad CHAR(50);
	DEFINE cCuenta CHAR(20);
	DEFINE cNum_cliente CHAR(20);
	DEFINE cId_estatus CHAR(1);
	DEFINE cDes_estatus CHAR(35);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cNombre_oficio = '';
	LET cNum_oficio = '';
	LET cNum_expediente = '';
	LET cSolicitud_siara = '';
	LET iFolio = 0;
	LET cAnio_oficio = '';
	LET cId_area = '';
	LET cDesc_area = '';
	LET cFecha_publicacion = '';
	LET cDias_plazo = '';
	LET cNombre_autoridad = '';
	LET cReferencia = '';
	LET iId_persona_ps = 0;
	LET cCaracter_ps = '';
	LET cDes_tipo_persona_ps = '';
	LET cNombre_ps = '';
	LET cAp_paterno_ps = '';
	LET cAp_materno_ps = '';
	LET cRfc_ps = '';
	LET cEntidad = '';
	LET cCuenta = '';
	LET cNum_cliente = '';
	LET cId_estatus = '';
	LET cDes_estatus = '';
	LET iRecuperacion = 0;
	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNombre_oficio, cNum_oficio, cNum_expediente, cSolicitud_siara, iFolio, cAnio_oficio, cId_area, cDesc_area, cFecha_publicacion, cDias_plazo, cNombre_autoridad, cReferencia,
			iId_persona_ps, cCaracter_ps, cDes_tipo_persona_ps, cNombre_ps, cAp_paterno_ps, cAp_materno_ps, cRfc_ps, cEntidad, cCuenta, cNum_cliente, cId_estatus, cDes_estatus;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_ca_detallearchivosxmlprocesados.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNombre_oficio, cNum_oficio, cNum_expediente, cSolicitud_siara, iFolio, cAnio_oficio, cId_area, cDesc_area, cFecha_publicacion, cDias_plazo, cNombre_autoridad, cReferencia,
			iId_persona_ps, cCaracter_ps, cDes_tipo_persona_ps, cNombre_ps, cAp_paterno_ps, cAp_materno_ps, cRfc_ps, cEntidad, cCuenta, cNum_cliente, cId_estatus, cDes_estatus;
		END IF;
		
		-- VALIDACIÃN DE LOS DATOS DE PAGINACIÃN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cNombre_oficio, cNum_oficio, cNum_expediente, cSolicitud_siara, iFolio, cAnio_oficio, cId_area, cDesc_area, cFecha_publicacion, cDias_plazo, cNombre_autoridad, cReferencia,
			iId_persona_ps, cCaracter_ps, cDes_tipo_persona_ps, cNombre_ps, cAp_paterno_ps, cAp_materno_ps, cRfc_ps, cEntidad, cCuenta, cNum_cliente, cId_estatus, cDes_estatus;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNombre_oficio, cNum_oficio, cNum_expediente, cSolicitud_siara, iFolio, cAnio_oficio, cId_area, cDesc_area, cFecha_publicacion, cDias_plazo, cNombre_autoridad, cReferencia,
			iId_persona_ps, cCaracter_ps, cDes_tipo_persona_ps, cNombre_ps, cAp_paterno_ps, cAp_materno_ps, cRfc_ps, cEntidad, cCuenta, cNum_cliente, cId_estatus, cDes_estatus;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pFechaInicio IS NOT NULL AND pFechaFin IS NOT NULL THEN
		
			FOREACH
			
				SELECT {+INDEX (bdicnweb:"informix".sw_ca_archivosxml idx_sw_ca_archivosxml)} SKIP pRegistros FIRST pRecuperacion nombre_oficio, num_oficio, num_expediente, solicitud_siara, folio, anio_oficio, id_area, desc_area, fecha_publicacion, dias_plazo, nombre_autoridad, referencia,
				id_persona_ps, caracter_ps, des_tipo_persona_ps, nombre_ps, ap_paterno_ps, ap_materno_ps, rfc_ps, entidad, cuenta, num_cliente, estatus
				INTO cNombre_oficio, cNum_oficio, cNum_expediente, cSolicitud_siara, iFolio, cAnio_oficio, cId_area, cDesc_area, cFecha_publicacion, cDias_plazo, cNombre_autoridad, cReferencia,
				iId_persona_ps, cCaracter_ps, cDes_tipo_persona_ps, cNombre_ps, cAp_paterno_ps, cAp_materno_ps, cRfc_ps, cEntidad, cCuenta, cNum_cliente, cId_estatus 
				FROM bdicnweb:"informix".sw_ca_archivosxml
				WHERE num_cliente = (CASE WHEN TRIM(pNumCliente) = '' THEN TRIM(num_cliente) ELSE TRIM(pNumCliente) END)
				AND estatus = (CASE WHEN TRIM(pIdEstatus) = '' THEN TRIM(estatus) ELSE TRIM(pIdEstatus) END)
				AND fecha_publicacion_date BETWEEN pFechaInicio AND pFechaFin
				AND num_oficio = (CASE WHEN TRIM(pNumOficio) = '' THEN TRIM(num_oficio) ELSE TRIM(pNumOficio) END)
				AND num_expediente = (CASE WHEN TRIM(pNumExpediente) = '' THEN TRIM(num_expediente) ELSE TRIM(pNumExpediente) END)
				AND id_area = (CASE WHEN TRIM(pIdAutoridad) = '' THEN TRIM(id_area) ELSE TRIM(pIdAutoridad) END)
				ORDER BY id_area,num_oficio ASC											
				
				IF TRIM(UPPER(cId_estatus)) = 'P' THEN
					LET cDes_estatus = 'POSITIVOS';
				ELIF TRIM(UPPER(cId_estatus)) = 'N' THEN
					LET cDes_estatus = 'NEGATIVOS';
				ELIF TRIM(UPPER(cId_estatus)) = 'M' THEN
					LET cDes_estatus = 'MIXTOS';
				ELIF TRIM(UPPER(cId_estatus)) = 'H' THEN
					LET cDes_estatus = 'HOMONIMOS';
				END IF;
				
				LET iRecuperacion = iRecuperacion + 1;
				RETURN cCodRet, UPPER(cNombre_oficio), UPPER(cNum_oficio), UPPER(cNum_expediente), UPPER(cSolicitud_siara), iFolio, cAnio_oficio, cId_area, UPPER(cDesc_area), cFecha_publicacion, cDias_plazo, UPPER(cNombre_autoridad), UPPER(cReferencia), 
				iId_persona_ps, UPPER(cCaracter_ps), UPPER(cDes_tipo_persona_ps), UPPER(cNombre_ps), UPPER(cAp_paterno_ps), UPPER(cAp_materno_ps), UPPER(cRfc_ps), UPPER(cEntidad), cCuenta, cNum_cliente, UPPER(cId_estatus), UPPER(cDes_estatus) WITH RESUME;
				
			END FOREACH;
			
		ELSE
		
			FOREACH
				
				SELECT {+INDEX (bdicnweb:"informix".sw_ca_archivosxml idx_sw_ca_archivosxml)} SKIP pRegistros FIRST pRecuperacion nombre_oficio, num_oficio, num_expediente, solicitud_siara, folio, anio_oficio, id_area, desc_area, fecha_publicacion, dias_plazo, nombre_autoridad, referencia,
				id_persona_ps, caracter_ps, des_tipo_persona_ps, nombre_ps, ap_paterno_ps, ap_materno_ps, rfc_ps, entidad, cuenta, num_cliente, estatus
				INTO cNombre_oficio, cNum_oficio, cNum_expediente, cSolicitud_siara, iFolio, cAnio_oficio, cId_area, cDesc_area, cFecha_publicacion, cDias_plazo, cNombre_autoridad, cReferencia,
				iId_persona_ps, cCaracter_ps, cDes_tipo_persona_ps, cNombre_ps, cAp_paterno_ps, cAp_materno_ps, cRfc_ps, cEntidad, cCuenta, cNum_cliente, cId_estatus 
				FROM bdicnweb:"informix".sw_ca_archivosxml
				WHERE num_cliente = (CASE WHEN TRIM(pNumCliente) = '' THEN TRIM(num_cliente) ELSE TRIM(pNumCliente) END)
				AND estatus = (CASE WHEN TRIM(pIdEstatus) = '' THEN TRIM(estatus) ELSE TRIM(pIdEstatus) END)
				AND num_oficio = (CASE WHEN TRIM(pNumOficio) = '' THEN TRIM(num_oficio) ELSE TRIM(pNumOficio) END)
				AND num_expediente = (CASE WHEN TRIM(pNumExpediente) = '' THEN TRIM(num_expediente) ELSE TRIM(pNumExpediente) END)
				AND id_area = (CASE WHEN TRIM(pIdAutoridad) = '' THEN TRIM(id_area) ELSE TRIM(pIdAutoridad) END)
				ORDER BY id_area,num_oficio ASC											
				
				IF TRIM(UPPER(cId_estatus)) = 'P' THEN
					LET cDes_estatus = 'POSITIVOS';
				ELIF TRIM(UPPER(cId_estatus)) = 'N' THEN
					LET cDes_estatus = 'NEGATIVOS';
				ELIF TRIM(UPPER(cId_estatus)) = 'M' THEN
					LET cDes_estatus = 'MIXTOS';
				ELIF TRIM(UPPER(cId_estatus)) = 'H' THEN
					LET cDes_estatus = 'HOMONIMOS';
				END IF;
				
				LET iRecuperacion = iRecuperacion + 1;
				RETURN cCodRet, UPPER(cNombre_oficio), UPPER(cNum_oficio), UPPER(cNum_expediente), UPPER(cSolicitud_siara), iFolio, cAnio_oficio, cId_area, UPPER(cDesc_area), cFecha_publicacion, cDias_plazo, UPPER(cNombre_autoridad), UPPER(cReferencia), 
				iId_persona_ps, UPPER(cCaracter_ps), UPPER(cDes_tipo_persona_ps), UPPER(cNombre_ps), UPPER(cAp_paterno_ps), UPPER(cAp_materno_ps), UPPER(cRfc_ps), UPPER(cEntidad), cCuenta, cNum_cliente, UPPER(cId_estatus), UPPER(cDes_estatus) WITH RESUME;
				
			END FOREACH;
			
		END IF;
		
		IF iRecuperacion = 0 AND pRegistros = 0 THEN
			LET cCodRet = '01030';
			RETURN cCodRet, cNombre_oficio, cNum_oficio, cNum_expediente, cSolicitud_siara, iFolio, cAnio_oficio, cId_area, cDesc_area, cFecha_publicacion, cDias_plazo, cNombre_autoridad, cReferencia,
			iId_persona_ps, cCaracter_ps, cDes_tipo_persona_ps, cNombre_ps, cAp_paterno_ps, cAp_materno_ps, cRfc_ps, cEntidad, cCuenta, cNum_cliente, cId_estatus, cDes_estatus;
		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cNombre_oficio, cNum_oficio, cNum_expediente, cSolicitud_siara, iFolio, cAnio_oficio, cId_area, cDesc_area, cFecha_publicacion, cDias_plazo, cNombre_autoridad, cReferencia,
			iId_persona_ps, cCaracter_ps, cDes_tipo_persona_ps, cNombre_ps, cAp_paterno_ps, cAp_materno_ps, cRfc_ps, cEntidad, cCuenta, cNum_cliente, cId_estatus, cDes_estatus;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 06/12/2015',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: CONSULTA DE ARCHIVOS XML',
'DESCRIPCION: SPL encargado de consultar el detalle de los archivos xml procesados.',
