CREATE PROCEDURE "informix".sp_atms_cargaarchivoconcentracionmasiva(pUsuario CHAR(8), pIdFuncion CHAR(10), pBloqueInf CHAR(2000), pIteracion CHAR(1))
	RETURNING CHAR(5) AS codret; 
	
	DEFINE cCodRet CHAR(5);
	DEFINE cSqlerr INTEGER;
	DEFINE cIsamErr	INTEGER;
	DEFINE cDescErr	CHAR(50);
	DEFINE cEmpresa CHAR(3);
	DEFINE cRegistro LVARCHAR;
	DEFINE cBloqueInf2 LVARCHAR;
	DEFINE iContador INTEGER;
	DEFINE iNumReg INTEGER;
	DEFINE cCc CHAR(4);
	DEFINE cId_atm CHAR(6);
	DEFINE cNombre VARCHAR(200);
	DEFINE cPlaza VARCHAR(100);
	DEFINE cTipo_ope VARCHAR(25);
	DEFINE iB_1000 INTEGER;
	DEFINE iB_500 INTEGER;
	DEFINE iB_200 INTEGER;
	DEFINE iB_100 INTEGER;
	DEFINE iB_50 INTEGER;
	DEFINE iB_20 INTEGER;
	DEFINE mTotal_b MONEY(18,2);
	DEFINE cPapeleta CHAR(15);
	DEFINE cStatus VARCHAR(50);
	DEFINE cFolio CHAR(8);
	
	LET cCodRet = '00000';
	LET cSqlerr = 0;
	LET cIsamErr = 0;
	LET cDescErr = '';
	LET cEmpresa = '001';
	LET cRegistro = '';
	LET cBloqueInf2 = '';
	LET iContador = 0;
	LET iNumReg = 0;
	LET cCc = '';
	LET cId_atm = '';
	LET cNombre = '';
	LET cPlaza = '';
	LET cTipo_ope = '';
	LET iB_1000 = 0;
	LET iB_500 = 0;
	LET iB_200 = 0;
	LET iB_100 = 0;
	LET iB_50 = 0;
	LET iB_20 = 0;
	LET mTotal_b = 0.00;
	LET cPapeleta = '';
	LET cStatus = '';
	LET cFolio = '';	
	
	BEGIN
		
		ON EXCEPTION SET cSqlerr, cIsamErr, cDescErr
			IF cSqlerr <> 0 THEN
				LET cCodRet = cSqlerr;
				RETURN cCodRet; 
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_cargaarchivoconcentracionmasiva.out';
		--TRACE ON;		
		
		IF pUsuario = '' OR pIdFuncion = '' OR pBloqueInf = '' OR pIteracion = '' THEN
			LET cCodRet = '00003';			
			RETURN cCodRet; 
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- SE LIMPIA TABLA
		IF pIteracion = '0' THEN
			DELETE FROM "informix".sw_atm_concentracionmasiva WHERE usuario = pUsuario;
		END IF;
		
		FOREACH
			
			EXECUTE PROCEDURE "informix".sp_split_cadena(pBloqueInf, '|')
			INTO cBloqueInf2
			
			LET cBloqueInf2 = TRIM(cBloqueInf2)||'+';
			LET cRegistro = '';
			LET iContador = 0;
			
			FOREACH
			
				EXECUTE PROCEDURE "informix".sp_split_cadena(cBloqueInf2, '+')
				INTO cRegistro
			
				LET iContador = iContador + 1;
				
				IF iContador = 1 THEN
					LET iNumReg = TRIM(cRegistro);
				ELIF iContador = 2 THEN
					LET cCc = TRIM(cRegistro);
				ELIF iContador = 3 THEN
					LET cId_atm = TRIM(cRegistro);
				ELIF iContador = 4 THEN
					LET cNombre = TRIM(cRegistro);
				ELIF iContador = 5 THEN
					LET cPlaza = TRIM(cRegistro);
				ELIF iContador = 6 THEN
					LET cTipo_ope = TRIM(cRegistro);
				ELIF iContador = 7 THEN
					LET iB_500 = TRIM(cRegistro);
				ELIF iContador = 8 THEN
					LET iB_200 = TRIM(cRegistro);
				ELIF iContador = 9 THEN
					LET iB_100 = TRIM(cRegistro);
				ELIF iContador = 10 THEN
					LET iB_50 = TRIM(cRegistro);
				ELIF iContador = 11 THEN
					LET iB_20 = TRIM(cRegistro);
				ELIF iContador = 12 THEN
					LET mTotal_b = TRIM(cRegistro);
				ELIF iContador = 13 THEN
					LET cPapeleta = TRIM(cRegistro);
				END IF;
			
			END FOREACH;
			
			INSERT INTO "informix".sw_atm_concentracionmasiva(num_reg,cc,id_atm,nombre,plaza,tipo_ope,b_500,b_200,b_100,b_50,b_20,total_b,papeleta,status,folio,procesado,duplicado,usuario) 
			VALUES(iNumReg,cCc,cId_atm,cNombre,cPlaza,cTipo_ope,iB_500,iB_200,iB_100,iB_50,iB_20,mTotal_b,cPapeleta,cStatus,cFolio,'f','f',pUsuario);			
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				--LET cCodRet = '00282'; --ERROR AL GUARDAR EL REGISTRO
				LET cCodRet = '01128'; --EL ARCHIVO NO SE CARGÓ CORRECTAMENTE
			END IF;
			
		END FOREACH;
		
		RETURN cCodRet;
		
	END;
END PROCEDURE
