CREATE PROCEDURE "informix".sp_puntoscompro_consulta_totales(pUsuario CHAR(8), pIdFuncion CHAR(10),psProdInd VARCHAR(2), psIdPOSATM VARCHAR(19), 
psGiro VARCHAR(4), psTarjetas CHAR(570), psModoCaptura VARCHAR(2), psCodigoIso VARCHAR(2),   pdtFechaIni DATE, pdtFechaFin DATE)
       RETURNING
	   CHAR(5) 	AS CodRet,
	   INTEGER AS total;

	DEFINE cCodRet CHAR(5);
    DEFINE iSqlErr INTEGER;
    DEFINE cCodRetSp CHAR(6);
    DEFINE iCodRetSp INTEGER;
	DEFINE iRecuperacion INTEGER;
    
	DEFINE	iTotal INTEGER;
	
    LET cCodRet = '00000';
    LET iSqlErr = 0;
    LET cCodRetSp = '000000';
    LET iCodRetSp = 0;
	LET iRecuperacion = 0;
   	
	LET	iTotal =0;

	BEGIN
        
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			
			UPDATE bdicnweb:"informix".statusconsultapuntoscompromiso
			SET  status = 'E', error_proceso = 'S', error = TRIM(cCodRet) 
			WHERE usuario_insert = TRIM(pUsuario);
			
			RETURN 	cCodRet,iTotal;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_puntoscompro_consulta_totales.out';
		--TRACE ON;
		
		-- SE LIMPIA TABLA POR USUARIO Y PROCESO
		SET LOCK MODE TO WAIT 3;
		DELETE FROM bdicnweb:"informix".statusconsultapuntoscompromiso
		WHERE usuario_insert = TRIM(pUsuario);
		
		-- SE INSERTA A TABLA PARA EL MONITOREO DEL STATUS
		SET LOCK MODE TO WAIT 3; 
		INSERT INTO bdicnweb:"informix".statusconsultapuntoscompromiso(usuario_insert,status,num_registros,error_proceso,error)
			VALUES(pUsuario,'I',0,'','');
		
		IF pUsuario = '' OR pIdFuncion = '' OR psProdInd ='' OR pdtFechaIni IS NULL OR pdtFechaFin IS NULL THEN
			LET cCodRet = '00003';
			
			UPDATE bdicnweb:"informix".statusconsultapuntoscompromiso
			SET  status = 'E', error_proceso = 'S', error = TRIM(cCodRet) 
			WHERE usuario_insert = TRIM(pUsuario);
			
			RETURN cCodRet, iTotal;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			
			UPDATE bdicnweb:"informix".statusconsultapuntoscompromiso
			SET  status = 'E', error_proceso = 'S', error = TRIM(cCodRet) 
			WHERE usuario_insert = TRIM(pUsuario);
		
			RETURN cCodRet, iTotal;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		DROP TABLE IF EXISTS tempTarjetas;  
		
		EXECUTE PROCEDURE intercard:"informix".sp_puntoscompromiso2_totales(psProdInd,psIdPOSATM,psGiro,psTarjetas,psModoCaptura,psCodigoIso,pUsuario,pdtFechaIni,pdtFechaFin)  
        INTO cCodRetSp, iTotal;
			
		IF cCodRetSp::INTEGER < 0 THEN 
			RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCION DEL SP intercard:sp_puntoscompromiso2_totales';
		ELIF cCodRetSp::INTEGER = 1 THEN
			LET cCodRet = '00450';
		ELIF cCodRetSp::INTEGER = 2 THEN		
			LET cCodRet = '00450';
		ELIF cCodRetSp::INTEGER = 3 THEN		
			LET cCodRet = '00003';	
		END IF;
		
		IF iTotal = 0 THEN
		
			LET cCodRet = '00017';
			
		END IF;
		
		IF cCodRet = '00000' THEN
			-- SE ACTUALIZA CON EXITO LA CONSULTA
			SET LOCK MODE TO WAIT 3;
			UPDATE bdicnweb:"informix".statusconsultapuntoscompromiso
			SET  status = 'T', num_registros = iTotal, error_proceso = 'N' 
			WHERE usuario_insert = TRIM(pUsuario);
		ELSE
			-- SE ACTUALIZA EN CASO DE ERROR
			SET LOCK MODE TO WAIT 3;
			UPDATE bdicnweb:"informix".statusconsultapuntoscompromiso
			SET  status = 'E', error_proceso = 'S', error = TRIM(cCodRet) 
			WHERE usuario_insert = TRIM(pUsuario);
		END IF;
		
		
	    RETURN cCodRet, iTotal;
		
    END;
END PROCEDURE
DOCUMENT 'AUTOR: Martha Salgado Mendoza',
'FECHA: 13/02/2016',
'MODULO: CONSULTAS > APOYO',
'FUNCIONALIDAD: CONSULTAS DE PUNTOS COMPROMISOS',
'DESCRIPCION:SPL Intermedio que consulta el total de registro para la consulta -Puntos Compromisos',
