CREATE PROCEDURE "informix".sp_verificastatusconsrepuntoscompromiso(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5) AS codret,
			  CHAR(1) AS status,
			  CHAR(80) AS ruta_archivo,
			  CHAR(30) AS nombre_archivo,
			  CHAR(1) AS error_proceso,
			  CHAR(5) AS error;
			  
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	DEFINE cStatus CHAR(1);
	DEFINE cRutaArchivo  CHAR(80);
	DEFINE cNombreArchivo  CHAR(30);
	DEFINE cErrorProceso CHAR(1);
	DEFINE cError CHAR(5);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cStatus = '';
	LET cRutaArchivo = '';
	LET cNombreArchivo = '';
	LET cErrorProceso = '';
	LET cError = '';
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = '00770'; --PROCESO CON ERRORES, POR FAVOR REINTENTE NUEVAMENTE
			RETURN cCodRet,cStatus,cRutaArchivo,cNombreArchivo,cErrorProceso,cError;	
		END EXCEPTION;
	 
		--SET DEBUG FILE TO '/tmp/mfinis/sp_verificastatusconsrepuntoscompromiso.out';
		--TRACE ON;
		
		---VALIDACION DE CAMPOS REQUERIDOS
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cStatus,cRutaArchivo,cNombreArchivo,cErrorProceso,cError;
		END IF;		
			
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cStatus,cRutaArchivo,cNombreArchivo,cErrorProceso,cError;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT status,ruta_archivo,nombre_archivo,error_proceso,error
		INTO cStatus,cRutaArchivo,cNombreArchivo,cErrorProceso,cError
		FROM bdicnweb:"informix".statusconsultareportepuntoscompromiso
		WHERE usuario_insert = TRIM(pUsuario);
		
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			LET cCodRet = '00770'; --PROCESO CON ERRORES, POR FAVOR REINTENTE NUEVAMENTE
			RETURN cCodRet,cStatus,cRutaArchivo,cNombreArchivo,cErrorProceso,cError;
		ELSE 			
			RETURN cCodRet,cStatus,cRutaArchivo,cNombreArchivo,cErrorProceso,cError;
		END IF;	
		
	END;
END PROCEDURE
