CREATE PROCEDURE "informix".sp_actualizacc(pUsuario CHAR(8), pIdFuncion CHAR(10), pSucursal CHAR(4),
pMontoMin MONEY(16,2), pMontoMax MONEY(16,2), pPzaCG CHAR(3),pPzaCB INTEGER)
		RETURNING CHAR(5) AS codret;		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(5);
	DEFINE cDescCodRetSp CHAR(100);
	DEFINE cEmpresa CHAR(3);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET cDescCodRetSp = '';
	LET cEmpresa = '001';
	LET iRecuperacion = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet;	
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_actualizacc.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pSucursal = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;	
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;	
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			EXECUTE PROCEDURE bdinteg:"informix".sp_actualizacccajagen(pSucursal,pMontoMin,pMontoMax,pPzaCG,pPzaCB)
			INTO cCodRetSp, cDescCodRetSp
			
			IF cCodRetSp::INTEGER < 0 THEN 
				RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdinteg:sp_actualizacccajagen';
			END IF;
		END FOREACH;
		
		RETURN cCodRet;
		
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 21/10/2019',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: MANTENIMIENTO A CATÁLOGO DE CENTRO DE COSTOS', 
'DESCRIPCION: SPL encargado de actualizar los montos minimos, maximos, caja general y plaza clabe del centro de costos capturado.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_dic_consultalertacomph_totales(pUsuario CHAR(8), pIdFuncion CHAR(10), pModo SMALLINT, pSkyp INTEGER,
			pStatus CHAR (1),pNumctenvo CHAR (20),pFechaIni DATE,pFechaFin DATE)
		RETURNING CHAR(5) AS codret,
			INTEGER AS num_registros;		
		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE iNoRegistros INTEGER;
	
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;	
	LET iNoRegistros = 0;
	LET pUsuario = TRIM(pUsuario);
	
	BEGIN
		

	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			UPDATE bdicnweb:"informix".sw_dic_statusconsultahuellas
            SET status = 'E', total_registros = iNoRegistros, error_proceso = 'S', error_code = TRIM(cCodRet) WHERE usuario = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/cristo/sp_dic_consultalertacomph_totales.out';
        --TRACE ON;
		
		SET ISOLATION TO dirty READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pModo IS NULL OR pModo NOT IN (1,2)  THEN
			LET cCodRet = '00003';			
			UPDATE bdicnweb:"informix".sw_dic_statusconsultahuellas
            SET status = 'E', total_registros = iNoRegistros, error_proceso = 'S', error_code = TRIM(cCodRet) WHERE usuario = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		IF pModo = '2' AND pNumctenvo = '' THEN
			LET cCodRet = '00003';
			UPDATE bdicnweb:"informix".sw_dic_statusconsultahuellas
            SET status = 'E', total_registros = iNoRegistros, error_proceso = 'S', error_code = TRIM(cCodRet) WHERE usuario = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD		
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE bdicnweb:"informix".sw_dic_statusconsultahuellas
            SET status = 'E', total_registros = iNoRegistros, error_proceso = 'S', error_code = TRIM(cCodRet) WHERE usuario = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		
		--
		DELETE FROM bdicnweb:"informix".sw_dic_statusconsultahuellas WHERE usuario = pUsuario;
		
		INSERT INTO bdicnweb:"informix".sw_dic_statusconsultahuellas(usuario,total_registros,status,error_proceso,error_code)
        VALUES(pUsuario, iNoRegistros,'I','', ''); 
		
				
		EXECUTE PROCEDURE bdinteg:"informix".sp_dicta_consultalertacomph2_totales(pModo, pSkyp, pStatus, pNumctenvo, pUsuario, pFechaIni, pFechaFin)		
		INTO cCodRetSp, iNoRegistros;
		
		LET iCodRetSp = cCodRetSp::INTEGER;
		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION iCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP bdinteg:sp_dicta_consultalertacomph2_totales';			
		ELIF iCodRetSp = 3 THEN
			LET cCodRet = '00017';	
			UPDATE bdicnweb:"informix".sw_dic_statusconsultahuellas
			SET status = 'E', total_registros = iNoRegistros, error_proceso = 'N', error_code = cCodRet WHERE usuario = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		UPDATE bdicnweb:"informix".sw_dic_statusconsultahuellas
        SET status = 'T', total_registros = iNoRegistros, error_proceso = 'N', error_code = cCodRet WHERE usuario = pUsuario;
		
		RETURN cCodRet, iNoRegistros;
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil Cuachayo',
'FECHA: 25/05/2018',
'MODULO: CLIENTES',
'FUNCIONALIDAD: MONITOR ALERTAS COMPARACION DE HUELLAS',
'DESCRIPCION: SPL que realiza la consulta para el llenado del buzon de alertas',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_catalogoscc(pUsuario CHAR(8), pIdFuncion CHAR(10), pIdConsulta CHAR(1), pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(11) AS clave,
			CHAR(60) AS descripcion;		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(5);
	DEFINE cDescCodRetSp CHAR(100);
	DEFINE cEmpresa CHAR(3);
	DEFINE cClave CHAR(11);
	DEFINE cDescripcion CHAR(60);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET cDescCodRetSp = '';
	LET cEmpresa = '001';
	LET cClave = '';
	LET cDescripcion = '';
	LET iRecuperacion = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cClave, cDescripcion;	
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_catalogoscc.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pIdConsulta = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cClave, cDescripcion;	
		END IF;
		
		-- VALIDACIÓN DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cClave, cDescripcion;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cClave, cDescripcion;	
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- Caja General
		IF pIdConsulta = 'C' THEN
		
			FOREACH
				
				SELECT {+INDEX (bdinteg:si_plazas_cajagen idx_si_plazas_cajagen)} SKIP pRegistros FIRST pRecuperacion codigo_plaza, TRIM(descripcion) AS nombre 
				INTO cClave, cDescripcion
				FROM bdinteg:"informix".si_plazas_cajagen			
				ORDER BY descripcion
			
				LET iRecuperacion = iRecuperacion + 1;
				RETURN cCodRet, cClave, UPPER(cDescripcion) WITH RESUME;
				
			END FOREACH;
		
		-- Plaza Clabe
		ELIF pIdConsulta = 'P' THEN
		
			FOREACH
				
				SELECT {+INDEX (bdinteg:si_plaza_clabe idx_si_plaza_clabe)} SKIP pRegistros FIRST pRecuperacion id_plazaclabe, TRIM(nombre) || ' ' || TRIM(estado) AS nombre 
				INTO cClave, cDescripcion
				FROM bdinteg:"informix".si_plaza_clabe									
				ORDER BY nombre
				
				LET iRecuperacion = iRecuperacion + 1;
				RETURN cCodRet, cClave, UPPER(cDescripcion) WITH RESUME;
				
			END FOREACH;
		
		END IF;
		
		IF iRecuperacion = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, cClave, cDescripcion;
		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cClave, cDescripcion;
		END IF;
		
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 21/10/2019',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: MANTENIMIENTO A CATÁLOGO DE CENTRO DE COSTOS', 
'DESCRIPCION: SPL que se encarga de consultar el detalle de los catálogos: caja general, plaza clabe.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_detallecatalogocc(pUsuario CHAR(8), pIdFuncion CHAR(10), pSucursal CHAR(4))
		RETURNING CHAR(5) AS codret,
			INTEGER AS dias_laborables,
			DECIMAL(9,2) AS factor_remesas,
			DECIMAL(10,2) AS factor_rem_sbc,
			DECIMAL(5,2) AS iva,
			DECIMAL(10,2) AS monto_minimo,
			DECIMAL(14,2) AS monto_min_sbc,
			DECIMAL(14,2) AS sal_min_pza,
			MONEY(16,2) AS mto_min_efect,
			MONEY(16,2) AS mto_max_efect,
			CHAR(3) AS plaza_cajagen,
			INTEGER AS id_plazaclabe;		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(5);
	DEFINE cDescCodRetSp CHAR(100);
	DEFINE cEmpresa CHAR(3);
	DEFINE iDias_laborables INTEGER;
	DEFINE dFactor_remesas DECIMAL(9,2); 
	DEFINE dFactor_rem_sbc DECIMAL(10,2);
	DEFINE dIva DECIMAL(5,2);            
	DEFINE dMonto_minimo DECIMAL(10,2);
	DEFINE dMonto_min_sbc DECIMAL(14,2);
	DEFINE dSal_min_pza DECIMAL(14,2);
	DEFINE mMto_min_efect MONEY(16,2);
	DEFINE mMto_max_efect MONEY(16,2);
	DEFINE cPlaza_cajagen CHAR(3);
	DEFINE iId_plazaclabe INTEGER;
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET cDescCodRetSp = '';
	LET cEmpresa = '001';
	LET iDias_laborables = 0;
	LET dFactor_remesas = 0.00;
	LET dFactor_rem_sbc = 0.00;
	LET dIva = 0.00;
	LET dMonto_minimo = 0.00;
	LET dMonto_min_sbc = 0.00;
	LET dSal_min_pza = 0.00;
	LET mMto_min_efect = 0.00;
	LET mMto_max_efect = 0.00;
	LET cPlaza_cajagen = '';
	LET iId_plazaclabe = 0;
	LET iRecuperacion = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,iDias_laborables,dFactor_remesas,dFactor_rem_sbc,dIva,dMonto_minimo,dMonto_min_sbc,dSal_min_pza,
			mMto_min_efect,mMto_max_efect,cPlaza_cajagen,iId_plazaclabe;	
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_detallecatalogocc.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pSucursal = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,iDias_laborables,dFactor_remesas,dFactor_rem_sbc,dIva,dMonto_minimo,dMonto_min_sbc,dSal_min_pza,
			mMto_min_efect,mMto_max_efect,cPlaza_cajagen,iId_plazaclabe;	
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,iDias_laborables,dFactor_remesas,dFactor_rem_sbc,dIva,dMonto_minimo,dMonto_min_sbc,dSal_min_pza,
			mMto_min_efect,mMto_max_efect,cPlaza_cajagen,iId_plazaclabe;	
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT dias_laborables,factor_remesas,factor_rem_sbc,iva,monto_minimo,monto_min_sbc,sal_min_pza,
		mto_min_efect,mto_max_efect,plaza_cajagen,id_plazaclabe
		INTO iDias_laborables,dFactor_remesas,dFactor_rem_sbc,dIva,dMonto_minimo,dMonto_min_sbc,dSal_min_pza,
		mMto_min_efect,mMto_max_efect,cPlaza_cajagen,iId_plazaclabe
		FROM bdinteg:"informix".si_sucursales
		WHERE sucursal = pSucursal;
		
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN 
			LET cCodRet = '00017';
		END IF;
		
		RETURN cCodRet,iDias_laborables,dFactor_remesas,dFactor_rem_sbc,dIva,dMonto_minimo,dMonto_min_sbc,dSal_min_pza,
		mMto_min_efect,mMto_max_efect,cPlaza_cajagen,iId_plazaclabe;	
		
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 21/10/2019',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: MANTENIMIENTO A CATÁLOGO DE CENTRO DE COSTOS', 
'DESCRIPCION: SPL que se encarga de consultar el detalle del catálogo de centro de costos.',
