CREATE PROCEDURE "informix".sp_detbusquedasucursales(pUsuario CHAR(8), pIdFuncion CHAR(10), pSucursal CHAR(4), pNomSucursal CHAR(45), pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(4) AS sucursal,
			CHAR(45) AS desc_sucursal;		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(5);
	DEFINE cDescCodRetSp CHAR(100);
	DEFINE cEmpresa CHAR(3);
	DEFINE cNumSucursal CHAR(4);
	DEFINE cDescSucursal CHAR(45);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET cDescCodRetSp = '';
	LET cEmpresa = '001';
	LET cNumSucursal = '';
	LET cDescSucursal = '';
	LET iRecuperacion = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNumSucursal, cDescSucursal;	
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_detbusquedasucursales.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNumSucursal, cDescSucursal;	
		END IF;
		
		-- VALIDACIÓN DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cNumSucursal, cDescSucursal;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNumSucursal, cDescSucursal;	
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pNomSucursal <> '' THEN
			LET pNomSucursal = '%'||TRIM(pNomSucursal)||'%';
		END IF;
		
		FOREACH
			SELECT {+INDEX (bdinteg:si_sucursales idx_si_sucursales_empzon)} SKIP pRegistros FIRST pRecuperacion sucursal, TRIM(nombre) AS nombre 
			INTO cNumSucursal, cDescSucursal
			FROM bdinteg:"informix".si_sucursales 
			WHERE UPPER(tpo_sucursal) = 'S'
			AND sucursal = (CASE WHEN pSucursal <> '' THEN pSucursal ELSE sucursal END)
			AND nombre LIKE (CASE WHEN pNomSucursal <> '' THEN pNomSucursal ELSE nombre END)
			ORDER BY nombre ASC
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, cNumSucursal, UPPER(cDescSucursal) WITH RESUME;
		END FOREACH;
		
		IF iRecuperacion = 0 AND pRegistros = 0 AND pSucursal <> '' AND pNomSucursal <> '' THEN
			LET cCodRet = '01135';	--LA SUCURSAL NO EXISTE
			RETURN cCodRet, cNumSucursal, cDescSucursal;
		ELIF iRecuperacion = 0 AND pRegistros = 0 AND pSucursal <> '' THEN
			LET cCodRet = '00833';	--EL NÚMERO DE LA SUCURSAL NO EXISTE
			RETURN cCodRet, cNumSucursal, cDescSucursal;
		ELIF iRecuperacion = 0 AND pRegistros = 0 AND pNomSucursal <> '' THEN
			LET cCodRet = '01070';	--EL NOMBRE DE LA SUCURSAL NO EXISTE
			RETURN cCodRet, cNumSucursal, cDescSucursal;
		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cNumSucursal, cDescSucursal;
		END IF;
		
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 21/10/2019',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: MANTENIMIENTO A CATÁLOGO DE CENTRO DE COSTOS', 
'DESCRIPCION: SPL que se encarga de consultar el detalle de las sucursales.',
