CREATE PROCEDURE "informix".sp_dic_consultasucursalesalertas(pUsuario CHAR(8), pIdFuncion CHAR(10), pSucursal CHAR(4), pNombreSucursal CHAR(10))
		RETURNING CHAR(5) AS codret,
		CHAR(4)  AS num_suc,
		CHAR(40) AS nombre_suc,
		CHAR(40) AS direccion,
		CHAR(3)  AS cod_ciudad,
		CHAR(60) AS nom_ciudad,
		CHAR(2)  AS cod_estado,
		CHAR(30) AS nom_estado,
		INTEGER  AS total_sucursales;
		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cNumSuc CHAR(4);
	DEFINE cNombreSuc CHAR(40);
	DEFINE cDireccion CHAR(40);
	DEFINE cCodCiu CHAR(3);
	DEFINE cNombreCiu CHAR(60);
	DEFINE cCodEst CHAR(2);
	DEFINE cNombreEst CHAR(30);
	DEFINE iTotsuc INTEGER;	
	
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cNumSuc = '';
	LET cNombreSuc = '';
	LET cDireccion = '';
	LET cCodCiu = '';
	LET cNombreCiu = '';
	LET cCodEst = '';
	LET cNombreEst = '';
	LET iTotsuc = 0;	
	
	BEGIN

	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNumSuc, cNombreSuc, cDireccion, cCodCiu, cNombreCiu, cCodEst, cNombreEst,iTotsuc;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_dic_consultasucursalesalertas.out';
		--TRACE ON;
		SET ISOLATION TO dirty READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNumSuc, cNombreSuc, cDireccion, cCodCiu, cNombreCiu, cCodEst, cNombreEst,iTotsuc;
		END IF;				
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD		
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNumSuc, cNombreSuc, cDireccion, cCodCiu, cNombreCiu, cCodEst, cNombreEst,iTotsuc;
		END IF;
		
		FOREACH
			EXECUTE PROCEDURE bdinteg:"informix".sp_dicta_consultasucursalesalertas(pSucursal, pNombreSucursal, '0', '0')
			INTO cCodRetSp, cNumSuc, cNombreSuc, cDireccion, cCodCiu, cNombreCiu, cCodEst, cNombreEst, iTotsuc
					
			LET iCodRetSp = cCodRetSp::INTEGER;
			IF iCodRetSp < 0 THEN
				RAISE EXCEPTION iCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP bdinteg:"informix".sp_dicta_consultasucursalesalertas';		
			ELIF pSucursal <> '' AND pNombreSucursal = '' AND iCodRetSp = 2 THEN 
				LET cCodRet = '00833';
				RETURN cCodRet, cNumSuc, cNombreSuc, cDireccion, cCodCiu, cNombreCiu, cCodEst, cNombreEst,iTotsuc; 
			ELIF pNombreSucursal <> '' AND pSucursal = '' AND iCodRetSp = 2 THEN
				LET cCodRet = '01070';
				RETURN cCodRet, cNumSuc, cNombreSuc, cDireccion, cCodCiu, cNombreCiu, cCodEst, cNombreEst,iTotsuc; 
			ELIF pSucursal <> '' AND pNombreSucursal <> '' AND iCodRetSp = 2 THEN
				LET cCodRet = '00017';
				RETURN cCodRet, cNumSuc, cNombreSuc, cDireccion, cCodCiu, cNombreCiu, cCodEst, cNombreEst,iTotsuc; 
			END IF;
						
			RETURN cCodRet, cNumSuc, cNombreSuc, cDireccion, cCodCiu, cNombreCiu, cCodEst, cNombreEst,iTotsuc WITH RESUME; 		
		END FOREACH;						
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil Cuachayo',
'FECHA: 28/05/2018',
'MODULO: CLIENTES',
'FUNCIONALIDAD: MONITOR ALERTAS COMPARACION DE HUELLAS',
'DESCRIPCION: SPL que consulta datos de sucursales',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_portanom_generacionarchivocancel(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaRegistro DATE)
	RETURNING CHAR(5) AS codret,
			  INTEGER AS total_solicitudes,
			  CHAR(80) AS ruta_archivo;
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(3);
	DEFINE iCodRetSp INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE cRutaArchivo CHAR(80);
	DEFINE cArchivo CHAR(20);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET iNoRegistros = 0;
	LET cRutaArchivo = '';
	LET cArchivo = 'cancpor40137'||TO_CHAR(CURRENT, '%Y%m%d%M%S');
	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			UPDATE bdicnweb:"informix".status_genarchportanomcan
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros, cRutaArchivo;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/RESPALDOSNEW/rsv/portabilidad/TASF/bdicheq/V2/sp_portanom_generacionarchivocancel.out';
		--TRACE ON;
		
		-- SE LIMPIA TABLA POR USUARIO
		DELETE FROM bdicnweb:"informix".status_genarchportanomcan WHERE usuario_insert = pUsuario;
		INSERT INTO bdicnweb:"informix".status_genarchportanomcan(usuario_insert,status,num_registros,ruta_archivo,error_proceso,error) VALUES(pUsuario,'I',0,'','',cCodRet);
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFechaRegistro IS NULL THEN
			LET cCodRet = '00003';
			UPDATE bdicnweb:"informix".status_genarchportanomcan
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros, cRutaArchivo;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE bdicnweb:"informix".status_genarchportanomcan
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros, cRutaArchivo;
		END IF;
		
		EXECUTE PROCEDURE bdicheq:"informix".sp_generarchivoportab_cancelaciones(pFechaRegistro, cArchivo)
		INTO cCodRetSp, iNoRegistros, cRutaArchivo;
		
		LET iCodRetSp = cCodRetSp::INTEGER;
		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION iCodRetSp, 0, "ERROR EN LA EJECUCION DEL SP bdicheq:'informix'.sp_generarchivoportab";
		ELIF iCodRetSp = 1 THEN
			LET cCodRet = '00670'; -- OCURRIO UN PROBLEMA EN LA GENERACION DEL ARCHIVO
			
			UPDATE bdicnweb:"informix".status_genarchportanomcan
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			
			RETURN cCodRet, iNoRegistros, cRutaArchivo;
		END IF;
		
		UPDATE bdicnweb:"informix".status_genarchportanomcan
		SET status = 'T', error_proceso = 'N', num_registros = iNoRegistros, ruta_archivo = TRIM(cRutaArchivo) WHERE usuario_insert = pUsuario;
		
		RETURN cCodRet, iNoRegistros, cRutaArchivo; 
	
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Martha Salgado Mendoza',
'FECHA: 25/10/2016',
'MODULO: Operaciones',
'FUNCIONALIDAD: Portabilidad de nomina - Solicitudes . Cancelaciones',
'DESCRIPCION: CreaciÃÂ³n de archivos con las solicitudes previamente consultadas para el proceso de portabilidad de nomina, Cancelaciones',
'AUTOR: L. Montserrat LeÃÂ³n Amador',
'FECHA 15/10/2019',
'DESCRIPCION: Se implementa tratado de volumetrÃÂ­a',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_verificastatus_consultaportanomcancel(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5) AS codret,
		      CHAR(1) AS status,
		      INTEGER AS num_registros,
		      CHAR(1) AS error_proceso,
		      CHAR(5) AS error;
			  
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	DEFINE cStatus CHAR(1);
	DEFINE cErrorProceso CHAR(1);
	DEFINE cError CHAR(5);
	DEFINE iNumRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cStatus = '';
	LET cErrorProceso = '';
	LET cError = '';
	LET iNumRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;	
		END EXCEPTION;
	 
		--SET DEBUG FILE TO '/tmp/mfinis/sp_verificastatus_consultaportanomcancel.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;	
		END IF;		
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
	
		SELECT status,num_registros,error_proceso,error
		INTO cStatus,iNumRegistros,cErrorProceso,cError
		FROM bdicnweb:"informix".status_consulportanomcancelaciones
		WHERE usuario_insert = pUsuario;
				
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN		
			RETURN cCodRet,'I','','',''; 
		ELSE 			
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;		
		END IF;	
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Rodolfo Conde Flores',
