CREATE PROCEDURE "informix".sp_dic_consultaclienteseindividual(pUsuario CHAR(8), pIdFuncion CHAR(10), pEmpresa CHAR(3), pNumCte CHAR(20), ptipoBusqueda INTEGER)
		RETURNING CHAR(5) AS codret,
			 CHAR(20) AS num_credito,
			 CHAR(20) AS num_tarjeta,
			 CHAR(1) AS sit_especial,
			 SMALLINT AS causa,
			 CHAR(75) AS descripcion,
             DATETIME YEAR TO SECOND AS fecha_mod;
		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cNumCredito CHAR(20);
	DEFINE cNumTarjeta CHAR(20);
	DEFINE cSitEspecial CHAR(1);
	DEFINE cCausa SMALLINT;
	DEFINE cDescripcion CHAR(75);
    DEFINE dFechaMod DATETIME YEAR TO SECOND;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cNumCredito = '';
	LET cNumTarjeta = '';
	LET cSitEspecial = '';
	LET cCausa = 0;
	LET cDescripcion = '';
    LET dFechaMod = '';
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNumCredito, cNumTarjeta, cSitEspecial, cCausa, cDescripcion, dFechaMod;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_dic_consultaclienteseindividual.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pEmpresa = '' OR pNumCte = '' OR ptipoBusqueda IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNumCredito, cNumTarjeta, cSitEspecial, cCausa, cDescripcion, dFechaMod;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD		
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNumCredito, cNumTarjeta, cSitEspecial, cCausa, cDescripcion, dFechaMod;
		END IF;
		
		EXECUTE PROCEDURE bdisitesp:"informix".sp_consultaclienteseindividual(pEmpresa, pNumCte, ptipoBusqueda)
		INTO cCodRetSp, cNumCredito, cNumTarjeta, cSitEspecial, cCausa, cDescripcion, dFechaMod;
		
		LET iCodRetSp = cCodRetSp::INTEGER;
		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION iCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP bdisitesp:"informix".sp_consultaclienteseindividual';
		ELIF iCodRetSp = 999 THEN
			LET cCodRet = '00003';
		END IF;
		
		RETURN cCodRet, cNumCredito, cNumTarjeta, cSitEspecial, cCausa, cDescripcion, dFechaMod;
	
	END;
	
END PROCEDURE
