CREATE PROCEDURE "informix".sp_atms_actualizadotacionesfaltsobr(pUsuario CHAR(8), pIdFuncion CHAR(10), 
	pIdProvCaja CHAR(4), pTipoOperacion CHAR(4), pOperacion CHAR(2), pMonto MONEY(14,2), 
	pDenominacion1 CHAR(18), pDenominacion2 CHAR(18), pDenominacion3 CHAR(18), pDenominacion4 CHAR(18), pDenominacion5 CHAR(18),	
	pDenominacion6 CHAR(18), pDenominacion7 CHAR(18), pDenominacion8 CHAR(18), pDenominacion9 CHAR(18), pDenominacion10 CHAR(18), 
	pDenominacion11 CHAR(18), pDenominacion12 CHAR(18), pDenominacion13 CHAR(18), pDenominacion14 CHAR(18), pDenominacion15 CHAR(18), 
	pCantidad1 FLOAT(8), pCantidad2 FLOAT(8), pCantidad3 FLOAT(8), pCantidad4 FLOAT(8), pCantidad5 FLOAT(8), 
	pCantidad6 FLOAT(8), pCantidad7 FLOAT(8), pCantidad8 FLOAT(8), pCantidad9 FLOAT(8), pCantidad10 FLOAT(8), 
	pCantidad11 FLOAT(8), pCantidad12 FLOAT(8), pCantidad13 FLOAT(8), pCantidad14 FLOAT(8), pCantidad15 FLOAT(8))
	RETURNING CHAR(5) AS codret, 
		CHAR(8) AS no_folio;
		
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cCodTrans CHAR(4);
	DEFINE cTipo CHAR(1);
	DEFINE cTipoMovto CHAR(1);
	DEFINE cDivisa CHAR(1);
	DEFINE cSecuencia CHAR(8);
	DEFINE cFechaEnvio DATE;
	DEFINE cCentecimas CHAR(1);
	DEFINE cHora CHAR(6);

	DEFINE cFolio CHAR(8);
	DEFINE iNoRegistros INTEGER; 
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cCodTrans = '';
	LET cTipo = '';
	LET cTipoMovto = '';
	LET cDivisa = '01';
	LET cSecuencia = '';
	LET cFechaEnvio = '';
	LET cCentecimas = '1';
	LET cHora = LPAD(CAST(SUBSTR(CURRENT,12,2) AS CHAR(2)),2,'0') ||
				LPAD(CAST(SUBSTR(CURRENT,15,2) AS CHAR(2)),2,'0') ||
				LPAD(CAST(SUBSTR(CURRENT,18,2) AS CHAR(2)),2,'0');
	
	LET cFolio = '';
	LET iNoRegistros = 0; 
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cFolio;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_actualizadotacionesfaltsobr.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pIdProvCaja = '' OR pTipoOperacion = '' OR pOperacion = '' OR pMonto IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cFolio;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cFolio;
		END IF;	
		
		IF pTipoOperacion = '0038' THEN
		
			SELECT valor INTO cCodTrans 
			FROM bdisuc:"informix".ss_param_cajagen WHERE codigo = '0038';
			
			LET cTipo = '0';
			LET cTipoMovto = '0';
			
		ELIF pTipoOperacion = '0039' THEN
		
			SELECT valor INTO cCodTrans 
			FROM bdisuc:"informix".ss_param_cajagen WHERE codigo = '0039';
			
			LET cTipo = '1';
			LET cTipoMovto = '1';
			
		END IF;
		
		LET cSecuencia = TRIM(cHora)||LPAD(cCentecimas,2,'0');
		
		SELECT TO_CHAR(fecha_hoy,'%m/%d/%Y') INTO cFechaEnvio 
		FROM bdinteg:"informix".si_fechas WHERE empresa = cEmpresa;
	
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
	
		EXECUTE PROCEDURE bdisuc:"informix".sp_faltsob_atm(cEmpresa, pIdProvCaja, pUsuario, TRIM(pUsuario)||TRIM(cSecuencia), cCodTrans, '01', pMonto, cFechaEnvio,
		pDenominacion1, pDenominacion2, pDenominacion3, pDenominacion4, pDenominacion5,	pDenominacion6, pDenominacion7, pDenominacion8, pDenominacion9, pDenominacion10, 
		pDenominacion11, pDenominacion12, pDenominacion13, pDenominacion14, pDenominacion15, pCantidad1, pCantidad2, pCantidad3, pCantidad4, pCantidad5, 
		pCantidad6, pCantidad7, pCantidad8, pCantidad9, pCantidad10, pCantidad11, pCantidad12, pCantidad13, pCantidad14, pCantidad15,cTipoMovto,pOperacion,0)
		INTO cCodRetSp, cFolio;
		
		IF cCodRetSp::INTEGER < 0 THEN 
			RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_faltsob_atm';
		ELIF cCodRetSp::INTEGER = 105 THEN
			LET cCodRet = '00877'; --LA CAJA GENERAL NO EXISTE, VERIFIQUE
			RETURN cCodRet, cFolio;
		ELIF cCodRetSp::INTEGER = 106 THEN
			LET cCodRet = '00411'; --LA SOLICITUD NO EXISTE O ES INCORRECTA, FAVOR DE VERIFICAR E INTENTAR NUEVAMENTE
			RETURN cCodRet, cFolio;
		ELIF cCodRetSp::INTEGER = 110 THEN
			LET cCodRet = '00003'; 
			RETURN cCodRet, cFolio;
		END IF;

		RETURN cCodRet, cFolio;
		
	END;
END PROCEDURE 
