CREATE PROCEDURE "informix".sp_atms_actualizarecepdota(pUsuario CHAR(8), pIdFuncion CHAR(10), 
	pIdProvCaja CHAR(4), pFolio CHAR(8), pDivisa CHAR(2), pMonto MONEY(14,2),
	pCantidad1 FLOAT(8), pCantidad2 FLOAT(8), pCantidad3 FLOAT(8), pCantidad4 FLOAT(8), pCantidad5 FLOAT(8), 
	pCantidad6 FLOAT(8), pCantidad7 FLOAT(8), pCantidad8 FLOAT(8), pCantidad9 FLOAT(8), pCantidad10 FLOAT(8), 
	pCantidad11 FLOAT(8), pCantidad12 FLOAT(8), pCantidad13 FLOAT(8), pCantidad14 FLOAT(8), pCantidad15 FLOAT(8))
	RETURNING CHAR(5) AS codret;
		
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cCodTrans CHAR(4);
	DEFINE cFechaEnvio DATE;
	DEFINE cSecuencia CHAR(8);
	DEFINE cCentecimas CHAR(1);
	DEFINE cHora CHAR(6);
	DEFINE cFolioSucursal  CHAR(16);
	DEFINE iNoRegistros INTEGER; 

	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cCodTrans = '';
	LET cFechaEnvio = '';
	LET cSecuencia = '';
	LET cCentecimas = '1';
	LET cHora = LPAD(CAST(SUBSTR(CURRENT,12,2) AS CHAR(2)),2,'0') ||
				LPAD(CAST(SUBSTR(CURRENT,15,2) AS CHAR(2)),2,'0') ||
				LPAD(CAST(SUBSTR(CURRENT,18,2) AS CHAR(2)),2,'0');
	LET cFolioSucursal  = '';
	LET iNoRegistros = 0; 
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_actualizarecepdota.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pIdProvCaja = '' OR pFolio = '' OR pDivisa = '' OR pMonto IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;	
		
		SELECT valor INTO cCodTrans 
		FROM bdisuc:"informix".ss_param_cajagen WHERE codigo = '0037';
		
		SELECT TO_CHAR(fecha_hoy,'%m/%d/%Y') INTO cFechaEnvio 
		FROM bdinteg:"informix".si_fechas WHERE empresa = cEmpresa;
		
		LET cSecuencia = TRIM(cHora)||LPAD(cCentecimas,2,'0');
	
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		EXECUTE PROCEDURE bdisuc:"informix".sp_recepdota_atm(cEmpresa, pIdProvCaja, pUsuario, TRIM(pUsuario)||TRIM(cSecuencia),
		pFolio, cCodTrans, pDivisa, cFechaEnvio, pMonto, pCantidad1, pCantidad2, pCantidad3, pCantidad4, pCantidad5, 
		pCantidad6, pCantidad7, pCantidad8, pCantidad9, pCantidad10, pCantidad11, pCantidad12, pCantidad13, pCantidad14, pCantidad15, '13')
		INTO cCodRetSp;
		
		IF cCodRetSp::INTEGER < 0 THEN 
			RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_recepdota_atm';
		ELIF cCodRetSp::INTEGER > 0 THEN
		
			IF cCodRetSp::INTEGER = 100 THEN
				LET cCodRet = '00878'; --FOLIO DE DOTACIÓN NO EXISTE, 
			ELIF cCodRetSp::INTEGER = 102 THEN
				LET cCodRet = '00882'; --MONTO DE LA DOTACIÓN NO CORRESPONDE AL ENVIADO, VERIFIQUE
			ELIF cCodRetSp::INTEGER = 103 THEN
				LET cCodRet = '00883'; --EL FOLIO APARECE COMO CANCELADO, VERIFIQUE
			ELIF cCodRetSp::INTEGER = 104 THEN
				LET cCodRet = '00879'; --SOLICITUD NO AUTORIZADA, VERIFIQUE
			ELIF cCodRetSp::INTEGER = 107 THEN
				LET cCodRet = '00884'; --LA SOLICITUD YA FUE RECIBIDA, VERIFIQUE
			ELIF cCodRetSp::INTEGER = 110 THEN
				LET cCodRet = '00003';
			END IF;
		
			RETURN cCodRet;
		
		ELIF cCodRetSp::INTEGER = 0 THEN
			
			EXECUTE PROCEDURE bdisuc:"informix".sp_inserta_atm(cEmpresa, pIdProvCaja, '01',
			pCantidad1, pCantidad2, pCantidad3, pCantidad4, pCantidad5, pCantidad6, pMonto)
			INTO cCodRetSp;
			
			IF cCodRetSp::INTEGER < 0 THEN 
				RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_inserta_atm';
			END IF;
		
		END IF;
		
		RETURN cCodRet;

	END;
END PROCEDURE 
DOCUMENT 'AUTOR: L. Montserrat León Amador',
