		IF pUsuario = '' OR pIdFuncion = '' OR pIdProvCaja = '' OR pDivisa = '' OR pMonto IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cFolio;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cFolio;
		END IF;	
		
		SELECT valor INTO cCodTrans 
		FROM bdisuc:"informix".ss_param_cajagen WHERE codigo = '0036';
		
		LET cSecuencia = TRIM(cHora)||'00';
		
		SELECT TO_CHAR(fecha_hoy,'%m/%d/%Y') INTO cFechaEnvio 
		FROM bdinteg:"informix".si_fechas WHERE empresa = cEmpresa;
	
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
	
		EXECUTE PROCEDURE bdisuc:"informix".sp_soldot_atm(cEmpresa, pIdProvCaja, pUsuario, TRIM(pUsuario)||TRIM(cSecuencia), cCodTrans, pDivisa, pMonto, cFechaEnvio,
		pDenominacion1, pDenominacion2, pDenominacion3, pDenominacion4, pDenominacion5,	pDenominacion6, pDenominacion7, pDenominacion8, pDenominacion9, pDenominacion10, 
		pDenominacion11, pDenominacion12, pDenominacion13, pDenominacion14, pDenominacion15, pCantidad1, pCantidad2, pCantidad3, pCantidad4, pCantidad5, 
		pCantidad6, pCantidad7, pCantidad8, pCantidad9, pCantidad10, pCantidad11, pCantidad12, pCantidad13, pCantidad14, pCantidad15)
		INTO cCodRetSp, cFolio;
		
		IF cCodRetSp::INTEGER < 0 THEN 
			RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_soldot_atm';
		ELIF cCodRetSp::INTEGER = 105 THEN
