CREATE PROCEDURE "informix".sp_atms_cargaarchivodotacionesmasivas(pUsuario CHAR(8), pIdFuncion CHAR(10), pBloqueInf CHAR(2000), pIteracion CHAR(1))
	RETURNING CHAR(5) AS codret; 
	
	DEFINE cCodRet CHAR(5);
	DEFINE cSqlerr INTEGER;
	DEFINE cIsamErr	INTEGER;
	DEFINE cDescErr	CHAR(50);
	DEFINE cEmpresa CHAR(3);
	DEFINE cRegistro LVARCHAR;
	DEFINE cBloqueInf2 LVARCHAR;
	DEFINE iContador INTEGER;
	DEFINE cCc CHAR(4);
	DEFINE cId_atm CHAR(6);
	DEFINE cNombre CHAR(200);
	DEFINE cPlaza CHAR(100);
	DEFINE cTipo_ope CHAR(25);
	DEFINE iB_1000 INTEGER;
	DEFINE iB_500 INTEGER;
	DEFINE iB_200 INTEGER;
	DEFINE iB_100 INTEGER;
	DEFINE iB_50 INTEGER;
	DEFINE iB_20 INTEGER;
	DEFINE mTotal_b MONEY(18,2);
	DEFINE cFolio CHAR(8);
	
	LET cCodRet = '00000';
	LET cSqlerr = 0;
	LET cIsamErr = 0;
	LET cDescErr = '';
	LET cEmpresa = '001';
	LET cRegistro = '';
	LET cBloqueInf2 = '';
	LET iContador = 0;
	LET cCc = '';
	LET cId_atm = '';
	LET cNombre = '';
	LET cPlaza = '';
	LET cTipo_ope = '';
	LET iB_1000 = 0;
	LET iB_500 = 0;
	LET iB_200 = 0;
	LET iB_100 = 0;
	LET iB_50 = 0;
	LET iB_20 = 0;
	LET mTotal_b = 0.00;
	LET cFolio = '';
	
	BEGIN
		
		ON EXCEPTION SET cSqlerr, cIsamErr, cDescErr
			IF cSqlerr <> 0 THEN
				LET cCodRet = cSqlerr;
				RETURN cCodRet; 
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_cargaarchivodotacionesmasivas.out';
		--TRACE ON;		
		
		IF pUsuario = '' OR pIdFuncion = '' OR pBloqueInf = '' OR pIteracion = '' THEN
			LET cCodRet = '00003';			
			RETURN cCodRet; 
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- SE LIMPIA TABLA
		IF pIteracion = '0' THEN
			DELETE {+AVOID_FULL( "informix".sw_atm_dotacionmasiva)} FROM "informix".sw_atm_dotacionmasiva WHERE usuario = pUsuario;
		END IF;
		
		FOREACH
			
			EXECUTE PROCEDURE "informix".sp_split_cadena(pBloqueInf, '|')
			INTO cBloqueInf2
			
			LET cBloqueInf2 = TRIM(cBloqueInf2)||'+';
			LET cRegistro = '';
			LET iContador = 0;
			
			FOREACH
			
				EXECUTE PROCEDURE "informix".sp_split_cadena(cBloqueInf2, '+')
				INTO cRegistro
			
				LET iContador = iContador + 1;
				
				IF iContador = 1 THEN
					LET cCc = TRIM(cRegistro);
				ELIF iContador = 2 THEN
					LET cId_atm = TRIM(cRegistro);
				ELIF iContador = 3 THEN
					LET cNombre = TRIM(cRegistro);
				ELIF iContador = 4 THEN
					LET cPlaza = TRIM(cRegistro);
				ELIF iContador = 5 THEN
					LET cTipo_ope = TRIM(cRegistro);
				ELIF iContador = 6 THEN
					LET iB_500 = TRIM(cRegistro);
				ELIF iContador = 7 THEN
					LET iB_200 = TRIM(cRegistro);
				ELIF iContador = 8 THEN
					LET iB_100 = TRIM(cRegistro);
				ELIF iContador = 9 THEN
					LET iB_50 = TRIM(cRegistro);
				ELIF iContador = 10 THEN
					LET iB_20 = TRIM(cRegistro);
				ELIF iContador = 11 THEN
					LET mTotal_b = TRIM(cRegistro);
				END IF;
			
			END FOREACH;
			
			INSERT INTO "informix".sw_atm_dotacionmasiva(cc,id_atm,nombre,plaza,tipo_ope,b_1000,b_500,b_200,b_100,b_50,b_20,total_b,folio,usuario) 
			VALUES(cCc,cId_atm,cNombre,cPlaza,cTipo_ope,iB_1000,iB_500,iB_200,iB_100,iB_50,iB_20,mTotal_b,cFolio,pUsuario);			
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '00282'; --ERROR AL GUARDAR EL REGISTRO
			END IF;
			
		END FOREACH;
		
		RETURN cCodRet;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 10/09/2018',
'MODULO: ATM´s',
'FUNCIONALIDAD: SOLICITUD DE DOTACIÓN MASIVA', 
'DESCRIPCION: SPL encargado de hacer la carga del contenido del archivo a la tabla de paso.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_atms_catmovimiento(pUsuario CHAR(8), pIdFuncion CHAR(10))
    RETURNING CHAR(5) AS codRet,
		CHAR(4) AS valor,
		CHAR(35) AS descripcion;

	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cValor CHAR(4);
	DEFINE cDescripcion CHAR(35);
	DEFINE iNumRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';
	LET cValor = '';
	LET cDescripcion = '';
	LET iNumRegistros = 0;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cValor, UPPER(cDescripcion);
			END IF;
		END EXCEPTION;
		
		ON EXCEPTION IN (-958)
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_catmovimiento.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cValor, UPPER(cDescripcion);
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cValor, UPPER(cDescripcion);
		END IF;
	
		-- CREACION DE TABLA TEMPORAL
		CREATE TEMP TABLE sw_atms_catalogos_tmp(id_serial_tmp INTEGER, valor_tmp CHAR(4), descripcion_tmp CHAR(35), usuario_tmp CHAR(8)) WITH NO LOG;
		DELETE FROM sw_atms_catalogos_tmp WHERE usuario_tmp = pUsuario;
	
		INSERT INTO sw_atms_catalogos_tmp(id_serial_tmp, valor_tmp, descripcion_tmp, usuario_tmp) 
		VALUES (iNumRegistros + 1, '0000', 'Arqueo de ATM', pUsuario);
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT DISTINCT valor,descripcion 
			INTO cValor, cDescripcion
			FROM bdisuc:"informix".ss_param_cajagen 
			WHERE codigo IN ('0036','0038','0039','0040','0041','0042','0043')
			ORDER BY valor
			
			LET iNumRegistros = iNumRegistros + 1;
			INSERT INTO sw_atms_catalogos_tmp(id_serial_tmp, valor_tmp, descripcion_tmp, usuario_tmp) 
			VALUES (iNumRegistros + 1, cValor, cDescripcion, pUsuario);
		END FOREACH;
		
		FOREACH
			SELECT valor_tmp, descripcion_tmp
			INTO cValor, cDescripcion
			FROM sw_atms_catalogos_tmp
			WHERE usuario_tmp = pUsuario ORDER BY id_serial_tmp ASC
			
			LET iNumRegistros = iNumRegistros + 1;
			RETURN cCodRet, cValor, UPPER(cDescripcion) WITH RESUME;
		END FOREACH;
		
		IF iNumRegistros = 0 THEN
			LET cCodRet = '00017';	
			RETURN cCodRet, cValor, UPPER(cDescripcion);
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA 27/10/2016',
'MODULO: ATMS',
'FUNCIONALIDAD: CONSULTA DE OPERACIONES',
'DESCRIPCION: Spl encargado de consultar el detalle del catálogo tipo de movimiento.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_atms_catoperaciones(pUsuario CHAR(8), pIdFuncion CHAR(10), pIdCatalogo CHAR(1), pTipoAfectacion CHAR(1))
	RETURNING CHAR(5) AS codret,
		CHAR(4) AS codigo,
		CHAR(35) AS descripcion;		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cCodigo CHAR(4);
	DEFINE cDescripcion  CHAR(35);
	DEFINE iNumRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cCodigo = '';
	LET cDescripcion = '';
	LET iNumRegistros = 0;

	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cCodigo, cDescripcion;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_catoperaciones.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pIdCatalogo = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cCodigo, cDescripcion;	
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cCodigo, cDescripcion;	
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;		
		
		IF pIdCatalogo = '1' THEN
		
			FOREACH
				SELECT codigo, descripcion INTO cCodigo, cDescripcion
				FROM bdisuc:"informix".ss_param_cajagen 
				WHERE codigo = '0038' OR codigo = '0039' ORDER BY codigo
				
				LET iNumRegistros = iNumRegistros + 1;
				RETURN cCodRet, TRIM(cCodigo), TRIM(UPPER(cDescripcion)) WITH RESUME;
			END FOREACH;
			
		ELIF pIdCatalogo = '2' THEN
		
			IF pTipoAfectacion = '' THEN
				LET cCodRet = '00003';
				RETURN cCodRet, cCodigo, cDescripcion;	
			END IF;
		
			FOREACH
				SELECT {+AVOID_FULL(bdisuc:"informix".ss_motiv_afecta)} codigo, descripcion INTO cCodigo, cDescripcion 
				FROM bdisuc:"informix".ss_motiv_afecta 
				WHERE codigo > '0' AND tpo_afecta = UPPER(pTipoAfectacion) ORDER BY codigo
				
				LET iNumRegistros = iNumRegistros + 1;
				RETURN cCodRet, TRIM(cCodigo), TRIM(UPPER(cDescripcion)) WITH RESUME;
			END FOREACH;

		END IF;
		
		IF NVL(iNumRegistros,0) = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cCodigo, cDescripcion;
		END IF;	
		
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 10/10/2016',
'MODULO: ATMS',
