CREATE PROCEDURE "informix".sp_atms_catplazacajero(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipo CHAR(1), pPlaza CHAR(3), pRegistros INTEGER, pRecuperacion INTEGER)
    RETURNING CHAR(5) AS codRet,
		CHAR(4) AS plaza_cajero,
		CHAR(100) AS descripcion;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cNombre CHAR(45);
	DEFINE cSucursal CHAR(4);
	DEFINE cNumAtm CHAR(4);
	DEFINE cNombreAtm CHAR(100); 
	DEFINE cCadenaNumAtm CHAR(5000);
	DEFINE cPlaza CHAR(3);
	DEFINE cDescripcion CHAR(100);
	DEFINE cSiSucursal CHAR(4);
	DEFINE cPlazaCajero CHAR(4);
	DEFINE dFechaHoy DATE;
	DEFINE iRecuperacion INTEGER;

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';
	LET cNombre = '';
	LET cSucursal = '';
	LET cNumAtm = '';
	LET cNombreAtm = ''; 
	LET cCadenaNumAtm = '';
	LET cPlaza = '';
	LET cDescripcion = '';
	LET cSiSucursal = '';
	LET cPlazaCajero = '';
	LET dFechaHoy = DATE(CURRENT);
	LET iRecuperacion = 0;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
				SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
				RETURN cCodRet,cPlazaCajero,cDescripcion;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_catplazacajero.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pTipo = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
			SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
			RETURN cCodRet,cPlazaCajero,cDescripcion;
		END IF;
		
		-- VALIDACIÓN DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
			SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
			RETURN cCodRet,cPlazaCajero,cDescripcion;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
			SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
			RETURN cCodRet,cPlazaCajero,cDescripcion;
		END IF;
		
		SELECT nombre,sucursal INTO cNombre,cSucursal
		FROM bdinteg:"informix".si_ejecut WHERE ejecutivo = pUsuario;
		
		IF NVL(cSucursal,'') = '' THEN
			LET cCodRet = '00833';
			UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
			SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
			RETURN cCodRet,cPlazaCajero,cDescripcion;
		END IF;
		
		-- SE LIMPIA TABLA POR USUARIO
		DELETE {+AVOID_FULL("informix".sw_atm_statuscargacat)} FROM bdicnweb:"informix".sw_atm_statuscargacat WHERE usuario_inserta = TRIM(pUsuario);
		
		-- SE INSERTA A TABLA PARA EL MONITOREO DEL STATUS
		INSERT INTO bdicnweb:"informix".sw_atm_statuscargacat(id_status,desc_status,usuario_inserta)
		VALUES('I','PROCESO_INICIADO',pUsuario);	
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 6;
		
		-- Carga Plazas
		IF pTipo = 'P' AND pRegistros = 0 THEN
		
			-- SE LIMPIA TABLA POR USUARIO
			DELETE FROM bdicnweb:"informix".sw_atm_catalogoplaza WHERE usuario = TRIM(pUsuario);
		
			FOREACH
				EXECUTE PROCEDURE bdisuc:"informix".sp_atms(cEmpresa,cSucursal,0)
				INTO cCodRetSp,cNumAtm,cNombreAtm
			
				IF cCodRetSp::INTEGER < 0 THEN 
					RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_atms';
				ELIF cCodRetSp::INTEGER = 110 THEN
					LET cCodRet = '00003';
					UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
					SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
					RETURN cCodRet,cPlazaCajero,cDescripcion;
				END IF;
				
				INSERT INTO bdicnweb:"informix".sw_atm_catalogoplaza(plaza,descripcion,usuario) 
				SELECT DISTINCT a.plaza_cajagen,b.descripcion,pUsuario 
				FROM bdinteg:"informix".si_sucursales AS a, bdinteg:"informix".si_plazas_cajagen AS b 
				WHERE a.sucursal = TRIM(cNumAtm) AND a.empresa = '001' AND a.plaza_cajagen = b.codigo_plaza 
				AND b.empresa = '001' AND b.codigo_plaza = a.plaza_cajagen ORDER BY a.plaza_cajagen;
			END FOREACH;
			
		-- Carga Cajeros
		ELIF pTipo = 'C' AND pRegistros = 0 THEN
		
			IF pPlaza = '' THEN
				LET cCodRet = '00003';
				UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
				SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
				RETURN cCodRet,cPlazaCajero,cDescripcion;
			END IF;
		
			-- SE LIMPIA TABLA POR USUARIO
			DELETE FROM bdicnweb:"informix".sw_atm_catalogocajero WHERE usuario = TRIM(pUsuario);
		
			FOREACH
				EXECUTE PROCEDURE bdisuc:"informix".sp_atms(cEmpresa,cSucursal,0)
				INTO cCodRetSp,cNumAtm,cNombreAtm
			
				IF cCodRetSp::INTEGER < 0 THEN 
					RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_atms';
				ELIF cCodRetSp::INTEGER = 110 THEN
					LET cCodRet = '00003';
					UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
					SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
					RETURN cCodRet,cPlazaCajero,cDescripcion;
				END IF;
					
					INSERT INTO bdicnweb:"informix".sw_atm_catalogocajero(cajero,descripcion,usuario) 
					SELECT a.sucursal,cNombreAtm,pUsuario
					FROM bdinteg:"informix".si_sucursales AS a, bdinteg:"informix".si_plazas_cajagen AS b, bdisuc:"informix".ss_atms_sucursal  AS c 
					WHERE a.sucursal = TRIM(cNumAtm) AND a.empresa = '001' AND a.plaza_cajagen = b.codigo_plaza 
					AND a.plaza_cajagen = TRIM(pPlaza) AND c.cod_atm = a.sucursal ORDER BY a.plaza_cajagen;
			END FOREACH;	
		
		END IF;
		
		IF pTipo = '1' THEN
		
			SET LOCK MODE TO WAIT 3;
			
			FOREACH
				SELECT {+AVOID_FULL("informix".sw_atm_catalogoplaza)} SKIP pRegistros FIRST pRecuperacion DISTINCT plaza,descripcion
				INTO cPlaza,cDescripcion 
				FROM bdicnweb:"informix".sw_atm_catalogoplaza
				WHERE usuario = TRIM(pUsuario)
			
				LET cPlazaCajero = cPlaza;
				LET iRecuperacion = iRecuperacion + 1;
				RETURN cCodRet,TRIM(cPlazaCajero),TRIM(UPPER(cDescripcion)) WITH RESUME;
			END FOREACH;
			
			IF iRecuperacion = 0 AND pRegistros = 0 THEN
				LET cCodRet = '00867'; --NO EXISTEN ATMS RELACIONADOS A ESTA REGIÓN
				UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
				SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
				RETURN cCodRet,cPlazaCajero,cDescripcion;
			ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
				LET cCodRet = '1001';
				UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
				SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
				RETURN cCodRet,cPlazaCajero,cDescripcion;
			END IF;
		
		ELIF pTipo = '2' THEN 
	
			SET LOCK MODE TO WAIT 3;
			
			FOREACH
				SELECT {+AVOID_FULL("informix".sw_atm_catalogocajero)} SKIP pRegistros FIRST pRecuperacion cajero,descripcion
				INTO cSiSucursal,cDescripcion 
				FROM bdicnweb:"informix".sw_atm_catalogocajero
				WHERE usuario = TRIM(pUsuario)
			
				LET cPlazaCajero = cSiSucursal;
				LET iRecuperacion = iRecuperacion + 1;
				RETURN cCodRet,TRIM(cPlazaCajero),TRIM(UPPER(cDescripcion)) WITH RESUME;
			END FOREACH;
			
			IF iRecuperacion = 0 AND pRegistros = 0 THEN
				LET cCodRet = '00867'; --NO EXISTEN ATMS RELACIONADOS A ESTA REGIÓN
				UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
				SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
				RETURN cCodRet,cPlazaCajero,cDescripcion;
			ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
				LET cCodRet = '1001';
				UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
				SET id_status = 'T', desc_status = 'PROCESO_TRUNCADO' WHERE usuario_inserta = pUsuario;
				RETURN cCodRet,cPlazaCajero,cDescripcion;
			END IF;	
		
		END IF;
		
		UPDATE {+AVOID_FULL("informix".sw_atm_statuscargacat)} bdicnweb:"informix".sw_atm_statuscargacat
		SET id_status = 'F', desc_status = 'PROCESO_FINALIZADO' WHERE usuario_inserta = pUsuario;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA 29/09/2016',
'MODULO: ATMS',
'FUNCIONALIDAD: SOLICITUD DE DOTACIÓN ATM A CAJA GENERAL',
