	LET cDenominacion11 = '';
	LET mTotal11 = NULL;
	LET dDisponible12 = 0.00; 
	LET cDenominacion12 = '';
	LET mTotal12 = NULL;
	LET dDisponible13 = 0.00; 
	LET cDenominacion13 = '';
	LET mTotal13 = NULL;
	LET dDisponible14 = 0.00; 		
	LET cDenominacion14 = '';
	LET mTotal14 = NULL;		
	LET dDisponible15 = 0.00; 
	LET cDenominacion15 = '';
	LET mTotal15 = NULL;
	LET mTotalActual = NULL;
	LET iNoRegistros = 0; 
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cSucursal, mMonto,
			cDenominacion1, dDisponible1, mTotal1, cDenominacion2, dDisponible2, mTotal2, cDenominacion3, dDisponible3, mTotal3,
			cDenominacion4, dDisponible4, mTotal4, cDenominacion5, dDisponible5, mTotal5, cDenominacion6, dDisponible6, mTotal6,
			cDenominacion7, dDisponible7, mTotal7, cDenominacion8, dDisponible8, mTotal8, cDenominacion9, dDisponible9, mTotal9,
			cDenominacion10, dDisponible10, mTotal10, cDenominacion11, dDisponible11, mTotal11, cDenominacion12, dDisponible12, mTotal12,
			cDenominacion13, dDisponible13, mTotal13, cDenominacion14, dDisponible14, mTotal14, cDenominacion15, dDisponible15, mTotal15, 
			cDivisa, NVL(mTotalActual,0);
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_consdotacion.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pIdProvCaja = '' OR pFolio = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cSucursal, mMonto,
			cDenominacion1, dDisponible1, mTotal1, cDenominacion2, dDisponible2, mTotal2, cDenominacion3, dDisponible3, mTotal3,
			cDenominacion4, dDisponible4, mTotal4, cDenominacion5, dDisponible5, mTotal5, cDenominacion6, dDisponible6, mTotal6,
			cDenominacion7, dDisponible7, mTotal7, cDenominacion8, dDisponible8, mTotal8, cDenominacion9, dDisponible9, mTotal9,
			cDenominacion10, dDisponible10, mTotal10, cDenominacion11, dDisponible11, mTotal11, cDenominacion12, dDisponible12, mTotal12,
			cDenominacion13, dDisponible13, mTotal13, cDenominacion14, dDisponible14, mTotal14, cDenominacion15, dDisponible15, mTotal15, 
			cDivisa, NVL(mTotalActual,0);
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cSucursal, mMonto,
			cDenominacion1, dDisponible1, mTotal1, cDenominacion2, dDisponible2, mTotal2, cDenominacion3, dDisponible3, mTotal3,
			cDenominacion4, dDisponible4, mTotal4, cDenominacion5, dDisponible5, mTotal5, cDenominacion6, dDisponible6, mTotal6,
			cDenominacion7, dDisponible7, mTotal7, cDenominacion8, dDisponible8, mTotal8, cDenominacion9, dDisponible9, mTotal9,
			cDenominacion10, dDisponible10, mTotal10, cDenominacion11, dDisponible11, mTotal11, cDenominacion12, dDisponible12, mTotal12,
			cDenominacion13, dDisponible13, mTotal13, cDenominacion14, dDisponible14, mTotal14, cDenominacion15, dDisponible15, mTotal15, 
			cDivisa, NVL(mTotalActual,0);
		END IF;	
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		EXECUTE PROCEDURE bdisuc:"informix".sp_dotatm(cEmpresa, pFolio)
		INTO cCodRetSp, cSucursal, mMonto;
		
		IF cCodRetSp::INTEGER < 0 THEN 
			RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_dotatm';
		ELIF cCodRetSp::INTEGER > 0 THEN
		
			IF cCodRetSp::INTEGER = 100 THEN
				LET cCodRet = '00878'; --FOLIO DE DOTACIÓN NO EXISTE, VERIFIQUE
			ELIF cCodRetSp::INTEGER = 104 THEN
				LET cCodRet = '00879'; --SOLICITUD NO AUTORIZADA, VERIFIQUE
			ELIF cCodRetSp::INTEGER = 107 THEN
				LET cCodRet = '00880'; --EL FOLIO APARECE COMO RECIBIDO, VERIFIQUE
			ELIF cCodRetSp::INTEGER = 110 THEN
				LET cCodRet = '00003';
			END IF;
			
			RETURN cCodRet, cSucursal, mMonto,
			cDenominacion1, dDisponible1, mTotal1, cDenominacion2, dDisponible2, mTotal2, cDenominacion3, dDisponible3, mTotal3,
			cDenominacion4, dDisponible4, mTotal4, cDenominacion5, dDisponible5, mTotal5, cDenominacion6, dDisponible6, mTotal6,
			cDenominacion7, dDisponible7, mTotal7, cDenominacion8, dDisponible8, mTotal8, cDenominacion9, dDisponible9, mTotal9,
			cDenominacion10, dDisponible10, mTotal10, cDenominacion11, dDisponible11, mTotal11, cDenominacion12, dDisponible12, mTotal12,
			cDenominacion13, dDisponible13, mTotal13, cDenominacion14, dDisponible14, mTotal14, cDenominacion15, dDisponible15, mTotal15, 
			cDivisa, NVL(mTotalActual,0);
			
		END IF;
		
		IF NVL(cSucursal,'') <> pIdProvCaja THEN
			LET cCodRet = '00881'; --EL FOLIO NO PERTENECE AL ATM SELECCIONADO, VERIFIQUE
			RETURN cCodRet, cSucursal, mMonto,
			cDenominacion1, dDisponible1, mTotal1, cDenominacion2, dDisponible2, mTotal2, cDenominacion3, dDisponible3, mTotal3,
			cDenominacion4, dDisponible4, mTotal4, cDenominacion5, dDisponible5, mTotal5, cDenominacion6, dDisponible6, mTotal6,
			cDenominacion7, dDisponible7, mTotal7, cDenominacion8, dDisponible8, mTotal8, cDenominacion9, dDisponible9, mTotal9,
			cDenominacion10, dDisponible10, mTotal10, cDenominacion11, dDisponible11, mTotal11, cDenominacion12, dDisponible12, mTotal12,
			cDenominacion13, dDisponible13, mTotal13, cDenominacion14, dDisponible14, mTotal14, cDenominacion15, dDisponible15, mTotal15, 
			cDivisa, NVL(mTotalActual,0);
		END IF;
		
		SET LOCK MODE TO WAIT 3;

		IF NOT EXISTS(SELECT * FROM bdisuc:"informix".ss_atm WHERE cod_atm = pIdProvCaja) THEN
		
			LET cCodRet = '00877'; --'LA CAJA GENERAL '||pIdProvCaja||' NO EXISTE, VERIFIQUE'
			RETURN cCodRet, cSucursal, mMonto,
			cDenominacion1, dDisponible1, mTotal1, cDenominacion2, dDisponible2, mTotal2, cDenominacion3, dDisponible3, mTotal3,
			cDenominacion4, dDisponible4, mTotal4, cDenominacion5, dDisponible5, mTotal5, cDenominacion6, dDisponible6, mTotal6,
			cDenominacion7, dDisponible7, mTotal7, cDenominacion8, dDisponible8, mTotal8, cDenominacion9, dDisponible9, mTotal9,
			cDenominacion10, dDisponible10, mTotal10, cDenominacion11, dDisponible11, mTotal11, cDenominacion12, dDisponible12, mTotal12,
			cDenominacion13, dDisponible13, mTotal13, cDenominacion14, dDisponible14, mTotal14, cDenominacion15, dDisponible15, mTotal15, 
			cDivisa, NVL(mTotalActual,0);
		
		ELSE
			
			SELECT divisa, saldo_anterior, saldo_asignado, saldo_total,
				NVL(denominacion_1,''), NVL(cantidad_1,''), NVL((denominacion_1::INTEGER * cantidad_1),'') AS total_1, 
				NVL(denominacion_2,''), NVL(cantidad_2,''), NVL((denominacion_2::INTEGER * cantidad_2),'') AS total_2, 
				NVL(denominacion_3,''), NVL(cantidad_3,''), NVL((denominacion_3::INTEGER * cantidad_3),'') AS total_3, 
				NVL(denominacion_4,''), NVL(cantidad_4,''), NVL((denominacion_4::INTEGER * cantidad_4),'') AS total_4, 
				NVL(denominacion_5,''), NVL(cantidad_5,''), NVL((denominacion_5::INTEGER * cantidad_5),'') AS total_5, 
				NVL(denominacion_6,''), NVL(cantidad_6,''), NVL((denominacion_6::INTEGER * cantidad_6),'') AS total_6, 	
				NVL(denominacion_7,''), NVL(cantidad_7,''), NVL((denominacion_7::INTEGER * cantidad_7),'') AS total_7,
				NVL(denominacion_8,''), NVL(cantidad_8,''), NVL((denominacion_8::INTEGER * cantidad_8),'') AS total_8,
				NVL(denominacion_9,''), NVL(cantidad_9,''), NVL((denominacion_9::INTEGER * cantidad_9),'') AS total_9,
				NVL(denominacion_10,''), NVL(cantidad_10,''), NVL((denominacion_10::INTEGER * cantidad_10),'') AS total_10,
				NVL(denominacion_11,''), NVL(cantidad_11,''), NVL((denominacion_11::INTEGER * cantidad_11),'') AS total_11,
				NVL(denominacion_12,''), NVL(cantidad_12,''), NVL((denominacion_12::INTEGER * cantidad_12),'') AS total_12,
				NVL(denominacion_13,''), NVL(cantidad_13,''), NVL((denominacion_13::INTEGER * cantidad_13),'') AS total_13,
				NVL(denominacion_14,''), NVL(cantidad_14,''), NVL((denominacion_14::INTEGER * cantidad_14),'') AS total_14,
				NVL(denominacion_15,''), NVL(cantidad_15,''), NVL((denominacion_15::INTEGER * cantidad_15),'') AS total_15  
			INTO cDivisa, mSaldoAnterior, mSaldoAsignado, mSaldoTotal,
				cDenominacion1, dDisponible1, mTotal1,
				cDenominacion2, dDisponible2, mTotal2,
				cDenominacion3, dDisponible3, mTotal3,
				cDenominacion4, dDisponible4, mTotal4,
				cDenominacion5, dDisponible5, mTotal5,
				cDenominacion6, dDisponible6, mTotal6,
				cDenominacion7, dDisponible7, mTotal7,
				cDenominacion8, dDisponible8, mTotal8,
				cDenominacion9, dDisponible9, mTotal9,
				cDenominacion10, dDisponible10, mTotal10,
				cDenominacion11, dDisponible11, mTotal11,
				cDenominacion12, dDisponible12, mTotal12,
				cDenominacion13, dDisponible13, mTotal13,
				cDenominacion14, dDisponible14, mTotal14,
				cDenominacion15, dDisponible15, mTotal15
			FROM bdisuc:"informix".ss_atm WHERE cod_atm = pIdProvCaja;
		
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '00877'; --'LA CAJA GENERAL '||pIdProvCaja||' NO EXISTE, VERIFIQUE'
				RETURN cCodRet, cSucursal, mMonto,
				cDenominacion1, dDisponible1, mTotal1, cDenominacion2, dDisponible2, mTotal2, cDenominacion3, dDisponible3, mTotal3,
				cDenominacion4, dDisponible4, mTotal4, cDenominacion5, dDisponible5, mTotal5, cDenominacion6, dDisponible6, mTotal6,
				cDenominacion7, dDisponible7, mTotal7, cDenominacion8, dDisponible8, mTotal8, cDenominacion9, dDisponible9, mTotal9,
				cDenominacion10, dDisponible10, mTotal10, cDenominacion11, dDisponible11, mTotal11, cDenominacion12, dDisponible12, mTotal12,
				cDenominacion13, dDisponible13, mTotal13, cDenominacion14, dDisponible14, mTotal14, cDenominacion15, dDisponible15, mTotal15, 
				cDivisa, NVL(mTotalActual,0);
			ELSE
				LET mTotalActual = NVL(mTotal1,0) + NVL(mTotal2,0) + NVL(mTotal3,0) + NVL(mTotal4,0) + NVL(mTotal5,0) + 
								   NVL(mTotal6,0) + NVL(mTotal7,0) + NVL(mTotal8,0) + NVL(mTotal9,0) + NVL(mTotal10,0) + 
								   NVL(mTotal11,0) + NVL(mTotal12,0) + NVL(mTotal13,0) + NVL(mTotal14,0) + NVL(mTotal15,0);
				
				RETURN cCodRet, cSucursal, NVL(mMonto,0),
				cDenominacion1, dDisponible1, mTotal1, cDenominacion2, dDisponible2, mTotal2, cDenominacion3, dDisponible3, mTotal3,
				cDenominacion4, dDisponible4, mTotal4, cDenominacion5, dDisponible5, mTotal5, cDenominacion6, dDisponible6, mTotal6,
				cDenominacion7, dDisponible7, mTotal7, cDenominacion8, dDisponible8, mTotal8, cDenominacion9, dDisponible9, mTotal9,
				cDenominacion10, dDisponible10, mTotal10, cDenominacion11, dDisponible11, mTotal11, cDenominacion12, dDisponible12, mTotal12,
				cDenominacion13, dDisponible13, mTotal13, cDenominacion14, dDisponible14, mTotal14, cDenominacion15, dDisponible15, mTotal15, 
				cDivisa, NVL(mTotalActual,0);
			END IF;
			
		END IF;
		
	END;
END PROCEDURE 
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA 05/10/2016',
'MODULO: ATMS',
'FUNCIONALIDAD: RECEPCIÓN DE DOTACIÓN ATM',
'DESCRIPCION: Spl que realiza la consulta de la dotación solicitada mediante el número de folio ingresado.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_atms_conseliminacionfaltsobr(pUsuario CHAR(8), pIdFuncion CHAR(10), pFolio CHAR(8), pIdProvCaja CHAR(4))
	RETURNING CHAR(5) AS codret,
		CHAR(30) AS desc_operacion,
		CHAR(30) AS desc_motivo,
		MONEY(14,2) AS monto,
		CHAR(2) AS tipo_afectacion;
	
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cDescOperacion  CHAR(30);
	DEFINE cDescMotivo CHAR(30);
	DEFINE cSucursal CHAR(4);
	DEFINE mMonto MONEY(14,2);
	DEFINE cTipoAfectacion CHAR(2);	
	DEFINE cAtm CHAR(4);
	DEFINE iNumRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cDescOperacion = '';
	LET cDescMotivo = '';
	LET cSucursal = '';
	LET mMonto = 0.00;
	LET cTipoAfectacion = '';	
	LET cAtm = '';
	LET iNumRegistros = 0;

	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_conseliminacionfaltsobr.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFolio = '' OR pIdProvCaja = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;		

		EXECUTE PROCEDURE bdisuc:"informix".sp_cons_faltsob(cEmpresa, pFolio)
		INTO cCodRetSp, cDescOperacion, cDescMotivo, cSucursal, mMonto, cTipoAfectacion;
		
		IF cCodRetSp::INTEGER < 0 THEN 
			RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_cons_faltsob';
		ELIF cCodRetSp::INTEGER = 100 THEN
			LET cCodRet = '00892'; --EL FOLIO NO EXISTE, VERIFIQUE
			RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		ELIF cCodRetSp::INTEGER = 108 THEN
			LET cCodRet = '00893'; --EL FOLIO NO CORRESPONDE A FALTANTES Y/O SOBRANTES, VERIFIQUE
			RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		ELIF cCodRetSp::INTEGER = 109 THEN
			LET cCodRet = '00894'; --EL FOLIO APARECE COMO APLICADO, VERIFIQUE
			RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		ELIF cCodRetSp::INTEGER = 110 THEN
			LET cCodRet = '00003'; 
			RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		END IF;
		
		LET cAtm = TRIM(cSucursal);
		
		IF cAtm <> pIdProvCaja THEN
			LET cCodRet = '00881'; --EL FOLIO NO PERTENECE AL ATM SELECCIONADO, VERIFIQUE
			RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		END IF;
		
		RETURN cCodRet, cDescOperacion, cDescMotivo, mMonto, cTipoAfectacion;
		
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 17/10/2016',
'MODULO: ATMS',
'FUNCIONALIDAD: ELIMINACIÓN DE FALTANTES Y SOBRANTES', 
'DESCRIPCION: Spl que obtiene el detalle de la operación que se va efectuar.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_atms_consultadenosdoactual(pUsuario CHAR(8), pIdFuncion CHAR(10), pIdProvCaja CHAR(4), pIdEjecucion CHAR(1))
	RETURNING CHAR(5) AS codret, 
