CREATE PROCEDURE "informix".sp_atms_validafechas(pUsuario CHAR(8),pIdFuncion CHAR(10))
    RETURNING CHAR(5) AS codRet;
	  
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cEmpresa CHAR(3);
	DEFINE dFechaHoy DATE;
	DEFINE dFechaIni DATE;
	DEFINE dFechaFin DATE;
	DEFINE sHoraActual CHAR(12);
	DEFINE dFechaServer DATE;

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET dFechaHoy = '';
	LET dFechaIni = '';
	LET dFechaFin = '';
	LET sHoraActual = '';
	LET dFechaServer = '';

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_validafechas.out';
		--TRACE ON;
		
		IF  pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN  cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SELECT TO_CHAR(fecha_hoy,'%m/%d/%Y') AS fecha_hoy, TO_CHAR(pri_dia_mes,'%m/%d/%Y') AS fecha_ini, TO_CHAR(ult_dia_mes,'%m/%d/%Y') AS fecha_fin, TO_CHAR(CURRENT,'%r') AS hora_actual, TO_CHAR(CURRENT,'%m/%d/%Y') AS fecha_server
		INTO dFechaHoy, dFechaIni, dFechaFin, sHoraActual, dFechaServer
		FROM bdinteg:"informix".si_fechas
		WHERE empresa = cEmpresa;
		
		IF dFechaHoy <> dFechaServer THEN
			LET cCodRet = '00864';
		END IF;   
		
		RETURN cCodRet;
	END;
END PROCEDURE
