CREATE PROCEDURE "informix".sp_atms_validapasecontable(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaPase DATE)
    RETURNING CHAR(5) AS codRet,
		CHAR(1) AS hay_pasecontable;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iPaseContable INTEGER;
	DEFINE cHayPaseContable CHAR(1);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';
	LET iPaseContable = 0;
	LET cHayPaseContable = '';

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cHayPaseContable;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_validapasecontable.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFechaPase IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cHayPaseContable;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cHayPaseContable;
		END IF;
		
		SELECT COUNT(*) INTO iPaseContable
		FROM bdicont:"informix".co_poldet
		WHERE empresa = '001'
        AND fecha_captura = pFechaPase
        AND usuario = 'atms';
		
		IF NVL(iPaseContable,0) = 0 THEN
			LET cHayPaseContable = '0';
		ELIF NVL(iPaseContable,0) > 0 THEN
			LET cHayPaseContable = '1';
		END IF;
		
		RETURN cCodRet, cHayPaseContable;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA 25/10/2016',
'MODULO: ATMS',
