CREATE PROCEDURE "informix".sp_atms_verificastatuscat(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5) AS codret,
			  CHAR(1) AS status,
			  CHAR(30) AS desc_status; 
			  
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	DEFINE cIdStatus CHAR(1);
	DEFINE cDescStatus CHAR(30);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cIdStatus = '';
	LET cDescStatus = '';
	LET iNoRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = '00770'; --PROCESO CON ERRORES, POR FAVOR REINTENTE NUEVAMENTE
			RETURN cCodRet, cIdStatus, cDescStatus;	
		END EXCEPTION;
	 
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_verificastatuscat.out';
		--TRACE ON;
		
		---VALIDACION DE CAMPOS REQUERIDOS
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cIdStatus, cDescStatus;
		END IF;		
			
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cIdStatus, cDescStatus;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		SELECT {+AVOID_FULL("informix".sw_atm_statuscargacat)} id_status, desc_status
		INTO cIdStatus, cDescStatus
		FROM "informix".sw_atm_statuscargacat
		WHERE usuario_inserta = pUsuario;
		
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			RETURN cCodRet, 'I', 'INICIA_PROCESO';		
		ELSE 			
			RETURN cCodRet, cIdStatus, cDescStatus;	
		END IF;	
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 24/11/2016',
'MODULO: ATMS',
'FUNCIONALIDAD: SOLICITUD DE DOTACIÓN ATM A CAJA GENERAL',
'DESCRIPCION: SPL encargado de hacer el monitoreo para el llenado de los catálogos plaza y cajero.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_atms_procesarecepciondotaciones(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5) AS codret;
		
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cDivisa CHAR(2);
	DEFINE cHora CHAR(6);
	DEFINE cSecuencia CHAR(8);
	DEFINE cFolioSuc CHAR(16);
	
	DEFINE iId_registro INTEGER;
	DEFINE iNumReg INTEGER;
	DEFINE cCc CHAR(4);
	DEFINE cId_atm CHAR(6);
	DEFINE cNombre VARCHAR(200);
	DEFINE cPlaza VARCHAR(100);
	DEFINE cTipo_ope VARCHAR(25);
	DEFINE iB_500 INTEGER;
	DEFINE iB_200 INTEGER;
	DEFINE iB_100 INTEGER;
	DEFINE iB_50 INTEGER;
	DEFINE iB_20 INTEGER;
	DEFINE mTotal_b MONEY(18,2);	
	DEFINE cFolio CHAR(8);
	DEFINE cStatus VARCHAR(50);
	DEFINE iNoRegistros INTEGER; 
	
	DEFINE iId_registro_dup INTEGER;
	DEFINE cId CHAR(6);
	DEFINE mMonto_500 MONEY(16,2);
	DEFINE mMonto_200 MONEY(16,2);
	DEFINE mMonto_100 MONEY(16,2);
	DEFINE mMonto_50 MONEY(16,2);
	DEFINE mMonto_20 MONEY(16,2);
	DEFINE mTotalMonto MONEY(18,2);
	DEFINE cRegValidado CHAR(1);
	
	DEFINE cSucursal CHAR(4);
	DEFINE mMonto MONEY(14,2);
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cDivisa = '01';
	LET cHora = LPAD(CAST(SUBSTR(CURRENT,12,2) AS CHAR(2)),2,'0') ||
				LPAD(CAST(SUBSTR(CURRENT,15,2) AS CHAR(2)),2,'0') ||
				LPAD(CAST(SUBSTR(CURRENT,18,2) AS CHAR(2)),2,'0');
	LET cSecuencia = TRIM(cHora)||'00';
	LET cFolioSuc = TRIM(pUsuario)||TRIM(cSecuencia);
	
	LET iId_registro = 0;
	LET iNumReg = 0;
	LET cCc = '';
	LET cId_atm = '';
	LET cNombre = '';
	LET cPlaza = '';
	LET cTipo_ope = '';
	LET iB_500 = 0;
	LET iB_200 = 0;
	LET iB_100 = 0;
	LET iB_50 = 0;
	LET iB_20 = 0;
	LET mTotal_b = 0.00;
	LET cFolio = '';
	LET cStatus = '';
	LET iNoRegistros = 0;
	
	LET iId_registro_dup = 0;
	LET cId = '';
	LET mMonto_500 = 0.00;
	LET mMonto_200 = 0.00;
	LET mMonto_100 = 0.00;
	LET mMonto_50 = 0.00;
	LET mMonto_20 = 0.00;
	LET mTotalMonto = 0.00;
	LET cRegValidado = 'f';
	
	LET cSucursal = '';
	LET mMonto = 0.00;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_atms_procesarecepciondotaciones.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- SE LIMPIA TABLA
		DELETE FROM "informix".sw_atm_regduplicados WHERE usuario = pUsuario;
		
		-- SEÑALA DUPLICADOS
		UPDATE "informix".sw_atm_recepcionmasiva 
		SET duplicado = 't'--, status = 'OPERACIÓN DUPLICADA O REPETIDA'
		WHERE id_registro IN (SELECT id_registro FROM "informix".sw_atm_recepcionmasiva
							  WHERE usuario = pUsuario
							  AND TRIM(folio) IN(SELECT TRIM(folio)
							  				  FROM "informix".sw_atm_recepcionmasiva
							  				  WHERE usuario = pUsuario
							  				  GROUP BY 1
							  				  HAVING COUNT(*) > 1));
		
		FOREACH
			
			SELECT id_registro,cc,id_atm,nombre,plaza,tipo_ope,b_500,b_200,b_100,b_50,b_20,total_b,folio,status
			INTO iId_registro,cCc,cId_atm,cNombre,cPlaza,cTipo_ope,iB_500,iB_200,iB_100,iB_50,iB_20,mTotal_b,cFolio,cStatus
			FROM "informix".sw_atm_recepcionmasiva
			WHERE usuario = pUsuario
			AND procesado = 'f'
			--AND duplicado = 'f'
			ORDER BY id_registro ASC
			
			-- VALIDA CENTRO DE COSTOS
			SELECT id INTO cId FROM bdisuc:"informix".ss_relacionccid WHERE id = cId_atm;
			
			IF NVL(cId_atm,'') <> NVL(cId,'') THEN
				UPDATE "informix".sw_atm_recepcionmasiva SET status = 'EL ID DEL CAJERO AUTOMATICO NO CORRESPONDE AL CENTRO DE COSTOS', procesado = 't' WHERE id_registro = iId_registro;
			ELSE
				
				-- VALIDA MONTOS					
				LET mMonto_500 = 500 * NVL(iB_500,0);
				LET mMonto_200 = 200 * NVL(iB_200,0);
				LET mMonto_100 = 100 * NVL(iB_100,0);
				LET mMonto_50 = 50 * NVL(iB_50,0);
				LET mMonto_20 = 20 * NVL(iB_20,0);
				LET mTotalMonto = mMonto_500 + mMonto_200 + mMonto_100 + mMonto_50 + mMonto_20;
				
				IF NVL(mTotal_b,0) <> NVL(mTotalMonto,0) THEN
					UPDATE "informix".sw_atm_recepcionmasiva SET status = 'NO COINCIDE EL DESGLOSE CON EL MONTO', procesado = 't' WHERE id_registro = iId_registro;
				ELSE
					--UPDATE "informix".sw_atm_recepcionmasiva SET status = 'OPERACION EXITOSA', procesado = 't' WHERE id_registro = iId_registro;
					UPDATE "informix".sw_atm_recepcionmasiva SET status = '00000', procesado = 't' WHERE id_registro = iId_registro;
					
					-- EJECUCIÓN SPLs
					
				END IF;
			
			END IF;
			
			-- VALIDA REGISTROS DUPLICADOS
			FOREACH
				SELECT id_registro INTO iId_registro_dup
				FROM "informix".sw_atm_recepcionmasiva
				WHERE usuario = pUsuario 
				AND procesado = 'f' AND duplicado = 't'
				AND folio = cFolio AND id_registro > iId_registro
				ORDER BY id_registro ASC
				
				IF DBINFO('sqlca.sqlerrd2') <> 0 THEN
					INSERT INTO "informix".sw_atm_regduplicados(id_registro,usuario)
					VALUES(iId_registro_dup,pUsuario);					
				END IF;
				
			END FOREACH;
			
			LET iId_registro_dup = '';
			
		END FOREACH;
		
		-- ACTUALIZA REGISTROS DUPLICADOS
		FOREACH
			
			SELECT id_registro INTO iId_registro_dup
			FROM "informix".sw_atm_regduplicados WHERE usuario = pUsuario
			
			UPDATE "informix".sw_atm_recepcionmasiva SET status = 'OPERACION DUPLICADA O REPETIDA' WHERE id_registro = iId_registro_dup;
			
			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			END IF;
			
		END FOREACH;
		
		-- SE INICIALIZAN VARIABLES
		LET iId_registro = 0;
		LET cCc = '';
		LET cId_atm = '';
		LET cNombre = '';
		LET cPlaza = '';
		LET cTipo_ope = '';
		LET iB_500 = 0;
		LET iB_200 = 0;
		LET iB_100 = 0;
		LET iB_50 = 0;
		LET iB_20 = 0;
		LET mTotal_b = 0.00;
		LET cFolio = '';
		LET cStatus = '';
		
		-- CONTINÚAN LAS VALIDACIONES DE CC SIN DETALLE DE ERROR (status = 00000)
		FOREACH
			
			SELECT id_registro,cc,id_atm,nombre,plaza,tipo_ope,b_500,b_200,b_100,b_50,b_20,total_b,folio,status
			INTO iId_registro,cCc,cId_atm,cNombre,cPlaza,cTipo_ope,iB_500,iB_200,iB_100,iB_50,iB_20,mTotal_b,cFolio,cStatus
			FROM "informix".sw_atm_recepcionmasiva
			WHERE usuario = pUsuario
			AND procesado = 't'
			AND status = '00000'
			ORDER BY id_registro ASC
			
			-- 
			EXECUTE PROCEDURE bdisuc:"informix".sp_dotatm_2(cEmpresa,cFolio)
			INTO cCodRetSp,cSucursal,mMonto;
			
			IF cCodRetSp::INTEGER < 0 THEN 
				--RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_dotatm_2';
				UPDATE "informix".sw_atm_recepcionmasiva SET status = TRIM(cCodRetSp) ||' - ERROR EN LA EJECUCION DEL SP bdisuc:sp_dotatm_2' WHERE id_registro = iId_registro;
			ELIF cCodRetSp::INTEGER > 0 THEN 
				
				IF cCodRetSp::INTEGER = 100 THEN
					--LET cCodRet = '00878';
					LET cStatus = 'EL FOLIO DE LA DOTACION NO EXISTE';
				ELIF cCodRetSp::INTEGER = 104 THEN
					--LET cCodRet = '00879';
					LET cStatus = 'SOLICITUD NO AUTORIZADA';
				ELIF cCodRetSp::INTEGER = 107 THEN
					--LET cCodRet = '00880';
					LET cStatus = 'EL FOLIO APARECE COMO RECIBIDO';
				ELIF cCodRetSp::INTEGER = 110 THEN
					--LET cCodRet = '00003';
				ELIF cCodRetSp::INTEGER = 560 THEN 
					--LET cCodRet = '01129';
					LET cStatus = 'CODIGO O NATURALEZA DE TRANSACCION NO PERMITIDA';
				END IF;
				
				UPDATE "informix".sw_atm_recepcionmasiva SET status = cStatus WHERE id_registro = iId_registro;
				
			ELIF cCodRetSp::INTEGER = 0 THEN
				
				--			
				EXECUTE PROCEDURE bdisuc:"informix".sp_inserta_atm_2(cEmpresa,cCc,cDivisa,0,iB_500,iB_200,iB_100,iB_50,iB_20,mTotal_b)
				INTO cCodRetSp;
				
				IF cCodRetSp::INTEGER < 0 THEN 
					--RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_inserta_atm_2';
					UPDATE "informix".sw_atm_recepcionmasiva SET status = TRIM(cCodRetSp) ||' - ERROR EN LA EJECUCION DEL SP bdisuc:sp_inserta_atm_2' WHERE id_registro = iId_registro;
				ELIF cCodRetSp::INTEGER = 0 THEN
					
					--			
					EXECUTE PROCEDURE bdisuc:"informix".sp_recepdota_atm(cEmpresa,cCc,pUsuario,cFolioSuc,cFolio,'0037',cDivisa,
					CURRENT,mTotal_b,0,iB_500,iB_200,iB_100,iB_50,iB_20,0,0,0,0,0,0,0,0,0,'13')
					INTO cCodRetSp;
					
					IF cCodRetSp::INTEGER < 0 THEN 
						--RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdisuc:sp_recepdota_atm';
						UPDATE "informix".sw_atm_recepcionmasiva SET status = TRIM(cCodRetSp) ||' - ERROR EN LA EJECUCION DEL SP bdisuc:sp_recepdota_atm' WHERE id_registro = iId_registro;
					ELIF cCodRetSp::INTEGER > 0 THEN 
						
						IF cCodRetSp::INTEGER = 100 THEN
							--LET cCodRet = '00878';
							LET cStatus = 'EL FOLIO DE LA DOTACION NO EXISTE';
						ELIF cCodRetSp::INTEGER = 102 THEN
							--LET cCodRet = '00882';
							LET cStatus = 'EL MONTO DE LA DOTACION NO CORRESPONDE AL ENVIADO';
						ELIF cCodRetSp::INTEGER = 103 THEN
							--LET cCodRet = '00883';
							LET cStatus = 'EL FOLIO APARECE COMO CANCELADO';
						ELIF cCodRetSp::INTEGER = 104 THEN
							--LET cCodRet = '00879';
							LET cStatus = 'SOLICITUD NO AUTORIZADA';
						ELIF cCodRetSp::INTEGER = 107 THEN
							--LET cCodRet = '00884';
							LET cStatus = 'EL FOLIO APARECE COMO RECIBIDO';
						ELIF cCodRetSp::INTEGER = 110 THEN
							--LET cCodRet = '00003';
						END IF;
						
						UPDATE "informix".sw_atm_recepcionmasiva SET status = cStatus WHERE id_registro = iId_registro;
					
					ELIF cCodRetSp::INTEGER = 0 THEN
						UPDATE "informix".sw_atm_recepcionmasiva SET status = 'OPERACION EXITOSA' WHERE id_registro = iId_registro;
					END IF;
					
				END IF;
				
			END IF;
			

		END FOREACH;
		
		RETURN cCodRet;
		
	END;
END PROCEDURE 
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 29/08/2019',
'MODULO: ATM´s',
'FUNCIONALIDAD: RECEPCIÓN MASIVA DOTACIONES DE EFECTIVO DE CAJEROS AUTOMÁTICOS', 
