CREATE PROCEDURE "informix".sp_cg_consultamelbconcentraciones(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaConsulta CHAR(10), pTipOperacion CHAR(5), 
			pSucursal CHAR(8), pDireccionMac CHAR(12),pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(5) AS idbanco,
			CHAR(25) AS idsolicitud,
			CHAR(10) AS fechaaplicacion,
			CHAR(120) AS motivovisita,
			CHAR(16) AS foliocomprobante,
			DECIMAL(17,2) AS dicecontener,
			DECIMAL(17,2) AS realverificado,
			CHAR(3) AS tipodomicilio,
			CHAR(3) AS tipomovimiento,
			CHAR(1) AS urbfor,
			CHAR(16) AS estadotransito,
			CHAR(16) AS estadovisita,
			CHAR(10) AS estadoboveda,
			CHAR(10) AS estadoverificada,
			CHAR(10) AS estadootro,
			CHAR(8) AS sucursalbanco,
			CHAR(40) AS misc1,
			CHAR(40) AS misc2,
			CHAR(40) AS misc3,
			CHAR(40) AS misc4,
			CHAR(40) AS misc5;

	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE cIdbanco CHAR(5);
	DEFINE cIdSolicitud CHAR(25);
	DEFINE cFechaAplicacion CHAR(10);
	DEFINE cMotivoVisita CHAR(120);
	DEFINE cFolioComprobante CHAR(16);
	DEFINE dDiceContener DECIMAL(17,2);
	DEFINE dRealVerificado DECIMAL(17,2);
	DEFINE cTipoDomicilio CHAR(3);
	DEFINE cTipoMovimiento CHAR(3);
