	DEFINE cMisc2 CHAR(40);
	DEFINE cMisc3 CHAR(40);
	DEFINE cMisc4 CHAR(40);
	DEFINE cMisc5 CHAR(40);	

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	LET cIdbanco = '';
	LET cIdSolicitud = '';
	LET cFechaAplicacion = '';
	LET cMotivoVisita = '';
	LET cFolioComprobante = '';
	LET dDiceContener = 0.00;
	LET dRealVerificado = 0.00;
	LET cTipoDomicilio = '';
	LET cTipoMovimiento = '';
	LET cUrbFor = '';
	LET cEstadoTransito = '';
	LET cEstadoVisita = '';
	LET cEstadoBoveda = '';
	LET cEstadoVerificada = '';
	LET cEstadoOtro = '';
	LET cSucursalBanco = '';
	LET cMisc1 = '';
	LET cMisc2 = '';
	LET cMisc3 = '';
	LET cMisc4 = '';
	LET cMisc5 = '';

	BEGIN

	    ON EXCEPTION SET iSqlErr
	    	LET cCodRet = iSqlErr;
	    	RETURN cCodRet,cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
	    	       cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
	    END EXCEPTION;

		--SET DEBUG FILE TO '/tmp/mfinis/sp_cg_consultamelbconcentraciones.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR  pFechaConsulta = '' OR pTipOperacion = '' OR pDireccionMac = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
			       cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
				   cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		END IF;			
		
		IF pTipOperacion = 'TODAS' THEN
			FOREACH SELECT {+INDEX (bdisuc:ss_recibe_datosconcentracionws idx_ss_recibe_datosconcentracionws01)} SKIP pRegistros FIRST pRecuperacion id_banco,id_solicitud,fecha_aplicacion,motivo_visita,folio_comprobante,dice_contener,real_verificado,tipo_domicilio,tipo_movimiento,urb_for,
				estado_transito,estado_visita,estado_boveda,estado_verificada,estado_otro,sucursal_banco,misc1,misc2,misc3,misc4,misc5
			INTO cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
			     cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5
			FROM bdisuc:"informix".ss_recibe_datosconcentracionws
				WHERE fecha_aplicacion = pFechaConsulta				
				AND usuario = pUsuario
				AND direccion_mac = pDireccionMac
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet,cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
				   cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5 WITH RESUME;
			
		    END FOREACH;
		 				
		ELSE 	
			IF  pSucursal = '' THEN
				LET cCodRet = '00003';
				RETURN cCodRet,cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
			       cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
			END IF;
			
			FOREACH SELECT {+INDEX (bdisuc:ss_recibe_datosconcentracionws idx_ss_recibe_datosconcentracionws01)} SKIP pRegistros FIRST pRecuperacion id_banco,id_solicitud,fecha_aplicacion,motivo_visita,folio_comprobante,dice_contener,real_verificado,tipo_domicilio,tipo_movimiento,urb_for,
				estado_transito,estado_visita,estado_boveda,estado_verificada,estado_otro,sucursal_banco,misc1,misc2,misc3,misc4,misc5
			INTO cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
			     cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5
			FROM bdisuc:"informix".ss_recibe_datosconcentracionws
				WHERE fecha_aplicacion = pFechaConsulta
				AND tipo_domicilio = pTipOperacion			
				AND sucursal_banco = pSucursal
				AND usuario = pUsuario
				AND direccion_mac = pDireccionMac
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet,cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
				   cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5 WITH RESUME;
			
		    END FOREACH;
		
		END IF; 
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
			       cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet,cIdbanco,cIdSolicitud,cFechaAplicacion,cMotivoVisita,cFolioComprobante,dDiceContener,dRealVerificado,cTipoDomicilio,cTipoMovimiento,cUrbFor,
			       cEstadoTransito,cEstadoVisita,cEstadoBoveda,cEstadoVerificada,cEstadoOtro,cSucursalBanco,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		END IF;		

	END;
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil Cuachayo',
'FECHA: 02/04/2018',
'MODULO: CAJA GENERAL',
