CREATE PROCEDURE "informix".sp_cg_consultamelbdotaciones(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaConsulta CHAR(10), pTipOperacion CHAR(5), 
			pSucursal CHAR(8), pDireccionMac CHAR(12),pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(5) AS id_banco, 			
			CHAR(25) AS id_solicitud, 		
			CHAR(10) AS fecha_aplicacion, 	
			CHAR(120) AS motivo_cambio, 		
			CHAR(120) AS motivo_devolucion, 	
			CHAR(16) AS folio_comprobante, 	
			MONEY(17,2) AS monto_comprobante,
			CHAR(3) AS tipo_domicilio, 		
			CHAR(1) AS urb_for, 			
			CHAR(10) AS estado_rechazada, 	
			CHAR(10) AS estado_aprobada, 	
			CHAR(10) AS estado_preparada, 	
			CHAR(10) AS estado_boveda, 		
			CHAR(10) AS estado_transito, 		
			CHAR(16) AS estado_entregada_banco, 	
			CHAR(10) AS estado_devolucion, 		
			CHAR(10) AS estado_cerrada, 			
			CHAR(10) AS estado_cerrada_dev, 		
			CHAR(120) AS motivo_rechazo, 			
			CHAR(8) AS sucursal_banco, 			
			INTEGER AS billete_1, 				
			INTEGER AS billete_2, 				
			INTEGER AS billete_5, 				
			INTEGER AS billete_10, 				
			INTEGER AS billete_20, 				
			INTEGER AS billete_50, 				
			INTEGER AS billete_100, 			
			INTEGER AS billete_200, 			
			INTEGER AS billete_500, 			
			INTEGER AS billete_1000, 			
			INTEGER AS moneda_001, 				
			INTEGER AS moneda_005, 				
			INTEGER AS moneda_010, 				
			INTEGER AS moneda_020, 				
			INTEGER AS moneda_025, 				
			INTEGER AS moneda_050, 				
			INTEGER AS moneda_1, 				
			INTEGER AS moneda_2, 				
			INTEGER AS moneda_5, 				
			INTEGER AS moneda_10, 				
			INTEGER AS moneda_20, 				
			INTEGER AS moneda_50, 				
			INTEGER AS moneda_100, 				
			CHAR(40) AS misc1, 					
			CHAR(40) AS misc2, 					
			CHAR(40) AS misc3, 					
			CHAR(40) AS misc4, 					
			CHAR(40) AS misc5;
		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE cIdBanco CHAR(5);
	DEFINE cIdSol CHAR(25);
	DEFINE cFechAplica CHAR(10);
	DEFINE cMtvoCambio CHAR(120);
	DEFINE cMtvoDev CHAR(120);
	DEFINE cFolioComp CHAR(16);
	DEFINE dMntoComp MONEY(17,2);
	DEFINE cTipoDomi CHAR(3);
	DEFINE cUrbFor CHAR(1);
	DEFINE cEdoRechazada CHAR(10);
	DEFINE cEdoAprobada CHAR(10);
	DEFINE cEdoPreparada CHAR(10);
	DEFINE cEdoBoveda CHAR(10);
	DEFINE cEdoTransito CHAR(10);
	DEFINE cEdoEntreBanco CHAR(16);
	DEFINE cEdoDevolucion CHAR(10);
	DEFINE cEdoCerrada CHAR(10);
	DEFINE cEdoCerradaDev CHAR(10);
	DEFINE cMtvoRechazo CHAR(120);
	DEFINE cSucBanco CHAR(8);
	DEFINE dBill1 INTEGER;
	DEFINE dBill2 INTEGER;
	DEFINE dBill5 INTEGER;
	DEFINE dBill10 INTEGER;
	DEFINE dBill20 INTEGER;
	DEFINE dBill50 INTEGER;
	DEFINE dBill100 INTEGER;
	DEFINE dBill200 INTEGER;
	DEFINE dBill500 INTEGER;
	DEFINE dBill1000 INTEGER;
	DEFINE dMon001 INTEGER;
	DEFINE dMon005 INTEGER;
	DEFINE dMon010 INTEGER;
	DEFINE dMon020 INTEGER;
	DEFINE dMon025 INTEGER;
	DEFINE dMon050 INTEGER;
	DEFINE dMon1 INTEGER;
	DEFINE dMon2 INTEGER;
	DEFINE dMon5 INTEGER;
	DEFINE dMon10 INTEGER;
	DEFINE dMon20 INTEGER;
	DEFINE dMon50 INTEGER;
	DEFINE dMon100 INTEGER;
	DEFINE cMisc1 CHAR(40);
	DEFINE cMisc2 CHAR(40);
	DEFINE cMisc3 CHAR(40);
	DEFINE cMisc4 CHAR(40);
	DEFINE cMisc5 CHAR(40);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	LET cIdBanco = '';
	LET cIdSol = '';
	LET cFechAplica = '';
	LET cMtvoCambio = '';
	LET cMtvoDev = '';
	LET cFolioComp = '';
	LET dMntoComp = 0;
	LET cTipoDomi = '';
	LET cUrbFor = '';
	LET cEdoRechazada = '';
	LET cEdoAprobada = '';
	LET cEdoPreparada = '';
	LET cEdoBoveda = '';
	LET cEdoTransito = '';
	LET cEdoEntreBanco = '';
	LET cEdoDevolucion = '';
	LET cEdoCerrada = '';
	LET cEdoCerradaDev = '';
	LET cMtvoRechazo = '';
	LET cSucBanco = '';
	LET dBill1 = 0;
	LET dBill2 = 0;
	LET dBill5 = 0;
	LET dBill10 = 0;
	LET dBill20 = 0;
	LET dBill50 = 0;
	LET dBill100 = 0;
	LET dBill200 = 0;
	LET dBill500 = 0;
	LET dBill1000 = 0;
	LET dMon001 = 0;
	LET dMon005 = 0;
	LET dMon010 = 0;
	LET dMon020 = 0;
	LET dMon025 = 0;
	LET dMon050 = 0;
	LET dMon1 = 0;
	LET dMon2 = 0;
	LET dMon5 = 0;
	LET dMon10 = 0;
	LET dMon20 = 0;
	LET dMon50 = 0;
	LET dMon100 = 0;
	LET cMisc1 = '';
	LET cMisc2 = '';
	LET cMisc3 = '';
	LET cMisc4 = '';
	LET cMisc5 = '';

	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		END EXCEPTION;

		--SET DEBUG FILE TO '/tmp/mfinis/sp_cg_consultamelbdotaciones.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR  pFechaConsulta = '' OR pTipOperacion = '' OR pDireccionMac = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		END IF;			
		
		IF pTipOperacion = 'TODAS' THEN
			FOREACH SELECT {+INDEX (bdisuc:ss_recibe_datosdotacionws idx_ss_recibe_datosdotacionws01)} SKIP pRegistros FIRST pRecuperacion id_banco,id_solicitud,fecha_aplicacion,motivo_cambio,motivo_devolucion,folio_comprobante,monto_comprobante,
				tipo_domicilio,urb_for,estado_rechazada,estado_aprobada,estado_preparada,estado_boveda,estado_transito,estado_entregada_banco,estado_devolucion,estado_cerrada,
				estado_cerrada_dev,motivo_rechazo,sucursal_banco,billete_1,billete_2,billete_5,billete_10,billete_20,billete_50,billete_100,billete_200,billete_500,billete_1000,
				moneda_001,moneda_005,moneda_010,moneda_020,moneda_025,moneda_050,moneda_1,moneda_2,moneda_5,moneda_10,moneda_20,moneda_50,moneda_100,misc1,misc2,misc3,misc4,misc5			
			INTO cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5
			FROM bdisuc:"informix".ss_recibe_datosdotacionws
				WHERE fecha_aplicacion = pFechaConsulta				
				AND usuario = pUsuario
				AND direccion_mac = pDireccionMac
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet,cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5 WITH RESUME;
			
		    END FOREACH;
		 				
		ELSE 	
			
			IF pSucursal = '' THEN
			LET cCodRet = '00003';
				RETURN cCodRet,cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
					cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
					dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
			END IF;
			
			FOREACH SELECT {+INDEX (bdisuc:ss_recibe_datosdotacionws idx_ss_recibe_datosdotacionws01)} SKIP pRegistros FIRST pRecuperacion id_banco,id_solicitud,fecha_aplicacion,motivo_cambio,motivo_devolucion,folio_comprobante,monto_comprobante,
				tipo_domicilio,urb_for,estado_rechazada,estado_aprobada,estado_preparada,estado_boveda,estado_transito,estado_entregada_banco,estado_devolucion,estado_cerrada,
				estado_cerrada_dev,motivo_rechazo,sucursal_banco,billete_1,billete_2,billete_5,billete_10,billete_20,billete_50,billete_100,billete_200,billete_500,billete_1000,
				moneda_001,moneda_005,moneda_010,moneda_020,moneda_025,moneda_050,moneda_1,moneda_2,moneda_5,moneda_10,moneda_20,moneda_50,moneda_100,misc1,misc2,misc3,misc4,misc5			
			INTO cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5
			FROM bdisuc:"informix".ss_recibe_datosdotacionws
				WHERE fecha_aplicacion = pFechaConsulta
				AND tipo_domicilio = pTipOperacion			
				AND sucursal_banco = pSucursal
				AND usuario = pUsuario
				AND direccion_mac = pDireccionMac
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet,cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5 WITH RESUME;
			
		    END FOREACH;
		
		END IF; 
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet,cIdBanco,cIdSol,cFechAplica,cMtvoCambio,cMtvoDev,cFolioComp,dMntoComp,cTipoDomi,cUrbFor,cEdoRechazada,cEdoAprobada,cEdoPreparada,cEdoBoveda,cEdoTransito,
				cEdoEntreBanco,cEdoDevolucion,cEdoCerrada,cEdoCerradaDev,cMtvoRechazo,cSucBanco,dBill1,dBill2,dBill5,dBill10,dBill20,dBill50,dBill100,dBill200,dBill500,
				dBill1000,dMon001,dMon005,dMon010,dMon020,dMon025,dMon050,dMon1,dMon2,dMon5,dMon10,dMon20,dMon50,dMon100,cMisc1,cMisc2,cMisc3,cMisc4,cMisc5;
		END IF;		

	END;
END PROCEDURE
