CREATE PROCEDURE "informix".sp_con_validadiainhabil(pUsuario CHAR(8), pIdFuncion CHAR(10), pDiaInhabil DATE)
    RETURNING CHAR(5) AS codRet;
		
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cEmpresa CHAR(3);
	DEFINE dFecha DATE;

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET dFecha = '';

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
--		SET DEBUG FILE TO '/tmp/mfinis/sp_con_validadiainhabil.out';
--		TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pDiaInhabil IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;	
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT sf.fecha
		INTO dFecha
		FROM  bdinteg:"informix".si_feriado sf
		INNER JOIN bdinteg:"informix".si_feriado_banca sfb ON sf.fecha = sfb.fecha
		WHERE sf.empresa = cEmpresa
		AND sf.fecha = pDiaInhabil;
		
		IF DBINFO('sqlca.sqlerrd2') > 0 THEN
			LET cCodRet = '01139'; -- EL DIA INHABIL YA EXISTE, VERIFIQUE
			RETURN cCodRet;
		END IF;
		
		RETURN cCodRet;
		
	END;
END PROCEDURE
