CREATE PROCEDURE "informix".sp_sw_validacoordinadorgerente(pUsuario CHAR(8), pIdFuncion CHAR(10), pIdUsuarioValidar CHAR(8))
    RETURNING CHAR(5) AS codRet;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cEmpresa CHAR(3);
	DEFINE cUsuario CHAR(8);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cUsuario = '';

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
--		SET DEBUG FILE TO '/tmp/mfinis/sp_sw_validacoordinadorgerente.out';
--		TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pIdUsuarioValidar = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT id_usuario
		INTO cUsuario
		FROM "informix".sw_seg_puesto_usuarios
		WHERE id_usuario = pIdUsuarioValidar;
		
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN
			LET cCodRet = '01140'; -- EL USUARIO NO ES VALIDO PARA AUTORIZAR LA OPERACION. VERIFIQUE
			RETURN cCodRet;
		END IF;
		
		RETURN cCodRet;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Rodolfo Conde Flores',
'FECHA: 12/11/2019',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: Mantenimiento a dias Inhabiles', 
