CREATE PROCEDURE "informix".sp_con_altamoddiasinhabiles(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipoOperacion CHAR(1), pFechaDiaInhOrigen DATE, pDescripcion CHAR(30),
 pFechaDiaInh DATE,	pFechaProxDiaLab DATE, pDiaLab CHAR(1), pDiaLabBanca CHAR(1))
    RETURNING CHAR(5) AS codRet;
		
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cEmpresa CHAR(3);
	DEFINE cPais CHAR(3);
	DEFINE cDescripcion CHAR(30);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cPais = '001';
	LET cDescripcion = '';

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
--		SET DEBUG FILE TO '/tmp/mfinis/sp_con_altamoddiasinhabiles.out';
--		TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pTipoOperacion = '' OR pDescripcion = '' OR
 		   pFechaDiaInh IS NULL OR pFechaProxDiaLab IS NULL OR pDiaLab = '' OR pDiaLabBanca = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO dirty READ;
		SET LOCK MODE TO WAIT 3;
			
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;	
		
		LET cDescripcion = REPLACE(UPPER(pDescripcion),'ñ' ,'Ñ');
		
		IF pTipoOperacion = '1' THEN  --ALTA		
			
			INSERT INTO bdinteg:"informix".si_feriado(empresa, pais, fecha, descripcion, laborable, user_insert, fecha_insert) 
			VALUES(cEmpresa, cPais, pFechaDiaInh, cDescripcion, pDiaLab, pUsuario, CURRENT);
			
			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
				LET cCodRet = '00282';
				RETURN cCodRet;
			END IF;
				
			INSERT INTO bdinteg:"informix".si_feriado_banca(empresa, pais, fecha, fecha_prox, descripcion, laborable, user_insert, fecha_insert) 
			VALUES(cEmpresa, cPais, pFechaDiaInh, pFechaProxDiaLab, cDescripcion, pDiaLabBanca, pUsuario, CURRENT);
			
			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
				LET cCodRet = '00282';
				RETURN cCodRet;
			END IF;
				
		ELIF pTipoOperacion = '2' THEN --MODIFICACION
		
			IF pFechaDiaInhOrigen IS NULL THEN
				LET cCodRet = '00003';
				RETURN cCodRet;
			END IF;
					
			UPDATE bdinteg:"informix".si_feriado
			SET	descripcion = cDescripcion,
			fecha = pFechaDiaInh,
			laborable = pDiaLab
			WHERE fecha = pFechaDiaInhOrigen;
			
			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
				LET cCodRet = '00283';
				RETURN cCodRet;
			END IF;
			
			UPDATE bdinteg:"informix".si_feriado_banca
			SET	descripcion = cDescripcion,
			fecha = pFechaDiaInh,
			fecha_prox = pFechaProxDiaLab,
			laborable = pDiaLabBanca
			WHERE fecha = pFechaDiaInhOrigen;
			
			IF DBINFO('sqlca.sqlerrd2') = 0 THEN
				LET cCodRet = '00283';
				RETURN cCodRet;
			END IF;
			
		END IF;
				
		RETURN cCodRet;
	
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Rodolfo Conde Flores',
'FECHA: 11/11/2019',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: Mantenimiento a dias Inhabiles', 
'DESCRIPCION: Spl encargado de insertar/actualizar dias inhabiles de si_feriado y si_feriado_banca.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_con_diasinhabiles(pUsuario CHAR(8), pIdFuncion CHAR(10))
    RETURNING CHAR(5) AS codRet,
		CHAR(30) AS descripcion,
		DATE AS fecha_dia_inhabil,
		DATE AS fecha_prox_laborable,
		CHAR(1) AS laborable,
		CHAR(1) AS laborable_banca;
		
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cEmpresa CHAR(3);
	DEFINE cDescripcion CHAR(30);
	DEFINE dFechaDiaInhabil DATE;
	DEFINE dFechaProxLaborable DATE;
	DEFINE cLaborable CHAR(1);
	DEFINE cLaborableBanca CHAR(1);
	DEFINE iRecuperacion INTEGER;

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cDescripcion = '';
	LET dFechaDiaInhabil = '';
	LET dFechaProxLaborable = '';
	LET cLaborable = '';
	LET cLaborableBanca = '';
	LET iRecuperacion = 0;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cDescripcion, dFechaDiaInhabil, dFechaProxLaborable, cLaborable, cLaborableBanca;
			END IF;
		END EXCEPTION;
		
--		SET DEBUG FILE TO '/tmp/mfinis/sp_con_diasinhabiles.out';
--		TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cDescripcion, dFechaDiaInhabil, dFechaProxLaborable, cLaborable, cLaborableBanca;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cDescripcion, dFechaDiaInhabil, dFechaProxLaborable, cLaborable, cLaborableBanca;
		END IF;	
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT sf.descripcion, sf.fecha, sfb.fecha_prox, sf.laborable, sfb.laborable 
			INTO cDescripcion, dFechaDiaInhabil, dFechaProxLaborable, cLaborable, cLaborableBanca
			FROM  bdinteg:"informix".si_feriado sf
			INNER JOIN bdinteg:"informix".si_feriado_banca sfb ON sf.fecha = sfb.fecha
			WHERE sf.empresa = cEmpresa
			AND (YEAR(sf.fecha) = YEAR(TODAY) OR YEAR(sf.fecha) = YEAR(TODAY)+1 )
			ORDER BY sf.fecha
			
			LET iRecuperacion = iRecuperacion + 1;
			
			RETURN cCodRet, cDescripcion, dFechaDiaInhabil, dFechaProxLaborable, cLaborable, cLaborableBanca WITH RESUME;
			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '01136'; -- NO EXISTE INFORMACION DE DIAS INHABILES
			RETURN cCodRet, cDescripcion, dFechaDiaInhabil, dFechaProxLaborable, cLaborable, cLaborableBanca;
		END IF;
	
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Rodolfo Conde Flores',
'FECHA: 11/11/2019',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: Mantenimiento a dias Inhabiles', 
'DESCRIPCION: Spl encargado de consultar dias inhabiles de si_feriado y si_feriado_banca.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_guardacambiosdatosgeneralespm(pUsuario CHAR(8), pIdFuncion CHAR(10), pNumCliente CHAR(20))
		
		RETURNING CHAR(5) AS codret;
		 
		DEFINE cCodRet CHAR(5);
        DEFINE cCodRetSp CHAR(6);
		DEFINE iCodRetSp INTEGER;
        DEFINE iSqlErr INTEGER;
		DEFINE iTotalReg INTEGER;
		
		LET cCodRet = '00000';
        LET cCodRetSp = '';
		LET iCodRetSp = 0;
        LET iSqlErr = 0;
		LET iTotalReg = 0;
		
		BEGIN
		
			ON EXCEPTION SET iSqlErr
                LET cCodRet = iSqlErr;
                RETURN cCodRet;
			END EXCEPTION;
            
            --SET DEBUG FILE TO '/tmp/mfinis/sp_guardacambiosdatosgeneralespm.out';
            --TRACE ON;
            
            IF pUsuario = '' OR pIdFuncion = '' OR pNumCliente = '' THEN
				LET cCodRet = '00003';
				RETURN cCodRet;
            END IF;
            
            -- VALIDACION DE ACCESO A LA FUNCIONALIDAD
            EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
            IF cCodRet <> '00000' THEN
				RETURN cCodRet;
			END IF;
		
			SET ISOLATION TO DIRTY READ;
			SET LOCK MODE TO WAIT 3;
			
			INSERT INTO bdicnweb:"informix".sw_si_cliente(
			fecha_modificacion,us_modificacion,empresa,numcte,status_cte,sucursal,ejecutivo,tpo_persona,tipo_cliente,apell_paterno,apell_materno,
			nombre1,nombre2,razon_social,rfc,sector,segmento,actividad_princ,grupo,subgrupo,residencia,fecha_alta,
			apell_casada,distrito,numcte_ref,string1,string2,numeric1,numeric2,money1,date1,puesto_ppes,familiar_ppes,
			actividad_esp,ejecut_autoriza,user_insert,fecha_insert,rfc_alterno,tpo_biometria,cliente_pros)
			SELECT CURRENT, pUsuario, empresa,numcte,status_cte,sucursal,ejecutivo,tpo_persona,tipo_cliente,apell_paterno,apell_materno,
			nombre1,nombre2,razon_social,rfc,sector,segmento,actividad_princ,grupo,subgrupo,residencia,fecha_alta,
			apell_casada,distrito,numcte_ref,string1,string2,numeric1,numeric2,money1,date1,puesto_ppes,familiar_ppes,
			actividad_esp,ejecut_autoriza,user_insert,fecha_insert,rfc_alterno,tpo_biometria,cliente_pros
			FROM bdinteg:"informix".si_cliente
			WHERE numcte = pNumCliente;
			
			INSERT INTO bdicnweb:"informix".sw_si_ctepm(
			fecha_modificacion,us_modificacion,empresa,numcte,nombre_comercial,nombre_titular,giro,fecha_inscrip,fecha_constitct,regpub_comer,
			no_inscripcion,oficina,num_ofi,tomo,protocolo,num_trimestre,fecha_trimestre,sucursal,operador,
			fecha_alta,nacionalidad,nombre_corto,nombre_contacto,telefono_contacto,sufijo,actividadsocial,
			pagina_internet,user_insert,fecha_insert,escritura_constitutiva,nombre_notarioct,numero_notarioct,
			ciudad_notarioct,numero_foliomercantilct,ciudad_foliomercantilct,escritura_poderes,nombre_notariopd,
			numero_notariopd,ciudad_notariopd,fecha_inscrippd,fecha_escritpd,numero_foliomercantilpd,
			ciudad_foliomercantilpd,nombre_sociedad,sat_fea,emailpm,tipo_poder,doc_constitucion,tipo_org,tipo_admon)
			SELECT CURRENT, pUsuario, empresa,numcte,nombre_comercial,nombre_titular,giro,fecha_inscrip,fecha_constitct,regpub_comer,
			no_inscripcion,oficina,num_ofi,tomo,protocolo,num_trimestre,fecha_trimestre,sucursal,operador,
			fecha_alta,nacionalidad,nombre_corto,nombre_contacto,telefono_contacto,sufijo,actividadsocial,
			pagina_internet,user_insert,fecha_insert,escritura_constitutiva,nombre_notarioct,numero_notarioct,
			ciudad_notarioct,numero_foliomercantilct,ciudad_foliomercantilct,escritura_poderes,nombre_notariopd,
			numero_notariopd,ciudad_notariopd,fecha_inscrippd,fecha_escritpd,numero_foliomercantilpd,
			ciudad_foliomercantilpd,nombre_sociedad,sat_fea,emailpm,tipo_poder,doc_constitucion,tipo_org,tipo_admon
			FROM bdinteg:"informix".si_ctepm
			WHERE numcte = pNumCliente;
			
			
			SELECT {+ INDEX(bdinteg:si_apoderado "informix".idx_si_apoderado)} COUNT(*) AS TOTAL 
			INTO iTotalReg
			FROM bdinteg:"informix".si_apoderado 
			WHERE numcte = pNumCliente;
			
			IF iTotalReg > 0 THEN
			
				INSERT INTO bdicnweb:"informix".sw_si_apoderado(
				fecha_modificacion,us_modificacion,empresa,numcte,secuencia,numcteapoderado,
				nombreapoderado,user_insert,fecha_insert)			
				SELECT {+ INDEX(bdinteg:si_apoderado "informix".idx_si_apoderado)} CURRENT, pUsuario,empresa,numcte,secuencia,numcteapoderado,
				nombreapoderado,user_insert,fecha_insert
				FROM bdinteg:"informix".si_apoderado
				WHERE numcte = pNumCliente;
		
				IF DBINFO('sqlca.sqlerrd2') = 0 THEN
					LET cCodRet = '00236';
					RETURN cCodRet;
				END IF;
			
			END IF;
			
			RETURN cCodRet;
		
		END;
	
END PROCEDURE 
