CREATE PROCEDURE "informix".sp_con_consultaltas_idbox_reporte(pUsuario CHAR(8), pIdFuncion CHAR(10), pRegistros INTEGER, pRecuperacion INTEGER)	
RETURNING 		CHAR(5) AS codret;
				
				
		DEFINE cCodRet CHAR(5);
		DEFINE iSqlErr INTEGER;
		DEFINE cSucursal CHAR(5);
		DEFINE iAltasTotal INTEGER;
		DEFINE iTotIdb INTEGER;
		DEFINE iNoRegistros INTEGER;
		DEFINE porciento_sin_idb NUMERIC;
		DEFINE porciento_idb NUMERIC;
		DEFINE iResultadoTotSnIdb 	INTEGER;
		DEFINE dFechaActual DATE;
	    DEFINE iAnioActual INTEGER;
	    DEFINE iAnioIngreso INTEGER;
		DEFINE pFecIni DATE;
		DEFINE pFecFin DATE;
		DEFINE vcodret				char(5);	
		DEFINE vsqlerr				integer;
	
	--Variable para ejecuciÃÂ³n de comandos
		DEFINE vsql	        		char(3000);

		Let vsql='';
		let vcodret = "";
		let vsqlerr = 0;
	    LET dFechaActual = '';
	    LET iAnioActual=0;
	    LET iAnioIngreso=0;
		LET cCodRet = '00000';
		LET iSqlErr = 0;
		LET cSucursal = '';
		LET iAltasTotal = 0;
		LET iTotIdb = 0;
		LET iNoRegistros = 0;	
		LET porciento_sin_idb = 0.00;
		LET porciento_idb = 0.00;	
		LET pFecIni = '';
		LET pFecFin = '';
		LET iResultadoTotSnIdb = 0;
		
		
	BEGIN	
			ON EXCEPTION SET iSqlErr
					LET cCodRet = iSqlErr;
					RETURN cCodRet;
			END EXCEPTION;	
	
--SET DEBUG FILE TO '/tmp/masv/sp_con_consultaltas_idbox.out';
--TRACE ON;
			SET LOCK MODE TO WAIT 3;
			SET ISOLATION TO DIRTY READ;
            ----- VALIDACION DE QUE ESTA USANDO EL ANIO EN CURSO(NO SE PUEDE USAR OTRO ANIO)
	            SELECT fecha_hoy INTO dFechaActual  FROM bdinteg:"informix".si_fechas;
				IF (dFechaActual - pFecIni) > 366 THEN 
				LET cCodRet= '00996';
	            RETURN cCodRet;
                
	            END IF;
------------ 
			SELECT pri_dia_mes, ult_dia_mes INTO pFecIni, pFecFin FROM bdinteg:"informix".si_fechas;
			
			DELETE FROM bdinteg:"informix".si_indicadores_idbox_reporte;
			
			IF pUsuario = '' OR pIdFuncion = '' OR pFecIni IS NULL OR pFecFin IS NULL OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
					LET cCodRet = '00003';
					RETURN cCodRet;
			END IF;		
			-- VALIDACION DE LA PAGINACION
			IF pRegistros < 0 OR pRecuperacion < 0 THEN
					LET cCodRet = '00098';
					RETURN cCodRet;
			END IF;		
			-- VALIDACION DE ACCESO A LA FUNCIONALIDAD		
			EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
			IF cCodRet <> '00000' THEN
					RETURN cCodRet;
			END IF;
            
			SELECT SUM(altas_total), SUM(total_idb)
			INTO iAltasTotal,iTotIdb
			FROM bdinteg:"informix".si_indicadores_idbox
			WHERE fecha_proceso BETWEEN pFecIni AND pFecFin;
			
					
			LET iResultadoTotSnIdb = (iAltasTotal - iTotIdb );
			LET porciento_sin_idb = (iResultadoTotSnIdb / iAltasTotal ) * 100;
			LET porciento_idb = (iTotIdb / iAltasTotal ) * 100;
				
			FOREACH 
					SELECT SKIP pRegistros FIRST pRecuperacion  sucursal,SUM(altas_total),SUM(total_idb)
					INTO cSucursal,iAltasTotal,iTotIdb
					FROM bdinteg:"informix".si_indicadores_idbox
					WHERE fecha_proceso BETWEEN pFecIni AND pFecFin
					GROUP BY 1
					ORDER BY 1
		
					LET iNoRegistros = iNoRegistros + 1;
					
					LET iResultadoTotSnIdb = (iAltasTotal - iTotIdb );
					
					IF iResultadoTotSnIdb = 0  THEN
					LET porciento_sin_idb = 0;
					ELSE
					LET porciento_sin_idb = (iResultadoTotSnIdb / iAltasTotal ) * 100;
					END IF;
					IF iTotIdb = 0  THEN 
					LET porciento_idb = 0;
					ELSE
					LET porciento_idb = (iTotIdb / iAltasTotal ) * 100;
					END IF;
					INSERT INTO bdinteg:"informix".si_indicadores_idbox_reporte (codret, sucursal, total_sn_idb, total_idb, altas_total, porc_total_sn_idb, porc_total_idb)
					VALUES (cCodRet, cSucursal,iResultadoTotSnIdb,  iTotIdb, iAltasTotal, porciento_sin_idb, porciento_idb);
					
					--RETURN cCodRet;	
			END FOREACH;

			IF iNoRegistros = 0 AND pRegistros = 0 THEN			
					LET cCodRet = '00017';
					RETURN cCodRet;
			ELIF iNoRegistros = 0 AND pRegistros > 0 THEN 
					LET cCodRet = '1001';		
					RETURN cCodRet;
			END IF;	
								
	--generacion de reporte 
		let vsql = ' echo "cCodRet|cSucursal|iResultadoTotSnIdb|iTotIdb|iAltasTotal|porciento_sin_idb|porciento_idb">/RESPALDOSNEW/rep_idbox_mensual.xls';
		system vsql;
		let vsql=  'echo "UNLOAD TO /RESPALDOSNEW/TmpIDBox.xls '||
		'SELECT codret, sucursal, total_sn_idb, total_idb, altas_total, porc_total_sn_idb, porc_total_idb '|| 
		'FROM bdinteg:"informix".si_indicadores_idbox_reporte order by sucursal;">/RESPALDOSNEW/rpt_idbox.sql';
		system vsql;
		let vsql= 'dbaccess bdinteg /RESPALDOSNEW/rpt_idbox.sql';
		system vsql;
		let vsql ='rm  /RESPALDOSNEW/rpt_idbox.sql';
		system vsql;
		let vsql = "sed 's/|$//g' /RESPALDOSNEW/TmpIDBox.xls >>/RESPALDOSNEW/rep_idbox_mensual.xls";
		system vsql;
		let vsql ='rm  /RESPALDOSNEW/TmpIDBox.xls';
		system vsql; 
		
		let vcodret = '00000';					
		
		RETURN cCodRet;		
								
	END;
END PROCEDURE
DOCUMENT 
'FECHA: 16/01/2020',
'MODULO: Consultas ',
'FUNCIONALIDAD: Reporte Procesos Sucursal',
'DESCRIPCION: SP que genera reporte de altas idbox de Reporte Procesos Sucursal',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_genreporteconsultatrimestralmc(pUsuario CHAR(8), pIdFuncion CHAR(10),pBandera CHAR(2), pNumProducto SMALLINT, pTrimestre SMALLINT, pFechaInicio DATE, pFechaFin DATE, pIdPoducto CHAR (3), pTipoCompras CHAR (60), pTipoTransaccion CHAR (60), pTipoDevolucion CHAR(60), pTipoCuenta CHAR (30), pIdTipo CHAR (1), pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
		SMALLINT AS 	id_reporte,
		INTEGER			AS total_compras,
		MONEY (18,2)	AS monto_compras,
		INTEGER			AS total_transacciones,
		MONEY (18,2)	AS monto_transacciones,
		INTEGER			AS total_devolucion, 
		MONEY (18,2)	AS monto_devolucion,
		INTEGER AS total_cuenta,
		CHAR(16) AS total_cmpras,
		CHAR(16) AS total_transac,
		CHAR(16) AS total_dev,
		CHAR(16) AS total_ctas;
		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iCodRetSp INTEGER;
	DEFINE sIdReporte SMALLINT;
	DEFINE iTotalCompras	INTEGER;
	DEFINE mMontoCompras	MONEY (18,2);
	DEFINE iTotalTransacciones	INTEGER;
	DEFINE mMontoTransacciones	MONEY (18,2);
	DEFINE iTotalDevolucion	INTEGER;
	DEFINE mMontoDevolucion	MONEY (18,2);
	DEFINE iTotalCuenta INTEGER;
	DEFINE cTotalCmprs	 CHAR(16);
	DEFINE cTotalTransac CHAR(16);	
	DEFINE cTotalDev     CHAR(16);
	DEFINE cTotalCta	 CHAR(16);
	DEFINE cTotalCta_Ab CHAR(16);
	DEFINE cTotalCta_Cr CHAR(16);
	DEFINE iNoRegistros INTEGER;
	DEFINE iSuma_cuentas_A INTEGER;
	DEFINE iSuma_cuentas_B INTEGER;

			
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iCodRetSp = 0;
	LET sIdReporte = 0;
	LET iTotalCompras	= 0 ;
	LET mMontoCompras	= 0.0;
	LET iTotalTransacciones	= 0 ;
	LET mMontoTransacciones	= 0.0;
	LET iTotalDevolucion	= 0 ;
	LET mMontoDevolucion	= 0.0;
	LET iTotalCuenta = 0;
	LET cTotalCmprs		= '';
	LET cTotalTransac  	= '';
	LET cTotalDev    	= '';
	LET cTotalCta		= '';
	LET iNoRegistros = 0;
	LET iSuma_cuentas_A=0;
	LET iSuma_cuentas_B=0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_genreporteconsultatrimestralmc.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pBandera = '' OR pNumProducto IS NULL OR pTrimestre IS NULL OR   pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta;
		END IF;
	
	SET ISOLATION TO DIRTY READ;
	SET LOCK MODE TO WAIT 3;
	

	-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:'informix'.sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta;
		END IF;
			IF pBandera = '1' THEN		
				FOREACH SELECT total_compras, monto_compras, id_reporte
						INTO iTotalCompras, mMontoCompras, sIdReporte
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col = pIdPoducto
							AND tipo_compras = pTipoCompras				
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '2' THEN		
				
				FOREACH SELECT total_transacciones, monto_transacciones, id_reporte
						INTO iTotalTransacciones,mMontoTransacciones, sIdReporte
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col = pIdPoducto
							AND tipo_transaccion  = pTipoTransaccion					
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				
				END FOREACH;	
				
				
				
			ELIF pBandera = '3' THEN		
				FOREACH SELECT total_transacciones, monto_transacciones, id_reporte
						INTO iTotalTransacciones,mMontoTransacciones, sIdReporte
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col = pIdPoducto
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '4' THEN		
				FOREACH SELECT  total_devolucion, monto_devolucion, id_reporte
						INTO iTotalDevolucion, mMontoDevolucion, sIdReporte
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col = pIdPoducto	
							AND tipo_devolucion = pTipoDevolucion
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '5' THEN		
				FOREACH SELECT total_cuentas, id_reporte
						INTO iTotalCuenta, sIdReporte
						FROM bdireports:'informix'.rpt_mc_cta_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND tipo_cuenta = pTipoCuenta
							AND id_tipo = pIdTipo
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '6' THEN
				IF pFechaInicio IS  NULL OR pFechaFin IS  NULL THEN
					LET cCodRet = '00003';
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END IF;
				FOREACH SELECT total_cuentas, id_reporte
					INTO iTotalCuenta, sIdReporte
					FROM bdireports:'informix'.rpt_mc_cta_tri
					WHERE num_producto = pNumProducto
						AND trimestre = pTrimestre
						AND fecha_reg  BETWEEN pFechaInicio AND pFechaFin
						AND tipo_cuenta = pTipoCuenta
						AND id_tipo = pIdTipo	    
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
			-- CONSULTA SUMAS 
			ELIF pBandera = '7' THEN
				FOREACH SELECT SUM(total_compras), SUM (monto_compras)
						INTO cTotalCmprs, mMontoCompras
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col IN ('CNC', 'CIC' )
							AND tipo_compras NOT IN ('CHEQUES DE CONVENIENCIA')
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '8' THEN
				FOREACH SELECT SUM (total_transacciones), SUM(monto_transacciones)
						INTO cTotalTransac,mMontoTransacciones
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col = 'TEC'
							AND tipo_transaccion IN('ATM TRANSACCION EFECTIVO PROPIO','ATM DOMESTICO OTROS BANCOS','ATM TRANSACCION EFECTIVO NO PROPIO','ATM TRANSACCION EFECTIVO INTERNACIONAL')
							LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '9' THEN		
				FOREACH SELECT  SUM(total_devolucion),SUM( monto_devolucion)
						INTO cTotalDev, mMontoDevolucion
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col IN ('DNC', 'DIC')
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '10' THEN		
				FOREACH 
						
				SELECT SUM(total_cuentas)
						INTO iSuma_cuentas_A
						FROM bdireports:'informix'.rpt_mc_cta_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND tipo_cuenta IN ('ACTIVAS')
							AND id_tipo = pIdTipo
							
				SELECT SUM(total_cuentas)
						INTO iSuma_cuentas_B
						FROM bdireports:'informix'.rpt_mc_cta_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND tipo_cuenta IN ('BLOQUEADAS')
							AND id_tipo = pIdTipo;	
					
					LET cTotalCta=iSuma_cuentas_A - iSuma_cuentas_B;
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				
				
				
				END FOREACH;
			
				
			ELIF pBandera = '11' THEN		
				FOREACH SELECT SUM(total_cuentas)
						INTO cTotalCta
						FROM bdireports:'informix'.rpt_mc_cta_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND tipo_cuenta = 'CON AL MENOS UNA TRANSACCION'
							AND id_tipo = pIdTipo
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
			
			ELIF pBandera = '12' THEN		
				FOREACH SELECT SUM(total_compras), SUM (monto_compras)
						INTO cTotalCmprs, mMontoCompras
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col IN ('CND','CID')							
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
			
			ELIF pBandera = '13' THEN
				FOREACH SELECT SUM (total_transacciones), SUM(monto_transacciones)
						INTO cTotalTransac,mMontoTransacciones
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col = 'TED'
							AND  tipo_transaccion IN('ATM TRANSACCION EFECTIVO PROPIO','ATM DOMESTICO OTROS BANCOS','ATM TRANSACCION EFECTIVO NO PROPIO','ATM TRANSACCION EFECTIVO INTERNACIONAL')
							LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
			
			 
			ELIF pBandera = '14' THEN		
				FOREACH SELECT  SUM(total_devolucion),SUM( monto_devolucion)
						INTO cTotalDev, mMontoDevolucion
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col IN ('DND', 'DID')
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '15' THEN		
				FOREACH SELECT SUM(total_cuentas)
						INTO cTotalCta
						FROM bdireports:'informix'.rpt_mc_cta_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND tipo_cuenta = 'ACTIVAS'
							AND id_tipo = pIdTipo
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;
				
			ELIF pBandera = '16' THEN		
				FOREACH  SELECT SUM (total_transacciones), SUM(monto_transacciones)
						INTO cTotalTransac,mMontoTransacciones
						FROM bdireports:'informix'.rpt_mc_vol_tri
						WHERE num_producto = pNumProducto
							AND trimestre = pTrimestre
							AND id_col IN  ('ADQ', 'ADN','ADI')
					LET iNoRegistros = iNoRegistros + 1;
					RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta WITH RESUME;
				END FOREACH;			
		END IF;		
	
		IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,sIdReporte,iTotalCompras,mMontoCompras,iTotalTransacciones,mMontoTransacciones,iTotalDevolucion,mMontoDevolucion,iTotalCuenta,cTotalCmprs,cTotalTransac,cTotalDev,cTotalCta;
		END IF;
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: Ing. Guadalupe Angelica Hernandez Perez',
'FECHA: 02/10/2015',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: REPORTE TRIMESTRAL MASTERCARD',
'DESCRIPCION: SPL que consulta los totales de compras, transacciones, devoluciones y cuentas y consulta la suma de los totales mencionados del reportes Trimestral MasterCard',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_cre_detallestatussolaudexcel(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaInicio CHAR(10), pFechaFin CHAR(10), 
pSucursal CHAR(4), pStatus CHAR(2), pRegistros INTEGER, pRecuperacion INTEGER)
    RETURNING CHAR(5) AS codret,          
		CHAR(20) AS num_solicitud,        
		CHAR(20) AS num_cliente,          
		DATE AS fecha_alta,               
		CHAR(104) AS nom_cliente,         
		CHAR(2) AS status_solicitud,      
		MONEY(14,2) AS monto_solicitud,   
		MONEY(14,2) AS monto_otorgado,    
		DATE AS fecha_cambio_status,      
		CHAR(45) AS nom_promotor_realizo, 
		CHAR(45) AS nom_promotor_autorizo,
		CHAR(45) AS nom_promotor_entrego, 
		CHAR(45) AS nom_promotor_asigno,  
		CHAR(13) AS tel_particular,       
		CHAR(13) AS tel_celular,          
		CHAR(13) AS tel_oficina,          
		CHAR(4) AS sucursal,		      
		CHAR(104) AS nom_referencia1,     
		CHAR(13) AS tel_ref1_particular,  
		CHAR(13) AS tel_ref1_celular,     
		CHAR(13) AS tel_ref1_oficina,     
		CHAR(104) AS nom_referencia2,     
		CHAR(13) AS tel_ref2_particular,  
		CHAR(13) AS tel_ref2_celular,     
		CHAR(13) AS tel_ref2_oficina,     
		CHAR(3) AS id_nacionalidad,       
		CHAR(15) AS desc_nacionalidad,    
		CHAR(20) AS utilizo_idbox,        
		CHAR(50) AS resultado_idbox,      
		CHAR(100) AS rechazo_idbox,       
		CHAR(2) AS id_status,             
		CHAR(60) AS desc_status,          
		DATE AS fecha_cta_saldada,        
		CHAR(2) AS idbox_alta_cte;		
	
    DEFINE cCodRet CHAR(5);
    DEFINE iSqlErr INTEGER;
    DEFINE cCodRetSp CHAR(6);
	DEFINE cDescCodRetSp CHAR(80);
    DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
    DEFINE cNum_solicitud CHAR(20);
	DEFINE cNum_cliente CHAR(20);
	DEFINE dFecha_alta DATE;
	DEFINE cNom_cliente CHAR(104);
	DEFINE cStatus_solicitud CHAR(2);
	DEFINE mMonto_solicitud MONEY(14,2);  
	DEFINE mMonto_otorgado MONEY(14,2); 
	DEFINE dFecha_cambio_status DATE;
	DEFINE cNom_promotor_realizo CHAR(45);
	DEFINE cNom_promotor_autorizo CHAR(45);
	DEFINE cNom_promotor_entrego CHAR(45);
	DEFINE cNom_promotor_asigno CHAR(45);
	DEFINE cTelefono_particular CHAR(13);
	DEFINE cTelefono_celular CHAR(13);
	DEFINE cTelefono_oficina CHAR(13);
	DEFINE cSucursal CHAR(4);
	DEFINE cNom_referencia1 CHAR(104); 
	DEFINE cTel_ref1_particular CHAR(13); 
	DEFINE cTel_ref1_celular CHAR(13); 
	DEFINE cTel_ref1_oficina CHAR(13);
	DEFINE cNom_referencia2 CHAR(104); 
	DEFINE cTel_ref2_particular CHAR(13); 
	DEFINE cTel_ref2_celular CHAR(13); 
	DEFINE cTel_ref2_oficina CHAR(13);
	DEFINE cId_nac CHAR(3); 
	DEFINE cDesc_nac CHAR(15);
	DEFINE cUtilizo_idbox CHAR(20);
	DEFINE cResultado_idbox CHAR(50);
	DEFINE cRechazo_idbox CHAR(100);
	DEFINE cId_status CHAR(2);
	DEFINE cDesc_status CHAR(60);
	DEFINE dFecha_cta_saldada DATE;
	DEFINE dFechaAlta DATE;
	DEFINE dFechaHoy DATE;
	DEFINE iUtilizoIdBox INTEGER;
	DEFINE cIdBoxAltaCte CHAR(2);
	DEFINE iRecuperacion INTEGER;
	
    LET cCodRet = '00000';
    LET iSqlErr = 0;
    LET cCodRetSp = '';
	LET cDescCodRetSp = '';
    LET iCodRetSp = 0;
	LET cEmpresa = '001';
    LET cNum_solicitud = '';
	LET cNum_cliente = '';
	LET dFecha_alta = '';
	LET cNom_cliente = '';
	LET cStatus_solicitud = '';
	LET mMonto_solicitud = 0.00; 
	LET mMonto_otorgado = 0.00; 
	LET dFecha_cambio_status = '';
	LET cNom_promotor_realizo = '';
	LET cNom_promotor_autorizo = '';
	LET cNom_promotor_entrego = '';
	LET cNom_promotor_asigno = '';
	LET cTelefono_particular = '';
	LET cTelefono_celular = '';
	LET cTelefono_oficina = '';
	LET cSucursal = '';
	LET cNom_referencia1 = ''; 
	LET cTel_ref1_particular = ''; 
	LET cTel_ref1_celular = ''; 
	LET cTel_ref1_oficina = '';
	LET cNom_referencia2 = ''; 
	LET cTel_ref2_particular = ''; 
	LET cTel_ref2_celular = ''; 
	LET cTel_ref2_oficina = '';
	LET cId_nac = '';
	LET cDesc_nac = '';
	LET cUtilizo_idbox = '';
	LET cResultado_idbox = '';
	LET cRechazo_idbox = '';
	LET cId_status = '';
	LET cDesc_status = '';
	LET dFecha_cta_saldada = '';
	LET dFechaAlta = '';
	LET dFechaHoy = CURRENT;
	LET iUtilizoIdBox = 0;
	LET cIdBoxAltaCte = '';
	LET iRecuperacion = 0;
	
    BEGIN
        
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNum_solicitud, cNum_cliente, dFecha_alta, cNom_cliente, cStatus_solicitud, 
			mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
			cNom_promotor_realizo, cNom_promotor_autorizo, cNom_promotor_entrego, cNom_promotor_asigno,
			cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
			cNom_referencia1, cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
			cNom_referencia2, cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina,
			cId_nac, cDesc_nac, cUtilizo_idbox, cResultado_idbox, cRechazo_idbox, 
			cId_status, cDesc_status, dFecha_cta_saldada, cIdBoxAltaCte;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_cre_detallestatussolaudexcel.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFechaInicio IS NULL OR pFechaFin IS NULL OR 
		pSucursal  = '' OR pStatus  = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNum_solicitud, cNum_cliente, dFecha_alta, cNom_cliente, cStatus_solicitud, 
			mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
			cNom_promotor_realizo, cNom_promotor_autorizo, cNom_promotor_entrego, cNom_promotor_asigno,
			cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
			cNom_referencia1, cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
			cNom_referencia2, cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina,
			cId_nac, cDesc_nac, cUtilizo_idbox, cResultado_idbox, cRechazo_idbox, 
			cId_status, cDesc_status, dFecha_cta_saldada, cIdBoxAltaCte;
		END IF;

		-- VALIDACIÃ?N DE LOS DATOS DE PAGINACIÃ?N
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cNum_solicitud, cNum_cliente, dFecha_alta, cNom_cliente, cStatus_solicitud, 
			mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
			cNom_promotor_realizo, cNom_promotor_autorizo, cNom_promotor_entrego, cNom_promotor_asigno,
			cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
			cNom_referencia1, cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
			cNom_referencia2, cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina,
			cId_nac, cDesc_nac, cUtilizo_idbox, cResultado_idbox, cRechazo_idbox, 
			cId_status, cDesc_status, dFecha_cta_saldada, cIdBoxAltaCte;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNum_solicitud, cNum_cliente, dFecha_alta, cNom_cliente, cStatus_solicitud, 
			mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
			cNom_promotor_realizo, cNom_promotor_autorizo, cNom_promotor_entrego, cNom_promotor_asigno,
			cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
			cNom_referencia1, cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
			cNom_referencia2, cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina,
			cId_nac, cDesc_nac, cUtilizo_idbox, cResultado_idbox, cRechazo_idbox, 
			cId_status, cDesc_status, dFecha_cta_saldada, cIdBoxAltaCte;
		END IF;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
		
			EXECUTE PROCEDURE bdicred:"informix".sp_status_sol_audexcel2(cEmpresa,pSucursal,pFechaInicio,pFechaFin,pStatus,pRegistros,pRecuperacion)			
			INTO cCodRetSp, cDescCodRetSp, cNum_solicitud, cNum_cliente, dFecha_alta, cNom_cliente, cStatus_solicitud, 
			mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
			cNom_promotor_realizo, cNom_promotor_autorizo, cNom_promotor_entrego, cNom_promotor_asigno,
			cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
			cNom_referencia1, cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
			cNom_referencia2, cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina			
			
			IF cCodRetSp::INTEGER < 0 THEN 
				RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÃ?N DEL SP bdicred:sp_status_sol_audexcel2';
			ELIF cCodRetSp::INTEGER > 0 THEN
				IF cCodRetSp::INTEGER = 1 OR cCodRetSp::INTEGER = 2 THEN
					LET cCodRet = '00003';
				ELIF cCodRetSp::INTEGER = 3 THEN
					LET cCodRet = '00996'; --EL ESTATUS NO ES VALIDO PARA LA EXPORTACIÃ?N A EXCEL
				ELIF cCodRetSp::INTEGER = 4 THEN
					LET cCodRet = '00997'; --EL RANGO DE FECHAS NO ES VALIDO PARA LA EXPORTACIÃ?N A EXCEL
				ELIF cCodRetSp::INTEGER = 5 AND pRegistros = 0 THEN
					LET cCodRet = '00017';
				ELIF cCodRetSp::INTEGER = 5 AND pRegistros > 0 THEN
					LET cCodRet = '1001';
				END IF;
				
				RETURN cCodRet, cNum_solicitud, cNum_cliente, dFecha_alta, cNom_cliente, cStatus_solicitud, 
				mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
				cNom_promotor_realizo, cNom_promotor_autorizo, cNom_promotor_entrego, cNom_promotor_asigno,
				cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
				cNom_referencia1, cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
				cNom_referencia2, cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina,
				cId_nac, cDesc_nac, cUtilizo_idbox, cResultado_idbox, cRechazo_idbox, 
				cId_status, cDesc_status, dFecha_cta_saldada, cIdBoxAltaCte;
			END IF;
			
			--SE INICIALIZAN VARIABLES
			LET cId_nac = '';
			LET cDesc_nac = '';
			LET cUtilizo_idbox = '';
			LET cResultado_idbox = '';
			LET cRechazo_idbox = '';
			LET cId_status = '';
			LET cDesc_status = '';
			LET dFecha_cta_saldada = '';
			LET dFechaAlta = '';
			LET cIdBoxAltaCte = '';
			LET iUtilizoIdBox = 0;
			
			IF NVL(cNum_cliente,'') <> '' THEN
				
				--NACIONALIDAD
				SELECT ct.nacionalidad, na.descripcion 
				INTO cId_nac, cDesc_nac
				FROM bdinteg:"informix".si_ctepf AS ct, bdinteg:"informix".si_nacion AS na
				WHERE ct.numcte = cNum_cliente
				AND na.nacion = ct.nacionalidad;
				
				/*
				--UTILIZÃ? ID BOX EN ALTA / RESULTADO ID BOX / CAUSA RECHAZO ID BOX
				FOREACH
					
					SELECT FIRST 1 numcte, resultado, causa_rechazo
					INTO cUtilizo_idbox, cResultado_idbox, cRechazo_idbox
					FROM bdinteg:"informix".si_bitacora_ife 
					WHERE numcte = cNum_cliente
					AND sucursal = pSucursal
					ORDER BY fecha DESC
					
				END FOREACH;				
				*/
				
				--UTILIZÃ? ID BOX EN ALTA DE CLIENTE NUEVO
				SELECT fecha_alta INTO dFechaAlta
				FROM bdinteg:"informix".si_cte_huella 
				WHERE numcte = cNum_cliente 
				--AND sucursal = pSucursal 
				AND secuencia = 1;
				
				--VALIDA EL ALTA DEl CLIENTE EN UN RANGO DE 6 MESES 
				IF dFechaHoy - dFechaAlta > 180 THEN
					LET cIdBoxAltaCte = '';
				ELIF dFechaHoy - dFechaAlta <= 180 THEN
					
					SELECT COUNT(*) INTO iUtilizoIdBox
					FROM bdinteg:"informix".si_bitacora_ife 
					WHERE numcte = cNum_cliente;
					--AND sucursal = pSucursal;
					
					IF NVL(iUtilizoIdBox,0) > 0 THEN
						LET cIdBoxAltaCte = 'SI';
					ELSE
						LET cIdBoxAltaCte = 'NO';
					END IF;
					
				END IF;
			
				IF NVL(cNum_solicitud,'') <> '' THEN
					
					--ESTATUS
					SELECT ma.status_cred, ti.descripcion 
					INTO cId_status, cDesc_status
					FROM bdicred:"informix".sd_maecred AS ma, bdicred:"informix".sd_tipocartera AS ti
					WHERE ma.numcte = cNum_cliente
					AND ti.status_cred = ma.status_cred
					AND num_credito = cNum_solicitud;
					
					IF NVL(cId_status,'') = '' THEN
						
						LET cId_status = '';
						LET cDesc_status = '';
						
						SELECT ma.status_cred, ti.descripcion 
						INTO cId_status, cDesc_status
						FROM bdicred:"informix".sd_maecredcrd AS ma, bdicred:"informix".sd_tipocartera AS ti
						WHERE ma.numcte = cNum_cliente
						AND ti.status_cred = ma.status_cred
						AND num_credito = cNum_solicitud;
					
					END IF;
					
					--FECHA CTA SALDADA
					SELECT fecha_proceso 
					INTO dFecha_cta_saldada
					FROM bdicred:"informix".sd_maecredanexo 
					WHERE num_credito = cNum_solicitud;
					
					IF NVL(dFecha_cta_saldada,'') = '' THEN
						
						LET dFecha_cta_saldada = '';
						
						SELECT fecha_proceso 
						INTO dFecha_cta_saldada
						FROM bdicred:"informix".sd_maecredanexocrd 
						WHERE num_credito = cNum_solicitud;
						
					END IF;
					
				END IF;
				
			END IF;
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, cNum_solicitud, cNum_cliente, dFecha_alta, UPPER(cNom_cliente), UPPER(cStatus_solicitud), 
			mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
			UPPER(cNom_promotor_realizo), UPPER(cNom_promotor_autorizo), UPPER(cNom_promotor_entrego), UPPER(cNom_promotor_asigno),
			cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
			UPPER(cNom_referencia1), cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
			UPPER(cNom_referencia2), cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina,
			cId_nac, UPPER(cDesc_nac), cUtilizo_idbox, UPPER(cResultado_idbox), UPPER(cRechazo_idbox), 
			UPPER(cId_status), UPPER(cDesc_status), dFecha_cta_saldada, cIdBoxAltaCte WITH RESUME;
			
			--SE INICIALIZAN VARIABLES
			LET cNum_cliente = '';
			LET cNum_solicitud = '';
			
		END FOREACH;
		
		IF iRecuperacion = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, cNum_solicitud, cNum_cliente, dFecha_alta, cNom_cliente, cStatus_solicitud, 
			mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
			cNom_promotor_realizo, cNom_promotor_autorizo, cNom_promotor_entrego, cNom_promotor_asigno,
			cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
			cNom_referencia1, cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
			cNom_referencia2, cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina,
			cId_nac, cDesc_nac, cUtilizo_idbox, cResultado_idbox, cRechazo_idbox, 
			cId_status, cDesc_status, dFecha_cta_saldada, cIdBoxAltaCte;
		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cNum_solicitud, cNum_cliente, dFecha_alta, cNom_cliente, cStatus_solicitud, 
			mMonto_solicitud, mMonto_otorgado, dFecha_cambio_status, 
			cNom_promotor_realizo, cNom_promotor_autorizo, cNom_promotor_entrego, cNom_promotor_asigno,
			cTelefono_particular, cTelefono_celular, cTelefono_oficina, cSucursal,
			cNom_referencia1, cTel_ref1_particular, cTel_ref1_celular, cTel_ref1_oficina,
			cNom_referencia2, cTel_ref2_particular, cTel_ref2_celular, cTel_ref2_oficina,
			cId_nac, cDesc_nac, cUtilizo_idbox, cResultado_idbox, cRechazo_idbox, 
			cId_status, cDesc_status, dFecha_cta_saldada, cIdBoxAltaCte;
		END IF;
		
    END;
END PROCEDURE
