CREATE PROCEDURE "informix".sp_caja_cons_denominaciones(pUsuario CHAR(8), pIdFuncion CHAR(10), pSucAtm CHAR(10), pFolioOper CHAR(8), pFechaInicial DATE, pFechaFinal DATE)
    RETURNING CHAR(5) AS codret,
		CHAR(18) AS cDenominacion1, 
		CHAR(18) AS cDenominacion2, 
		CHAR(18) AS cDenominacion3, 
		CHAR(18) AS cDenominacion4, 
		CHAR(18) AS cDenominacion5, 
		CHAR(18) AS cDenominacion6, 
		DECIMAL(12,2) AS dCantidad1,
		DECIMAL(12,2) AS dCantidad2,
		DECIMAL(12,2) AS dCantidad3,
		DECIMAL(12,2) AS dCantidad4,
		DECIMAL(12,2) AS dCantidad5,
		DECIMAL(12,2) AS dCantidad6;
		
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iRecuperacion INTEGER;
	
	DEFINE cDenominacion1 CHAR(18);
    DEFINE cDenominacion2 CHAR(18);
    DEFINE cDenominacion3 CHAR(18);
    DEFINE cDenominacion4 CHAR(18);
    DEFINE cDenominacion5 CHAR(18);
    DEFINE cDenominacion6 CHAR(18);
	DEFINE dCantidad1 DECIMAL(12,2);
    DEFINE dCantidad2 DECIMAL(12,2);
    DEFINE dCantidad3 DECIMAL(12,2);
    DEFINE dCantidad4 DECIMAL(12,2);
    DEFINE dCantidad5 DECIMAL(12,2);
    DEFINE dCantidad6 DECIMAL(12,2);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';	
	LET iRecuperacion = 0;
	
	LET cDenominacion1 = '';
    LET cDenominacion2 = '';
    LET cDenominacion3 = '';
    LET cDenominacion4 = '';
    LET cDenominacion5 = '';
    LET cDenominacion6 = '';
	LET dCantidad1 = 0.00;
    LET dCantidad2 = 0.00;
    LET dCantidad3 = 0.00;
    LET dCantidad4 = 0.00;
    LET dCantidad5 = 0.00;
    LET dCantidad6 = 0.00;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cDenominacion1, cDenominacion2, cDenominacion3, cDenominacion4, cDenominacion5, cDenominacion6, dCantidad1, dCantidad2, dCantidad3, dCantidad4, dCantidad5, dCantidad6;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_caja_cons_denominaciones.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pSucAtm = '' OR pFechaInicial IS NULL OR pFechaFinal IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cDenominacion1, cDenominacion2, cDenominacion3, cDenominacion4, cDenominacion5, cDenominacion6, dCantidad1, dCantidad2, dCantidad3, dCantidad4, dCantidad5, dCantidad6;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cDenominacion1, cDenominacion2, cDenominacion3, cDenominacion4, cDenominacion5, cDenominacion6, dCantidad1, dCantidad2, dCantidad3, dCantidad4, dCantidad5, dCantidad6;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT denominacion_1, denominacion_2, denominacion_3, denominacion_4, denominacion_5, denominacion_6, cantidad_1, cantidad_2,cantidad_3,cantidad_4,cantidad_5,cantidad_6
			INTO cDenominacion1, cDenominacion2, cDenominacion3, cDenominacion4, cDenominacion5, cDenominacion6, dCantidad1, dCantidad2, dCantidad3, dCantidad4, dCantidad5, dCantidad6
			FROM bdisuc:"informix".ss_operaciones o
			WHERE o.sucursal = pSucAtm
			AND o.fecha_operacion BETWEEN pFechaInicial AND pFechaFinal 
			AND o.folio_oper = pFolioOper

			LET iRecuperacion = iRecuperacion + 1;
			
			RETURN cCodRet,cDenominacion1, cDenominacion2, cDenominacion3, cDenominacion4, cDenominacion5, cDenominacion6, dCantidad1, dCantidad2, dCantidad3, dCantidad4, dCantidad5, dCantidad6 WITH RESUME;
		END FOREACH;				
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cDenominacion1, cDenominacion2, cDenominacion3, cDenominacion4, cDenominacion5, cDenominacion6, dCantidad1, dCantidad2, dCantidad3, dCantidad4, dCantidad5, dCantidad6;
		END IF;
		
	END;
END PROCEDURE
