CREATE PROCEDURE "informix".sp_caja_cons_detalle_operacion(pUsuario CHAR(8), pIdFuncion CHAR(10), pCajaGral CHAR(4), pSucAtm CHAR(10), pFolioOper CHAR(8), pFechaInicial DATE, pFechaFinal DATE)
    RETURNING CHAR(5) AS codret,
		CHAR(16) AS FolioServicio, 		
		CHAR(2) AS Divisa, 			
		CHAR(2) AS Status, 			
		DATE 	AS FechaSolicitud, 	
		CHAR(5) AS HoraSolicitud, 		
		CHAR(8) AS UsuarioSolicitud, 	
		DATE 	AS FechaEnvio, 		
		DATE 	AS FechaRecepcion, 	
		INTEGER AS Pzas, 				
		MONEY(16,2) AS Montos,
		CHAR(30) AS cDescDivisa, 
		CHAR(30) AS cDescStatus;			
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iRecuperacion INTEGER;
	
	
	DEFINE cFolioServicio CHAR(16);
	DEFINE cDivisa CHAR(2);
	DEFINE cStatus CHAR(2);
	DEFINE dFechaSolicitud DATE;
	DEFINE cHoraSolicitud CHAR(5);
	DEFINE cUsuarioSolicitud CHAR(8);
	DEFINE dFechaEnvio DATE;
	DEFINE dFechaRecepcion DATE;
	DEFINE iPzas INTEGER;
	DEFINE mMontos MONEY(16,2);
	DEFINE cDescDivisa CHAR(30);
	DEFINE cDescStatus CHAR(30);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';	
	LET iRecuperacion = 0;
	
	LET cFolioServicio = '';
	LET cDivisa = '';
	LET cStatus = '';
	LET dFechaSolicitud = '';
	LET cHoraSolicitud = '';
	LET cUsuarioSolicitud = '';
	LET dFechaEnvio = '';
	LET dFechaRecepcion = '';
	LET iPzas = 0;
	LET mMontos = 0.00;
	LET cDescDivisa = '';
	LET cDescStatus = '';
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cFolioServicio,	cDivisa, cStatus, dFechaSolicitud, cHoraSolicitud, cUsuarioSolicitud, dFechaEnvio, dFechaRecepcion, iPzas, mMontos, cDescDivisa, cDescStatus;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_caja_cons_detalle_operacion.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pCajaGral = '' OR pSucAtm = '' OR pFolioOper = '' OR pFechaInicial IS NULL OR pFechaFinal IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cFolioServicio,	cDivisa, cStatus, dFechaSolicitud, cHoraSolicitud, cUsuarioSolicitud, dFechaEnvio, dFechaRecepcion, iPzas, mMontos, cDescDivisa, cDescStatus;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cFolioServicio,	cDivisa, cStatus, dFechaSolicitud, cHoraSolicitud, cUsuarioSolicitud, dFechaEnvio, dFechaRecepcion, iPzas, mMontos, cDescDivisa, cDescStatus;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT m.folio_oper,  o.divisa, m.status, m.fecha_solicitud, m.hora_solicitud, m.usuario_solicitud, m.fecha_envio, m.fecha_recepcion, pzas.pza, mont.monto
			INTO  cFolioServicio,	cDivisa, cStatus, dFechaSolicitud, cHoraSolicitud, cUsuarioSolicitud, dFechaEnvio, dFechaRecepcion, iPzas, mMontos
			FROM bdisuc:"informix".ss_mae_entradasalida m
			INNER JOIN bdisuc:"informix".ss_operaciones o ON o.folio_oper = m.folio_oper AND o.sucursal = pSucAtm AND o.fecha_operacion BETWEEN pFechaInicial AND pFechaFinal  
			INNER JOIN (
				SELECT sucursal,folio_oper, SUM((cantidad_1 + cantidad_2 + cantidad_3 + cantidad_4 + cantidad_5 + cantidad_6)) AS pza
				FROM bdisuc:"informix".ss_operaciones
				WHERE fecha_operacion BETWEEN pFechaInicial AND pFechaFinal  
				AND sucursal = pSucAtm
				AND folio_oper = pFolioOper
				GROUP BY sucursal, folio_oper
			)AS pzas ON pzas.folio_oper = m.folio_oper AND pzas.sucursal = pSucAtm 
			INNER JOIN (
				SELECT cod_proveedor,sucursal, SUM(monto) AS monto
				FROM bdisuc:"informix".ss_mae_entradasalida
				WHERE fecha_solicitud BETWEEN pFechaInicial AND pFechaFinal  
				AND cod_proveedor = pCajaGral
				AND sucursal = pSucAtm
				AND folio_oper = pFolioOper
				GROUP BY  cod_proveedor,sucursal
			)AS mont ON mont.cod_proveedor = pCajaGral AND mont.sucursal = pSucAtm
			WHERE m.cod_proveedor = pCajaGral
			AND m.sucursal = pSucAtm
			AND m.fecha_solicitud BETWEEN pFechaInicial AND pFechaFinal AND m.folio_oper = pFolioOper
			
			
			IF cDivisa = 'MR' THEN
				LET cDescDivisa = 'MONEDA NACIONAL';
			ELIF NVL(cDivisa,'') <> '' THEN
			
				SELECT descripcion 
				INTO cDescDivisa
				FROM bdinteg:"informix".si_divisas
				WHERE divisa = cDivisa;							
			END IF;
			
			IF NVL(cStatus,'') <> '' THEN
			
				SELECT descripcion 
				INTO cDescStatus
				FROM bdisuc:"informix".ss_catstatus
				WHERE status = cStatus;
			
			END IF;			
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, cFolioServicio,	cDivisa, cStatus, dFechaSolicitud, cHoraSolicitud, cUsuarioSolicitud, dFechaEnvio, dFechaRecepcion, iPzas, mMontos, cDescDivisa, UPPER(cDescStatus) WITH RESUME;
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cFolioServicio,	cDivisa, cStatus, dFechaSolicitud, cHoraSolicitud, cUsuarioSolicitud, dFechaEnvio, dFechaRecepcion, iPzas, mMontos, cDescDivisa, cDescStatus;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Uriel CaamaÃÂÃÂ±o Mejia',
'FECHA 14/11/2018',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: REPORTERIA MENSUAL CAJA GENRAL',
'DESCRIPCION: SPL encargado de consultar el detalle de lo Reportes individual.',
