CREATE PROCEDURE "informix".sp_caja_cons_detalle_reporte(pUsuario CHAR(8), pIdFuncion CHAR(10), pCajaGral CHAR(4), pSucAtm CHAR(10), pFolioOper CHAR(8), pFechaInicial DATE, pFechaFinal DATE)
    RETURNING CHAR(5) AS codret,
		CHAR(10) AS Fecha,
		MONEY(16,2) AS Monto,
		CHAR(30) AS CajaGral,
		CHAR(4) AS Sucursal,
		CHAR(16) AS NoPapeleta,
		CHAR(4) AS Operacion,
		MONEY(16,2) AS SdoAsignado,
		MONEY(16,2) AS SdoTotal,	
		CHAR(40) AS DescSuc,
		CHAR(35) AS DescOp;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iRecuperacion INTEGER;
	
	DEFINE dFecha DATE;
	DEFINE mMonto MONEY(16,2);
	DEFINE cSucursal CHAR(4);
	DEFINE cNoPapeleta CHAR(16);
	DEFINE cCajaGral CHAR(30);
	DEFINE cCodTrans CHAR(4);
	DEFINE mSaldoAsignado MONEY(16,2);
	DEFINE mSaldoTotal MONEY(16,2);
	DEFINE cDescSuc CHAR(40);
	DEFINE cDescCodTrans CHAR(35);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';	
	LET iRecuperacion = 0;
	
	LET dFecha = '';
	LET mMonto = 0.00;
	LET cSucursal = '';
	LET cNoPapeleta = '';
	LET cCajaGral = '';
	LET cCodTrans = '';
	LET mSaldoAsignado = 0.00;
	LET mSaldoTotal = 0.00;
	LET cDescSuc = '';
	LET cDescCodTrans = '';

	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,dFecha, mMonto, cCajaGral, cSucursal, cNoPapeleta, cCodTrans, mSaldoAsignado, mSaldoTotal, cDescSuc, cDescCodTrans;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_caja_cons_detalle_reporte.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFechaInicial IS NULL OR pFechaFinal IS NULL OR pCajaGral = '' OR pSucAtm = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,dFecha, mMonto, cCajaGral, cSucursal, cNoPapeleta, cCodTrans, mSaldoAsignado, mSaldoTotal, cDescSuc, cDescCodTrans;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,dFecha, mMonto, cCajaGral, cSucursal, cNoPapeleta, cCodTrans, mSaldoAsignado, mSaldoTotal, cDescSuc, cDescCodTrans;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT m.fecha_solicitud, m.monto, m.sucursal, m.folio_servicio, p.descripcion, o.cod_trans, c.saldo_asignado, c.saldo_total
			INTO dFecha, mMonto, cSucursal, cNoPapeleta, cCajaGral, cCodTrans, mSaldoAsignado, mSaldoTotal
			FROM bdisuc:"informix".ss_mae_entradasalida m
			INNER JOIN bdisuc:"informix".ss_proveedores p ON p.cod_proveedor = m.cod_proveedor
			INNER JOIN bdisuc:"informix".ss_operaciones o ON o.folio_oper = m.folio_oper AND o.sucursal = pSucAtm AND o.fecha_operacion BETWEEN pFechaInicial AND pFechaFinal  
			INNER JOIN bdisuc:"informix".ss_cajageneral c ON c.cod_proveedor = m.cod_proveedor
			WHERE m.cod_proveedor = pCajaGral
			AND m.sucursal = pSucAtm
			AND m.fecha_solicitud BETWEEN pFechaInicial AND pFechaFinal 
			AND m.folio_oper = pFolioOper			
			
			IF NVL(cSucursal,'') <> '' THEN
			
				SELECT nombre 
				INTO cDescSuc
				FROM bdinteg:"informix".si_sucursales 
				WHERE sucursal = cSucursal;

			END IF;
			
			IF NVL(cCodTrans,'') <> '' THEN
			
				SELECT descripcion 
				INTO cDescCodTrans
				FROM bdisuc:"informix".ss_param_cajagen 
				WHERE codigo = cCodTrans;

			END IF;
			
			LET iRecuperacion = iRecuperacion + 1;
			
			RETURN cCodRet,dFecha, mMonto,  UPPER(cCajaGral), cSucursal, cNoPapeleta, cCodTrans, mSaldoAsignado, mSaldoTotal, cDescSuc, UPPER(cDescCodTrans) WITH RESUME;
		END FOREACH;				
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet,dFecha, mMonto, cCajaGral, cSucursal, cNoPapeleta, cCodTrans, mSaldoAsignado, mSaldoTotal, cDescSuc, cDescCodTrans;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Uriel Caamaño Mejia',
'FECHA 14/11/2018',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: REPORTERIA MENSUAL CAJA GENRAL',
'DESCRIPCION: SPL encargado de consultar el detalle de Operacion.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_caja_cons_informacion_reporte(pUsuario CHAR(8), pIdFuncion CHAR(10), pCajaGral CHAR(4), pSucAtm CHAR(10), pFechaInicial DATE, pFechaFinal DATE, 
pRegistros INTEGER, pRecuperacion INTEGER)
    RETURNING CHAR(5) AS codret,
		CHAR(10) AS Fecha,
		MONEY(16,2) AS Monto,
		CHAR(4) AS Sucursal,
		CHAR(8) AS Folio,
		CHAR(4) AS CodTran,
		MONEY(16,2) AS SdoAsignado,
		MONEY(16,2) AS SdoTotal,
		INTEGER AS Piezas,
		MONEY(16,2) AS Montos,
		INTEGER AS  TotalPzas, 
		MONEY(16,2) AS  TotalMontos, 
		MONEY(16,2) AS  TotalSaldoAsignado, 
		MONEY(16,2) AS  TotalSaldoTotal,
		CHAR(4) AS CajaGral,
		CHAR(30) AS Descripcion; 
		
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iRecuperacion INTEGER;
	
	DEFINE dFecha DATE;
	DEFINE mMonto MONEY(16,2);
	DEFINE cSucursal CHAR(4);
	DEFINE cFolio CHAR(8);
	DEFINE cCodTrans CHAR(4);
	DEFINE mSaldoAsignado MONEY(16,2);
	DEFINE mSaldoTotal MONEY(16,2);
	DEFINE iPzas INTEGER;
	DEFINE mMontos MONEY(16,2);
	DEFINE cCajaGral char(30);
	DEFINE cDescripcion char(30);
	
	DEFINE iTotalPzas INTEGER;
	DEFINE mTotalMontos MONEY(16,2);
	DEFINE mTotalSaldoAsignado MONEY(16,2);
	DEFINE mTotalSaldoTotal MONEY(16,2);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';	
	LET iRecuperacion = 0;
	
	LET dFecha = '';
	LET mMonto = 0.00;
	LET cSucursal = '';
	LET cFolio = '';
	LET cCodTrans = '';
	LET mSaldoAsignado = 0.00;
	LET mSaldoTotal = 0.00;
	LET iPzas = 0;
	LET mMontos = 0.00;
	LET iTotalPzas  = 0;
	LET mTotalMontos = 0.00;
	LET mTotalSaldoAsignado = 0.00;
	LET mTotalSaldoTotal = 0.00;
	LET cCajaGral = '';
	LET cDescripcion = '';

	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,dFecha, mMonto, cSucursal, cFolio, cCodTrans, mSaldoAsignado, mSaldoTotal, iPzas, mMontos, iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal, cCajaGral, cDescripcion;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_caja_cons_informacion_reporte.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = ''  OR pCajaGral = '' OR pSucAtm = '' OR pFechaInicial  IS NULL OR pFechaFinal IS NULL OR
		pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet,dFecha, mMonto, cSucursal, cFolio, cCodTrans, mSaldoAsignado, mSaldoTotal, iPzas, mMontos, iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal, cCajaGral, cDescripcion;
		END IF;
		
		-- VALIDACIÓN DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet,dFecha, mMonto, cSucursal, cFolio, cCodTrans, mSaldoAsignado, mSaldoTotal, iPzas, mMontos, iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal, cCajaGral, cDescripcion;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,dFecha, mMonto, cSucursal, cFolio, cCodTrans, mSaldoAsignado, mSaldoTotal, iPzas, mMontos, iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal, cCajaGral, cDescripcion;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
		
			SELECT SKIP pRegistros FIRST pRecuperacion fecha, monto, sucursal, folio, codTrans, saldoAsignado, saldoTotal, pzas, montos, total_pzas, total_montos, total_saldoAsignado, total_saldoTotal, caja_general, descripcion
			INTO dFecha, mMonto, cSucursal, cFolio, cCodTrans, mSaldoAsignado, mSaldoTotal, iPzas, mMontos, iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal, cCajaGral, cDescripcion
			FROM "informix".sw_repdetalle_mensual_cajagral
			WHERE usuario_insert = pUsuario 
			AND caja_general = pCajaGral 
			AND sucursal_atm = pSucAtm
			AND fecha BETWEEN pFechaInicial AND pFechaFinal  

			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet,dFecha, mMonto, cSucursal, cFolio, cCodTrans, mSaldoAsignado, mSaldoTotal, iPzas, mMontos, iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal, cCajaGral, cDescripcion WITH RESUME;
			
		END FOREACH;				
		
		IF iRecuperacion = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet,dFecha, mMonto, cSucursal, cFolio, cCodTrans, mSaldoAsignado, mSaldoTotal, iPzas, mMontos, iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal, cCajaGral, cDescripcion;
		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '01001';
			RETURN cCodRet,dFecha, mMonto, cSucursal, cFolio, cCodTrans, mSaldoAsignado, mSaldoTotal, iPzas, mMontos, iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal, cCajaGral, cDescripcion;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Uriel Caamaño Mejia',
'FECHA 14/11/2018',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: REPORTERIA MENSUAL CAJA GENRAL',
'DESCRIPCION: SPL encargado de consultar informacion del Reportes.',
