CREATE PROCEDURE "informix".sp_caja_consulta_caja_general(pUsuario CHAR(8), pIdFuncion CHAR(10), pRegistros INTEGER, pRecuperacion INTEGER)
	RETURNING CHAR(5) AS codret,
		INTEGER AS cod_proveedor, 
		CHAR(30) AS desc_reporte,
		CHAR(3) AS plaza;
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	
	DEFINE cCodProveedor CHAR(4);
	DEFINE cDescripcion CHAR(30);
	DEFINE cPlaza CHAR(3);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	
	LET cCodProveedor = '';
	LET cDescripcion = '';
	LET cPlaza = '';

	BEGIN	
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cCodProveedor, cDescripcion, cPlaza;
		END EXCEPTION;
	
		--SET DEBUG FILE TO '/informix/jepolanco/sp_caja_consulta_caja_general.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = ''  THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cCodProveedor, cDescripcion, cPlaza;
		END IF;					
		
		-- VALIDACIÓN DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cCodProveedor, cDescripcion, cPlaza;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD		
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cCodProveedor, cDescripcion, cPlaza;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT {+INDEX ss_proveedores idx_provplaza} SKIP pRegistros FIRST pRecuperacion cod_proveedor, descripcion, plaza
			INTO cCodProveedor, cDescripcion, cPlaza
			FROM bdisuc:"informix".ss_proveedores
			LET iNoRegistros = iNoRegistros + 1;		
			
			RETURN cCodRet, cCodProveedor, UPPER(TRIM(cDescripcion)), UPPER(TRIM(cPlaza)) WITH RESUME;		
		END FOREACH;

		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cCodProveedor, cDescripcion, cPlaza;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cCodProveedor, cDescripcion, cPlaza;
		END IF;
		
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: L. Uriel Caamaño Mejia',
'FECHA: 13/11/2018',
'MODULO: Caja General',
'FUNCIONALIDAD: REPORTERIA MENSUAL CAJA GENRAL',
'DESCRIPCION: SPL que consulta Caja General para llenado de combo',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_caja_consulta_sucursal_atm(pUsuario CHAR(8), pIdFuncion CHAR(10), pPlaza CHAR(3), pTipo CHAR(1), pRegistros INTEGER, pRecuperacion INTEGER)
	RETURNING CHAR(5) AS codret,
		CHAR(4) AS NoSucAtm,
		CHAR(40) AS Descripcion;
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	
	DEFINE cNoSucursalAtm CHAR(4);
	DEFINE cDescripcion CHAR(40);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	
	LET cNoSucursalAtm = '';
	LET cDescripcion = '';

	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNoSucursalAtm, cDescripcion;
		END EXCEPTION;
	
		--SET DEBUG FILE TO '/tmp/mfinis/sp_caja_consulta_sucursal_atm.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = ''  THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNoSucursalAtm, cDescripcion;
		END IF;	

		-- VALIDACIÓN DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cNoSucursalAtm, cDescripcion;
		END IF;		

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD		
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNoSucursalAtm, cDescripcion;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

		FOREACH
			
			SELECT SKIP pRegistros FIRST pRecuperacion sucursal, nombre 
			INTO cNoSucursalAtm, cDescripcion
			FROM bdinteg:"informix".si_sucursales 
			WHERE plaza_cajagen = pPlaza AND tpo_sucursal = pTipo 
			ORDER BY sucursal DESC

			LET iNoRegistros = iNoRegistros + 1;		
			RETURN cCodRet, cNoSucursalAtm, UPPER(TRIM(cDescripcion)) WITH RESUME;	
			
		END FOREACH;
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cNoSucursalAtm, cDescripcion;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '01001';
			RETURN cCodRet, cNoSucursalAtm, cDescripcion;
		END IF;
		
	END;	
END PROCEDURE
DOCUMENT 'AUTOR: L. Uriel Caamaño Mejia',
'FECHA: 13/11/2018',
'MODULO: Caja General',
'FUNCIONALIDAD: REPORTERIA MENSUAL CAJA GENRAL',
'DESCRIPCION: SPL que consulta Caja General para llenado de combo sucursal/atm',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_caja_totrepmenscajagral(pUsuario CHAR(8), pIdFuncion CHAR(10), pCajaGral CHAR(4), pSucAtm CHAR(10), pFechaInicial DATE, pFechaFinal DATE)
    RETURNING CHAR(5) AS codret,
        INTEGER AS total;
	
    DEFINE cCodRet CHAR(5);
    DEFINE iSqlErr INTEGER;
	DEFINE iNumRegistros INTEGER;
	DEFINE iTotalPzas INTEGER;
	DEFINE mTotalMontos MONEY(16,2);
	DEFINE mTotalSaldoAsignado MONEY(16,2);
	DEFINE mTotalSaldoTotal MONEY(16,2);
	DEFINE cDescripcion CHAR(30);
	
    LET cCodRet = '00000';
    LET iSqlErr = 0;
	LET iNumRegistros = 0;
	LET iTotalPzas  = 0;
	LET mTotalMontos = 0.00;
	LET mTotalSaldoAsignado = 0.00;
	LET mTotalSaldoTotal = 0.00;
	LET cDescripcion = '';
	
    BEGIN
        
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				UPDATE "informix".status_caja_inf_reporte
				SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
				RETURN cCodRet, iNumRegistros;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_caja_totrepmenscajagral.out';
		--TRACE ON;
		
		-- SE LIMPIA TABLA POR USUARIO
		DELETE FROM "informix".status_caja_inf_reporte WHERE usuario_insert = TRIM(pUsuario);
		INSERT INTO "informix".status_caja_inf_reporte(usuario_insert,status,total,error_proceso,error) VALUES(pUsuario,'I',0,'',cCodRet);
		
		IF pUsuario = '' OR pIdFuncion = '' OR pCajaGral = '' OR pSucAtm = '' OR pFechaInicial IS NULL OR pFechaFinal IS NULL THEN
			LET cCodRet = '00003';
			UPDATE "informix".status_caja_inf_reporte
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNumRegistros;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE "informix".status_caja_inf_reporte
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNumRegistros;
		END IF;

		-- SE LIMPIA TABLA DE PASO
		DELETE FROM "informix".sw_repdetalle_mensual_cajagral WHERE usuario_insert = pUsuario;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		INSERT INTO "informix".sw_repdetalle_mensual_cajagral(caja_general, sucursal_atm, fecha ,monto ,sucursal, folio ,codTrans, saldoAsignado, saldoTotal, pzas ,montos ,usuario_insert, fecha_insert)			
		SELECT pCajaGral, pSucAtm, e.fecha_solicitud, e.monto, e.sucursal, o.folio_oper, o.cod_trans, c.saldo_asignado, c.saldo_total, pzas.pza, mont.monto, pUsuario, DATE(CURRENT)			
		FROM bdisuc:"informix".ss_mae_entradasalida e
		INNER JOIN bdisuc:"informix".ss_operaciones o ON o.folio_oper = e.folio_oper AND o.sucursal = pSucAtm AND o.fecha_operacion BETWEEN pFechaInicial AND pFechaFinal 
		INNER JOIN bdisuc:"informix".ss_cajageneral c ON c.cod_proveedor = e.cod_proveedor
		INNER JOIN (
			SELECT sucursal,folio_oper, SUM((cantidad_1 + cantidad_2 + cantidad_3 + cantidad_4 + cantidad_5 + cantidad_6)) AS pza
			FROM bdisuc:"informix".ss_operaciones
			WHERE fecha_operacion BETWEEN pFechaInicial AND pFechaFinal 
			AND sucursal = pSucAtm 
			GROUP BY sucursal,folio_oper
		)AS pzas ON pzas.folio_oper = e.folio_oper AND pzas.sucursal = pSucAtm
		INNER JOIN (
			SELECT folio_oper, cod_proveedor,sucursal, SUM(monto) AS monto
			FROM bdisuc:"informix".ss_mae_entradasalida
			WHERE fecha_solicitud BETWEEN pFechaInicial AND pFechaFinal 
			AND cod_proveedor = pCajaGral
			AND sucursal = pSucAtm 
			GROUP BY folio_oper, cod_proveedor,sucursal
		)AS mont ON mont.folio_oper = e.folio_oper AND mont.cod_proveedor = pCajaGral AND mont.sucursal = pSucAtm
		WHERE e.cod_proveedor = pCajaGral
		AND e.sucursal = pSucAtm
		AND e.fecha_solicitud BETWEEN pFechaInicial AND pFechaFinal
		ORDER BY e.fecha_solicitud;
		
		SELECT COUNT(*)
		INTO iNumRegistros
		FROM "informix".sw_repdetalle_mensual_cajagral
		WHERE usuario_insert = pUsuario 
		AND caja_general = pCajaGral 
		AND sucursal_atm = pSucAtm
		AND fecha BETWEEN pFechaInicial AND pFechaFinal;

		IF NVL(iNumRegistros,0) = 0 THEN
			LET cCodRet = '00017';
			UPDATE "informix".status_caja_inf_reporte
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNumRegistros;
		END IF;
		
		SELECT UPPER(TRIM(descripcion))
		INTO cDescripcion
		FROM bdisuc:"informix".ss_proveedores
		WHERE cod_proveedor = pCajaGral;
		
		SELECT SUM(pzas) AS total_pzas , SUM(montos) AS total_montos, SUM(saldoasignado) AS total_saldoAsignado, SUM(saldototal) AS total_saldoTotal
		INTO iTotalPzas, mTotalMontos, mTotalSaldoAsignado, mTotalSaldoTotal
		FROM "informix".sw_repdetalle_mensual_cajagral
		WHERE usuario_insert = pUsuario 
		AND caja_general = pCajaGral 
		AND sucursal_atm = pSucAtm
		AND fecha BETWEEN pFechaInicial AND pFechaFinal;
		
		UPDATE "informix".sw_repdetalle_mensual_cajagral
		SET total_pzas = iTotalPzas,
		total_montos = mTotalMontos,
		total_saldoAsignado = mTotalSaldoAsignado,
		total_saldoTotal = mTotalSaldoTotal,
		descripcion = cDescripcion
		WHERE usuario_insert = pUsuario 
		AND caja_general = pCajaGral 
		AND sucursal_atm = pSucAtm
		AND fecha BETWEEN pFechaInicial AND pFechaFinal;
		
		UPDATE "informix".status_caja_inf_reporte
		SET status = 'T', error_proceso = 'N', 
		total = iNumRegistros		
		WHERE usuario_insert = pUsuario;		
			
		RETURN cCodRet, iNumRegistros;
		
    END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Uriel Caamaño Mejia',
'FECHA: 14/11/2018',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: REPORTERIA MENSUAL CAJA GENRAL',
'DESCRIPCION: SPL encargado de consultar el detalle de los totales del reporte de caja general.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_caja_verificastatusrepmenscajagral(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5) AS codret,
		CHAR(1) AS status,
		INTEGER AS total,
		CHAR(1) AS error_proceso,
		CHAR(5) AS error;
			  
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	
	DEFINE cStatus CHAR(1);
    DEFINE iTotal INTEGER;
    DEFINE cErrorProceso CHAR(1);
    DEFINE cError CHAR(5);
	DEFINE iNumRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cStatus = '';
	LET iTotal = 0;
	LET cErrorProceso = '';
	LET cError = '';
	LET iNumRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			--LET cCodRet = '00770'; --PROCESO CON ERRORES, POR FAVOR REINTENTE NUEVAMENTE
			RETURN cCodRet,cStatus, iTotal, cErrorProceso, cError;		
		END EXCEPTION;
	 
		--SET DEBUG FILE TO '/tmp/mfinis/sp_caja_verificastatusrepmenscajagral.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cStatus, iTotal, cErrorProceso, cError;
		END IF;		
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cStatus, iTotal, cErrorProceso, cError;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
	
		SELECT status, total, error_proceso, error
		INTO cStatus, iTotal, cErrorProceso, cError
		FROM "informix".status_caja_inf_reporte WHERE usuario_insert = pUsuario;
		
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN		
			RETURN cCodRet,'I','','',''; 
		ELSE 			
			RETURN cCodRet,cStatus, iTotal, cErrorProceso, cError;
		END IF;	
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Uriel Caamaño Mejia',
'FECHA 14/11/2018',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: REPORTERIA MENSUAL CAJA GENRAL',
'DESCRIPCION: SPL encargado de consultar el estatus de la informacion del reporte mensual de entradas y salidas de caja general.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_pp_actualizacategorias (pUsuario CHAR(8), pIdFuncion CHAR(10), 
pIdCategoria SMALLINT, pAccesoGratis INTEGER, pAccesoGratisAd INTEGER, pCuota DECIMAL(14,6))
	RETURNING CHAR(5)		AS codigo_retorno;

	---DECLARACIONES   
	DEFINE cCodRet			CHAR(5); 
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);

	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';


	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_actualizacategorias.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR NVL(pIdCategoria,'') = '' OR NVL(pAccesoGratis,'') = '' OR NVL(pAccesoGratisAd,'') = '' OR NVL(pCuota,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		UPDATE bdicred:"informix".catcategoriappass SET
			acceso_gratis = pAccesoGratis, 
			acceso_gratis_ad = pAccesoGratisAd, 
			cuota = pCuota,
			usario_modif = pUsuario,
			fecha_modif = TODAY
		WHERE id_categoria = pIdCategoria;
		
		RETURN cCodRet;
		
	END
END PROCEDURE
DOCUMENT 'AUTOR: Johnattan Esquivel Sanchez',
'FECHA: 03/09/2019',
'MODULO: CREDITO',
'FUNCIONALIDAD: Mantenimiento a Tablas del Programa Priority Pass', 
'DESCRIPCION: SPL encargado de hacer el mantenimiento a Tablas del Programa Priority Pass',
