CREATE PROCEDURE "informix".sp_pp_actualizacorreo (pUsuario CHAR(8), pIdFuncion CHAR(10), 
pIdCorreo SMALLINT, pCompany CHAR(25), pEmail CHAR(100), pStatus CHAR(1), pTipoEnvio CHAR(1))
	RETURNING CHAR(5)		AS codigo_retorno;

	---DECLARACIONES   
	DEFINE cCodRet			CHAR(5); 
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE iMaximo			INTEGER;

	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET iMaximo			= 0;

	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_actualizacorreo.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR NVL(pCompany,'') = '' OR NVL(pEmail,'') = '' OR NVL(pStatus,'') = '' OR NVL(pTipoEnvio,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		
		
		IF NVL(pIdCorreo,'') = '' THEN
			SELECT MAX(id_correo)
			INTO iMaximo
			FROM bdicred:"informix".catcorreosppass;
		
			LET iMaximo = NVL(iMaximo, 0) + 1;
			
			INSERT INTO bdicred:"informix".catcorreosppass(id_correo, company, email, status, envio, usario_modif, fecha_modif) 
			VALUES(iMaximo, pCompany, pEmail, pStatus, pTipoEnvio, pUsuario, TODAY);
			
		ELSE
			UPDATE bdicred:"informix".catcorreosppass SET
				email = pEmail, 
				company = pCompany, 
				status = pStatus,
				usario_modif = pUsuario,
				envio = pTipoEnvio,
				fecha_modif = TODAY
			WHERE id_correo = pIdCorreo;
		END IF;
		
		RETURN cCodRet;
		
	END
END PROCEDURE
