CREATE PROCEDURE "informix".sp_pp_cargaarchivomensual_genrep(pUsuario CHAR(8), pIdFuncion CHAR(10), pRutaDescarga CHAR(150),
pNombreReporte CHAR(70), fecha_reporte CHAR(8))
		RETURNING CHAR(5) AS codret,
		CHAR(150) AS archivo_generado;		

	DEFINE cCodRet 		CHAR(5);
	DEFINE iSqlErr 		INTEGER;
	DEFINE cIsamErr	INTEGER;
	DEFINE cDescErr	CHAR(50);	
	DEFINE cCmd1 CHAR(3000);	
	DEFINE cReporteGenerar CHAR(150);
	DEFINE cBinesElimina CHAR(150);
	DEFINE cNombreArchivo CHAR(150);
	--DEFINE cRuta CHAR(80);
	DEFINE cRutaInformix CHAR(100);
	DEFINE cUsrBin CHAR(100);
	DEFINE cSql CHAR(3000);
	DEFINE bInTransaction BOOLEAN;
	DEFINE ven_transacc SMALLINT;

	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cIsamErr = 0;
	LET cDescErr = '';
	LET cCmd1 = '';	
	LET cNombreArchivo = 'BanCoppel_Mexico_13798_MC_Platinum_70012513798_LV_Report_'||TRIM(fecha_reporte)||'.xls';	
	LET cReporteGenerar = TRIM(pRutaDescarga) ||cNombreArchivo;	
	--LET cArchDescarga = '';
	--LET cRuta = '/tmp/mfinis/prioritypass/';
	LET cRutaInformix = '/informix/bin/';
	LET cUsrBin = '/usr/bin/';
	LET cSql = '';
	LET bInTransaction = 'f';
	LET ven_transacc = 0;

	BEGIN

		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				
				IF ven_transacc = 1 THEN
					ROLLBACK WORK;		
				END IF;
				
				RETURN cCodRet, cNombreArchivo;
			END IF;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668,-535,-255)			
			LET bInTransaction = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;	

		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_cargaarchivomensual_genrep.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR pRutaDescarga = '' OR pNombreReporte = '' THEN
			LET cCodRet = '00003';			
			RETURN cCodRet, cNombreArchivo;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNombreArchivo;
		END IF;
			
		BEGIN WORK;
		LET ven_transacc = 1;	
		LET cCmd1 = "";
		LET cCmd1 = "SELECT 'Item','Bank','Deal Type','Associate Code','ICA','Priority Pass Id','Cardholder Name','Visit','Lounge Name','Lounge Code','Domestic or INT','ISO Country','Visit ISO Country Code','Members Count',"|| 
		"'Guests Count','Total Visit Count','Batch','Voucher Number','MC Billing Region of Issue','Total FREE Guests','Total Chargeable Guests'"||
		'FROM systables WHERE tabid = 1 UNION ALL '|| " SELECT t.id::CHAR(10),t.banco,t.tipo_producto,t.codigo_asociado,t.num_ica,''''||t.numtarjeta_ppass,t.nombre_tarjetappass,t.fecha_visita::CHAR(10),t.nombre_lounge,t.codigo_lounge, " ||
		" t.dom_int,t.pais_visita,t.id_pais_visita, t.totalpp_deslizada::CHAR(11),t.total_invitados::CHAR(11),t.total_visitas::CHAR(11),t.grupo_voucher::CHAR(11),t.numero_voucher,t.region_cuenta,t.total_gratis_inv::CHAR(11), "||
		" t.total_cargos_inv::CHAR(11)  FROM  (SELECT id,banco,tipo_producto,codigo_asociado,num_ica,numtarjeta_ppass,nombre_tarjetappass,fecha_visita,nombre_lounge,codigo_lounge,dom_int,pais_visita,id_pais_visita, " ||
		" totalpp_deslizada,total_invitados,total_visitas,grupo_voucher,numero_voucher,region_cuenta,total_gratis_inv,total_cargos_inv " ||
		" FROM bdicred:sd_movmes_ppass "||
		'WHERE nombre_archivo = ' || "'" || TRIM(pNombreReporte) ||"'" || " order by id ) t";					
		 
		LET cSql = ''; 
		LET cSql = TRIM(cUsrBin)|| 'echo "SET ISOLATION TO DIRTY READ;UNLOAD TO  '||TRIM(cReporteGenerar)|| ' DELIMITER '|| '''	'''|| ' ' || trim(cCmd1)||'" > '|| TRIM(pRutaDescarga) ||'query.sql';
		SYSTEM TRIM(cSql);
	
		LET cSql = '';
		LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(pRutaDescarga)||'query.sql';
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = TRIM(cRutaInformix)||'dbaccess bdicnweb '||TRIM(pRutaDescarga)||'query.sql';
		SYSTEM TRIM(cSql);
		
		-- Eliminamos el archivo query.sql
		--LET cSql = '';
		--LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(pRutaDescarga)||'query.sql';
		--SYSTEM TRIM(cSql);
		
		-- Se manipula el archivo para agregar el salto de lÃÂ­nea
		LET cSql = '';
		LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cReporteGenerar);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cReporteGenerar)||" > "||TRIM(cReporteGenerar)||".tmp";
		SYSTEM TRIM(cSql);
		
		-- Eliminamos el archivo original
		LET cSql = '';
		LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cReporteGenerar);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cReporteGenerar)||".tmp";
		SYSTEM TRIM(cSql);
		
		-- Eliminamos el caracter delimitador ';' al final de la lÃÂ­nea
		LET cSql = '';
		LET cSql =  "sed 's/..$//g' "||TRIM(cReporteGenerar)||".tmp > "||TRIM(cReporteGenerar);
		SYSTEM TRIM(cSql);
		
		-- Se manipula el archivo para agregar el salto de lÃÂ­nea
		LET cSql = '';
		LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cReporteGenerar);
		SYSTEM TRIM(cSql);
							
		LET cSql = '';
		LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cReporteGenerar)||" > "||TRIM(cReporteGenerar)||".tmp";
		SYSTEM TRIM(cSql);
						
		LET cSql = '';
		LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cReporteGenerar)||".tmp";
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cReporteGenerar)||'; /usr/bin/mv '||TRIM(cReporteGenerar)||'.tmp '||TRIM(cReporteGenerar);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cReporteGenerar);
		SYSTEM TRIM(cSql);
	
		COMMIT WORK;		
		
		LET ven_transacc = 0;
		IF bInTransaction = 't' THEN
			BEGIN WORK;
		END IF;
		
		RETURN cCodRet, cNombreArchivo;

	END;

END PROCEDURE
