CREATE PROCEDURE "informix".sp_pp_cargaarchivoprioritypass(pUsuario CHAR(8), pIdFuncion CHAR(10), 
pFecha_Aplicacion DATE, pNombreArchivo CHAR(80),  pBloqueInf CHAR(2000), pIteracion CHAR(1))
	RETURNING CHAR(5) AS codret; 
	
	DEFINE cCodRet CHAR(5);
	DEFINE cSqlerr INTEGER;
	DEFINE cIsamErr	INTEGER;
	DEFINE cDescErr	CHAR(50);
	DEFINE cEmpresa CHAR(3);
	DEFINE cRegistro LVARCHAR;
	DEFINE cBloqueInf2 LVARCHAR;
	DEFINE iContador INTEGER;
	
	DEFINE iIdItem INTEGER;
	DEFINE cBank CHAR(30);
	DEFINE cDealType CHAR(15);
	DEFINE cAssociate CHAR(6);
	DEFINE cIca CHAR(5);
	DEFINE cPriorityId CHAR(20);
	DEFINE cHoldName CHAR(30);
	DEFINE dVisit CHAR(10);
	DEFINE cLounName CHAR(65);
	DEFINE cLoungeCode CHAR(6);
	DEFINE cDomesticInt CHAR(1);
	DEFINE cIsoCountry CHAR(30);
	DEFINE cVisitIso CHAR(3);
	DEFINE iMembersCout INTEGER;	
	DEFINE iGuestsCount INTEGER;
	DEFINE iTotalVisitCount INTEGER;
	DEFINE iBatch INTEGER;
	DEFINE cVoucherNumber CHAR(50);
	DEFINE cMBilling CHAR(30);
	DEFINE iTotalFreeGuest INTEGER;
	DEFINE iTotalChargeableGuests INTEGER;
	DEFINE iTotalVisitasAnual INTEGER;
	DEFINE iExisteArchivo INTEGER;
	
	DEFINE cDia CHAR(2);
	DEFINE cMes CHAR(3);
	DEFINE cAnio CHAR(2);
	
	LET cCodRet = '00000';
	LET cSqlerr = 0;
	LET cIsamErr = 0;
	LET cDescErr = '';
	LET cEmpresa = '001';
	LET cRegistro = '';
	LET cBloqueInf2 = '';
	LET iContador = 0;
	
	LET iIdItem = 0;
	LET cBank = '';
	LET cDealType = '';
	LET cAssociate = '';
	LET cIca = '';
	LET cPriorityId = '';
	LET cHoldName = '';
	LET dVisit = '';
	LET cLounName = '';
	LET cLoungeCode = '';
	LET cDomesticInt = '';
	LET cIsoCountry = '';
	LET cVisitIso = '';
	LET iMembersCout = 0;	
	LET iGuestsCount = 0;
	LET iTotalVisitCount = 0;
	LET iBatch = 0;
	LET cVoucherNumber = '';
	LET cMBilling = '';
	LET iTotalFreeGuest = 0;
	LET iTotalChargeableGuests = 0;
	LET iTotalVisitasAnual = 0;
	LET iExisteArchivo = 0;
	
	LET cDia = '';
	LET cMes = '';
	LET cAnio = '';
	
	
	BEGIN
		
		ON EXCEPTION SET cSqlerr, cIsamErr, cDescErr
			IF cSqlerr <> 0 THEN
				LET cCodRet = cSqlerr;
				RETURN cCodRet; 
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO 'sp_pp_cargaarchivoprioritypass.out';
		--TRACE ON;		
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFecha_Aplicacion IS NULL OR pNombreArchivo = '' OR pBloqueInf = '' OR pIteracion = '' THEN
			LET cCodRet = '00003';			
			RETURN cCodRet; 
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- SE LIMPIA TABLA
		IF pIteracion = '0' THEN
			DELETE FROM bdicred:"informix".sd_movmes_ppass WHERE nombre_archivo = pNombreArchivo;			
		END IF;
		
		SELECT COUNT(*)
			INTO iExisteArchivo
		FROM bdicnweb:"informix".sd_bitacora_cargaarchivo_ppass 
		WHERE  nombre_archivo = pNombreArchivo;
		
		IF iExisteArchivo = 0 THEN
			INSERT INTO bdicnweb:"informix".sd_bitacora_cargaarchivo_ppass(fecha_aplicacion,fecha_alta,fecha_modif,nombre_archivo,usuario_modif)
			VALUES (pFecha_Aplicacion, CURRENT, null, pNombreArchivo,pUsuario);
		ELSE
			UPDATE bdicnweb:"informix".sd_bitacora_cargaarchivo_ppass SET fecha_aplicacion = pFecha_Aplicacion, fecha_modif = CURRENT, usuario_modif = pUsuario
			WHERE nombre_archivo = pNombreArchivo;
		END IF;
		
		FOREACH
			
			EXECUTE PROCEDURE "informix".sp_split_cadena(pBloqueInf, '|')
			INTO cBloqueInf2
			
			LET cBloqueInf2 = TRIM(cBloqueInf2)||'+';
			LET cRegistro = '';
			LET iContador = 0;
			
			FOREACH
			
				EXECUTE PROCEDURE "informix".sp_split_cadena(cBloqueInf2, '+')
				INTO cRegistro
			
				LET iContador = iContador + 1;
				
				IF iContador = 1 THEN
					LET iIdItem = cRegistro;
				ELIF iContador = 2 THEN
					LET cBank = TRIM(cRegistro);
				ELIF iContador = 3 THEN
					LET cDealType = TRIM(cRegistro);
				ELIF iContador = 4 THEN
					LET cAssociate = TRIM(cRegistro);
				ELIF iContador = 5 THEN
					LET cIca = TRIM(cRegistro);
				ELIF iContador = 6 THEN
					LET cPriorityId = TRIM(cRegistro);
				ELIF iContador = 7 THEN
					LET cHoldName = TRIM(cRegistro);
				ELIF iContador = 8 THEN
					LET dVisit = cRegistro;
				ELIF iContador = 9 THEN
					LET cLounName = TRIM(cRegistro);
				ELIF iContador = 10 THEN
					LET cLoungeCode = TRIM(cRegistro);
				ELIF iContador = 11 THEN
					LET cDomesticInt = TRIM(cRegistro);
				ELIF iContador = 12 THEN
					LET cIsoCountry = TRIM(cRegistro);				
				ELIF iContador = 13 THEN
					LET cVisitIso = TRIM(cRegistro);
				ELIF iContador = 14 THEN
					LET iMembersCout = cRegistro;				
				ELIF iContador = 15 THEN
					LET iGuestsCount = cRegistro;
				ELIF iContador = 16 THEN
					LET iTotalVisitCount = cRegistro;
				ELIF iContador = 17 THEN
					LET iBatch = cRegistro;
				ELIF iContador = 18 THEN
					LET cVoucherNumber = TRIM(cRegistro);
				ELIF iContador = 19 THEN
					LET cMBilling = TRIM(cRegistro); 
				ELIF iContador = 20 THEN
					LET iTotalFreeGuest = cRegistro;
				ELIF iContador = 21 THEN
					LET iTotalChargeableGuests = cRegistro;			
				END IF;								
			
			END FOREACH;
			
			INSERT INTO bdicred:"informix".sd_movmes_ppass(id, banco, tipo_producto, codigo_asociado, num_ica, numtarjeta_ppass, nombre_tarjetappass, fecha_visita, nombre_lounge, codigo_lounge, dom_int, pais_visita, id_pais_visita, totalpp_deslizada, total_invitados, total_visitas, grupo_voucher, numero_voucher, region_cuenta, total_gratis_inv, total_cargos_inv, total_visitas_anual, nombre_archivo, usario_modif, fecha_modif) 
			VALUES(iIdItem, cBank, cDealType, cAssociate, cIca, cPriorityId, cHoldName, dVisit, cLounName, cLoungeCode, cDomesticInt, cIsoCountry, cVisitIso, iMembersCout, iGuestsCount, iTotalVisitCount, iBatch, cVoucherNumber, cMBilling, iTotalFreeGuest, iTotalChargeableGuests, iTotalVisitasAnual, pNombreArchivo, pUsuario, CURRENT);			
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '00282'; --ERROR AL GUARDAR EL REGISTRO
			END IF;
			
		END FOREACH;
		
		RETURN cCodRet;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil C.',
'FECHA: 02/09/2019',
'MODULO: CREDITO',
'FUNCIONALIDAD: CARGA ARCHIVO PRIORITY PASS', 
'DESCRIPCION: SPL encargado de hacer la carga del contenido del archivo a la tabla de paso.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_pp_combocategoriapp(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5)	AS codigo_retorno,
			  SMALLINT 	AS categoria;

	---DECLARACIONES   
	DEFINE cCodRet			CHAR(5); 
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE sCategoria		SMALLINT;
    DEFINE iRecuperacion 	INTEGER;

	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET sCategoria		= 0;
	LET iRecuperacion	= 0;

	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet, sCategoria;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_combocategoriapp.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, sCategoria;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, sCategoria;
		END IF;

		
		FOREACH
			SELECT id_categoria
			INTO sCategoria
			FROM bdicred:"informix".catcategoriappass
			ORDER BY id_categoria ASC
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, sCategoria WITH RESUME;
			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, sCategoria;
		END IF;	 	
		
	END
END PROCEDURE
DOCUMENT 'AUTOR: Johnattan Esquivel Sanchez',
'FECHA: 10/01/2020',
'MODULO: CREDITO',
'FUNCIONALIDAD: Mantenimiento a Cuentas Priority Pass', 
