CREATE PROCEDURE "informix".sp_pp_comboestatuspp(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5)	AS codigo_retorno,
			  CHAR(1)	AS clave_status,
			  CHAR(40)  AS descripcion;

	---DECLARACIONES   
	DEFINE cCodRet		CHAR(5); 
	DEFINE iSqlErr		INTEGER;
	DEFINE iIsamErr		INTEGER;
	DEFINE cErrorInfo	CHAR(80);

	DEFINE iRecuperacion INTEGER;
	DEFINE cClaveStatus	 CHAR(1);
	DEFINE cDescripcion  CHAR(40);
    
	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET iRecuperacion	= 0;
	LET cClaveStatus	= '';
	LET cDescripcion	= '';
    
	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cClaveStatus, cDescripcion;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_comboestatuspp.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cClaveStatus, cDescripcion;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cClaveStatus, cDescripcion;
		END IF;
		
		FOREACH
		
			SELECT clave_status, descripcion
			INTO cClaveStatus, cDescripcion
			FROM bdicnweb:"informix".sw_statusppass
			WHERE status = '1'
			ORDER BY clave_status ASC
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, cClaveStatus, cDescripcion WITH RESUME;
			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cClaveStatus, cDescripcion;
		END IF;
		
	END
END PROCEDURE
DOCUMENT 'AUTOR: Johnattan Esquivel Sanchez',
'FECHA: 22/08/2019',
'MODULO: CREDITO',
'FUNCIONALIDAD: Mantenimiento a Cuentas Priority Pass', 
'DESCRIPCION: SPL encargado de hacer el mantenimiento a la solicitud de plastico Priority Pass',
