CREATE PROCEDURE "informix".sp_pp_combotarjetaspp(pUsuario CHAR(8), pIdFuncion CHAR(10), pNumCredito CHAR(20))
	RETURNING CHAR(5)	AS codigo_retorno,
			  CHAR(20) 	AS tarjetas_pp,
			  CHAR(20) 	AS num_tarjeta,
			  CHAR(30) 	AS nombre,
			  DATE 		AS expiracion,
			  CHAR(1)  	AS status_tar,
			  CHAR(1)	AS tipo_tarjeta,
			  SMALLINT 	AS categoria;

	---DECLARACIONES   
	DEFINE cCodRet			CHAR(5); 
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);

	DEFINE cTipoTarjeta		CHAR(1);
	DEFINE cTarjetasPp		CHAR(20);
	DEFINE cNumTarjeta		CHAR(20);
	DEFINE cNombre			CHAR(30);
	DEFINE dExpiracion		DATE;
	DEFINE cStatusTar		CHAR(1);
	DEFINE sCategoria		SMALLINT;
    DEFINE iRecuperacion 	INTEGER;

	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET cTipoTarjeta	= '';
	LET cTarjetasPp		= '';
	LET cNumTarjeta		= '';
	LET cNombre			= '';
	LET dExpiracion		= DATE(1);
	LET cStatusTar		= '';
	LET sCategoria		= 0;
	LET iRecuperacion	= 0;

	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cTarjetasPp, cNumTarjeta, cNombre, dExpiracion, cStatusTar, cTipoTarjeta, sCategoria;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_combotarjetaspp.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR NVL(pNumCredito,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cTarjetasPp, cNumTarjeta, cNombre, dExpiracion, cStatusTar, cTipoTarjeta, sCategoria;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cTarjetasPp, cNumTarjeta, cNombre, dExpiracion, cStatusTar, cTipoTarjeta, sCategoria;
		END IF;

		
		FOREACH
			SELECT A.tipo_tarjeta, A.num_tarjeta, A.numtarjeta_ppass, A.status_tar, A.expiracion, A.nombre, A.categoria
			INTO cTipoTarjeta, cNumTarjeta, cTarjetasPp, cStatusTar, dExpiracion, cNombre, sCategoria
			FROM bdicred:"informix".sd_tarjeta_ppass AS A 
			WHERE A.num_credito = pNumCredito
			ORDER BY A.numtarjeta_ppass ASC
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, cTarjetasPp, cNumTarjeta, cNombre, dExpiracion, cStatusTar, cTipoTarjeta, sCategoria WITH RESUME;
			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cTarjetasPp, cNumTarjeta, cNombre, dExpiracion, cStatusTar, cTipoTarjeta, sCategoria;
		END IF;	 	
		
	END
END PROCEDURE
