CREATE PROCEDURE "informix".sp_pp_consultacategorias(pUsuario CHAR(8), pIdFuncion CHAR(10), pRegistros INTEGER, pRecuperacion INTEGER)
	RETURNING CHAR(5)		AS codigo_retorno,
			  SMALLINT		AS id_categoria,
			  INTEGER		AS acceso_gratis_ad,
			  INTEGER		AS acceso_gratis,
			  DECIMAL(14,6)	AS cuota;

	---DECLARACIONES   
	DEFINE cCodRet			CHAR(5); 
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cEmpresa			CHAR(3);
	DEFINE sIdCategoria		SMALLINT;
	DEFINE iAccesoGratisAd	INTEGER;
	DEFINE iAccesoGratis	INTEGER;
	DEFINE dCuota			DECIMAL(14,6);
	DEFINE iRecuperacion 	INTEGER;

	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET cEmpresa		= '001';
	
	LET sIdCategoria	= 0;
	LET iAccesoGratisAd	= 0;
	LET iAccesoGratis	= 0;
	LET dCuota			= 0;
	LET iRecuperacion 	= 0;
	
	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet, sIdCategoria, iAccesoGratisAd, iAccesoGratis, dCuota;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_consultacategorias.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, sIdCategoria, iAccesoGratisAd, iAccesoGratis, dCuota;
		END IF;
		
		-- VALIDACION DE LA PAGINACION
		IF pRegistros < 0 OR pRecuperacion < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, sIdCategoria, iAccesoGratisAd, iAccesoGratis, dCuota;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, sIdCategoria, iAccesoGratisAd, iAccesoGratis, dCuota;
		END IF;
		
		FOREACH
		
			SELECT SKIP pRegistros FIRST pRecuperacion id_categoria, acceso_gratis, acceso_gratis_ad, cuota 
			INTO sIdCategoria, iAccesoGratis, iAccesoGratisAd, dCuota
			FROM bdicred:"informix".catcategoriappass
			ORDER BY id_categoria ASC
		
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, sIdCategoria, iAccesoGratisAd, iAccesoGratis, dCuota WITH RESUME;
			
		END FOREACH;
		
		IF iRecuperacion = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, sIdCategoria, iAccesoGratisAd, iAccesoGratis, dCuota;
		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, sIdCategoria, iAccesoGratisAd, iAccesoGratis, dCuota;
		END IF;	
		
	END
END PROCEDURE
