	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET cEmpresa		= '001';
	
	LET sIdCorreo		= 0;
	LET cCompany		= '';
	LET cEmail			= '';
	LET cStatus			= '';
	LET cDescEnvio			= '';
	LET iRecuperacion 	= 0;
	
	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet, sIdCorreo, cCompany, cEmail, cStatus, cDescEnvio;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_consultacorreos.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
