		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, sIdCorreo, cCompany, cEmail, cStatus, cDescEnvio;
		END IF;
		
		-- VALIDACION DE LA PAGINACION
		IF pRegistros < 0 OR pRecuperacion < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, sIdCorreo, cCompany, cEmail, cStatus, cDescEnvio;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, sIdCorreo, cCompany, cEmail, cStatus, cDescEnvio;
		END IF;
		
		FOREACH
		
			SELECT SKIP pRegistros FIRST pRecuperacion A.id_correo, A.email, A.company, A.status, B.descripcion_envio
			INTO sIdCorreo, cEmail, cCompany, cStatus, cDescEnvio
			FROM bdicred:"informix".catcorreosppass AS A 
			INNER JOIN bdicred:"informix".tipo_envio AS B ON B.id_envio = A.envio 
			ORDER BY A.id_correo ASC
		
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, sIdCorreo, cCompany, cEmail, cStatus, cDescEnvio WITH RESUME;
			
