		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, sIdCorreo, cCompany, cEmail, cStatus, cDescEnvio;
		END IF;	
		
		
	END
