CREATE PROCEDURE "informix".sp_pp_consultarchivoscarga(pUsuario CHAR(8), pIdFuncion CHAR(10), 
pFechaInicio DATE, pFechaFin DATE, pRegistros INTEGER, pRecuperacion INTEGER)
	RETURNING CHAR(5)  AS codigo_retorno,
			  CHAR(10) AS fecha_aplicacion,
			  CHAR(10) AS fecha_alta,
			  CHAR(10) AS fecha_modificacion,
			  CHAR(70) AS nombre_archivo,
			  CHAR(8)  AS id_usuario;			  

	---DECLARACIONES   
	DEFINE cCodRet		CHAR(5); 
	DEFINE iSqlErr		INTEGER;
	DEFINE iIsamErr		INTEGER;
	DEFINE cErrorInfo	CHAR(80);

	DEFINE iRecuperacion 	INTEGER;
	DEFINE cFechaAplicacion CHAR(10);
	DEFINE cFechaAlta 		CHAR(10);
	DEFINE cFechaMod 		CHAR(10);
	DEFINE cNombreArchivo   CHAR(70);
	DEFINE cIdUsuario 		CHAR(8);		
    
	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET iRecuperacion	= 0;
	LET cFechaAplicacion = '';
	LET cFechaAlta = '';
	LET cFechaMod = '';
	LET cNombreArchivo = '';
	LET cIdUsuario = '';
    

	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cFechaAplicacion, cFechaAlta, cFechaMod, cNombreArchivo, cIdUsuario;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_consultarchivoscarga.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR pFechaInicio IS NULL OR pFechaFin IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cFechaAplicacion, cFechaAlta, cFechaMod, cNombreArchivo, cIdUsuario;
		END IF;
		
		-- VALIDACION DE LA PAGINACION
		IF pRegistros < 0 OR pRecuperacion < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cFechaAplicacion, cFechaAlta, cFechaMod, cNombreArchivo, cIdUsuario;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cFechaAplicacion, cFechaAlta, cFechaMod, cNombreArchivo, cIdUsuario;
		END IF;
		
		FOREACH
		
			SELECT SKIP pRegistros FIRST pRecuperacion fecha_aplicacion, fecha_alta, fecha_modif, nombre_archivo, usuario_modif
			INTO cFechaAplicacion, cFechaAlta, cFechaMod, cNombreArchivo, cIdUsuario			
			FROM bdicnweb:"informix".sd_bitacora_cargaarchivo_ppass
			WHERE fecha_aplicacion >= pFechaInicio
			AND fecha_aplicacion <= pFechaFin			
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, cFechaAplicacion, cFechaAlta, cFechaMod, cNombreArchivo, cIdUsuario WITH RESUME;
			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cFechaAplicacion, cFechaAlta, cFechaMod, cNombreArchivo, cIdUsuario;
		END IF;
		
	END
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil C.',
'FECHA: 03/09/2019',
'MODULO: CREDITO',
