'MODULO: CREDITO',
'FUNCIONALIDAD: Carga Archivo Priority Pass',
'DESCRIPCION: SP que consulta el total de archivos cargados de movimientos de cliente',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_pp_consultastatusprogpp(pUsuario CHAR(8), pIdFuncion CHAR(10), pNumCredito CHAR(20))
	RETURNING CHAR(5)	AS codigo_retorno,
			  CHAR(1)	AS status;

	---DECLARACIONES   
	DEFINE cCodRet		CHAR(5); 
	DEFINE iSqlErr		INTEGER;
	DEFINE iIsamErr		INTEGER;
	DEFINE cErrorInfo	CHAR(80);
	DEFINE iRecuperacion INTEGER;
	DEFINE cClaveStatus	 CHAR(1);
    
	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET iRecuperacion	= 0;
	LET cClaveStatus	= '';
    
	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cClaveStatus;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_consultastatusprogpp.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cClaveStatus;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cClaveStatus;
		END IF;
		IF (SELECT COUNT(*) FROM bdicred:"informix".sd_tarjeta_ppass WHERE num_credito = pNumCredito ) = 0 THEN 
			LET cCodRet = '00017';
		ELSE
			SELECT FIRST 1 status_progppass 
			INTO cClaveStatus 
			FROM bdicred:"informix".sd_tarjeta_ppass 
			WHERE num_credito = pNumCredito;
		END IF;
		
		RETURN cCodRet, cClaveStatus;
		
	END
END PROCEDURE
