CREATE PROCEDURE "informix".sp_pp_generareportedetallemovimientos(pUsuario CHAR(8), pIdFuncion CHAR(10), 
pInicio DATE, pFin DATE, pTarjeta CHAR(20), pRuta CHAR(100), pDolares CHAR(3))
	RETURNING CHAR(5)	AS codigo_retorno,
		CHAR(100) AS archivo_generado;

	---DECLARACIONES   
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cDescCodRet CHAR(80);
	DEFINE cEmpresa CHAR(3);
	DEFINE iIdRegistro INTEGER;
	DEFINE iTotal INTEGER;
	
	DEFINE iSerial INTEGER;
	DEFINE cRespMensaje CHAR(45);
	DEFINE iRegistros INTEGER;
	DEFINE cQuery CHAR(255);
	DEFINE cCmd1 CHAR(7000);
	DEFINE cSql CHAR(7500);
	DEFINE cRutaGral CHAR(150);
	DEFINE cRutaInformix CHAR(100);
	DEFINE cUsrBin CHAR(100);
	DEFINE iCountRep INTEGER;
	DEFINE iProcesaRep INT;
	DEFINE iArmaReporte INT;
	DEFINE cArchivoCP CHAR(45);
	DEFINE cCmdQuery CHAR(7000);
	DEFINE bInTransaction BOOLEAN;
	DEFINE ven_transacc SMALLINT;
	DEFINE dFechaHora DATETIME YEAR TO FRACTION(5);
	DEFINE cReporte CHAR(100);
	DEFINE cNombreArchivo CHAR(100);
	DEFINE iRecuperacion INTEGER;
	
	DEFINE cCategoria CHAR(1);
	DEFINE iAccGratis INTEGER;
	DEFINE iViTitular INTEGER;
	DEFINE iViTitularAd INTEGER;
	DEFINE iTotalVi INTEGER;
	DEFINE iViSinCosto INTEGER;
	DEFINE iViFacturable INTEGER;
	DEFINE iTotalFacturable INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cDescCodRet = '';
	LET cEmpresa = '001';
	LET iIdRegistro = 0;
	
	LET iSerial = 0;
	LET cRespMensaje = '';
	LET iRegistros = 0;
	LET cQuery = '';
	LET cCmd1 = '';
	LET cSql = '';
	LET cRutaGral = '';
	LET cRutaInformix = '/informix/bin/';
	LET cUsrBin = '/usr/bin/';
	LET iCountRep = 0;
	LET iProcesaRep = 0;
	LET iArmaReporte = 0;
	LET cArchivoCP = '';
	LET cCmdQuery = '';
	LET bInTransaction = 'f';
	LET ven_transacc = 0;
	LET dFechaHora = CURRENT YEAR TO FRACTION(5);
	LET cReporte = '';
	LET cNombreArchivo = '';
	LET iRecuperacion = 0;
	LET iTotal = 0;
	
	LET cCategoria = '';
	LET iAccGratis = 0;
	LET iViTitular = 0;
	LET iViTitularAd = 0;
	LET iTotalVi = 0;
	LET iViSinCosto = 0;
	LET iViFacturable = 0;
	LET iTotalFacturable = 0;
	
	
	BEGIN

		ON EXCEPTION SET iSqlErr
				LET cCodRet = iSqlErr;
				
				IF ven_transacc = 1 THEN
					ROLLBACK WORK; --		
				END IF;
				
				RETURN cCodRet,cNombreArchivo;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bInTransaction = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_generareportedetallemovimientos.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR NVL(pTarjeta,'') = '' OR pInicio IS NULL OR pFin IS NULL OR NVL(pRuta,'') = '' OR NVL(pDolares,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		-- SE DEFINE NOMENCLATURA DEL REPORTE
		LET pRuta = TRIM(pRuta) || '/';
		LET cReporte = 'DETALLE_MOVIMIENTOS_PRIORITY_PASS_'||TO_CHAR(CURRENT, '%Y%m%d')||'_'||TO_CHAR(CURRENT, '%H%M');
		LET cRutaGral = TRIM(pRuta)||TRIM(cReporte)||'.xls';
		LET cNombreArchivo = TRIM(cReporte)||'.xls';
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT FIRST 1 categoria INTO cCategoria
		FROM bdicred:"informix".sd_tarjeta_ppass
		WHERE numtarjeta_ppass = pTarjeta;
		
		SELECT acceso_gratis INTO iAccGratis
		FROM bdicred:"informix".catcategoriappass
		WHERE id_categoria = cCategoria;
		
		SELECT COUNT(*) INTO iTotal
		FROM bdicred:"informix".sd_movmes_ppass
		WHERE numtarjeta_ppass = pTarjeta AND fecha_visita BETWEEN pInicio AND pFin;
		
		IF iTotal = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		BEGIN WORK;
			LET ven_transacc = 1;
			
			LET cCmd1 = "SELECT 'Fecha Visita', 'No. de Visitas Titular', 'No. de Visitas Adicionales', 'Total Visitas', 'No. Visitas sin Costo', 'No. Visitas Facturables', 'Total Facturable' FROM systables WHERE tabid = 1 UNION ALL ";
			LET cCmd1 = "" || TRIM(cCmd1)|| " SELECT * FROM (SELECT TO_CHAR(A.fecha_visita, '%d/%m/%Y'), TO_CHAR(A.totalpp_deslizada), TO_CHAR(A.total_invitados), TO_CHAR(A.total_visitas),";
			LET cCmd1 = "" || TRIM(cCmd1)|| " TO_CHAR((CASE WHEN ("||iAccGratis||" >= A.total_visitas) THEN 0 ELSE "||iAccGratis||" END)) AS vi_sinc,";
			LET cCmd1 = "" || TRIM(cCmd1)|| " TO_CHAR((CASE WHEN ("||iAccGratis||" >= A.total_visitas) THEN 0 ELSE (A.total_visitas - "||iAccGratis||") END)) AS vi_fact,";
			LET cCmd1 = "" || TRIM(cCmd1)|| " TO_CHAR(((CASE WHEN ("||iAccGratis||" >= A.total_visitas) THEN 0 ELSE (A.total_visitas - "||iAccGratis||") END) *";
			LET cCmd1 = "" || TRIM(cCmd1)|| " NVL((SELECT precio_venta FROM bdinteg:""informix"".si_histdiv WHERE fecha_tc = A.fecha_visita AND divisa = '02'";
			LET cCmd1 = "" || TRIM(cCmd1)|| " AND hora_tc = (SELECT MAX(hora_tc) FROM bdinteg:""informix"".si_histdiv WHERE fecha_tc = A.fecha_visita AND divisa = '02')), 0) * "|| pDolares ||")) AS total_facturable";
			LET cCmd1 = "" || TRIM(cCmd1)|| " FROM bdicred:""informix"".sd_movmes_ppass AS A WHERE A.numtarjeta_ppass = '"||pTarjeta||"' AND A.fecha_visita BETWEEN '"||pInicio||"' AND '"||pFin||"' ORDER BY A.fecha_visita ASC)";
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cRutaGral)|| ' DELIMITER '|| '''	'''|| ' ' ||TRIM(cCmd1)||' " > '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cRutaInformix)||'dbaccess bdicnweb '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el archivo query.sql
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			-- Se manipula el archivo para agregar el salto de lÃÂ­nea
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGral)||" > "||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el archivo original
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el caracter delimitador ';' al final de la lÃÂ­nea
			LET cSql = '';
			LET cSql =  "sed 's/..$//g' "||TRIM(cRutaGral)||".tmp > "||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			-- Se manipula el archivo para agregar el salto de lÃÂ­nea
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
								
			LET cSql = '';
			LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGral)||" > "||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
							
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cRutaGral)||'; /usr/bin/mv '||TRIM(cRutaGral)||'.tmp '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
		COMMIT WORK;
		
		LET ven_transacc = 0;
		IF bInTransaction = 't' THEN
			BEGIN WORK;
		END IF;		
		
		RETURN cCodRet,cNombreArchivo;
		
	END
END PROCEDURE
DOCUMENT 'AUTOR: Johnattan Esquivel Sanchez',
'FECHA: 05/09/2019',
'MODULO: CREDITO',
'FUNCIONALIDAD: Detalle Movimientos Priority Pass', 
'DESCRIPCION: SPL encargado de generar el reporte de Detalle Movimientos Priority Pass',
