CREATE PROCEDURE "informix".sp_pp_generareporteportafolio(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipoReporte CHAR(1), pRuta CHAR(100))
	RETURNING CHAR(5)	AS codigo_retorno,
		CHAR(100) AS archivo_generado;

	---DECLARACIONES   
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cDescCodRet CHAR(80);
	DEFINE cEmpresa CHAR(3);
	DEFINE iIdRegistro INTEGER;
	
	DEFINE iSerial INTEGER;
	DEFINE cRespMensaje CHAR(45);
	DEFINE iRegistros INTEGER;
	DEFINE cQuery CHAR(255);
	DEFINE cCmd1 CHAR(2000);
	DEFINE cSql CHAR(2500);
	DEFINE cRutaGral CHAR(150);
	DEFINE cRutaInformix CHAR(100);
	DEFINE cUsrBin CHAR(100);
	DEFINE iCountRep INTEGER;
	DEFINE iProcesaRep INT;
	DEFINE iArmaReporte INT;
	DEFINE cArchivoCP CHAR(45);
	DEFINE cCmdQuery CHAR(2500);
	DEFINE bInTransaction BOOLEAN;
	DEFINE ven_transacc SMALLINT;
	DEFINE dFechaHora DATETIME YEAR TO FRACTION(5);
	DEFINE cReporte CHAR(100);
	DEFINE cNombreArchivo CHAR(100);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cDescCodRet = '';
	LET cEmpresa = '001';
	LET iIdRegistro = 0;
	
	LET iSerial = 0;
	LET cRespMensaje = '';
	LET iRegistros = 0;
	LET cQuery = '';
	LET cCmd1 = '';
	LET cSql = '';
	LET cRutaGral = '';
	LET cRutaInformix = '/informix/bin/';
	LET cUsrBin = '/usr/bin/';
	LET iCountRep = 0;
	LET iProcesaRep = 0;
	LET iArmaReporte = 0;
	LET cArchivoCP = '';
	LET cCmdQuery = '';
	LET bInTransaction = 'f';
	LET ven_transacc = 0;
	LET dFechaHora = CURRENT YEAR TO FRACTION(5);
	LET cReporte = '';
	LET cNombreArchivo = '';
	LET iRecuperacion = 0;

	BEGIN

		ON EXCEPTION SET iSqlErr
				LET cCodRet = iSqlErr;
				
				IF ven_transacc = 1 THEN
					ROLLBACK WORK; --		
				END IF;
				
				RETURN cCodRet,cNombreArchivo;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bInTransaction = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_generareporteportafolio.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR NVL(pRuta,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		-- SE DEFINE NOMENCLATURA DEL REPORTE
		LET pRuta = TRIM(pRuta) || '/';
		IF pTipoReporte = 1 THEN 
			LET cReporte = 'MOVIMIENTOS_PRIORITY_PASS_'||TO_CHAR(CURRENT, '%d%m%Y');
		ELSE 
			LET cReporte = 'HIST_MOVIMIENTOS_PRIORITY_PASS_'||TO_CHAR(CURRENT, '%d%m%Y');
		END IF;
		LET cRutaGral = TRIM(pRuta)||TRIM(cReporte)||'.xls';
		LET cNombreArchivo = TRIM(cReporte)||'.xls';
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		BEGIN WORK;
			LET ven_transacc = 1;
			
			LET cCmd1 = "";
			
			IF pTipoReporte = 1 THEN
				LET cCmd1 = "SELECT 'Numero de Credito','Numero de Tarjeta Relacionado al Credito','Titular/Adicional','Nombre Embozado Priority Pass','Numero de Plastico Priority Pass','Estatus de Plastico','Fecha de Vigencia','Categoria','Numero de Accesos Acumulados Libres Utilizados en el Anio','Numero de Accesos Acumulados Libres por Utilizar en el Anio','Numero de Accesos Acumulados Facturados en el Anio' FROM systables WHERE tabid = 1";	
				LET cCmd1 = ""||TRIM(cCmd1)|| " UNION ALL SELECT ''''||TO_CHAR(A.num_credito), ''''||TO_CHAR(A.num_tarjeta),CASE WHEN (A.tipo_tarjeta = 'T') THEN 'Titular' ELSE 'Adicional' END AS tipo_tarjeta, A.nombre, ''''||A.numtarjeta_ppass, CASE WHEN (A.status_tar = 'A') THEN 'ACTIVA' ELSE 'CANCELADA' END AS status_tar, TO_CHAR(A.expiracion, '%d-%m-%y'), TO_CHAR(A.categoria), ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " TO_CHAR((A.accesos_adic + A.accesos)) AS accesos_usados, TO_CHAR(((C.acceso_gratis + C.acceso_gratis_ad) - (A.accesos_adic + A.accesos))) AS accesos_disponibles, ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " TO_CHAR((C.acceso_gratis + C.acceso_gratis_ad)) AS accesos_facturados ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " FROM bdicred:""informix"".sd_tarjeta_ppass AS A ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " INNER JOIN (SELECT  MAX(A.secuencia) AS secuencia, A.numcte, A.num_credito, A.num_tarjeta ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " FROM bdicred:""informix"".sd_tarjeta_ppass AS A WHERE status_tar = 'A' GROUP BY A.numcte, A.num_credito, A.num_tarjeta) ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " AS B ON A.secuencia = B.secuencia AND A.numcte = B.numcte AND A.num_credito = B.num_credito AND A.num_tarjeta = B.num_tarjeta  ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " INNER JOIN bdicred:""informix"".catcategoriappass AS C ON A.categoria = C.id_categoria ";
			ELSE
				LET cCmd1 = "SELECT 'Numero de Credito','Numero de Tarjeta Relacionado al Credito','Titular/Adicional','Nombre Embozado Priority Pass','Numero de Plastico Priority Pass','Estatus de Plastico','Fecha de Vigencia','Fecha de Cancelacion' FROM systables WHERE tabid = 1";	
				LET cCmd1 = ""||TRIM(cCmd1)|| " UNION ALL SELECT ''''||TO_CHAR(A.num_credito), ''''||TO_CHAR(A.num_tarjeta), CASE WHEN (A.tipo_tarjeta = 'T') THEN 'Titular' ELSE 'Adicional' END AS tipo_tarjeta, A.nombre, ''''||A.numtarjeta_ppass, ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " CASE WHEN (A.status_tar = 'A') THEN 'ACTIVA' ELSE 'CANCELADA' END AS status_tar, TO_CHAR(A.expiracion, '%d-%m-%y'), CASE WHEN (A.status_tar = 'A') THEN '   ' ELSE TO_CHAR(A.fecha_modif, '%d-%m-%y')  END AS fecha_modif FROM bdicred:""informix"".sd_tarjeta_ppass AS A";
				LET cCmd1 = ""||TRIM(cCmd1)|| " INNER JOIN (SELECT  MAX(A.secuencia) AS secuencia, A.numcte, A.num_credito, A.num_tarjeta FROM bdicred:""informix"".sd_tarjeta_ppass AS A GROUP BY A.numcte, A.num_credito, A.num_tarjeta) ";
				LET cCmd1 = ""||TRIM(cCmd1)|| " AS B ON A.secuencia = B.secuencia AND A.numcte = B.numcte AND A.num_credito = B.num_credito AND A.num_tarjeta = B.num_tarjeta ";
			END IF;
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cRutaGral)|| ' DELIMITER '|| '''	'''|| ' ' ||TRIM(cCmd1)||' " > '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cRutaInformix)||'dbaccess bdicnweb '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el archivo query.sql
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			-- Se manipula el archivo para agregar el salto de linea
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGral)||" > "||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el archivo original
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el caracter delimitador ';' al final de la linea
			LET cSql = '';
			LET cSql =  "sed 's/..$//g' "||TRIM(cRutaGral)||".tmp > "||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			-- Se manipula el archivo para agregar el salto de linea
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
								
			LET cSql = '';
			LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGral)||" > "||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
							
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cRutaGral)||'; /usr/bin/mv '||TRIM(cRutaGral)||'.tmp '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
		COMMIT WORK;
		
		LET ven_transacc = 0;
		IF bInTransaction = 't' THEN
			BEGIN WORK;
		END IF;
		
		RETURN cCodRet,cNombreArchivo;
		
	END
END PROCEDURE
DOCUMENT 'AUTOR: Johnattan Esquivel Sanchez',
'FECHA: 05/09/2019',
'MODULO: CREDITO',
'FUNCIONALIDAD: Portafolio Priority Pass', 
'DESCRIPCION: SPL encargado de generar el reporte de portafolios vigente e historico',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_pp_insertalayoutpp(pUsuario CHAR(8), pIdFuncion CHAR(10), pEnvio CHAR(1), 
pSucursal CHAR(4), pNumTarjeta CHAR(20), pRutaDescarga CHAR(100))
	RETURNING CHAR(5) AS codigo_retorno,
		CHAR(100) AS archivo_generado;

	---DECLARACIONES   
	DEFINE cCodRet				CHAR(5); 
	DEFINE iSqlErr				INTEGER;
	DEFINE iIsamErr				INTEGER;
	DEFINE cErrorInfo			CHAR(80);
	DEFINE cEmpresa				CHAR(3);
	
	DEFINE cNumCredito			CHAR(20);
	DEFINE cNumCte				CHAR(20);
	DEFINE cNumTarjeta			CHAR(20);
	DEFINE cNumTarjetaPP	    CHAR(20);
	DEFINE cNombreTarjeta		CHAR(20);
	DEFINE cSucursal			CHAR(4);
	DEFINE dExpiracion			DATE;
	DEFINE dMiembroDesde		DATE;
	DEFINE iMaximo				INTEGER;

	DEFINE cNombre1				CHAR(26);
	DEFINE cApellPaterno		CHAR(26);
	DEFINE cTipoTarjeta			CHAR(1);
	DEFINE cDescTipoTarjeta		CHAR(10);
	DEFINE cDomicilio			CHAR(150);
	DEFINE cDireccion1			CHAR(40); 
	DEFINE cDireccion2			CHAR(40);  
	DEFINE cCiudad 				CHAR(3); 
	DEFINE cEstado 				CHAR(2); 
	DEFINE cDescCiudad 			CHAR(30); 
	DEFINE cDescEstado 			CHAR(30);
	DEFINE cCP 					CHAR(5);	
	
	DEFINE cExtCalle 			CHAR(10);
	DEFINE cIntCalle 			CHAR(10);
	DEFINE cDepto 				CHAR(6);
	DEFINE cCalle				CHAR(40); 
	DEFINE cColonia				CHAR(60); 
	DEFINE cEnvio	    		CHAR(4);
	
	DEFINE cQuery CHAR(255);
	DEFINE cCmd1 CHAR(2000);
	DEFINE cSql CHAR(2500);
	DEFINE cRutaGral CHAR(150);
	DEFINE cRutaInformix CHAR(100);
	DEFINE cUsrBin CHAR(100);
	DEFINE cReporte CHAR(100);
	DEFINE cNombreArchivo CHAR(100);
	
	---INICIALIZACIONES
	LET iSqlErr					= 0;
	LET iIsamErr				= 0;
	LET cErrorInfo				= '';
	LET cCodRet					= '00000';

	LET cEmpresa				= '001';
	LET cNumCredito				= '';
	LET cNumCte					= '';
	LET cNumTarjeta				= '';
	LET cNombreTarjeta			= '';
	LET cSucursal				= '';
	LET dExpiracion				= DATE(1);
	LET dMiembroDesde			= DATE(1);
	LET cNombre1				= '';
	LET cApellPaterno			= '';
	LET cTipoTarjeta			= '';
	LET cDescTipoTarjeta		= '';
	LET cDomicilio				= '';
	LET cDireccion1				= '';
	LET cDireccion2				= '';
	LET cCiudad					= '';
	LET cEstado					= '';
	LET cDescCiudad 			= '';
	LET cDescEstado 			= '';
	LET iMaximo					= 0;
	LET cNumTarjetaPP	    	= '';
	LET cEnvio	    			= '';
		
	LET cExtCalle='';
	LET cIntCalle='';
	LET cDepto='';
	LET cCP ='';
	
	LET cCalle					= '';
	LET cColonia				= '';
	
	LET cQuery = '';
	LET cCmd1 = '';
	LET cSql = '';
	LET cRutaGral = '';
	LET cRutaInformix = '/informix/bin/';
	LET cUsrBin = '/usr/bin/';
	LET cReporte = '';
	LET cNombreArchivo = '';
	
	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet,cNombreArchivo;
		END EXCEPTION;
		
		--ON EXCEPTION IN (-668,-535,-255)
		--	LET bInTransaction = 't';
		--	COMMIT WORK;
		--	BEGIN WORK;
		--END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_pp_insertalayoutpp.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 4;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR NVL(pIdFuncion,'') = '' OR NVL(pEnvio,'') = '' OR pRutaDescarga = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		SELECT num_credito, numcte, num_tarjeta, expiracion, tipo_tarjeta, numtarjeta_ppass
			INTO cNumCredito, cNumCte, cNumTarjeta, dExpiracion, cTipoTarjeta, cNumTarjetaPP
		FROM bdicred:"informix".sd_tarjeta_ppass 
		--WHERE numtarjeta_ppass = pNumTarjeta;
		WHERE numcte = pNumTarjeta;
		
		SELECT nombre1, apell_paterno 
			INTO cNombre1, cApellPaterno
		FROM bdinteg:"informix".si_cliente 
		WHERE numcte = cNumCte;
		
		SELECT nombretarjeta 
			INTO cNombreTarjeta
		FROM intercard:"informix".solicitudtarjeta 
		WHERE numcuenta = cNumCredito 
		AND numcliente = cNumCte 
		AND numtarjeta = cNumTarjeta;
		
		SELECT fecha_apertura, sucursal 
			INTO dMiembroDesde, cSucursal
		FROM bdicred:sd_maecred 
		WHERE empresa = cEmpresa 
		AND num_credito = cNumCredito;
		--AND numcte = cNumCte;
		
		IF pEnvio = 'S' THEN
			LET cSucursal = pSucursal;
			LET cEnvio = 'O';
		END IF;
		
		IF pEnvio = 'O' THEN
			LET cEnvio = 'S';
		END IF;

		IF pEnvio = 'C' THEN
			LET cEnvio = pEnvio;
			SELECT sictacall.nombrecalle, sidiract.numeroextcalle, sidiract.numerointcalle, 
				sidiract.departamento, sicatzonas.nombrezona, siciudades.nombre, siedos.nombre, sidiract.cod_postal
			INTO
				cCalle, cExtCalle, cIntCalle, cDepto, cColonia,cCiudad,cEstado,cCP	
			FROM bdinteg:"informix".si_direcciones_actual AS sidiract
			LEFT JOIN bdinteg:"informix".si_catcalles AS sictacall ON sidiract.numerocalle = sictacall.numerocalle
			LEFT JOIN bdinteg:"informix".si_catzonas AS sicatzonas ON sicatzonas.numerociudad = sidiract.numerociudad AND sicatzonas.numerocolonia = sidiract.numerocolonia
			LEFT JOIN bdinteg:"informix".si_ciudades AS siciudades ON siciudades.pais = sidiract.pais AND siciudades.estado = sidiract.estado AND siciudades.ciudad = sidiract.ciudad
			LEFT JOIN bdinteg:"informix".si_estados AS siedos ON siedos.pais = sidiract.pais AND siedos.estado = sidiract.estado
			WHERE sidiract.numcte = cNumCte AND sidiract.secuencia = (SELECT MAX(secuencia) FROM bdinteg:"informix".si_direcciones_actual WHERE numcte = cNumCte AND tipo_dir = 1) AND sidiract.tipo_dir = 1; 
		
			LET cDomicilio = TRIM(NVL(cCalle,''))||' '||TRIM(NVL(cExtCalle,''))||' '||TRIM(NVL(cIntCalle,''))||' '||TRIM(NVL(cDepto,''))||' '|| TRIM(NVL(cColonia,''))||' '||TRIM(NVL(cCiudad,''))||' '||TRIM(NVL(cEstado,''))||' '||TRIM(NVL(cCP,''));
			LET cSucursal = '9999';
			
		ELSE
		
			SELECT direccion1, direccion2, ciudad, estado 
				INTO cDireccion1, cDireccion2, cCiudad, cEstado 				
			FROM bdinteg:"informix".si_sucursales 
			WHERE empresa = cEmpresa 
			AND sucursal = cSucursal;
			
			SELECT TRIM(nombre)
				INTO cDescEstado
			FROM bdinteg:"informix".si_estados
			WHERE estado = cEstado;

			SELECT TRIM(nombreciudad)
				INTO cDescCiudad
			FROM bdinteg:"informix".si_catciudades
			WHERE numerociudad = cCiudad;		
		
			LET cDomicilio = TRIM(NVL(cDireccion1,'')) || ' ' || TRIM(NVL(cDireccion2,'')) || ' ' || TRIM(NVL(cCiudad,'')) || ', ' || TRIM(NVL(cEstado,''));
			
		END IF;
		
		IF cTipoTarjeta = 'T' THEN
			LET cDescTipoTarjeta = 'Titular';
		ELSE
			LET cDescTipoTarjeta = 'Adicional';
		END IF;
		
		LET cDomicilio = TRIM(cDomicilio);
		
		SELECT MAX(id_reg)
			INTO iMaximo
		FROM bdicred:"informix".sd_info_layout_ppass;
		
		LET iMaximo = NVL(iMaximo, 0) + 1;
		
		INSERT INTO bdicred:"informix".sd_info_layout_ppass(id_reg, pan, miembro_desde, nombrecompleto, nombre_cte, apellido_cte, numcte, fecha_exp, sucursal, direccion, tipo, estatus_layout, destino, fecha_insert, usuario_modif) 
		VALUES(iMaximo, cNumTarjetaPP, dMiembroDesde, cNombreTarjeta, cNombre1, cApellPaterno, cNumCte, dExpiracion, cSucursal, cDomicilio, cDescTipoTarjeta, 'P', cEnvio, TODAY, pUsuario);
		
		IF DBINFO('sqlca.sqlerrd2') <> 0 THEN 
			
			-- SE DEFINE NOMENCLATURA DEL REPORTE
			--LET pRutaDescarga = TRIM(pRutaDescarga) || '/';
			LET cReporte = 'Solicitud_Batch_3_Priority_Pass_'||TO_CHAR(CURRENT, '%d%m%Y_%H%M%S');
			LET cRutaGral = TRIM(pRutaDescarga)||TRIM(cReporte)||'.xls';
			LET cNombreArchivo = TRIM(cReporte)||'.xls';
			
			--BEGIN WORK;
			--	LET ven_transacc = 1;
				
				LET cCmd1 ="";
				LET cCmd1 = "SELECT '#','PAN','MIEMBRO DESDE','NOMBRE COMPLETO','NOMBRE','APELLIDO','ID','FECHA EXP','SUC','DIRECCION','TIPO' FROM systables WHERE tabid = 1 UNION ALL SELECT * FROM";	
				LET cCmd1 =""||TRIM(cCmd1)||" (SELECT id_reg::CHAR(11), ''''||pan, miembro_desde::CHAR(10), nombrecompleto, nombre_cte, apellido_cte, ''''||numcte, fecha_exp::CHAR(10), ''''||sucursal, direccion, UPPER(tipo)";
				LET cCmd1 =""||TRIM(cCmd1)||" FROM bdicred:""informix"".sd_info_layout_ppass WHERE id_reg = '"||iMaximo||"')";
				
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cRutaGral)|| ' DELIMITER '|| '''	'''|| ' ' ||TRIM(cCmd1)||' " > '||TRIM(pRutaDescarga)||'query.sql';
				SYSTEM TRIM(cSql);
				
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(pRutaDescarga)||'query.sql';
				SYSTEM TRIM(cSql);
				
				LET cSql = '';
				LET cSql = TRIM(cRutaInformix)||'dbaccess bdicred '||TRIM(pRutaDescarga)||'query.sql';
				SYSTEM TRIM(cSql);
				
				-- Eliminamos el archivo query.sql
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(pRutaDescarga)||'query.sql';
				SYSTEM TRIM(cSql);
				
				-- Se manipula el archivo para agregar el salto de lÃÂ­nea
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
				SYSTEM TRIM(cSql);
				
				LET cSql = '';
				LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGral)||" > "||TRIM(cRutaGral)||".tmp";
				SYSTEM TRIM(cSql);
				
				-- Eliminamos el archivo original
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cRutaGral);
				SYSTEM TRIM(cSql);
				
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral)||".tmp";
				SYSTEM TRIM(cSql);
				
				-- Eliminamos el caracter delimitador ';' al final de la lÃÂ­nea
				LET cSql = '';
				LET cSql =  "sed 's/..$//g' "||TRIM(cRutaGral)||".tmp > "||TRIM(cRutaGral);
				SYSTEM TRIM(cSql);
				
				-- Se manipula el archivo para agregar el salto de lÃÂ­nea
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
				SYSTEM TRIM(cSql);
									
				LET cSql = '';
				LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGral)||" > "||TRIM(cRutaGral)||".tmp";
				SYSTEM TRIM(cSql);
								
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral)||".tmp";
				SYSTEM TRIM(cSql);
				
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cRutaGral)||'; /usr/bin/mv '||TRIM(cRutaGral)||'.tmp '||TRIM(cRutaGral);
				SYSTEM TRIM(cSql);
				
				LET cSql = '';
				LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
				SYSTEM TRIM(cSql);
				
			--COMMIT WORK;
			--
			--LET ven_transacc = 0;
			--IF bInTransaction = 't' THEN
			--	BEGIN WORK;
			--END IF;
			
		END IF;
		
		RETURN cCodRet,cNombreArchivo;	
		
	END
END PROCEDURE
DOCUMENT 'AUTOR: Johnattan Esquivel Sanchez',
'FECHA: 22/08/2019',
'MODULO: CREDITO',
'FUNCIONALIDAD: Mantenimiento a Cuentas Priority Pass', 
'DESCRIPCION: SPL encargado de hacer el mantenimiento a la solicitud de plastico Priority Pass',
'AUTOR: L. Montserrat LeÃÂ³n Amador',
'FECHA: 22/10/2019',
'DESCRIPCION: Se modifica spl para hacer el cambio de busqueda por nÃÂºmero de cliente (numcte) y no por tarjeta.',
'FECHA: 23/10/2019',
'DESCRIPCION: Se modifica spl para agregar generaciÃÂ³n de archivo en formato .xls.',
'BD: bdicnweb',
'FECHA: 12/11/2019',
'DESCRIPCION: Se modifica spl para obtener de manera correcta el domicilio.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_evaldispefeccred(pUsuario CHAR(8),pIdFuncion CHAR(10),pNumCredito CHAR(20),pMonto MONEY(16,2))
	RETURNING CHAR(5) AS codret,
		CHAR(3) AS porc_disp_efec,
		DECIMAL(18,2) AS monto_disp,
		CHAR(100) AS msj_disp_efec;
	 
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRet INTEGER;
	DEFINE iSqlErr INTEGER;	
	DEFINE cStatus CHAR(1);
	DEFINE cErrorProceso CHAR(1);
	DEFINE cError CHAR(5);
	DEFINE iNumRegistros INTEGER;
	DEFINE cPorc_disp_efec CHAR(3);
	--DEFINE cPorc_disp_efec CHAR(5);
	DEFINE dMonto_disp DECIMAL(18,2);
	DEFINE cMsj_disp_efec CHAR(100);
	DEFINE cEntero CHAR(3);
	DEFINE cDecimal CHAR(2);
	DEFINE dPorc_disp_efec DECIMAL(5,2);
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRet = 0;
	LET iSqlErr = 0;	
	LET cStatus = '';
	LET cErrorProceso = '';
	LET cError = '';
	LET iNumRegistros = 0;
	LET cPorc_disp_efec = '';
	LET dMonto_disp = 0.00;
	LET cMsj_disp_efec = '';
	LET cEntero = '';
	LET cDecimal = '';
	LET dPorc_disp_efec = 0.00;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cPorc_disp_efec,dMonto_disp,cMsj_disp_efec;	
		END EXCEPTION;
	 
		--SET DEBUG FILE TO '/informix/krgb/sp_evaldispefeccred.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cPorc_disp_efec,dMonto_disp,cMsj_disp_efec;
		END IF;		
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cPorc_disp_efec,dMonto_disp,cMsj_disp_efec;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;		
		
		EXECUTE PROCEDURE bdicred:"informix".sp_evaldispefec_cred(pNumCredito,pMonto)
		INTO cCodRetSp,cPorc_disp_efec,dMonto_disp,cMsj_disp_efec;
		
		LET iCodRet = cCodRetSp::INTEGER;
		IF iCodRet < 0 THEN
			RAISE EXCEPTION iCodRet, 0, 'ERROR EN LA EJECUCION DEL SP bdicred:sp_evaldispefec_cred';
		--ELIF iCodRet = 3 THEN
		--	LET cCodRet = '99999'; --NÚMERO DE CRÉDITO INVALIDO
		--ELIF iCodRet = 4 THEN
		--	LET cCodRet = '99999'; --MONTO DE DISPOSICION INVALIDO
		--ELIF iCodRet = 6 THEN
		--	LET cCodRet = '99999'; --EL PRODUCTO NO CUENTA CON INDICADOR DE DISPOSICION EN EFECTIVO
		--ELIF iCodRet = 7 THEN
		--	LET cCodRet = '99999'; --EL CRÉDITO NO CUENTA CON PORCENTAJE DE DISPOSICION DE EFECTIVO			
		--ELIF iCodRet = 301 THEN
		--	LET cCodRet = '99999'; --LA TDC ACUMULÓ EL 100% DE DISPOSICIONES DE EFECTIVO DEL MONTO AUTORIZADO EN 12 MESES
		--ELIF iCodRet = 302 THEN
		--	LET cCodRet = '99999'; --EL MONTO SOLICITADO EN LA TDC ES MAYOR AL MONTO DISPONIBLE
		--ELIF iCodRet = 303 THEN
		--	LET cCodRet = '99999'; --LA TDC NO TIENE ACCESO A DISPOSICIONES DE EFECTIVO
		END IF;
		
		IF cPorc_disp_efec LIKE '%.%' THEN
			LET cEntero = SUBSTR(cPorc_disp_efec, 1, CHARINDEX('.', cPorc_disp_efec) - 1);
			LET cDecimal = SUBSTR(cPorc_disp_efec, CHARINDEX('.', cPorc_disp_efec) + 1);
			LET dPorc_disp_efec = TRIM(cEntero)||RPAD(TRIM(cDecimal),2,'0');
			LET dPorc_disp_efec = dPorc_disp_efec/100;
			LET cPorc_disp_efec = dPorc_disp_efec/100;
			
			RETURN cCodRet,cPorc_disp_efec,dMonto_disp,UPPER(cMsj_disp_efec);
		ELSE
			LET dPorc_disp_efec = cPorc_disp_efec::INTEGER/100;
			LET cPorc_disp_efec = dPorc_disp_efec;
		
			RETURN cCodRet,cPorc_disp_efec,dMonto_disp,UPPER(cMsj_disp_efec);
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA 04/12/2019',
'MODULO: CONSULTAS',
'FUNCIONALIDAD: Generalizada de Cuentas',
'DESCRIPCION: Spl encargado de consultar los límites de disposición de las cuentas de los clientes.',
