CREATE PROCEDURE "informix".sp_consultareporterelacionbcpcp(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaInicial DATE, pFechaFinal DATE, pDescripcion CHAR(20), pRegistros INTEGER, pRecuperacion INTEGER)
	RETURNING CHAR(5) 	AS codret, 
			CHAR(20) 	AS num_cliente,
			CHAR(107) 	AS nombre_cliente,
			DATE 		AS fecha_nac,
			CHAR(100)  	AS descripcion_tipo_relacion_inicial,
			CHAR(20) 	AS num_cliente_coppel,
			CHAR(104) 	AS nombre_cliente_coppel,
			CHAR(10) 	AS fecha_nac_coppel,
			CHAR(10)  	AS modificacion,
			CHAR(10) 	AS fecha_relacion,
			CHAR(100)  	AS descripcion_tipo_relacion,
			CHAR(107) 	AS nombre_analista;
			
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRet INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE cMensajeRetorno CHAR(80);
	DEFINE cNumCliente CHAR(20);
	DEFINE cNombreCliente CHAR(107);
	DEFINE dFechaNacimiento DATE;
	DEFINE cDescripcionTipoRelacionInicial CHAR(100);
	DEFINE cNumClienteCoppel CHAR(20);
	DEFINE cNombreClienteCoppel CHAR(104);
	DEFINE cFechaNacimientoCoppel CHAR(10);
	DEFINE cModificacion CHAR(10);
	DEFINE cFechaRelacion CHAR(10);
	DEFINE cDescripcionTipoRelacion CHAR(100);
	DEFINE cNombreAnalista CHAR(107);
	DEFINE iNoRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRet = 0;
	LET iSqlErr = 0;
	LET cMensajeRetorno = '';
	LET cNumCliente = '';
	LET cNombreCliente = '';
	LET dFechaNacimiento = NULL;
	LET cDescripcionTipoRelacionInicial  = '';
	LET cNumClienteCoppel = '';
	LET cNombreClienteCoppel = '';
	LET cFechaNacimientoCoppel = '';
	LET cModificacion = '';
	LET cFechaRelacion = '';
	LET cDescripcionTipoRelacion = '';
	LET cNombreAnalista = '';
	LET iNoRegistros = 0;
	LET iRecuperacion = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, 
					cNumClienteCoppel, cNombreClienteCoppel, cFechaNacimientoCoppel, cModificacion, 
					cFechaRelacion,cDescripcionTipoRelacion, cNombreAnalista;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_consultareporterelacionbcpcp.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFechaInicial IS NULL OR pFechaFinal IS NULL OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, 
					cNumClienteCoppel, cNombreClienteCoppel, cFechaNacimientoCoppel, cModificacion, 
					cFechaRelacion,cDescripcionTipoRelacion, cNombreAnalista;
		END IF;
		
		IF pRecuperacion < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, 
					cNumClienteCoppel, cNombreClienteCoppel, cFechaNacimientoCoppel, cModificacion, 
					cFechaRelacion,cDescripcionTipoRelacion, cNombreAnalista;
		END IF;
		
		-- VALIDACIÃN DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, 
					cNumClienteCoppel, cNombreClienteCoppel, cFechaNacimientoCoppel, cModificacion, 
					cFechaRelacion,cDescripcionTipoRelacion, cNombreAnalista;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			
			SELECT SKIP pRegistros FIRST pRecuperacion
			numero_cte,nombre_cte,fecha_nacimiento,desc_tiporelacionini,numero_ctecoppel,nombre_ctecoppel,
			fecha_nacimientoctecoppel,modificacion,fecha_relacion,desc_tiporelacion,nombre_analista
			INTO cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, cNumClienteCoppel, cNombreClienteCoppel, 
			cFechaNacimientoCoppel, cModificacion, cFechaRelacion, cDescripcionTipoRelacion, cNombreAnalista
			FROM bdicnweb:"informix".sw_det_relacionbcpcp 
			WHERE usuario_inserta = pUsuario ORDER BY id_registro ASC
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet, cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, 
			cNumClienteCoppel, cNombreClienteCoppel, cFechaNacimientoCoppel, cModificacion, 
			cFechaRelacion,cDescripcionTipoRelacion, cNombreAnalista WITH RESUME;
			
		END FOREACH;
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, 
					cNumClienteCoppel, cNombreClienteCoppel, cFechaNacimientoCoppel, cModificacion, 
					cFechaRelacion,cDescripcionTipoRelacion, cNombreAnalista;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, 
					cNumClienteCoppel, cNombreClienteCoppel, cFechaNacimientoCoppel, cModificacion, 
					cFechaRelacion,cDescripcionTipoRelacion, cNombreAnalista;
		END IF;
	
	END;
	
END PROCEDURE
