CREATE PROCEDURE "informix".sp_consultasolicitudesaumlincred(pUsuario CHAR(8), pIdFuncion CHAR(10), pStatus CHAR(2), pFechaIni CHAR(10),
pFechaFin CHAR(10), pOrigen CHAR(1), pNumCte CHAR(20), pNumCred CHAR(20), pNumTarjeta CHAR(20), pRegistros INTEGER, pRecuperacion INTEGER)
        RETURNING CHAR(5)     AS cod_ret,
			CHAR(20)      AS num_cred,
			CHAR(20)      AS num_cte,
			CHAR(107)     AS nombre_cte,
			DATE              AS fecha_solicitud,
			CHAR(2)       AS status,
			CHAR(3)           AS cve_rtcm,
			CHAR(10)      AS origen,
			CHAR(4)       AS sucursal,
			DATE          AS fecha_cambio_estatus,
			DECIMAL(18,2) AS lincred_actual,
			DECIMAL(18,2) AS lincred_sugerida,
			SMALLINT          AS nivel_autorizacion,
			CHAR(5)  AS    cCodRetAnalista,
			CHAR(107)  AS cMensajeRetornoAsig; 
		
        DEFINE cCodRet CHAR(5);
        DEFINE cCodRetSp CHAR(6);
        DEFINE iCodRet INTEGER;
        DEFINE iSqlErr INTEGER;
        DEFINE iNoRegsEncontrados INTEGER;
        DEFINE iNoRegistros INTEGER;
        DEFINE iRecuperacion INTEGER;
        -- VARIABLES DE SALIDA DEL PROCEDIMIENTO
        DEFINE cMensajeRetorno CHAR(100);
        DEFINE cNumCredito CHAR(20);
        DEFINE cNumCliente CHAR(20);
        DEFINE cNombreCliente CHAR(107);
        DEFINE cStatus CHAR(2);
        DEFINE cOrigen CHAR(10);
        DEFINE cSucursal CHAR(4);
        DEFINE dFechaSolicitud DATE;
        DEFINE mLineaActual MONEY(18,2);
        DEFINE mLineaSugerida MONEY(18,2);
        DEFINE iNivelAutorizacion SMALLINT;
        DEFINE cUsuarioTrabajando CHAR(107);
        DEFINE iContinua SMALLINT;
        DEFINE iPagina INTEGER;
        DEFINE iTotRegsSp INTEGER;
        DEFINE dFechaCambioEstatus DATE;
        DEFINE cCveRtCm CHAR(3);
        -- VARIABLES DE ENTRADA AL SP PRODUCTIVO
        DEFINE cEmpresa CHAR(3);
        DEFINE cNombre1 CHAR(26);
        DEFINE cNombre2 CHAR(26);
        DEFINE cApellidoPaterno CHAR(26);
        DEFINE cApellidoMaterno CHAR(26);
        DEFINE dFechaNacimiento DATE;
        DEFINE iNumeroPagina SMALLINT;
        DEFINE iRecuperarRegistros SMALLINT;
		DEFINE cCodRetAnalista CHAR(5);
		DEFINE iGuardoHistorica INTEGER;
		DEFINE cMensajeRetornoAsig CHAR(107);
		DEFINE iCodRetAsig INTEGER;
        
        LET cCodRet = '00000';
        LET cCodRetSp = '';
        LET iCodRet = 0;
        LET iSqlErr = 0;
        LET iNoRegsEncontrados = 0;
        LET iNoRegistros = 0;
        LET iRecuperacion = 0;
        -- VARIABLES DE SALIDA DEL PROCEDIMIENTO
        LET cMensajeRetorno = '';
        LET cNumCredito = '';
        LET cNumCliente = '';
        LET cNombreCliente = '';
        LET cStatus = '';
        LET cOrigen = '';
        LET cSucursal = '';
        LET dFechaSolicitud = NULL;
        LET mLineaActual = NULL;
        LET mLineaSugerida = NULL;
        LET iNivelAutorizacion = 0;
        LET cUsuarioTrabajando = '';
        LET iContinua = 0;
        LET iPagina = 0;
        LET iTotRegsSp = 0;
        LET dFechaCambioEstatus = NULL;
        LET cCveRtCm = '';
        -- VARIABLES DE ENTRADA AL SP PRODUCTIVO
        LET cEmpresa = '001';
        LET cNombre1 = '';
        LET cNombre2 = '';
        LET cApellidoPaterno = '';
        LET cApellidoMaterno = '';
        LET dFechaNacimiento = '';
        LET iNumeroPagina = 0; -- Desde la pagina 0
        LET iRecuperarRegistros = 3; -- Consulta general sin paginaciÃ?Â³n
		LET cCodRetAnalista= '';
		LET iGuardoHistorica = 0;
		LET cMensajeRetornoAsig = '';
		LET iCodRetAsig = 0;
        
        BEGIN
			ON EXCEPTION SET iSqlErr
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
						dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig;
			END EXCEPTION;
			
			--SET DEBUG FILE TO '/tmp/mfinis/sp_consultasolicitudesaumlincred.out';
			--TRACE ON;
			
			IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
				LET cCodRet = '00003';
			    RETURN cCodRet, cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
						dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig;
			END IF;
			
			-- VALIDACIÃ?N DEL PARAMETRO DE PAGINACION
			IF pRegistros < 0 THEN
				LET cCodRet = '00098';
				RETURN cCodRet, cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
						dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig;
			END IF;
			
			-- VALIDACIÃ?N DE ACCESO A LA FUNCIONALIDAD
			EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
			IF cCodRet <> '00000' THEN
				RETURN cCodRet, cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
						dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig;
			END IF;
			
			SET ISOLATION TO DIRTY READ;
			SET LOCK MODE TO WAIT 3;
			
		   FOREACH
			
				SELECT SKIP pRegistros FIRST pRecuperacion
				numero_cre,numero_cte,nombre_cte,fecha_sol,status,cvertcm,origen,sucursal,fecha_cambioestatus,
				linea_actual,linea_sugerida,nivel_autorizacion,codret_analista,mensaje_codret_analista
				INTO cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
				dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig
				FROM bdicnweb:"informix".sw_det_aumlincred 
				WHERE usuario_inserta = pUsuario ORDER BY id_registro ASC
				
				LET iNoRegistros = iNoRegistros + 1;
				RETURN cCodRet, cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
						dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig WITH RESUME;
			
			END FOREACH;
                
			IF iNoRegistros = 0 AND pRegistros = 0 THEN
				LET cCodRet = '00017';
				RETURN cCodRet, cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
						dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig;
			ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
				LET cCodRet = '1001';
				RETURN cCodRet, cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
						dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig;
			END IF;
            
        END;
END PROCEDURE
DOCUMENT
