CREATE PROCEDURE "informix".sp_consultatotreporterelacionbcpcp(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaInicial DATE, pFechaFinal DATE, pDescripcion CHAR(20))
	RETURNING CHAR(5) 	AS codret, 
			INTEGER AS total_registros;
			
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRet INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE cMensajeRetorno CHAR(80);
	DEFINE cNumCliente CHAR(20);
	DEFINE cNombreCliente CHAR(107);
	DEFINE dFechaNacimiento DATE;
	DEFINE cDescripcionTipoRelacionInicial CHAR(100);
	DEFINE cNumClienteCoppel CHAR(20);
	DEFINE cNombreClienteCoppel CHAR(104);
	DEFINE cFechaNacimientoCoppel CHAR(10);
	DEFINE cModificacion CHAR(10);
	DEFINE cFechaRelacion CHAR(10);
	DEFINE cDescripcionTipoRelacion CHAR(100);
	DEFINE cNombreAnalista CHAR(107);
	DEFINE iNoRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	
	DEFINE iIdRegistro INTEGER;
	DEFINE bEnTransaccion BOOLEAN;
	DEFINE iContador INTEGER;
	DEFINE iMaxCommit INTEGER;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRet = 0;
	LET iSqlErr = 0;
	LET cMensajeRetorno = '';
	LET cNumCliente = '';
	LET cNombreCliente = '';
	LET dFechaNacimiento = NULL;
	LET cDescripcionTipoRelacionInicial  = '';
	LET cNumClienteCoppel = '';
	LET cNombreClienteCoppel = '';
	LET cFechaNacimientoCoppel = '';
	LET cModificacion = '';
	LET cFechaRelacion = '';
	LET cDescripcionTipoRelacion = '';
	LET cNombreAnalista = '';
	LET iNoRegistros = 0;
	LET iRecuperacion = 0;
	
	LET iIdRegistro = 0;
	LET bEnTransaccion = 'f';
	LET iContador = 0;
	LET iMaxCommit = 1000;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			IF bEnTransaccion = 't' THEN
				ROLLBACK WORK;
			END IF;
			
			UPDATE "informix".status_relacionbcpcp
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet,iNoRegistros;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bEnTransaccion = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_consultatotreporterelacionbcpcp.out';
		--TRACE ON;
		
		-- SE LIMPIA TABLA VERIFICA STATUS
		DELETE FROM "informix".status_relacionbcpcp WHERE usuario_insert = pUsuario;
		INSERT INTO "informix".status_relacionbcpcp(usuario_insert,status,num_registros,error_proceso,error) VALUES(pUsuario,'I',0,'',cCodRet);
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFechaInicial IS NULL OR pFechaFinal IS NULL THEN
			LET cCodRet = '00003';
			UPDATE "informix".status_relacionbcpcp
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet,iNoRegistros;
		END IF;
		
		-- VALIDACIÃN DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE "informix".status_relacionbcpcp
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet,iNoRegistros;
		END IF;
		
		-- SE LIMPIA TABLA PRINCIPAL
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		FOREACH WITH HOLD
			SELECT id_registro INTO iIdRegistro 
			FROM bdicnweb:"informix".sw_det_relacionbcpcp WHERE usuario_inserta = pUsuario
			
			DELETE FROM bdicnweb:"informix".sw_det_relacionbcpcp WHERE usuario_inserta = pUsuario AND id_registro = iIdRegistro;
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
		END FOREACH;		
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH 
			
			EXECUTE PROCEDURE bdinteg:"informix".sp_relacion_consultadatosrpt(pDescripcion, pFechaInicial, pFechaFinal)
			INTO cCodRetSp, cMensajeRetorno, cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, cNumClienteCoppel, 
			     cNombreClienteCoppel, cFechaNacimientoCoppel, cModificacion, cFechaRelacion, cDescripcionTipoRelacion, cNombreAnalista
			
			LET iCodRet = cCodRetSp::INTEGER;
			IF iCodRet < 0 THEN
				RAISE EXCEPTION iCodRet, 0, 'ERROR EN EJECUCIÃN DEL SP sp_relacion_consultadatosrpt';
			ELIF iCodRet > 0 THEN
				IF iCodRet = 1 THEN
					LET cCodRet = '00003';
				ELIF iCodRet = 2 THEN
					LET cCodRet = '00017';
				END IF;
				
				UPDATE "informix".status_relacionbcpcp
				SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
				RETURN cCodRet,iNoRegistros;
			ELSE
				
				LET iNoRegistros = iNoRegistros + 1;
				INSERT INTO bdicnweb:"informix".sw_det_relacionbcpcp(numero_cte,nombre_cte,fecha_nacimiento,desc_tiporelacionini,numero_ctecoppel,nombre_ctecoppel,
				fecha_nacimientoctecoppel,modificacion,fecha_relacion,desc_tiporelacion,nombre_analista,usuario_inserta)
				VALUES(cNumCliente, cNombreCliente, dFechaNacimiento, cDescripcionTipoRelacionInicial, cNumClienteCoppel,cNombreClienteCoppel,
				cFechaNacimientoCoppel, cModificacion, cFechaRelacion, cDescripcionTipoRelacion, cNombreAnalista, pUsuario);
				
				LET iContador = iContador + 1;
				IF iContador = iMaxCommit THEN
					COMMIT WORK;
					BEGIN WORK;
					LET iContador = 0;
				END IF;
				
			END IF;
			
		END FOREACH;
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
			UPDATE "informix".status_relacionbcpcp
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet,iNoRegistros;
		END IF;
		
		UPDATE "informix".status_relacionbcpcp
		SET status = 'T', error_proceso = 'N', num_registros = iNoRegistros WHERE usuario_insert = pUsuario;
		
		RETURN cCodRet,iNoRegistros;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Oscar Flores Conde',
'FECHA: 06/03/2014',
'DESCRIPCION: Consulta que obtiene el total de registros de informaciÃ³n general del cliente en bancoppel y coppel de acuerdo a los tipos de reportes para mesa de control',
'AUTOR: L. Montserrat Leon Amador',
'FECHA: 11/03/2020',
'DESCRIPCION: Se modifica SPL para implementar ejecuciones en segundo plano.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_consultatotsolicitudesaumlincred(pUsuario CHAR(8), pIdFuncion CHAR(10), pStatus CHAR(2), pFechaIni CHAR(10),
pFechaFin CHAR(10), pOrigen CHAR(1), pNumCte CHAR(20), pNumCred CHAR(20), pNumTarjeta CHAR(20))
	RETURNING CHAR(5) AS cod_ret,
		INTEGER AS no_registros;
		
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRet INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegsEncontrados INTEGER;
	DEFINE iRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	-- VARIABLES DE SALIDA DEL PROCEDIMIENTO
	DEFINE cMensajeRetorno CHAR(100);
	DEFINE cNumCredito CHAR(20);
	DEFINE cNumCliente CHAR(20);
	DEFINE cNombreCliente CHAR(107);
	DEFINE cStatus CHAR(2);
	DEFINE cOrigen CHAR(10);
	DEFINE cSucursal CHAR(4);
	DEFINE dFechaSolicitud DATE;
	DEFINE mLineaActual MONEY(18,2);
	DEFINE mLineaSugerida MONEY(18,2);
	DEFINE iNivelAutorizacion SMALLINT;
	DEFINE cUsuarioTrabajando CHAR(107);
	DEFINE iContinua SMALLINT;
	DEFINE iPagina INTEGER;
	DEFINE iTotRegsSp INTEGER;
	DEFINE dFechaCambioEstatus DATE;
	DEFINE cCveRtCm CHAR(3);
	-- VARIABLES DE ENTRADA AL SP PRODUCTIVO
	DEFINE cEmpresa CHAR(3);
	DEFINE cNombre1 CHAR(26);
	DEFINE cNombre2 CHAR(26);
	DEFINE cApellidoPaterno CHAR(26);
	DEFINE cApellidoMaterno CHAR(26);
	DEFINE dFechaNacimiento DATE;
	DEFINE iNumeroPagina SMALLINT;
	DEFINE iRecuperarRegistros SMALLINT;
	
	DEFINE iGuardoHistorica INTEGER;
	DEFINE cMensajeRetornoAsig CHAR(107);
	DEFINE iCodRetAsig INTEGER;
	DEFINE cCodRetAnalista CHAR(5);
	
	DEFINE iIdRegistro INTEGER;
	DEFINE bEnTransaccion BOOLEAN;
	DEFINE iContador INTEGER;
	DEFINE iMaxCommit INTEGER;
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRet = 0;
	LET iSqlErr = 0;
	LET iNoRegsEncontrados = 0;
	LET iRegistros = 0;
	LET iRecuperacion = 0;
	-- VARIABLES DE SALIDA DEL PROCEDIMIENTO
	LET cMensajeRetorno = '';
	LET cNumCredito = '';
	LET cNumCliente = '';
	LET cNombreCliente = '';
	LET cStatus = '';
	LET cOrigen = '';
	LET cSucursal = '';
	LET dFechaSolicitud = NULL;
	LET mLineaActual = NULL;
	LET mLineaSugerida = NULL;
	LET iNivelAutorizacion = 0;
	LET cUsuarioTrabajando = '';
	LET iContinua = 0;
	LET iPagina = 0;
	LET iTotRegsSp = 0;
	LET dFechaCambioEstatus = NULL;
	LET cCveRtCm = '';
	-- VARIABLES DE ENTRADA AL SP PRODUCTIVO
	LET cEmpresa = '001';
	LET cNombre1 = '';
	LET cNombre2 = '';
	LET cApellidoPaterno = '';
	LET cApellidoMaterno = '';
	LET dFechaNacimiento = '';
	LET iNumeroPagina = 0; -- Desde la pagina 0
	LET iRecuperarRegistros = 0; -- Consulta general sin paginaciÃ³n
	
	LET iGuardoHistorica = 0;
	LET cMensajeRetornoAsig = '';
	LET iCodRetAsig = 0;
	LET cCodRetAnalista = '';
	
	LET iIdRegistro = 0;
	LET bEnTransaccion = 'f';
	LET iContador = 0;
	LET iMaxCommit = 1000;
	LET iNoRegistros = 0;
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			IF bEnTransaccion = 't' THEN
				ROLLBACK WORK;
			END IF;
			
			UPDATE "informix".status_aumlincred
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bEnTransaccion = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_consultatotsolicitudesaumlincred.out';
		--TRACE ON;
		
		-- SE LIMPIA TABLA VERIFICA STATUS
		DELETE FROM "informix".status_aumlincred WHERE usuario_insert = pUsuario;
		INSERT INTO "informix".status_aumlincred(usuario_insert,status,num_registros,error_proceso,error) VALUES(pUsuario,'I',0,'',cCodRet);
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			UPDATE "informix".status_aumlincred
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		-- VALIDACIÃN DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE "informix".status_aumlincred
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		-- SE LIMPIA TABLA PRINCIPAL
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		FOREACH WITH HOLD
			SELECT id_registro INTO iIdRegistro 
			FROM bdicnweb:"informix".sw_det_aumlincred WHERE usuario_inserta = pUsuario
			
			DELETE FROM bdicnweb:"informix".sw_det_aumlincred WHERE usuario_inserta = pUsuario AND id_registro = iIdRegistro;
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
		END FOREACH;		
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			
			EXECUTE PROCEDURE bdicred:"informix".sp_cac_consultasolincrelincred(cEmpresa, pStatus, pFechaIni, pFechaFin, 
			cNombre1, cNombre2, cApellidoPaterno, cApellidoMaterno, dFechaNacimiento,
			pOrigen, pNumCte, pNumCred, pNumTarjeta, pUsuario, iNumeroPagina, iRecuperarRegistros)
			INTO cCodRetSp, cMensajeRetorno, cNumCredito, cNumCliente, cNombreCliente, cStatus, cOrigen, cSucursal, dFechaSolicitud,
			mLineaActual, mLineaSugerida, iNivelAutorizacion, cUsuarioTrabajando, iContinua, iPagina, iTotRegsSp, dFechaCambioEstatus, cCveRtCm
			
			LET iCodRet = cCodRetSp::INTEGER;
			IF iCodRet < 0 THEN
				RAISE EXCEPTION iCodRet, 0, 'ERROR EN LA EJECUCION DEL SP bdicred:sp_cac_consultasolincrelincred';
			ELIF iCodRet > 0 THEN
				IF iCodRet IN (1, 2) THEN
					LET cCodRet = '00098';
				ELIF iCodRet = 3 THEN
					LET cCodRet = '00252';
				END IF;
				
				UPDATE "informix".status_aumlincred
				SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
				RETURN cCodRet, iNoRegistros;
			END IF;
			
			--IF iRegistros >= pRegistros THEN
			-- IF iRecuperacion < pRecuperacion THEN
				IF pStatus = 'AC' THEN
					EXECUTE PROCEDURE bdicred:"informix".sp_cac_asignasolanalista(cEmpresa, cNumCredito, pUsuario, mLineaActual) INTO cCodRetSp, cMensajeRetornoAsig, iGuardoHistorica;
					LET iCodRetAsig = cCodRetSp::INTEGER;
				END IF;	
				IF iCodRetAsig < 0 THEN
						RAISE EXCEPTION iCodRetAsig, 0, 'ERROR EN LA EJECUCION DEL SP sp_cac_asignasolanalista';
				ELIF iCodRetAsig = 1 THEN -- FALTAN PARAMETROS DE ENTRADA
						LET cCodRetAnalista = '00003';
				ELIF iCodRetAsig = 7 THEN -- EL ESTATUS DE LA SOLICITUD CAMBIÃ?? FAVOR DE VERIFICAR
						LET cCodRetAnalista = '00253';
				ELIF iCodRetAsig = 2 THEN -- SOLICITUD ESTÃ? SIENDO ATENDIDA POR XXXXXX XXXXXX XXXXX XXXXX
						LET cCodRetAnalista = '90000'; 
				ELIF iCodRetAsig = 6 THEN -- MISMO USUARIO ATENDIENDO LA SOLICITUD PERO YA PASO DE REVISION
						LET cCodRetAnalista = '00254';
				ELIF iCodRetAsig = 4 THEN -- MISMO USUARIO ATENDIENDO LA SOLICITUD (CASOS DE ERROR)
						LET cCodRetAnalista = '00255';
				ELIF iCodRetAsig = 5 THEN -- MISMO USUARIO QUE ATENDIO LA SOLICITUD
						LET cCodRetAnalista = '00256';
				ELIF iCodRetAsig = 3 THEN -- LA AUTORIZACIÃ??N NO CORRESPONDE A ESE NIVEL, FAVOR DE VALIDAR
						LET cCodRetAnalista = '00257';
				ELIF iCodRetAsig = 0 THEN -- LA AUTORIZACIÃ??N NO CORRESPONDE A ESE NIVEL, FAVOR DE VALIDAR
						LET cCodRetAnalista = '00000';
				END IF;
				
			--	RETURN cCodRet, cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, 
			--			dFechaCambioEstatus, mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig WITH RESUME;
			--	LET iNoRegsEncontrados = iNoRegsEncontrados + 1;
			--	LET iRecuperacion = iRecuperacion + 1;
            --
			-- ELSE
			-- 	EXIT FOREACH;
			-- END IF;
			--			
			--END IF;
			
			LET iNoRegistros = iNoRegistros + 1;
			INSERT INTO bdicnweb:"informix".sw_det_aumlincred(numero_cre,numero_cte,nombre_cte,fecha_sol,status,cvertcm,origen,sucursal,fecha_cambioestatus,
			linea_actual,linea_sugerida,nivel_autorizacion,codret_analista,mensaje_codret_analista,usuario_inserta)
			VALUES(cNumCredito, cNumCliente, cNombreCliente, dFechaSolicitud, cStatus, cCveRtCm, cOrigen, cSucursal, dFechaCambioEstatus,
			mLineaActual, mLineaSugerida, iNivelAutorizacion, cCodRetAnalista, cMensajeRetornoAsig, pUsuario);
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
				
		END FOREACH;
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
			UPDATE "informix".status_aumlincred
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet,iNoRegistros;
		END IF;
		
		UPDATE "informix".status_aumlincred
		SET status = 'T', error_proceso = 'N', num_registros = iNoRegistros WHERE usuario_insert = pUsuario;
		
		RETURN cCodRet,iNoRegistros;
		
	END;
END PROCEDURE
DOCUMENT
'DESCRIPCION: Se realiza procedimiento para la generaciÃ³n de la informaciÃ³n para la consulta de incrementos v2',
'AUTOR : Oscar Flores Conde',
'FECHA : 21/03/2014',
'AUTOR: L. Montserrat Leon Amador',
'FECHA: 11/03/2020',
'DESCRIPCION: Se modifica SPL para implementar ejecuciones en segundo plano.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_verificastatusreporterelacionbcpcp(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5) AS codret,
		CHAR(1) AS status,
		INTEGER AS num_registros,
		CHAR(1) AS error_proceso,
		CHAR(5) AS error;
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	DEFINE cStatus CHAR(1);
	DEFINE cErrorProceso CHAR(1);
	DEFINE cError CHAR(5);
	DEFINE iNumRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cStatus = '';
	LET cErrorProceso = '';
	LET cError = '';
	LET iNumRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			--LET cCodRet = '00770'; --PROCESO CON ERRORES, POR FAVOR REINTENTE NUEVAMENTE
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;	
		END EXCEPTION;
	 
		--SET DEBUG FILE TO '/tmp/mfinis/sp_verificastatusreporterelacionbcpcp.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;	
		END IF;		
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
	
		SELECT status,num_registros,error_proceso,error
		INTO cStatus,iNumRegistros,cErrorProceso,cError
		FROM "informix".status_relacionbcpcp WHERE usuario_insert = pUsuario;
		
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN		
			RETURN cCodRet,'I','','',''; 
		ELSE 			
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;		
		END IF;	
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
