CREATE PROCEDURE "informix".sp_ccl_conciliadorautoinvcreciente(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipoReporte CHAR(1), pFechaInicio DATE, pFechaFin DATE, pTotalRegistros INTEGER,pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
		DATE AS fecha,
		CHAR(20) AS num_cte,
		CHAR(20) AS cuenta_eje,
		CHAR(4) AS transacc_cuenta_eje,
		CHAR(50) AS desc_cuenta_eje,
		CHAR(14) AS cta_cargo_cta_eje,
		CHAR(14) AS cta_abono_cta_eje,
		MONEY(18,2) AS importe_cta_eje,
		CHAR(20) AS invers_crecte,
		CHAR(4) AS transacc_invers_crecte,
		CHAR(50) AS desc_invers_crecte,
		CHAR(14) AS cta_cargo_invers_crecte,
		MONEY(18,2) AS monto_cargo,
		CHAR(14) AS cta_abono_invers_crecte,
		MONEY(18,2) AS monto_abono,
		MONEY(18,2) AS importe_invers_crecte,
		MONEY(18,2) AS diferencia;

	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE dFecha DATE;
	DEFINE cNumCliente CHAR(20);
	DEFINE cCuentaEje CHAR(20);
	DEFINE cTransCtaEje CHAR(4);
	DEFINE cDescCtaEje CHAR(50);
	DEFINE cCtaCargoCtaEje CHAR(14);
	DEFINE cCtaAbonoCtaEje CHAR(14);
	DEFINE mImporteCtaEje MONEY(18,2);
	DEFINE cInversCrecte CHAR(20);
	DEFINE cTransInversCrecte CHAR(4);
	DEFINE cDescInversCrecte CHAR(50);
	DEFINE cCtaCargoInversCrecte CHAR(14);
	DEFINE mMontoCargo MONEY(18,2);
	DEFINE cCtaAbonoInversCrecte CHAR(14);
	DEFINE mMontoAbono MONEY(18,2);
	DEFINE mImporteInversCrecte MONEY(18,2);
	DEFINE mDiferencia MONEY(18,2);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	LET dFecha = '';
	LET cNumCliente = '';
	LET cCuentaEje = '';
	LET cTransCtaEje = '';
	LET cDescCtaEje = '';
	LET cCtaCargoCtaEje = '';
	LET cCtaAbonoCtaEje = '';
	LET mImporteCtaEje = 0.00;
	LET cInversCrecte = '';
	LET cTransInversCrecte = '';
	LET cDescInversCrecte = '';
	LET cCtaCargoInversCrecte = '';
	LET mMontoCargo = 0.00;
	LET cCtaAbonoInversCrecte = '';
	LET mMontoAbono = 0.00;
	LET mImporteInversCrecte = 0.00;
	LET mDiferencia = 0.00;

	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
		
			RETURN cCodRet, dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte, mDiferencia;
		END EXCEPTION;

		--SET DEBUG FILE TO '/tmp/mfinis/sp_ccl_conciliadorautoinvcreciente.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR pFechaInicio IS NULL OR pFechaFin IS NULL  THEN
			LET cCodRet = '00003';
			
			RETURN cCodRet, dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte, mDiferencia;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte, mDiferencia;
		END IF;
	
		IF(pTipoReporte = 1) THEN
		
			FOREACH 
				SELECT SKIP pRegistros FIRST pRecuperacion fecha_alt, num_cte, cuenta_eje, transacc_cta_eje, descripcion_cta_eje, cta_cargo_cta_eje, cta_abono_cta_eje, importe_cta_eje, invers_crecte, transacc_invers_crecte, descripcion_invers_crecte, cta_cargo_invers_crecte, monto_cargo, cta_abono_invers_crecte, monto_abono, importe_invers_crecte
				INTO dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte
				FROM bdicheq:"informix".sc_concilia_transacc
				WHERE fecha_alt >= pFechaInicio
				AND fecha_alt <= pFechaFin
				ORDER BY 1 DESC, num_cte
				
				LET iNoRegistros = iNoRegistros + 1;
				RETURN cCodRet, dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte, mDiferencia WITH RESUME;
			END FOREACH;
			
		END IF;
		
		IF(pTipoReporte = 2) THEN
		
			FOREACH 
				SELECT SKIP pRegistros FIRST pRecuperacion fecha_alt, num_cte, cuenta_eje, transacc_cta_eje, descripcion_cta_eje, cta_cargo_cta_eje, cta_abono_cta_eje, importe_cta_eje, invers_crecte, transacc_invers_crecte, descripcion_invers_crecte, cta_cargo_invers_crecte, monto_cargo, cta_abono_invers_crecte, monto_abono, importe_invers_crecte, diferencia
				INTO dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte, mDiferencia
				FROM bdicheq:"informix".sc_diferencia_concilia
				WHERE fecha_alt >= pFechaInicio
					AND fecha_alt <= pFechaFin
				ORDER BY 1 DESC, num_cte

				LET iNoRegistros = iNoRegistros + 1;
				RETURN cCodRet, dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte, mDiferencia WITH RESUME;				
			END FOREACH;
		
		END IF;		
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN			
			LET cCodRet = '00017';
			RETURN cCodRet, dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte, mDiferencia;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, dFecha, cNumCliente, cCuentaEje, cTransCtaEje, cDescCtaEje, cCtaCargoCtaEje, cCtaAbonoCtaEje, mImporteCtaEje, cInversCrecte, cTransInversCrecte, cDescInversCrecte, cCtaCargoInversCrecte, mMontoCargo, cCtaAbonoInversCrecte, mMontoAbono, mImporteInversCrecte, mDiferencia;
		END IF;								
	
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil Cuachayo',
'FECHA: 13/01/2017',
'MODULO: CONCILIACIONES',
'FUNCIONALIDAD: Conciliador Automatico Inversion Creciente',
'DESCRIPCION: SP que consulta las Transacciones Conciliadas de Inversion Creciente',
'AUTOR: L. Montserrat LeÃ³n Amador',
'FECHA: 06/04/2017',
'DESCRIPCION: Se modifica spl para incrementar el tamaÃ±o de la definiciÃ³n de las cuentas de un CHAR(10) a un CHAR(14).',
'AUTOR: L. Montserrat Leon Amador',
'FECHA: 13/03/2020',
'DESCRIPCION: Se modifica SPL para agregar Monto Cargo y Monto Abono al detalle de la consulta.',
