CREATE PROCEDURE "informix".sp_ccl_conciliadorautoinvcreciente_genrep(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipoReporte CHAR(1), pFechaInicio DATE, pFechaFin DATE, pFechaReporte CHAR(8), pRutaDescarga CHAR(150))
		RETURNING CHAR(5) AS codret,
		CHAR(150) AS archivo_generado;		

	DEFINE cCodRet 		CHAR(5);
	DEFINE iSqlErr 		INTEGER;
	DEFINE cCmd1 CHAR(3000);	
	DEFINE cArchSinDif CHAR(150);
	DEFINE cArchConDif CHAR(150);
	DEFINE cArchDescarga CHAR(150);
	DEFINE iNoRegistros INTEGER;
	DEFINE mMontoCargo CHAR(22); --MONEY(20,2);
	DEFINE mMontoAbono CHAR(22); --MONEY(20,2);
	DEFINE mImporteInversCrecte CHAR(20); --MONEY(18,2);
	DEFINE mImporteDiferencia CHAR(20); --MONEY(18,2);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cCmd1 = '';	
	LET cArchSinDif = TRIM(pRutaDescarga) || 'repconcilsindif.txt';
	LET cArchConDif = TRIM(pRutaDescarga) || 'repconcilcondif.txt';
	LET cArchDescarga = '';
	LET iNoRegistros = 0;
	LET mMontoCargo = '';
	LET mMontoAbono = '';
	LET mImporteInversCrecte = '';
	LET mImporteDiferencia = '';
	
	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;		
			RETURN cCodRet, cArchDescarga;
		END EXCEPTION;

		--SET DEBUG FILE TO '/tmp/mfinis/sp_ccl_conciliadorautoinvcreciente_genrep.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR pFechaInicio IS NULL OR pFechaFin IS NULL OR pFechaReporte = '' OR pRutaDescarga = '' THEN
			LET cCodRet = '00003';			
			RETURN cCodRet, cArchDescarga;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cArchDescarga;
		END IF;
		
		IF(pTipoReporte = 1) THEN
			
			SELECT COUNT(*), (SUM(monto_cargo))::CHAR(22), (SUM(monto_abono))::CHAR(22), (SUM(importe_invers_crecte))::CHAR(20)
			INTO iNoRegistros, mMontoCargo, mMontoAbono, mImporteInversCrecte
			FROM bdicheq:"informix".sc_concilia_transacc
			WHERE fecha_alt >= pFechaInicio
			AND fecha_alt <= pFechaFin;
			
			LET mMontoCargo = REPLACE(mMontoCargo,'$','');
			LET mMontoAbono = REPLACE(mMontoAbono,'$','');
			LET mImporteInversCrecte = REPLACE(mImporteInversCrecte,'$','');
			
			LET cCmd1 = "";
			LET cCmd1 = "SELECT 'FECHA', 'NO. CLIENTE', 'NO. CUENTA EJE', 'TRANSACCIÃâN CUENTA EJE', 'DESCRIPCIÃâN CUENTA EJE', 'CUENTA CARGO CUENTA EJE', 'CUENTA ABONO CUENTA EJE','IMPORTE CUENTA EJE', 'INVERSIÃâN CRECIENTE',"|| 
			"'TRANSACCIÃâN INVERSIÃâN CRECIENTE', 'DESCRIPCIÃâN INVERSIÃâN CRECIENTE', 'CUENTA CARGO INVERSIÃâN CRECIENTE', 'MONTO CARGO', 'CUENTA ABONO INVERSIÃâN CRECIENTE', 'MONTO ABONO', 'IMPORTE INVERSIÃâN CRECIENTE'"||	
			'FROM systables WHERE tabid = 1 UNION ALL SELECT * FROM ('|| 'SELECT TO_CHAR(fecha_alt,''%d/%m/%Y''), num_cte, cuenta_eje, transacc_cta_eje, descripcion_cta_eje, cta_cargo_cta_eje, cta_abono_cta_eje, ' ||
			'importe_cta_eje::CHAR(18), invers_crecte, transacc_invers_crecte, descripcion_invers_crecte, cta_cargo_invers_crecte, monto_cargo::CHAR(20), cta_abono_invers_crecte, monto_abono::CHAR(20), importe_invers_crecte::CHAR(18) FROM bdicheq:sc_concilia_transacc ' ||
			'WHERE fecha_alt BETWEEN ' || "'" || pFechaInicio ||"' AND '"||pFechaFin||"'" || ' ORDER BY 1 DESC, 2)';				
			LET cCmd1 =""||TRIM(cCmd1)||" UNION ALL SELECT 'TOTAL DE TRANSACCIONES: "||iNoRegistros||"',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ' FROM systables WHERE tabid = 1";
			LET cCmd1 =""||TRIM(cCmd1)||" UNION ALL SELECT 'TOTAL MONTO CARGO: $ "||TRIM(mMontoCargo)||"',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ' FROM systables WHERE tabid = 1";
			LET cCmd1 =""||TRIM(cCmd1)||" UNION ALL SELECT 'TOTAL MONTO ABONO: $ "||TRIM(mMontoAbono)||"',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ' FROM systables WHERE tabid = 1";
			LET cCmd1 =""||TRIM(cCmd1)||" UNION ALL SELECT 'TOTAL INVERSIÃâN CRECIENTE: $ "||TRIM(mImporteInversCrecte)||"',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ' FROM systables WHERE tabid = 1";
			
			SYSTEM TRIM('echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cArchSinDif)||' ' || TRIM(cCmd1)||';" | /informix/bin/dbaccess bdicnweb > /dev/null 2>&1');
			LET cArchDescarga = cArchSinDif;
			
			RETURN cCodRet, cArchDescarga;
		END IF;
		
		IF(pTipoReporte = 2) THEN
			
			SELECT COUNT(*), (SUM(monto_cargo))::CHAR(22), (SUM(monto_abono))::CHAR(22), (SUM(diferencia))::CHAR(20)
			INTO iNoRegistros, mMontoCargo, mMontoAbono, mImporteDiferencia 
			FROM bdicheq:"informix".sc_diferencia_concilia
			WHERE fecha_alt >= pFechaInicio
			AND fecha_alt <= pFechaFin;
			
			LET mMontoCargo = REPLACE(mMontoCargo,'$','');
			LET mMontoAbono = REPLACE(mMontoAbono,'$','');
			LET mImporteDiferencia = REPLACE(mImporteDiferencia,'$','');
			
			LET cCmd1 = "";
			LET cCmd1 = "SELECT 'FECHA', 'NO. CLIENTE', 'NO. CUENTA EJE', 'TRANSACCIÃâN CUENTA EJE', 'DESCRIPCIÃâN CUENTA EJE', 'CUENTA CARGO CUENTA EJE', 'CUENTA ABONO CUENTA EJE','IMPORTE CUENTA EJE', 'INVERSIÃâN CRECIENTE',"|| 
			"'TRANSACCIÃâN INVERSIÃâN CRECIENTE', 'DESCRIPCIÃâN INVERSIÃâN CRECIENTE', 'CUENTA CARGO INVERSIÃâN CRECIENTE', 'MONTO CARGO', 'CUENTA ABONO INVERSIÃâN CRECIENTE', 'MONTO ABONO', 'IMPORTE INVERSIÃâN CRECIENTE', 'DIFERENCIA'"||	
			'FROM systables WHERE tabid = 1 UNION ALL SELECT * FROM ('|| 'SELECT TO_CHAR(fecha_alt,''%d/%m/%Y''), num_cte, cuenta_eje, transacc_cta_eje, descripcion_cta_eje, cta_cargo_cta_eje, cta_abono_cta_eje, ' ||
			'importe_cta_eje::CHAR(18), invers_crecte, transacc_invers_crecte, descripcion_invers_crecte, cta_cargo_invers_crecte, monto_cargo::CHAR(20), cta_abono_invers_crecte, monto_abono::CHAR(20), importe_invers_crecte::CHAR(18), diferencia::CHAR(18) FROM bdicheq:sc_diferencia_concilia ' ||
			'WHERE fecha_alt BETWEEN ' || "'" || pFechaInicio ||"' AND '"||pFechaFin||"'" || ' ORDER BY 1 DESC, 2)';				
			LET cCmd1 =""||TRIM(cCmd1)||" UNION ALL SELECT 'TOTAL DE TRANSACCIONES: "||iNoRegistros||"',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ' FROM systables WHERE tabid = 1";
			LET cCmd1 =""||TRIM(cCmd1)||" UNION ALL SELECT 'TOTAL MONTO CARGO: $ "||TRIM(mMontoCargo)||"',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ' FROM systables WHERE tabid = 1";
			LET cCmd1 =""||TRIM(cCmd1)||" UNION ALL SELECT 'TOTAL MONTO ABONO: $ "||TRIM(mMontoAbono)||"',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ' FROM systables WHERE tabid = 1";
			LET cCmd1 =""||TRIM(cCmd1)||" UNION ALL SELECT 'TOTAL DIFERENCIA: $ "||TRIM(mImporteDiferencia)||"',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ',' ' FROM systables WHERE tabid = 1";
			
			SYSTEM TRIM('echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cArchConDif)||' ' || TRIM(cCmd1)||';" | /informix/bin/dbaccess bdicnweb > /dev/null 2>&1');
			
			LET cArchDescarga = cArchConDif;
			RETURN cCodRet, cArchDescarga;
		END IF;											

	END;
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil Cuachayo',
'FECHA: 13/01/2017',
'MODULO: CONCILIACIONES',
'FUNCIONALIDAD: Conciliador Automatico Inversion Creciente',
'DESCRIPCION: SP que genera reporte txt de las Transacciones Conciliadas de Inversion Creciente',
'AUTOR: L. Montserrat Leon Amador',
'FECHA: 13/03/2020',
'DESCRIPCION: Se modifica SPL para agregar Monto Cargo y Monto Abono al detalle de la consulta que conforma la estructura del reporte.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_ccl_conciliadorautoinvcreciente_totales(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipoReporte CHAR(1), pFechaInicio DATE, pFechaFin DATE)
		RETURNING CHAR(5) AS codret,
		INTEGER AS num_registros,
		MONEY(20,2) AS monto_cargo,
		MONEY(20,2) AS monto_abono,
		MONEY(18,2) AS importe_invers_crecte,
		MONEY(18,2) AS importe_diferencia;

	DEFINE cCodRet 		CHAR(5);
	DEFINE iSqlErr 		INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE mMontoCargo MONEY(20,2);
	DEFINE mMontoAbono MONEY(20,2);
	DEFINE mImporteInversCrecte MONEY(18,2);
	DEFINE mImporteDiferencia MONEY(18,2);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	LET mMontoCargo = 0.00;
	LET mMontoAbono = 0.00;
	LET mImporteInversCrecte = 0.00;
	LET mImporteDiferencia = 0.00;
	
	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, iNoRegistros, mMontoCargo, mMontoAbono, mImporteInversCrecte, mImporteDiferencia;
		END EXCEPTION;

		--SET DEBUG FILE TO '/tmp/mfinis/sp_ccl_conciliadorautoinvcreciente_totales.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR pFechaInicio IS NULL OR pFechaFin IS NULL  THEN
			LET cCodRet = '00003';
			RETURN cCodRet, iNoRegistros, mMontoCargo, mMontoAbono, mImporteInversCrecte, mImporteDiferencia;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, iNoRegistros, mMontoCargo, mMontoAbono, mImporteInversCrecte, mImporteDiferencia;
		END IF;
		
		--Tipo Reporte Conciliadas
		IF(pTipoReporte = 1) THEN
		
			SELECT COUNT(*), SUM(monto_cargo), SUM(monto_abono), SUM(importe_invers_crecte)
			INTO iNoRegistros, mMontoCargo, mMontoAbono, mImporteInversCrecte
			FROM bdicheq:"informix".sc_concilia_transacc
			WHERE fecha_alt >= pFechaInicio
			AND fecha_alt <= pFechaFin;
			
		END IF;
		
		--Tipo Reporte Conciliadas con Diferencia
		IF(pTipoReporte = 2) THEN
		
			SELECT COUNT(*), SUM(monto_cargo), SUM(monto_abono), SUM(diferencia)
			INTO iNoRegistros, mMontoCargo, mMontoAbono, mImporteDiferencia 
			FROM bdicheq:"informix".sc_diferencia_concilia
			WHERE fecha_alt >= pFechaInicio
			AND fecha_alt <= pFechaFin;		
		
		END IF;
		
		IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
		END IF;
		
		RETURN cCodRet, iNoRegistros, mMontoCargo, mMontoAbono, mImporteInversCrecte, mImporteDiferencia;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil Cuachayo',
'FECHA: 13/01/2017',
'MODULO: CONCILIACIONES',
'FUNCIONALIDAD: Conciliador Automatico Inversion Creciente',
'DESCRIPCION: SP que consulta el total de Transacciones Conciliadas de Inversion Creciente',
'AUTOR: L. Montserrat Leon Amador',
'FECHA: 13/03/2020',
'DESCRIPCION: Se modifica SPL para agregar la suma del Monto Cargo, Monto Abono e InversiÃ³n Creciente.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_ope_consultastatusprefijosparticipantesspei(pUsuario CHAR(8), pIdFuncion CHAR(10), pClave INTEGER)
		RETURNING CHAR(5) AS codRet,
			CHAR(1) AS status;
			
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cStatus CHAR(1);	

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cStatus = '';

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cStatus;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_ope_consultastatusprefijosparticipantesspei.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pClave IS NULL OR pClave < 0 THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cStatus;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cStatus;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
			
		SELECT chrstatus
		INTO cStatus
		FROM bdispei:"informix".tblbcobloqueo
		WHERE cvecesif = pClave;
		
		RETURN cCodRet, cStatus;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil Cuachayo',
'FECHA 06/03/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: BLOQUEO/DESBLOQUEO DE PARTICIPANTES SPEI',
'DESCRIPCION: Spl encargado de consultar el estatus de Prefijos Participantes SPEI.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_ope_consultaprefijosparticipantesspei(pUsuario CHAR(8), pIdFuncion CHAR(10), pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codRet,
			INTEGER AS claveCesif,
			CHAR(20) AS nombrecorto;
			
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE iClaveCesif INTEGER;	
	DEFINE cNombrecorto CHAR(20);	
	DEFINE iRecuperacion INTEGER;

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iClaveCesif = 0;	
	LET cNombrecorto = '';
	LET iRecuperacion = 0;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,iClaveCesif, cNombrecorto;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_ope_consultaprefijosparticipantesspei.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet,iClaveCesif, cNombrecorto;
		END IF;
		
		-- VALIDACION DE LA PAGINACION
		IF pRegistros < 0 OR pRecuperacion < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet,iClaveCesif, cNombrecorto;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,iClaveCesif, cNombrecorto;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT SKIP pRegistros FIRST pRecuperacion cvecesif, vchrnombrecorto
			INTO iClaveCesif, cNombrecorto
			FROM bdispei:"informix".tblbanco
			ORDER BY UPPER(vchrnombrecorto)
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet,iClaveCesif, cNombrecorto WITH RESUME;			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,iClaveCesif, cNombrecorto;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Miguel Huitzil Cuachayo',
'FECHA 06/03/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: BLOQUEO/DESBLOQUEO DE PARTICIPANTES SPEI',
'DESCRIPCION: Spl encargado de consultar el Detalle de Prefijos Participantes SPEI.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_ope_actualizaprefijosparticipantesspei(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipoEjecucion INTEGER, pTipoOperacion CHAR(1), pClaveBnco INTEGER)
		RETURNING CHAR(5) AS codRet;			
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;

	LET cCodRet = '00000';
	LET iSqlErr = 0;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_ope_actualizaprefijosparticipantesspei.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pTipoEjecucion IS NULL OR pTipoOperacion = '' OR pClaveBnco IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pTipoEjecucion = 1 AND pTipoOperacion = 'B' THEN
		--insertar
			INSERT INTO bdispei:"informix".tblbcobloqueo(cvecesif, chrstatus, vchruser_ins, dtfecha_ins, vchruser_mod, fecha_mod)
			VALUES(pClaveBnco, pTipoOperacion, pUsuario, TO_CHAR(TODAY, '%m/%d/%Y'), null, null);
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '00282';
			END IF;
		
		ELIF pTipoEjecucion = 2 AND pTipoOperacion = 'B' THEN
		--actualizar
		
			UPDATE bdispei:"informix".tblbcobloqueo 
			SET chrstatus = pTipoOperacion, vchruser_ins = pUsuario, dtfecha_ins = TO_CHAR(TODAY, '%m/%d/%Y')
			WHERE cvecesif = pClaveBnco;
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '00283';
			END IF;
			
		ELIF pTipoEjecucion = 2 AND pTipoOperacion = 'D' THEN
		--ACTUALIZAR
			UPDATE bdispei:"informix".tblbcobloqueo 
			SET  chrstatus = pTipoOperacion, vchruser_mod = pUsuario, fecha_mod = TO_CHAR(TODAY, '%m/%d/%Y')
			WHERE cvecesif = pClaveBnco;
			
			IF DBINFO("sqlca.sqlerrd2") = 0 THEN
				LET cCodRet = '00283';
			END IF;
		
		END IF;
		
		
		
		RETURN cCodRet;
		
	END;
END PROCEDURE
