CREATE PROCEDURE "informix".sp_mc_buscasoliccac(pUsuario CHAR(8), pIdFuncion CHAR(10), pNumSolicitud CHAR(20), pRegistros INTEGER, pRecuperacion INTEGER)
    RETURNING CHAR(5) AS codret,
		CHAR(80) AS mensaje_ret,
		CHAR(20) AS num_cred,
		CHAR(4) AS num_suc,
		CHAR(107) AS nombre_cte,
		CHAR(13) AS rfc_cte,
		DATE AS fecha_solic,
		CHAR(1) AS OS,
		CHAR(40) AS nom_pdcto,
		DECIMAL(18,2) AS lin_calculada,
		CHAR(45) AS nom_analista,
		CHAR(2) AS consulta,
		SMALLINT AS continua,
		INTEGER AS pagina,
		CHAR(8) AS cEjec_autoriza; 
	
    DEFINE cCodRet CHAR(5);
    DEFINE iSqlErr INTEGER;
    DEFINE cCodRetSp CHAR(5);
	DEFINE cDescCodRetSp CHAR(150);
    DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iRecuperacion INTEGER;
	DEFINE cMensajeRet CHAR(80);
	DEFINE cNumSolic CHAR(20);
	DEFINE cSucursal CHAR(4);
	DEFINE cNombreCte CHAR(107);
	DEFINE cRfcCte CHAR(13);
	DEFINE cEjec_autoriza CHAR(8);
	DEFINE dtFechSolic DATE;
	DEFINE cTieneOS CHAR(1);
	DEFINE cNomPdcto CHAR(40) ;
	DEFINE dLinCalculada DECIMAL(18,2);
	DEFINE cNomAnalista CHAR(45);
	DEFINE cConsulta CHAR(2) ;
	DEFINE cStatus CHAR(2);
	DEFINE iNumPag INTEGER;
	define cEjec_Atde CHAR(8);
	
    LET cCodRet = '00000';
    LET iSqlErr = 0;
    LET cCodRetSp = '';
	LET cDescCodRetSp = '';
    LET iCodRetSp = 0;
	LET cEmpresa = '001';
	LET iRecuperacion = 0;
	LET cMensajeRet = '';
	LET cNumSolic = '';
	LET cSucursal = '';
	LET cNombreCte = '';
	LET cRfcCte = '';
	LET cEjec_autoriza = '';
	LET dtFechSolic = DATE(1);
	LET cTieneOS = '';
	LET cNomPdcto = '';
	LET dLinCalculada = 0.00;
	LET cNomAnalista = '';
	LET cConsulta = '';
	LET cStatus = '';
	LET iNumPag = 0;
	LET cEjec_Atde = '';
	
    BEGIN
        
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cMensajeRet, cNumSolic, cSucursal, cNombreCte, cRfcCte, dtFechSolic, cTieneOS, cNomPdcto, dLinCalculada, cNomAnalista, cConsulta, cEjec_Atde, iNumPag, cEjec_autoriza;
			END IF;
		END EXCEPTION;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;					  			  
		--SET DEBUG FILE TO '/tmp/mfinis/sp_mc_buscasoliccac.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cMensajeRet, cNumSolic, cSucursal, cNombreCte, cRfcCte, dtFechSolic, cTieneOS, cNomPdcto, dLinCalculada, cNomAnalista, cConsulta, cEjec_Atde, iNumPag, cEjec_autoriza;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cMensajeRet, cNumSolic, cSucursal, cNombreCte, cRfcCte, dtFechSolic, cTieneOS, cNomPdcto, dLinCalculada, cNomAnalista, cConsulta, cEjec_Atde, iNumPag, cEjec_autoriza;
		END IF;
		
		-- VALIDACION DE LOS DATOS DE PAGINACIÃN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cMensajeRet, cNumSolic, cSucursal, cNombreCte, cRfcCte, dtFechSolic, cTieneOS, cNomPdcto, dLinCalculada, cNomAnalista, cConsulta, cEjec_Atde, iNumPag, cEjec_autoriza;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH cusor1 WITH HOLD FOR
 
       			SELECT SKIP pRegistros FIRST pRecuperacion mensaje_ret, num_cred, num_suc, nombre_cte, rfc_cte,	fecha_solic, OS, nom_pdcto, lin_calculada, nom_analista, consulta
				INTO   cMensajeRet, cNumSolic, cSucursal, cNombreCte, cRfcCte, dtFechSolic, cTieneOS, cNomPdcto, dLinCalculada, cNomAnalista, cConsulta
			    FROM   bdicnweb:"informix".sw_mc_buscasoliccac
				WHERE  usuario = pUsuario
				
				LET iRecuperacion = iRecuperacion + 1;
                   --- show grid 
	            RETURN 
	 		 		TRIM(NVL(cCodRet, '')), 
					TRIM(UPPER(NVL(cMensajeRet, ''))),
			        TRIM(UPPER(NVL(cNumSolic, ''))), 
					TRIM(UPPER(NVL(cSucursal, ''))), 
					TRIM(UPPER(NVL(cNombreCte, ''))), 
					TRIM(UPPER(NVL(cRfcCte, ''))), 
					dtFechSolic,
					TRIM(UPPER(NVL(cTieneOS, ''))), 
					TRIM(UPPER(NVL(cNomPdcto, ''))), 
					NVL(dLinCalculada, 0.00),
					TRIM(UPPER(NVL(cNomAnalista, ''))),
					TRIM(UPPER(NVL(cConsulta, ''))),
					TRIM(UPPER(NVL(cEjec_Atde, ''))),
					NVL(iNumPag, 0),
					TRIM(UPPER(NVL(cEjec_autoriza, ''))) 
	            WITH RESUME;
              
		END FOREACH;
		
		IF iRecuperacion = 0 AND pRegistros = 0 THEN
			LET cCodRet = '01086';
			RETURN cCodRet, cMensajeRet, cNumSolic, cSucursal, cNombreCte, cRfcCte, dtFechSolic, cTieneOS, cNomPdcto, dLinCalculada, cNomAnalista, cConsulta, cEjec_Atde, iNumPag, cEjec_autoriza;
		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cMensajeRet, cNumSolic, cSucursal, cNombreCte, cRfcCte, dtFechSolic, cTieneOS, cNomPdcto, dLinCalculada, cNomAnalista, cConsulta, cEjec_Atde, iNumPag, cEjec_autoriza;
		END IF;
		
    END;
END PROCEDURE
