CREATE PROCEDURE "informix".sp_obtieneultimg(pUsuario CHAR(8), pIdFuncion CHAR(10), pNumCte CHAR(10))
	RETURNING CHAR(5) AS codret,
	CHAR(5) AS cod_docto_comprobante,
	SMALLINT AS secuencia_max_comprobante; 
	
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(5);
	DEFINE cSqlerr INTEGER;
	DEFINE cIsamErr	INTEGER;
	DEFINE cDescErr	CHAR(50);
	DEFINE cEmpresa CHAR(3);
	DEFINE iRecuperacion INTEGER;
	DEFINE cCodDctoComprobante CHAR(5);
	DEFINE sSecuenciaMaxComprobante SMALLINT;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET cSqlerr = 0;
	LET cIsamErr = 0;
	LET cDescErr = '';
	LET cEmpresa = '001';
	LET iRecuperacion = 0;
	LET cCodDctoComprobante = "";	
	LET sSecuenciaMaxComprobante = 0;
	
	BEGIN
		
		ON EXCEPTION SET cSqlerr, cIsamErr, cDescErr
			IF cSqlerr <> 0 THEN
				LET cCodRet = cSqlerr;
				RETURN cCodRet, cCodDctoComprobante, sSecuenciaMaxComprobante; 
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_obtieneultimg.out';
		--TRACE ON;		
		
		IF pUsuario = '' OR pIdFuncion = '' OR pNumCte = '' THEN
			LET cCodRet = '00003';			
			RETURN cCodRet, cCodDctoComprobante, sSecuenciaMaxComprobante;  
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cCodDctoComprobante, sSecuenciaMaxComprobante; 
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		CALL bdidigital@coppelimg_tcp:sp_obtiene_ult_img_digi_comp_ingreso(cEmpresa, pNumCte)
		RETURNING cCodRetSp, cCodDctoComprobante, sSecuenciaMaxComprobante;
			
		IF cCodRetSp::INTEGER < 0 THEN 
			RAISE EXCEPTION cCodRetSp::INTEGER, 0, 'ERROR EN LA EJECUCIÓN DEL SP bdidigital:sp_obtiene_ult_img_digi_comp_ingreso';
		ELIF cCodRetSp::INTEGER = 24 THEN 
			LET cCodRet = '00003';
			RETURN cCodRet, cCodDctoComprobante, sSecuenciaMaxComprobante;
		END IF;
			
		RETURN cCodRet, cCodDctoComprobante, sSecuenciaMaxComprobante;
		
	END;
END PROCEDURE
