CREATE PROCEDURE "informix".sp_cg_enviodotacionmasivo(pUsuario CHAR(8), pIdFuncion CHAR(10), pLote INTEGER, pIdPlantilla CHAR(25), pTituloPlantilla CHAR(255))
					RETURNING CHAR(5) AS codret,
						INTEGER AS registros_procesados;

	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegsProcesados INTEGER;
	DEFINE iIdRegistro INTEGER;
	DEFINE cFolioOperacion CHAR(8);
	DEFINE cCodTrans CHAR(4);
	DEFINE cStatus CHAR(2);
	DEFINE cDenominacion1 CHAR(18);
	DEFINE cDenominacion2 CHAR(18);
	DEFINE cDenominacion3 CHAR(18);
	DEFINE cDenominacion4 CHAR(18);
	DEFINE cDenominacion5 CHAR(18);
	DEFINE cDenominacion6 CHAR(18);
	DEFINE cDenominacion7 CHAR(18);
	DEFINE cDenominacion8 CHAR(18);
	DEFINE cDenominacion9 CHAR(18);
	DEFINE cDenominacion10 CHAR(18);
	DEFINE cDenominacion11 CHAR(18);
	DEFINE cDenominacion12 CHAR(18);
	DEFINE cDenominacion13 CHAR(18);
	DEFINE cDenominacion14 CHAR(18);
	DEFINE cDenominacion15 CHAR(18);
	DEFINE dCantidadIng1 DECIMAL(14, 2);
	DEFINE dCantidadIng2 DECIMAL(14, 2);
	DEFINE dCantidadIng3 DECIMAL(14, 2);
	DEFINE dCantidadIng4 DECIMAL(14, 2);
	DEFINE dCantidadIng5 DECIMAL(14, 2);
	DEFINE dCantidadIng6 DECIMAL(14, 2);
	DEFINE dCantidadIng7 DECIMAL(14, 2);
	DEFINE dCantidadIng8 DECIMAL(14, 2);
	DEFINE dCantidadIng9 DECIMAL(14, 2);
	DEFINE dCantidadIng10 DECIMAL(14, 2);
	DEFINE dCantidadIng11 DECIMAL(14, 2);
	DEFINE dCantidadIng12 DECIMAL(14, 2);
	DEFINE dCantidadIng13 DECIMAL(14, 2);
	DEFINE dCantidadIng14 DECIMAL(14, 2);
	DEFINE dCantidadIng15 DECIMAL(14, 2);
	DEFINE dTotalBilletes DECIMAL(18, 2);
	DEFINE dTotalMorralla DECIMAL(18, 2);
	DEFINE dSumaIngreso DECIMAL(18, 2);
	DEFINE dSaldoTotal DECIMAL(18,2);
	DEFINE dTotalBilletesEgr DECIMAL(18, 2);
	DEFINE dTotalMorrallaEgr DECIMAL(18, 2);
	DEFINE dSumaEgreso DECIMAL(18, 2);

	DEFINE dCantidadEgr1 DECIMAL(14, 2);
	DEFINE dCantidadEgr2 DECIMAL(14, 2);
	DEFINE dCantidadEgr3 DECIMAL(14, 2);
	DEFINE dCantidadEgr4 DECIMAL(14, 2);
	DEFINE dCantidadEgr5 DECIMAL(14, 2);
	DEFINE dCantidadEgr6 DECIMAL(14, 2);
	DEFINE dCantidadEgr7 DECIMAL(14, 2);
	DEFINE dCantidadEgr8 DECIMAL(14, 2);
	DEFINE dCantidadEgr9 DECIMAL(14, 2);
	DEFINE dCantidadEgr10 DECIMAL(14, 2);
	DEFINE dCantidadEgr11 DECIMAL(14, 2);
	DEFINE dCantidadEgr12 DECIMAL(14, 2);
	DEFINE dCantidadEgr13 DECIMAL(14, 2);
	DEFINE dCantidadEgr14 DECIMAL(14, 2);
	DEFINE dCantidadEgr15 DECIMAL(14, 2);
	DEFINE cCodProveedor CHAR(4);
	DEFINE cMensaje CHAR(150);
	DEFINE bSumasIguales BOOLEAN;
	DEFINE bSaldoIngresoMayor BOOLEAN;
	DEFINE cCodRetorno CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cCodRetSp CHAR(6);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegsProcesados = 0;
	LET iIdRegistro = 0;
	LET cFolioOperacion = '';
	LET cCodTrans = '';
	LET cStatus = '';
	LET cDenominacion1 = '';
	LET cDenominacion2 = '';
	LET cDenominacion3 = '';
	LET cDenominacion4 = '';
	LET cDenominacion5 = '';
	LET cDenominacion6 = '';
	LET cDenominacion7 = '';
	LET cDenominacion8 = '';
	LET cDenominacion9 = '';
	LET cDenominacion10 = '';
	LET cDenominacion11 = '';
	LET cDenominacion12 = '';
	LET cDenominacion13 = '';
	LET cDenominacion14 = '';
	LET cDenominacion15 = '';
	LET dCantidadIng1 = NULL;
	LET dCantidadIng2 = NULL;
	LET dCantidadIng3 = NULL;
	LET dCantidadIng4 = NULL;
	LET dCantidadIng5 = NULL;
	LET dCantidadIng6 = NULL;
	LET dCantidadIng7 = NULL;
	LET dCantidadIng8 = NULL;
	LET dCantidadIng9 = NULL;
	LET dCantidadIng10 = NULL;
	LET dCantidadIng11 = NULL;
	LET dCantidadIng12 = NULL;
	LET dCantidadIng13 = NULL;
	LET dCantidadIng14 = NULL;
	LET dCantidadIng15 = NULL;
	LET dTotalBilletes = 0.0;
	LET dTotalMorralla = 0.0;
	LET dSaldoTotal = 0.0;
	LET dSumaIngreso = 0.0;
	LET dTotalBilletesEgr = 0.0;
	LET dTotalMorrallaEgr = 0.0;
	LET dSumaEgreso = 0.0;
	LET bSumasIguales = 'f';
	LET bSaldoIngresoMayor = 'f';

	LET dCantidadEgr1 = NULL;
	LET dCantidadEgr2 = NULL;
	LET dCantidadEgr3 = NULL;
	LET dCantidadEgr4 = NULL;
	LET dCantidadEgr5 = NULL;
	LET dCantidadEgr6 = NULL;
	LET dCantidadEgr7 = NULL;
	LET dCantidadEgr8 = NULL;
	LET dCantidadEgr9 = NULL;
	LET dCantidadEgr10 = NULL;
	LET dCantidadEgr11 = NULL;
	LET dCantidadEgr12 = NULL;
	LET dCantidadEgr13 = NULL;
	LET dCantidadEgr14 = NULL;
	LET dCantidadEgr15 = NULL;
	LET cCodProveedor = '';
	LET cMensaje = '';
	LET cCodRetorno = '';
	LET iCodRetSp = 0;
	LET cCodRetSp = '';

	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, iNoRegsProcesados;
		END EXCEPTION;

		--SET DEBUG FILE TO '/tmp/mfinis/sp_cg_enviodotacionmasivo.out';
		--TRACE ON;
		
		SET LOCK MODE TO WAIT 3;
		SET ISOLATION TO DIRTY READ;

		IF pUsuario = '' OR pIdFuncion = '' OR pLote IS NULL OR pIdPlantilla = '' OR pTituloPlantilla = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, iNoRegsProcesados;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:'informix'.sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, iNoRegsProcesados;
		END IF;

		FOREACH SELECT {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} folio_operacion, id_registro 
				INTO cFolioOperacion, iIdRegistro
				FROM bdicnweb:'informix'.sw_cg_enviodotaciones
				WHERE id_usuario_soc = pUsuario
				AND id_lote = pLote
				AND status = 'P'

			-- VALIDACIÃÂN DE QUE EL FOLIO EXISTA
			IF EXISTS (SELECT folio_oper FROM bdisuc:'informix'.ss_operaciones WHERE folio_oper = cFolioOperacion) THEN

				SELECT crs.cod_trans, rstablas.status,
					CASE WHEN TRIM(crs.denominacion_1) = '' THEN '0' ELSE crs.denominacion_1 END,
					CASE WHEN TRIM(crs.denominacion_2) = '' THEN '0' ELSE crs.denominacion_2 END,
					CASE WHEN TRIM(crs.denominacion_3) = '' THEN '0' ELSE crs.denominacion_3 END,
					CASE WHEN TRIM(crs.denominacion_4) = '' THEN '0' ELSE crs.denominacion_4 END,
					CASE WHEN TRIM(crs.denominacion_5) = '' THEN '0' ELSE crs.denominacion_5 END,
					CASE WHEN TRIM(crs.denominacion_6) = '' THEN '0' ELSE crs.denominacion_6 END,
					CASE WHEN TRIM(crs.denominacion_7) = '' THEN '0' ELSE crs.denominacion_7 END,
					CASE WHEN TRIM(crs.denominacion_8) = '' THEN '0' ELSE crs.denominacion_8 END,
					CASE WHEN TRIM(crs.denominacion_9) = '' THEN '0' ELSE crs.denominacion_9 END,
					CASE WHEN TRIM(crs.denominacion_10) = '' THEN '0' ELSE crs.denominacion_10 END,
					CASE WHEN TRIM(crs.denominacion_11) = '' THEN '0' ELSE crs.denominacion_11 END,
					CASE WHEN TRIM(crs.denominacion_12) = '' THEN '0' ELSE crs.denominacion_12 END,
					CASE WHEN TRIM(crs.denominacion_13) = '' THEN '0' ELSE crs.denominacion_13 END,
					CASE WHEN TRIM(crs.denominacion_14) = '' THEN '0' ELSE crs.denominacion_14 END,
					CASE WHEN TRIM(crs.denominacion_15) = '' THEN '0' ELSE crs.denominacion_15 END,
					crs.cantidad_1, crs.cantidad_2, crs.cantidad_3, crs.cantidad_4, crs.cantidad_5,
					crs.cantidad_6, crs.cantidad_7, crs.cantidad_8, crs.cantidad_9, crs.cantidad_10,
					crs.cantidad_11, crs.cantidad_12, crs.cantidad_13, crs.cantidad_14, crs.cantidad_15, 
					rs2.saldo_total,
					rs2.cantidad_1, rs2.cantidad_2, rs2.cantidad_3, rs2.cantidad_4, rs2.cantidad_5,
					rs2.cantidad_6, rs2.cantidad_7, rs2.cantidad_8, rs2.cantidad_9, rs2.cantidad_10,
					rs2.cantidad_11, rs2.cantidad_12, rs2.cantidad_13, rs2.cantidad_14, rs2.cantidad_15,
					rstablas.cod_proveedor
				INTO cCodTrans, cStatus, 
					cDenominacion1, cDenominacion2, cDenominacion3, cDenominacion4, cDenominacion5, 
					cDenominacion6, cDenominacion7, cDenominacion8, cDenominacion9, cDenominacion10,
					cDenominacion11, cDenominacion12, cDenominacion13, cDenominacion14, cDenominacion15,
					dCantidadIng1, dCantidadIng2, dCantidadIng3, dCantidadIng4, dCantidadIng5,
					dCantidadIng6, dCantidadIng7, dCantidadIng8, dCantidadIng9, dCantidadIng10,
					dCantidadIng11, dCantidadIng12, dCantidadIng13, dCantidadIng14, dCantidadIng15,
					dSaldoTotal,
					dCantidadEgr1, dCantidadEgr2, dCantidadEgr3, dCantidadEgr4, dCantidadEgr5,
					dCantidadEgr6, dCantidadEgr7, dCantidadEgr8, dCantidadEgr9, dCantidadEgr10,
					dCantidadEgr11, dCantidadEgr12, dCantidadEgr13, dCantidadEgr14, dCantidadEgr15,
					cCodProveedor
				FROM bdisuc:'informix'.ss_operaciones crs LEFT JOIN bdisuc:'informix'.ss_mae_entradasalida rstablas ON rstablas.folio_oper = crs.folio_oper
					LEFT JOIN bdisuc:'informix'.ss_cajageneral rs2 ON rs2.cod_proveedor = rstablas.cod_proveedor
				WHERE crs.folio_oper = cFolioOperacion;

				IF (cCodTrans = '0001' AND cStatus = '01') OR (cCodTrans = '0010' AND cStatus = '01') OR (cCodTrans = '0036' AND cStatus IN ('01','12')) THEN
					LET dTotalBilletes = 0.0;
					LET dTotalMorralla = 0.0;

					IF NVL(cDenominacion1, '') <> '' THEN
						IF dCantidadIng1 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng1 * cDenominacion1);
						END IF;
					END IF;

					IF NVL(cDenominacion2, '') <> '' THEN
						IF dCantidadIng2 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng2 * cDenominacion2);
						END IF;
					END IF;

					IF NVL(cDenominacion3, '') <> '' THEN
						IF dCantidadIng3 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng3 * cDenominacion3);
						END IF;
					END IF;

					IF NVL(cDenominacion4, '') <> '' THEN
						IF dCantidadIng4 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng4 * cDenominacion4);
						END IF;
					END IF;

					IF NVL(cDenominacion5, '') <> '' THEN
						IF dCantidadIng5 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng5 * cDenominacion5);
						END IF;
					END IF;

					IF NVL(cDenominacion6, '') <> '' THEN
						IF dCantidadIng6 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng6 * cDenominacion6);
						END IF;
					END IF;

					IF NVL(cDenominacion7, '') <> '' THEN
						IF dCantidadIng7 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng7 * cDenominacion7);
						END IF;
					END IF;

					IF NVL(cDenominacion8, '') <> '' THEN
						IF dCantidadIng8 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng8 * cDenominacion8);
						END IF; 
					END IF;

					IF NVL(cDenominacion9, '') <> '' THEN
						IF dCantidadIng9 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng9 * cDenominacion9);
						END IF;
					END IF;

					IF NVL(cDenominacion10, '') <> '' THEN
						IF dCantidadIng10 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng10 * cDenominacion10);
						END IF;
					END IF;

					IF NVL(cDenominacion11, '') <> '' THEN
						IF dCantidadIng11 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng11 * cDenominacion11);
						END IF;
					END IF;

					IF NVL(cDenominacion12, '') <> '' THEN
						IF dCantidadIng12 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng12 * cDenominacion12);
						END IF;
					END IF;

					IF NVL(cDenominacion13, '') <> '' THEN
						IF dCantidadIng13 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng13 * cDenominacion13);
						END IF;
					END IF;

					IF NVL(cDenominacion14, '') <> '' THEN
						IF dCantidadIng14 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng14 * cDenominacion14);
						END IF;
					END IF;

					IF NVL(cDenominacion15, '') <> '' THEN
						IF dCantidadIng15 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng15 * cDenominacion15);
						END IF;
					END IF;

					-- COMPARACIÃÂN DEL MONTO TOTAL
					LET dSumaIngreso = dTotalBilletes + dTotalMorralla;
					IF dSumaIngreso > dSaldoTotal THEN
						LET cMensaje = 'LA DOTACION SOLICITADA '||TRIM(cFolioOperacion)||' ES MAYOR AL SALDO DISPONIBLE EN CAJA GENERAL';
						LET cCodRetorno = '00001';
					ELSE
						IF dCantidadIng1 > dCantidadEgr1 THEN
							LET dCantidadEgr1 = 0;
						ELSE
							LET dCantidadEgr1 = dCantidadIng1 * cDenominacion1;
						END IF;

						IF dCantidadIng2 > dCantidadEgr2 THEN
							LET dCantidadEgr2 = 0;
						ELSE
							LET dCantidadEgr2 = dCantidadIng2 * cDenominacion2;
						END IF;

						IF dCantidadIng3 > dCantidadEgr3 THEN
							LET dCantidadEgr3 = 0;
						ELSE
							LET dCantidadEgr3 = dCantidadIng3 * cDenominacion3;
						END IF;

						IF dCantidadIng4 > dCantidadEgr4 THEN
							LET dCantidadEgr4 = 0;
						ELSE
							LET dCantidadEgr4 = dCantidadIng4 * cDenominacion4;
						END IF;

						IF dCantidadIng5 > dCantidadEgr5 THEN
							LET dCantidadEgr5 = 0;
						ELSE
							LET dCantidadEgr5 = dCantidadIng5 * cDenominacion5;
						END IF;

						IF dCantidadIng6 > dCantidadEgr6 THEN
							LET dCantidadEgr6 = 0;
						ELSE
							LET dCantidadEgr6 = dCantidadIng6 * cDenominacion6;
						END IF;

						IF dCantidadIng7 > dCantidadEgr7 THEN
							LET dCantidadEgr7 = 0;
						ELSE
							LET dCantidadEgr7 = dCantidadIng7 * cDenominacion7;
						END IF;

						IF dCantidadIng8 > dCantidadEgr8 THEN
							LET dCantidadEgr8 = 0;
						ELSE
							LET dCantidadEgr8 = dCantidadIng8 * cDenominacion8;
						END IF;

						IF dCantidadIng9 > dCantidadEgr9 THEN
							LET dCantidadEgr9 = 0;
						ELSE
							LET dCantidadEgr9 = dCantidadIng9 * cDenominacion9;
						END IF;

						IF dCantidadIng10 > dCantidadEgr10 THEN
							LET dCantidadEgr10 = 0;
						ELSE
							LET dCantidadEgr10 = dCantidadIng10 * cDenominacion10;
						END IF;

						IF dCantidadIng11 > dCantidadEgr11 THEN
							LET dCantidadEgr11 = 0;
						ELSE
							LET dCantidadEgr11 = dCantidadIng11 * cDenominacion11;
						END IF;

						IF dCantidadIng12 > dCantidadEgr12 THEN
							LET dCantidadEgr12 = 0;
						ELSE
							LET dCantidadEgr12 = dCantidadIng12 * cDenominacion12;
						END IF;

						IF dCantidadIng13 > dCantidadEgr13 THEN
							LET dCantidadEgr13 = 0;
						ELSE
							LET dCantidadEgr13 = dCantidadIng13 * cDenominacion13;
						END IF;

						IF dCantidadIng14 > dCantidadEgr14 THEN
							LET dCantidadEgr14 = 0;
						ELSE
							LET dCantidadEgr14 = dCantidadIng14 * cDenominacion14;
						END IF;

						IF dCantidadIng15 > dCantidadEgr15 THEN
							LET dCantidadEgr15 = 0;
						ELSE
							LET dCantidadEgr15 = dCantidadIng15 * cDenominacion15;
						END IF;

						LET dTotalBilletesEgr = 0.0;
						LET dTotalMorrallaEgr = 0.0;

						LET dTotalBilletesEgr = dCantidadEgr1 + dCantidadEgr2 + dCantidadEgr3 + dCantidadEgr4 + dCantidadEgr5 + dCantidadEgr6 + dCantidadEgr7;
						LET dTotalMorrallaEgr = dCantidadEgr8 + dCantidadEgr9 + dCantidadEgr10 + dCantidadEgr11 + dCantidadEgr12 + dCantidadEgr13 + dCantidadEgr14 + dCantidadEgr15;
						LET dSumaEgreso = dTotalBilletesEgr + dTotalMorrallaEgr;

						IF dSumaIngreso = dSumaEgreso THEN
							LET bSumasIguales = 't';
						ELSE
							LET bSumasIguales = 'f';
						END IF;

						IF dSumaIngreso > dSaldoTotal THEN
							LET bSaldoIngresoMayor = 't';
						ELSE
							LET bSaldoIngresoMayor = 'f';
						END IF;

						-- VALIDACIÃÂN DE LAS SUMAS
						IF bSumasIguales AND NOT bSaldoIngresoMayor THEN

							IF cStatus IN ('01', '12') THEN

								-- ACTUALIZACIÃÂN DEL FOLIO DE OPERACION
								UPDATE bdisuc:'informix'.ss_mae_entradasalida
								SET status = '03',
									hora_envio = TO_CHAR(CURRENT, '%H:%m'),
									fecha_envio = CURRENT,
									usuario_envio = pUsuario
								WHERE folio_oper = cFolioOperacion;

								-- ACTUALIZACIÃÂN DE LA DOTACIÃÂN
								UPDATE bdisuc:'informix'.ss_cajageneral
								SET cantidad_1 = cantidad_1 - dCantidadIng1,
									cantidad_2 = cantidad_2 - dCantidadIng2,
									cantidad_3 = cantidad_3 - dCantidadIng3,
									cantidad_4 = cantidad_4 - dCantidadIng4,
									cantidad_5 = cantidad_5 - dCantidadIng5,
									cantidad_6 = cantidad_6 - dCantidadIng6,
									cantidad_7 = cantidad_7 - dCantidadIng7,
									cantidad_8 = cantidad_8 - dCantidadIng8,
									cantidad_9 = cantidad_9 - dCantidadIng9,
									cantidad_10 = cantidad_10 - dCantidadIng10,
									cantidad_11 = cantidad_11 - dCantidadIng11,
									cantidad_12 = cantidad_12 - dCantidadIng12,
									cantidad_13 = cantidad_13 - dCantidadIng13,
									cantidad_14 = cantidad_14 - dCantidadIng14,
									cantidad_15 = cantidad_15 - dCantidadIng15,
									saldo_total = saldo_total - dSumaEgreso,
									saldo_asignado = saldo_asignado + dSumaEgreso
								WHERE cod_proveedor = cCodProveedor;

								LET cMensaje = 'OPERACION EXITOSA';
								LET cCodRetorno = '00000';
							ELSE    
								LET cMensaje = 'LA OPERACION NO CUENTA CON EL ESTATUS REQUERIDO DE SOLICITUD DOTACION SUCURSAL';
								LET cCodRetorno = '00004';
							END IF;
						ELSE
							LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
							LET cCodRetorno = '00003';
						END IF;

					END IF;

				END IF;

			ELSE
				LET cMensaje = 'EL FOLIO DE OPERACION '||TRIM(cFolioOperacion)||' NO EXISTE';
				LET cCodRetorno = '00002';
			END IF;

			-- ACTUALIZACION DEL MENSAJE
			UPDATE bdicnweb:'informix'.sw_cg_enviodotaciones
			SET mensaje = cMensaje,
				fecha_proceso = CURRENT,
				cod_retorno = cCodRetorno
			WHERE id_registro = iIdRegistro;

			LET iNoRegsProcesados = iNoRegsProcesados + 1;

		END FOREACH;

		---- ACTUALIZACION DEL ESTATUS A TERMINADO
		UPDATE bdicnweb:'informix'.sw_cg_enviodotaciones
		SET status = 'T'
		WHERE id_lote = pLote
		AND fecha_proceso IS NOT NULL;

		-- SE MUEVE TODO EL LOTE AL HISTORICO
		INSERT INTO bdicnweb:'informix'.sw_cg_enviodotaciones_hist
		SELECT *
		FROM bdicnweb:'informix'.sw_cg_enviodotaciones
		WHERE id_lote = pLote
		AND fecha_proceso IS NOT NULL;

		DELETE FROM bdicnweb:'informix'.sw_cg_enviodotaciones
		WHERE id_lote = pLote;

		-- ENVIO DE LA INFORMACIÃÂN POR CORREO ELECTRONICO
		EXECUTE PROCEDURE bdimnsj:'informix'.sp_registra_evento(
			'1', 
			TRIM(pIdPlantilla), 
			TRIM(pIdPlantilla), 
			pUsuario, 
			'', 
			'', 
			'1', 
			'', 
			'', 
			'', 
			'', 
			'', 
			TRIM(pTituloPlantilla), 
			'ENVIO DE DOTACIONES CAJA GENERAL ', 
			'', 
			'', 
			'', 
			'', 
			'',
			'0', 
			'0', 
			'0', 
			'0', 
			'0', 
			CURRENT, 
			CURRENT) INTO cCodRetSp;

		LET iCodRetSp = cCodRetSp::INTEGER;
		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION iCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP sp_registra_evento';
		ELIF iCodRetSp > 0 THEN
			LET cCodRet = LPAD(iCodRetSp, 5, '0');
			RETURN cCodRet, iNoRegsProcesados;
		END IF; 

		RETURN cCodRet, iNoRegsProcesados;

	END;

END PROCEDURE
DOCUMENT 'AUTOR: Oscar Flores Conde',
'FECHA: 11/02/2015',
'DESCRIPCION: Ejecuta en envio masivo de dotaciÃÂ³n de caja general',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_rem_actualizalimite(pUsuario CHAR(8), pIdFuncion CHAR(10), pSucursal CHAR(4), pRemesa CHAR(3), 
pLimiteDom INTEGER, pLimiteTel INTEGER, pActMaxLim CHAR(1), pValorMaxLim CHAR(100))
		RETURNING CHAR(5) AS codret;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iCodParam INTEGER;
	DEFINE cSucursal CHAR(4);
	DEFINE cRemesa CHAR(3);
	DEFINE iLimDom INTEGER;
	DEFINE iLimTel INTEGER;
	DEFINE cUsuario_insert CHAR(8);
	DEFINE dFecha_insert DATETIME YEAR TO SECOND;
	DEFINE iExiste INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET iCodParam = 0;
	LET cSucursal = '';
	LET cRemesa = '';
	LET iLimDom = 0;
	LET iLimTel = 0;
	LET cUsuario_insert = '';
	LET dFecha_insert = '';
	LET iExiste = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_actualizalimite.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pSucursal <> '' AND pRemesa <> '' THEN
			
			--GUARDA/ACTUALIZA LÍMITES
			SELECT id_sucursal, tipo_remesa, limitedom, limitetel, usuario_insert, fecha_insert 
			INTO cSucursal, cRemesa, iLimDom, iLimTel, cUsuario_insert, dFecha_insert 
			FROM bdisac:"informix".sac_pldlimite_teldom_excpsuc WHERE id_sucursal = pSucursal AND tipo_remesa = pRemesa;
			
			IF NVL(cSucursal,'') = '' THEN
				
				INSERT INTO bdisac:"informix".sac_pldlimite_teldom_excpsuc(id_sucursal,tipo_remesa,limitedom,limitetel,usuario_insert,fecha_insert) 
				VALUES (pSucursal,pRemesa,pLimiteDom,pLimiteTel,pUsuario,CURRENT);
				
				IF DBINFO('sqlca.sqlerrd2') = 0 THEN
					LET cCodRet = '00282';
				ELSE
					INSERT INTO bdisac:"informix".sac_pldlimite_bitacoramodsoc(id_sucursal,tipo_remesa,limitedomant,limitedommod,limitetelant,limitetelmod,usuario_insert,usuario_modifica,fecha_insert,fecha_modifica) 
					VALUES (pSucursal,pRemesa,'',pLimiteDom,'',pLimiteTel,pUsuario,'',CURRENT,'');
					
					IF DBINFO('sqlca.sqlerrd2') = 0 THEN
						LET cCodRet = '00282';
					END IF;
				END IF;
				
			ELIF NVL(cSucursal,'') <> '' THEN
				
				UPDATE bdisac:"informix".sac_pldlimite_teldom_excpsuc 
				SET limitedom = pLimiteDom, limitetel = pLimiteTel
				WHERE id_sucursal = pSucursal AND tipo_remesa = pRemesa;
				
				IF DBINFO('sqlca.sqlerrd2') = 0 THEN
					LET cCodRet = '00283';
				ELSE
					INSERT INTO bdisac:"informix".sac_pldlimite_bitacoramodsoc(id_sucursal,tipo_remesa,limitedomant,limitedommod,limitetelant,limitetelmod,usuario_insert,usuario_modifica,fecha_insert,fecha_modifica) 
					VALUES (pSucursal,pRemesa,iLimDom,pLimiteDom,iLimTel,pLimiteTel,cUsuario_insert,pUsuario,dFecha_insert,CURRENT);
					
					IF DBINFO('sqlca.sqlerrd2') = 0 THEN
						LET cCodRet = '00282';
					END IF;
				END IF;
				
			END IF;
		
		END IF;
		
		IF NVL(pActMaxLim,'') <> '' THEN
			
			--MAX DOMICILIOS
			IF pActMaxLim = '1' THEN
				LET iCodParam = 130;
				LET iLimDom = 0;
				LET cUsuario_insert = '';
				LET dFecha_insert = '';
				
				SELECT valor, user_insert, fecha_insert INTO iLimDom, cUsuario_insert, dFecha_insert
				FROM bdisac:"informix".sac_param WHERE empresa = cEmpresa AND cod_param = iCodParam;
				
				UPDATE bdisac:"informix".sac_param SET valor = pValorMaxLim WHERE empresa = cEmpresa AND cod_param = iCodParam;
				
				IF DBINFO('sqlca.sqlerrd2') = 0 THEN
					LET cCodRet = '00283';
				ELSE
					
					IF NVL(cUsuario_insert,'') = '' OR NVL(dFecha_insert,'') = '' THEN
						LET cUsuario_insert = pUsuario;
						LET dFecha_insert = CURRENT;
					END IF;
					
					INSERT INTO bdisac:"informix".sac_pldlimite_bitacoramodsoc(id_sucursal,tipo_remesa,limitedomant,limitedommod,usuario_insert,usuario_modifica,fecha_insert,fecha_modifica) 
					VALUES ('0000','GEN',iLimDom,pValorMaxLim,cUsuario_insert,pUsuario,dFecha_insert,CURRENT);
					
					IF DBINFO('sqlca.sqlerrd2') = 0 THEN
						LET cCodRet = '00282';
					END IF;
				END IF;
				
			--MAX TELÉFONOS
			ELIF pActMaxLim = '2' THEN
				LET iCodParam = 131;
				LET iLimTel = 0;
				LET cUsuario_insert = '';
				LET dFecha_insert = '';
				
				SELECT valor, user_insert, fecha_insert INTO iLimTel, cUsuario_insert, dFecha_insert 
				FROM bdisac:"informix".sac_param WHERE empresa = cEmpresa AND cod_param = iCodParam;
				
				UPDATE bdisac:"informix".sac_param SET valor = pValorMaxLim WHERE empresa = cEmpresa AND cod_param = iCodParam;
				
				IF DBINFO('sqlca.sqlerrd2') = 0 THEN
					LET cCodRet = '00283';
				ELSE
					
					IF NVL(cUsuario_insert,'') = '' OR NVL(dFecha_insert,'') = '' THEN
						LET cUsuario_insert = pUsuario;
						LET dFecha_insert = CURRENT;
					END IF;
					
					INSERT INTO bdisac:"informix".sac_pldlimite_bitacoramodsoc(id_sucursal,tipo_remesa,limitetelant,limitetelmod,usuario_insert,usuario_modifica,fecha_insert,fecha_modifica) 
					VALUES ('0000','GEN',iLimTel,pValorMaxLim,cUsuario_insert,pUsuario,dFecha_insert,CURRENT);
					
					IF DBINFO('sqlca.sqlerrd2') = 0 THEN
						LET cCodRet = '00282';
					END IF;
				END IF;
				
			END IF;
			
		END IF;
		
		RETURN cCodRet;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 25/02/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: LÍMITES DE DOMICILIOS Y TELÉFONOS DE REMESAS',
'DESCRIPCION: SPL encargado de guardar/actualizar los límites de la sucursal-remesa consultada.',
'AUTOR: L. Montserrat Leon Amador',
'FECHA: 20/03/2020',
'DESCRIPCION: Se modifica SPL para agregar el registro en bitácora cuando se actualizan los limites máximos de la tabla sac_param.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_rem_cattipolimite(pUsuario CHAR(8), pIdFuncion CHAR(10))
		RETURNING CHAR(5) AS codret,
			SMALLINT AS id_limite,
			CHAR(35) AS desc_limite;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cIdLimite SMALLINT;
	DEFINE cDescLimite CHAR(35);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cIdLimite = 0;
	LET cDescLimite = '';
	LET iNoRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cIdLimite, cDescLimite;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_cattipolimite.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cIdLimite, cDescLimite;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cIdLimite, cDescLimite;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			
			SELECT id_limite, desc_limite
			INTO cIdLimite, cDescLimite
			FROM bdicnweb:"informix".sw_tipolimite
			ORDER BY id_limite ASC
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet, cIdLimite, cDescLimite WITH RESUME;
			
		END FOREACH;
		
		IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, cIdLimite, cDescLimite;
		END IF;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 25/02/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: LÍMITES DE DOMICILIOS Y TELÉFONOS DE REMESAS',
'DESCRIPCION: SPL encargado de consultar el detalle del catálogo tipo de límite.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_rem_cattiporemesa(pUsuario CHAR(8), pIdFuncion CHAR(10))
		RETURNING CHAR(5) AS codret,
			CHAR(10) AS id_remesa,
			CHAR(35) AS desc_remesa;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cIdRemesa CHAR(10);
	DEFINE cDescRemesa CHAR(35);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cIdRemesa = 0;
	LET cDescRemesa = '';
	LET iNoRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cIdRemesa, cDescRemesa;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_cattiporemesa.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cIdRemesa, cDescRemesa;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cIdRemesa, cDescRemesa;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			
			SELECT numconvenio, tipo_remesa
			INTO cIdRemesa, cDescRemesa
			FROM bdisac:"informix".sac_cat_tiporemesa
			--ORDER BY numconvenio ASC
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet, cIdRemesa, cDescRemesa WITH RESUME;
			
		END FOREACH;
		
		IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, cIdRemesa, cDescRemesa;
		END IF;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 25/02/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: LÍMITES DE DOMICILIOS Y TELÉFONOS DE REMESAS',
