CREATE PROCEDURE "informix".sp_rem_consultalimite(pUsuario CHAR(8), pIdFuncion CHAR(10), pSucursal CHAR(4), pRemesa CHAR(3))
		RETURNING CHAR(5) AS codret,
			INTEGER AS limite_dom,
			INTEGER AS limite_tel;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iCodParam INTEGER;
	DEFINE cSucursal CHAR(4);
	DEFINE cRemesa CHAR(3);
	DEFINE iLimDom INTEGER;
	DEFINE iLimTel INTEGER;
	DEFINE iExiste INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET iCodParam = 0;
	LET cSucursal = '';
	LET cRemesa = '';
	LET iLimDom = 0;
	LET iLimTel = 0;
	LET iExiste = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, iLimDom, iLimTel;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_consultalimite.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pSucursal = '' OR pRemesa = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, iLimDom, iLimTel;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, iLimDom, iLimTel;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT limitedom, limitetel INTO iLimDom, iLimTel 
		FROM bdisac:"informix".sac_pldlimite_teldom_excpsuc WHERE id_sucursal = pSucursal AND tipo_remesa = pRemesa;
		
		RETURN cCodRet, iLimDom, iLimTel;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 25/02/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: LÍMITES DE DOMICILIOS Y TELÉFONOS DE REMESAS',
