CREATE PROCEDURE "informix".sp_rem_consultasucursal(pUsuario CHAR(8), pIdFuncion CHAR(10), pSucursal CHAR(4))
		RETURNING CHAR(5) AS codret,
			CHAR(4)  AS sucursal,
			CHAR(40) AS nomsucursal;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);	
	DEFINE cSucursal CHAR(4);
	DEFINE cNombreSucursal CHAR(40);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cEmpresa = '001';	
	LET cSucursal = '';
	LET cNombreSucursal = '';
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cSucursal, cNombreSucursal;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_consultasucursal.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pSucursal = ''  THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cSucursal, cNombreSucursal;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cSucursal, cNombreSucursal;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT sucursal, nombre INTO cSucursal, cNombreSucursal FROM bdinteg:"informix".si_sucursales WHERE sucursal = pSucursal;
		
		RETURN cCodRet, cSucursal, cNombreSucursal;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Julio Martínez',
'FECHA: 10/03/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: LÍMITES DE DOMICILIOS Y TELÉFONOS DE REMESAS',
'DESCRIPCION: SPL encargado de obtener el nombre de la sucursal por medio del numero de sucursal.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_rem_consultasucursalremrechazadas(pUsuario CHAR(8), pIdFuncion CHAR(10))
		RETURNING CHAR(5) AS codret,
			CHAR(4)  AS sucursal,
			CHAR(40) AS nomsucursal;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);	
	DEFINE cSucursal CHAR(4);
	DEFINE cIdSucursal CHAR(4);
	DEFINE cNombreSucursal CHAR(40);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cSucursal = '';
	LET cNombreSucursal = '';
	LET iNoRegistros = 0;
	LET cIdSucursal =  '';
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cSucursal, cNombreSucursal;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_consultasucursalremrechazadas.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = ''  THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cSucursal, cNombreSucursal;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cSucursal, cNombreSucursal;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH WITH HOLD
			SELECT DISTINCT id_sucursal INTO cIdSucursal
			FROM bdisac:"informix".sac_pldlimite_teldom_rechazos
			
			FOREACH
				SELECT first 1 sucursal, nombre INTO cSucursal, cNombreSucursal 
				FROM bdinteg:"informix".si_sucursales 
				WHERE sucursal = cIdSucursal ORDER BY sucursal ASC
			
				LET iNoRegistros = iNoRegistros + 1;
			END FOREACH;
			
			RETURN cCodRet, cSucursal, cNombreSucursal WITH RESUME;
		END FOREACH;
		
		IF iNoRegistros = 0  THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cSucursal, cNombreSucursal;		
		END IF;
		
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Julio Martínez',
'FECHA: 10/03/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: LÍMITES DE DOMICILIOS Y TELÉFONOS DE REMESAS',
'DESCRIPCION: SPL encargado de obtener el numero y nombre de la sucursal de remesas rechazadas.',
'AUTOR: L. Montserrat León Amador',
'FECHA: 30/03/2020',
'DESCRIPCION: Se realiza el cambio de tabla (sac_pldlimite_teldom_rechazos) para recuperar el detalle de las sucursales rechazadas.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_rem_detremesasrechazadas(pUsuario CHAR(8), pIdFuncion CHAR(10), pPeriodoDel DATE, pPeriodoAl DATE, pSucursal CHAR(4),
pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(3) AS tipo_remesa,
			CHAR(4) AS id_sucursal,
			CHAR(200) AS direccion,
			CHAR(100) AS municipio,
			CHAR(30) AS estado,
			CHAR(50) AS codigo_postal,
			CHAR(6) AS periodo,
			INTEGER AS conteodom,
			INTEGER AS limitedom,
			CHAR(10) AS telefono,
			CHAR(10) AS celular,
			INTEGER AS conteotel,
			INTEGER AS limitetel,
			INTEGER AS tiporechazo,
			CHAR(40) AS motivorechazo,
			CHAR(20) AS numremesa,
			CHAR(16) AS folio_suc,
			CHAR(8) AS usuario_insert,
			DATETIME YEAR TO SECOND AS fecha_insert,
			CHAR(40) AS emisor_nombre1,
			CHAR(40) AS emisor_nombre2,
			CHAR(40) AS emisor_appaterno,
			CHAR(40) AS emisor_apmaterno,
			CHAR(3) AS emisor_cod_pais,
			CHAR(20) AS monto_total_origen,
			CHAR(20) AS monto_total_destino,
			CHAR(40) AS benef_nombre1,
			CHAR(40) AS benef_nombre2,
			CHAR(40) AS benef_appaterno,
			CHAR(40) AS benef_apmaterno;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE cTipo_remesa VARCHAR(3);
	DEFINE cId_sucursal VARCHAR(4);
	DEFINE cDireccion VARCHAR(200);
	DEFINE cMunicipio VARCHAR(100);
	DEFINE cEstado VARCHAR(30);
	DEFINE cCodigo_postal VARCHAR(50);
	DEFINE cPeriodo VARCHAR(6);
	DEFINE iConteodom INTEGER;
	DEFINE ilimitedom INTEGER;
	DEFINE cTelefono VARCHAR(10);
	DEFINE cCelular VARCHAR(10);
	DEFINE iConteotel INTEGER;
	DEFINE iLimitetel INTEGER;
	DEFINE iTiporechazo INTEGER;
	DEFINE cMotivorechazo VARCHAR(40);
	DEFINE cNumremesa VARCHAR(20);
	DEFINE cFolio_suc VARCHAR(16);
	DEFINE cUsuario_insert VARCHAR(8);
	DEFINE dFecha_insert DATETIME YEAR TO SECOND;
	DEFINE cEmisor_nombre1 CHAR(40);
	DEFINE cEmisor_nombre2 CHAR(40);
	DEFINE cEmisor_appaterno CHAR(40);
	DEFINE cEmisor_apmaterno CHAR(40);
	DEFINE cEmisor_cod_pais CHAR(3);
	DEFINE cMonto_total_origen CHAR(20);
	DEFINE cMonto_total_destino CHAR(20);
	DEFINE cBenef_nombre1 CHAR(40);
	DEFINE cBenef_nombre2 CHAR(40);
	DEFINE cBenef_appaterno CHAR(40);
	DEFINE cBenef_apmaterno CHAR(40);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	LET cTipo_remesa = '';
	LET cId_sucursal = '';
	LET cDireccion = '';
	LET cMunicipio = '';
	LET cEstado = '';
	LET cCodigo_postal = '';
	LET cPeriodo = '';
	LET iConteodom = 0;
	LET ilimitedom = 0;
	LET cTelefono = '';
	LET cCelular = '';
	LET iConteotel = 0;
	LET iLimitetel = 0;
	LET iTiporechazo = 0;
	LET cMotivorechazo = '';
	LET cNumremesa = '';
	LET cFolio_suc = '';
	LET cUsuario_insert = '';
	LET dFecha_insert = '';
	LET cEmisor_nombre1 = '';
	LET cEmisor_nombre2 = '';
	LET cEmisor_appaterno = '';
	LET cEmisor_apmaterno = '';
	LET cEmisor_cod_pais = '';
	LET cMonto_total_origen = '';
	LET cMonto_total_destino = '';
	LET cBenef_nombre1 = '';
	LET cBenef_nombre2 = '';
	LET cBenef_appaterno = '';
	LET cBenef_apmaterno = '';
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,
			cTelefono,cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,
			cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
			cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_detremesasrechazadas.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pPeriodoDel IS NULL OR pPeriodoAl IS NULL OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,
			cTelefono,cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,
			cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
			cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno;
		END IF;
		
		-- VALIDACIÓN DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet,cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,
			cTelefono,cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,
			cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
			cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,
			cTelefono,cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,
			cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
			cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			
			SELECT SKIP pRegistros FIRST pRecuperacion
			tipo_remesa,id_sucursal,direccion,municipio,estado,codigo_postal,periodo,conteodom,limitedom,telefono,
			celular,conteotel,limitetel,tiporechazo,motivorechazo,numremesa,folio_suc,usuario_insert,fecha_insert,
			emisor_nombre1,emisor_nombre2,emisor_appaterno,emisor_apmaterno,emisor_cod_pais,monto_total_origen,monto_total_destino,
			benef_nombre1,benef_nombre2,benef_appaterno,benef_apmaterno
			INTO cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,
			cTelefono,cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,
			cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
			cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno
			FROM bdicnweb:"informix".sw_det_remesasrechazadas 
			WHERE usuario_inserta = pUsuario ORDER BY id_registro ASC
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet,cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,
			cTelefono,cCelular,iConteotel,iLimitetel,iTiporechazo,UPPER(cMotivorechazo),cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,
			cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
			cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno WITH RESUME;
			
		END FOREACH;
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,
			cTelefono,cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,
			cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
			cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet,cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,
			cTelefono,cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,
			cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
			cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno;
		END IF;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 25/02/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: REPORTE DE REMESAS RECHAZADAS',
'DESCRIPCION: SPL encargado de consultar el detalle de las remesas rechazadas.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_rem_detremesasrechazadas_totales(pUsuario CHAR(8), pIdFuncion CHAR(10), pPeriodoDel DATE, pPeriodoAl DATE, pSucursal CHAR(4))
		RETURNING CHAR(5) AS codret,
			INTEGER AS num_registros;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE cTipo_remesa VARCHAR(3);
	DEFINE cId_sucursal VARCHAR(4);
	DEFINE cDireccion VARCHAR(200);
	DEFINE cMunicipio VARCHAR(100);
	DEFINE cEstado VARCHAR(30);
	DEFINE cCodigo_postal VARCHAR(50);
	DEFINE cPeriodo VARCHAR(6);
	DEFINE iConteodom INTEGER;
	DEFINE ilimitedom INTEGER;
	DEFINE cTelefono VARCHAR(10);
	DEFINE cCelular VARCHAR(10);
	DEFINE iConteotel INTEGER;
	DEFINE iLimitetel INTEGER;
	DEFINE iTiporechazo INTEGER;
	DEFINE cMotivorechazo VARCHAR(40);
	DEFINE cNumremesa VARCHAR(20);
	DEFINE cFolio_suc VARCHAR(16);
	DEFINE cUsuario_insert VARCHAR(8);
	DEFINE dFecha_insert DATETIME YEAR TO SECOND;
	DEFINE cEmisor_nombre1 CHAR(40);
	DEFINE cEmisor_nombre2 CHAR(40);
	DEFINE cEmisor_appaterno CHAR(40);
	DEFINE cEmisor_apmaterno CHAR(40);
	DEFINE cEmisor_cod_pais CHAR(3);
	DEFINE cMonto_total_origen CHAR(20);
	DEFINE cMonto_total_destino CHAR(20);
	DEFINE cBenef_nombre1 CHAR(40);
	DEFINE cBenef_nombre2 CHAR(40);
	DEFINE cBenef_appaterno CHAR(40);
	DEFINE cBenef_apmaterno CHAR(40);
	
	DEFINE iIdRegistro INTEGER;
	DEFINE bEnTransaccion BOOLEAN;
	DEFINE iContador INTEGER;
	DEFINE iMaxCommit INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	LET cTipo_remesa = '';
	LET cId_sucursal = '';
	LET cDireccion = '';
	LET cMunicipio = '';
	LET cEstado = '';
	LET cCodigo_postal = '';
	LET cPeriodo = '';
	LET iConteodom = 0;
	LET ilimitedom = 0;
	LET cTelefono = '';
	LET cCelular = '';
	LET iConteotel = 0;
	LET iLimitetel = 0;
	LET iTiporechazo = 0;
	LET cMotivorechazo = '';
	LET cNumremesa = '';
	LET cFolio_suc = '';
	LET cUsuario_insert = '';
	LET dFecha_insert = '';
	LET cEmisor_nombre1 = '';
	LET cEmisor_nombre2 = '';
	LET cEmisor_appaterno = '';
	LET cEmisor_apmaterno = '';
	LET cEmisor_cod_pais = '';
	LET cMonto_total_origen = '';
	LET cMonto_total_destino = '';
	LET cBenef_nombre1 = '';
	LET cBenef_nombre2 = '';
	LET cBenef_appaterno = '';
	LET cBenef_apmaterno = '';
	
	LET iIdRegistro = 0;
	LET bEnTransaccion = 'f';
	LET iContador = 0;
	LET iMaxCommit = 1000;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			
			IF bEnTransaccion = 't' THEN
				ROLLBACK WORK;
			END IF;
			
			RETURN cCodRet,iNoRegistros;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bEnTransaccion = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_detremesasrechazadas_totales.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pPeriodoDel IS NULL OR pPeriodoAl IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet,iNoRegistros;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,iNoRegistros;
		END IF;
		
		-- SE LIMPIA TABLA PRINCIPAL
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		FOREACH WITH HOLD
			SELECT id_registro INTO iIdRegistro 
			FROM bdicnweb:"informix".sw_det_remesasrechazadas WHERE usuario_inserta = pUsuario
			
			DELETE FROM bdicnweb:"informix".sw_det_remesasrechazadas WHERE usuario_inserta = pUsuario AND id_registro = iIdRegistro;
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
		END FOREACH;		
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF NVL(pSucursal,'') <> '' THEN
			
			BEGIN WORK;
			LET bEnTransaccion = 't';
			
			FOREACH WITH HOLD
				
				SELECT tipo_remesa,id_sucursal,direccion,municipio,estado,codigo_postal,periodo,conteodom,limitedom,telefono,
				celular,conteotel,limitetel,tiporechazo,motivorechazo,numremesa,folio_suc,usuario_insert,fecha_insert
				INTO cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,cTelefono,
				cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert
				FROM bdisac:"informix".sac_pldlimite_teldom_rechazos 
				WHERE id_sucursal = pSucursal AND DATE(fecha_insert) BETWEEN pPeriodoDel AND pPeriodoAl ORDER BY tipo_remesa,numremesa ASC
				
				IF cTipo_remesa = 'APP' THEN
					
					FOREACH
						SELECT FIRST 1 
						r_firstname,r_middlename,r_lastname,r_mommaidenname,r_countrycode,r_originamount,r_destinamount,
						r_firstname_b,r_middlename_b,r_lastname_b,r_mommaidenna_b
						INTO cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
						cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno
						FROM bdisac:"informix".sac_app_qryi 
						WHERE unirefnum = cNumremesa AND nnumber = cId_sucursal
						AND user_insert = cUsuario_insert AND DATE(fecha) = DATE(dFecha_insert)
					END FOREACH;
					
				ELIF cTipo_remesa = 'BTS' THEN
					
					FOREACH
						SELECT FIRST 1 
						s_first_name,s_middle_name,s_last_name,s_mother_m_name,s_country_cd,origin_am,destination_am,
						r_first_name,r_middle_name,r_last_name,r_mother_m_name
						INTO cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
						cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno
						FROM bdisac:"informix".sac_bts_qryi 
						WHERE confirmation_nm = cNumremesa AND branch_sd = cId_sucursal 
						AND user_insert = cUsuario_insert AND DATE(fecha_insert) = DATE(dFecha_insert)
					END FOREACH;
					
				ELSE
					
					FOREACH
						SELECT FIRST 1 
						emisor_nombre1,emisor_nombre2,emisor_appaterno,emisor_apmaterno,emisor_cod_pais,monto_total_origen,monto_total_destino,
						benef_nombre1,benef_nombre2,benef_appaterno,benef_apmaterno
						INTO cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
						cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno
						FROM bdisac:"informix".sac_wu_search 
						WHERE mtcn = cNumremesa AND foreign_rs_refnum_rq = cFolio_suc
					END FOREACH;
					
				END IF;
				
				LET iNoRegistros = iNoRegistros + 1;
				INSERT INTO bdicnweb:"informix".sw_det_remesasrechazadas(tipo_remesa,id_sucursal,direccion,municipio,estado,codigo_postal,periodo,conteodom,limitedom,telefono,
				celular,conteotel,limitetel,tiporechazo,motivorechazo,numremesa,folio_suc,usuario_insert,fecha_insert,emisor_nombre1,emisor_nombre2,emisor_appaterno,emisor_apmaterno,
				emisor_cod_pais,monto_total_origen,monto_total_destino,benef_nombre1,benef_nombre2,benef_appaterno,benef_apmaterno,usuario_inserta)
				VALUES(cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,cTelefono,
				cCelular,iConteotel,iLimitetel,iTiporechazo,UPPER(cMotivorechazo),cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,
				cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno,pUsuario);
				
				LET iContador = iContador + 1;
				IF iContador = iMaxCommit THEN
					COMMIT WORK;
					BEGIN WORK;
					LET iContador = 0;
				END IF;
				
			END FOREACH;
			
			COMMIT WORK;
			IF bEnTransaccion = 't' THEN
				BEGIN WORK;
				LET bEnTransaccion = 'f';
				LET iContador = 0;
			END IF;
			
		ELIF NVL(pSucursal,'') = '' THEN
			
			BEGIN WORK;
			LET bEnTransaccion = 't';
			
			FOREACH WITH HOLD
				
				SELECT tipo_remesa,id_sucursal,direccion,municipio,estado,codigo_postal,periodo,conteodom,limitedom,telefono,
				celular,conteotel,limitetel,tiporechazo,motivorechazo,numremesa,folio_suc,usuario_insert,fecha_insert
				INTO cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,cTelefono,
				cCelular,iConteotel,iLimitetel,iTiporechazo,cMotivorechazo,cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert
				FROM bdisac:"informix".sac_pldlimite_teldom_rechazos 
				WHERE DATE(fecha_insert) BETWEEN pPeriodoDel AND pPeriodoAl ORDER BY tipo_remesa,numremesa ASC
				
				IF cTipo_remesa = 'APP' THEN
					
					FOREACH
						SELECT FIRST 1 
						r_firstname,r_middlename,r_lastname,r_mommaidenname,r_countrycode,r_originamount,r_destinamount,
						r_firstname_b,r_middlename_b,r_lastname_b,r_mommaidenna_b
						INTO cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
						cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno
						FROM bdisac:"informix".sac_app_qryi 
						WHERE unirefnum = cNumremesa AND nnumber = cId_sucursal
						AND user_insert = cUsuario_insert AND DATE(fecha) = DATE(dFecha_insert)
					END FOREACH;
					
				ELIF cTipo_remesa = 'BTS' THEN
					
					FOREACH
						SELECT FIRST 1 
						s_first_name,s_middle_name,s_last_name,s_mother_m_name,s_country_cd,origin_am,destination_am,
						r_first_name,r_middle_name,r_last_name,r_mother_m_name
						INTO cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
						cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno
						FROM bdisac:"informix".sac_bts_qryi 
						WHERE confirmation_nm = cNumremesa AND branch_sd = cId_sucursal 
						AND user_insert = cUsuario_insert AND DATE(fecha_insert) = DATE(dFecha_insert)
					END FOREACH;
					
				ELSE
					
					FOREACH
						SELECT FIRST 1 
						emisor_nombre1,emisor_nombre2,emisor_appaterno,emisor_apmaterno,emisor_cod_pais,monto_total_origen,monto_total_destino,
						benef_nombre1,benef_nombre2,benef_appaterno,benef_apmaterno
						INTO cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,
						cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno
						FROM bdisac:"informix".sac_wu_search 
						WHERE mtcn = cNumremesa AND foreign_rs_refnum_rq = cFolio_suc
					END FOREACH;
					
				END IF;
				
				LET iNoRegistros = iNoRegistros + 1;
				INSERT INTO bdicnweb:"informix".sw_det_remesasrechazadas(tipo_remesa,id_sucursal,direccion,municipio,estado,codigo_postal,periodo,conteodom,limitedom,telefono,
				celular,conteotel,limitetel,tiporechazo,motivorechazo,numremesa,folio_suc,usuario_insert,fecha_insert,emisor_nombre1,emisor_nombre2,emisor_appaterno,emisor_apmaterno,
				emisor_cod_pais,monto_total_origen,monto_total_destino,benef_nombre1,benef_nombre2,benef_appaterno,benef_apmaterno,usuario_inserta)
				VALUES(cTipo_remesa,cId_sucursal,cDireccion,cMunicipio,cEstado,cCodigo_postal,cPeriodo,iConteodom,ilimitedom,cTelefono,
				cCelular,iConteotel,iLimitetel,iTiporechazo,UPPER(cMotivorechazo),cNumremesa,cFolio_suc,cUsuario_insert,dFecha_insert,cEmisor_nombre1,cEmisor_nombre2,cEmisor_appaterno,cEmisor_apmaterno,
				cEmisor_cod_pais,cMonto_total_origen,cMonto_total_destino,cBenef_nombre1,cBenef_nombre2,cBenef_appaterno,cBenef_apmaterno,pUsuario);
				
				LET iContador = iContador + 1;
				IF iContador = iMaxCommit THEN
					COMMIT WORK;
					BEGIN WORK;
					LET iContador = 0;
				END IF;
				
			END FOREACH;
			
			COMMIT WORK;
			IF bEnTransaccion = 't' THEN
				BEGIN WORK;
				LET bEnTransaccion = 'f';
				LET iContador = 0;
			END IF;
			
		END IF;
		
		IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
		END IF;
		
		RETURN cCodRet,iNoRegistros;
		
	END;
	
END PROCEDURE
