CREATE PROCEDURE "informix".sp_rem_maximoreg(pUsuario CHAR(8), pIdFuncion CHAR(10), pIdLimite CHAR(1))
		RETURNING CHAR(5) AS codret,
			CHAR(100) AS max_valor;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iCodParam INTEGER;
	DEFINE cMaxValor CHAR(100);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET iCodParam = 0;
	LET cMaxValor = '';
	LET iNoRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cMaxValor;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_maximoreg.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pIdLimite = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cMaxValor;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cMaxValor;
		END IF;
		
		--MAX DOMICILIOS
		IF pIdLimite = '1' THEN
			LET iCodParam = 130;
		--MAX TELÉFONOS
		ELIF pIdLimite = '2' THEN
			LET iCodParam = 131;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT valor INTO cMaxValor FROM bdisac:"informix".sac_param WHERE empresa = cEmpresa AND cod_param = iCodParam;
		
		IF NVL(cMaxValor,'') = '' THEN
			LET cMaxValor = '';
		END IF;
		
		RETURN cCodRet, cMaxValor;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 25/02/2020',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: LÍMITES DE DOMICILIOS Y TELÉFONOS DE REMESAS',
'DESCRIPCION: SPL encargado de consultar el valor máximo de registros.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_rem_repgenremesasrechazadas(pUsuario CHAR(8), pIdFuncion CHAR(10), pRutaDescarga CHAR(100))
		RETURNING CHAR(5) AS codret,
			CHAR(45) AS reporte_generado_xls,
			CHAR(45) AS reporte_generado_txt;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cIdLimite SMALLINT;
	DEFINE cDescLimite CHAR(35);
	DEFINE iNoRegistros INTEGER;
	
	DEFINE cQuery CHAR(255);
	DEFINE cCmd1 CHAR(2000);
	DEFINE cSql CHAR(2500);
	DEFINE cRutaGral CHAR(150);
	DEFINE cRutaInformix CHAR(100);
	DEFINE cUsrBin CHAR(100);
	DEFINE cNombreRepXls CHAR(45);
	DEFINE cNombreRepTxt CHAR(45);
	DEFINE cRutaGralXls CHAR(150);
	DEFINE cRutaGralTxt CHAR(150);

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cIdLimite = 0;
	LET cDescLimite = '';
	LET iNoRegistros = 0;
	
	LET cQuery = '';
	LET cCmd1 = '';
	LET cSql = '';
	LET cRutaGral = '';
	--LET cRutaInformix = '/informix/bin/';  --DESARROLLO Y PRE PRODUCCION SOC
	LET cRutaInformix = '/ifxsif01/bin/';  -- PRODUCCION 
	LET cUsrBin = '/usr/bin/';
	LET cNombreRepXls = '';
	LET cNombreRepTxt = '';
	LET cRutaGralXls = '';
	LET cRutaGralTxt = '';
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cNombreRepXls,cNombreRepTxt;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_rem_repgenremesasrechazadas.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRutaDescarga = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cNombreRepXls,cNombreRepTxt;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cNombreRepXls,cNombreRepTxt;
		END IF;
		
		-- SE DEFINE NOMENCLATURA DEL REPORTE A GENERAR		
		LET cNombreRepXls = 'REPORTE_REMESAS_RECHAZADAS_'||TO_CHAR(CURRENT, '%d%m%Y')||'.xls';
		LET cNombreRepTxt = 'REPORTE_REMESAS_RECHAZADAS_'||TO_CHAR(CURRENT, '%d%m%Y')||'.txt';
		LET pRutaDescarga = TRIM(pRutaDescarga) || '/';
		LET cRutaGralXls = TRIM(pRutaDescarga)||TRIM(cNombreRepXls);
		LET cRutaGralTxt = TRIM(pRutaDescarga)||TRIM(cNombreRepTxt);
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		LET cCmd1 ="";	
		LET cCmd1 =""||TRIM(cCmd1)||"SELECT 'TIPO DE REMESA','ID SUCURSAL','DIRECCION','MUNICIPIO','ESTADO','CODIGO POSTAL','PERIODO','CONTEO DOMICILIO','LIMITE DOMICILIO','TELEFONO',";
		LET cCmd1 =""||TRIM(cCmd1)||"'CELULAR','CONTEO TELEFONO','LIMITE TELEFONO','TIPO DE RECHAZO','MOTIVO DE RECHAZO','NUMERO DE REMESA','FOLIO SUCURSAL','USUARIO INSERT','FECHA INSERT',";
		LET cCmd1 =""||TRIM(cCmd1)||"'NOMBRE 1 ORDENANTE','NOMBRE 2 ORDENANTE','APELLIDO PATERNO ORDENANTE','APELLIDO MATERNO ORDENANTE','PAIS ORDENANTE','MONTO ORIGEN','MONTO DESTINO',";
		LET cCmd1 =""||TRIM(cCmd1)||"'NOMBRE 1 BENEFICIARIO','NOMBRE 2 BENEFICIARIO','APELLIDO PATERNO BENEFICIARIO','APELLIDO MATERNO BENEFICIARIO'";
		LET cCmd1 =""||TRIM(cCmd1)||" FROM systables WHERE tabid = 1 UNION ALL SELECT * FROM( ";
		LET cCmd1 =""||TRIM(cCmd1)||"SELECT tipo_remesa,id_sucursal,TRIM(direccion),TRIM(municipio),estado,codigo_postal,periodo,conteodom::CHAR(11),limitedom::CHAR(11),telefono,";
		LET cCmd1 =""||TRIM(cCmd1)||"REPLACE(TRIM(celular),'\',''),conteotel::CHAR(11),limitetel::CHAR(11),tiporechazo::CHAR(11),UPPER(TRIM(motivorechazo)),''''||TRIM(numremesa),''''||folio_suc,usuario_insert,''''||fecha_insert::CHAR(25),";
		LET cCmd1 =""||TRIM(cCmd1)||"TRIM(emisor_nombre1),TRIM(emisor_nombre2),TRIM(emisor_appaterno),TRIM(emisor_apmaterno),emisor_cod_pais,TRIM(monto_total_origen),TRIM(monto_total_destino),";
		LET cCmd1 =""||TRIM(cCmd1)||"TRIM(benef_nombre1),TRIM(benef_nombre2),TRIM(benef_appaterno),TRIM(benef_apmaterno)";
		LET cCmd1 =""||TRIM(cCmd1)||" FROM bdicnweb:""informix"".sw_det_remesasrechazadas";
		LET cCmd1 =""||TRIM(cCmd1)||" WHERE usuario_inserta = '"|| pUsuario ||"' ORDER BY id_registro ASC)";
		
		--GENERACION DE ARCHIVO XLS
		LET cSql = '';
		LET cSql = '/usr/bin/echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cRutaGralXls)||' DELIMITER '|| '''	'' '||TRIM(cCmd1)||' " > '||TRIM(pRutaDescarga)||'query.sql';
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = '/usr/bin/chmod 777 '||TRIM(pRutaDescarga)||'query.sql';
		SYSTEM TRIM(cSql);
	
		LET cSql = '';
		--LET cSql = '/informix/bin/dbaccess bdicnweb '||TRIM(pRutaDescarga)||'query.sql'; --DESARROLLO Y PRE PRODUCCION SOC
		LET cSql = '/ifxsif01/bin/dbaccess bdicnweb '||TRIM(pRutaDescarga)||'query.sql'; --PRODUCCION
		
		
		SYSTEM TRIM(cSql);
	
		LET cSql = '';
		LET cSql = '/usr/bin/rm -rf '||TRIM(pRutaDescarga)||'query.sql';
		SYSTEM TRIM(cSql);
	
		-- Se manipula el archivo para agregar el salto de línea
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralXls);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGralXls)||" > "||TRIM(cRutaGralXls)||".tmp";
		SYSTEM TRIM(cSql);
		
		-- Eliminamos el archivo original
		LET cSql = '';
		LET cSql = "rm -rf "||TRIM(cRutaGralXls);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralXls)||".tmp";
		SYSTEM TRIM(cSql);
		
		-- Eliminamos el caracter delimitador ';' al final de la línea
		LET cSql = '';
		LET cSql =  "sed 's/..$//g' "||TRIM(cRutaGralXls)||".tmp > "||TRIM(cRutaGralXls);
		SYSTEM TRIM(cSql);
		
		-- Se manipula el archivo para agregar el salto de línea
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralXls);
		SYSTEM TRIM(cSql);
							
		LET cSql = '';
		LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGralXls)||" > "||TRIM(cRutaGralXls)||".tmp";
		SYSTEM TRIM(cSql);
						
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralXls)||".tmp";
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = '/usr/bin/rm -rf '||TRIM(cRutaGralXls)||'; /usr/bin/mv '||TRIM(cRutaGralXls)||'.tmp '||TRIM(cRutaGralXls);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralXls);
		SYSTEM TRIM(cSql);
		
		-- GENERACION DE ARCHIVO TXT
		LET cSql = '';
		--LET cSql = '/usr/bin/echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cRutaGralTxt)||' DELIMITER '|| '''	'' '||TRIM(cCmd1)||' " > '||TRIM(pRutaDescarga)||'query.sql';
		LET cSql = '/usr/bin/echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cRutaGralTxt)||' '||TRIM(cCmd1)||' " > '||TRIM(pRutaDescarga)||'query.sql';
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = '/usr/bin/chmod 777 '||TRIM(pRutaDescarga)||'query.sql';
		SYSTEM TRIM(cSql);
	
		LET cSql = '';
		--LET cSql = '/informix/bin/dbaccess bdicnweb '||TRIM(pRutaDescarga)||'query.sql'; --DESARROLLO Y PRE PRODUCCION
		LET cSql = '/ifxsif01/bin/dbaccess bdicnweb '||TRIM(pRutaDescarga)||'query.sql'; --PRODUCCION
		SYSTEM TRIM(cSql);
	
		LET cSql = '';
		LET cSql = '/usr/bin/rm -rf '||TRIM(pRutaDescarga)||'query.sql';
		SYSTEM TRIM(cSql);
	
		-- Se manipula el archivo para agregar el salto de línea
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralTxt);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGralTxt)||" > "||TRIM(cRutaGralTxt)||".tmp";
		SYSTEM TRIM(cSql);
		
		-- Eliminamos el archivo original
		LET cSql = '';
		LET cSql = "rm -rf "||TRIM(cRutaGralTxt);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralTxt)||".tmp";
		SYSTEM TRIM(cSql);
		
		-- Eliminamos el caracter delimitador ';' al final de la línea
		LET cSql = '';
		LET cSql =  "sed 's/..$//g' "||TRIM(cRutaGralTxt)||".tmp > "||TRIM(cRutaGralTxt);
		SYSTEM TRIM(cSql);
		
		-- Se manipula el archivo para agregar el salto de línea
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralTxt);
		SYSTEM TRIM(cSql);
							
		LET cSql = '';
		LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGralTxt)||" > "||TRIM(cRutaGralTxt)||".tmp";
		SYSTEM TRIM(cSql);
						
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralTxt)||".tmp";
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = '/usr/bin/rm -rf '||TRIM(cRutaGralTxt)||'; /usr/bin/mv '||TRIM(cRutaGralTxt)||'.tmp '||TRIM(cRutaGralTxt);
		SYSTEM TRIM(cSql);
		
		LET cSql = '';
		LET cSql = 'chmod 777 '||TRIM(cRutaGralTxt);
		SYSTEM TRIM(cSql);
		
		RETURN cCodRet,cNombreRepXls,cNombreRepTxt;
		
	END;
	
END PROCEDURE
