CREATE PROCEDURE "informix".sp_generafoliocallezona(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipoConsulta CHAR(1), pIdCiudad INTEGER)
	RETURNING CHAR(5) AS codret,
			INTEGER AS folio;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iFolio INTEGER;
	DEFINE cValorParam CHAR(100);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iFolio = 0;
	LET cValorParam = '';
	
	BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, iFolio;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_generafoliocallezona.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pTipoConsulta = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, iFolio;
		END IF;
		
		IF pTipoConsulta NOT IN ('1', '2') THEN
			LET cCodRet = '00044';
			RETURN cCodRet, iFolio;
		ELIF pTipoConsulta = '1' AND (pIdCiudad IS NULL OR pIdCiudad = 0) THEN
			LET cCodRet = '00003';
			RETURN cCodRet, iFolio;
		END IF;
		
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, iFolio;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		IF pTipoConsulta = '1' THEN -- Consulta de folio para zonas
			SELECT MAX(numerocolonia)
			INTO iFolio
			FROM bdinteg:si_catzonas
			WHERE numerociudad = pIdCiudad;
			
			IF iFolio IS NULL THEN
				LET iFolio = 8001;
			--ELIF iFolio = 10999 THEN
				--LET cCodRet = '00216'; -- No existen mas folios para asignar claves de zonas para esta ciudad
			ELSE
				SELECT valor
				INTO cValorParam
				FROM bdinteg:si_param_dom
				WHERE cod_param = 8;
				
				IF iFolio < cValorParam::INTEGER THEN
					LET iFolio = cValorParam::INTEGER;
				ELSE
					LET iFolio = iFolio + 1;
				END IF;
			END IF;
			
			RETURN cCodRet, iFolio;
			
		ELIF pTipoConsulta = '2' THEN -- Consulta de folio para calles
			
			SELECT MAX(numerocalle)
			INTO iFolio
			FROM bdinteg:si_catcalles
			WHERE numerocalle > 900000;
			--WHERE numerocalle > 800000 AND numerocalle < 900000;
			
			IF iFolio IS NULL THEN
				LET iFolio = 800001;
			--ELIF iFolio = 900000 THEN
				--LET cCodRet = '00217'; -- No existen mas folios para asignar claves de calles
			ELSE
				LET iFolio = iFolio + 1;
			END IF;
			
			RETURN cCodRet, iFolio;
			
		END IF;
		
	END;
	
END PROCEDURE
DOCUMENT "AUTOR: Oscar Flores Conde",
"FECHA: 05/11/2013",
"DESCRIPCION: Consulta los folios de las zonas y calles por asignar",
"BD: bdicnweb";

CREATE PROCEDURE "informix".sp_verificastatusclientescoppel(pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5) AS codret,
		CHAR(1) AS status,
		INTEGER AS num_registros,
		CHAR(1) AS error_proceso,
		CHAR(5) AS error;
			  
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	DEFINE cStatus CHAR(1);
	DEFINE cErrorProceso CHAR(1);
	DEFINE cError CHAR(5);
	DEFINE iNumRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;	
	LET cStatus = '';
	LET cErrorProceso = '';
	LET cError = '';
	LET iNumRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			--LET cCodRet = '00770'; --PROCESO CON ERRORES, POR FAVOR REINTENTE NUEVAMENTE
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;	
		END EXCEPTION;
	 
		--SET DEBUG FILE TO '/tmp/mfinis/sp_verificastatusclientescoppel.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;	
		END IF;		
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
	
		SELECT status,num_registros,error_proceso,error
		INTO cStatus,iNumRegistros,cErrorProceso,cError
		FROM "informix".statusctescoppel WHERE usuario_insert = pUsuario;
		
		IF DBINFO('sqlca.sqlerrd2') = 0 THEN		
			RETURN cCodRet,'I','','',''; 
		ELSE 			
			RETURN cCodRet,cStatus,iNumRegistros,cErrorProceso,cError;		
		END IF;	
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 20/03/2020',
'MODULO: Consultas',
'FUNCIONALIDAD: Consulta Detallada de Clientes',
'DESCRIPCION: SPL encargado verificar el status de la consulta que obtiene el detalle de clientes Coppel.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_consclientescoppel_totales(pUsuario CHAR(8), pIdFuncion CHAR(10), pCteBanco CHAR(20))
	RETURNING CHAR(5) AS cod_ret,
		INTEGER AS no_registros;
		
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRet INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegsEncontrados INTEGER;
	DEFINE iRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	
	DEFINE cTicket CHAR(20);
	DEFINE cCteCoppel CHAR(20);
	DEFINE cCteBanco CHAR(20);
	DEFINE cNombre1 CHAR(26); 
	DEFINE cNombre2 CHAR(26);
	DEFINE cApell_paterno CHAR(26);
	DEFINE cApell_materno CHAR(26);
	DEFINE dFecha_nac DATE;
	DEFINE dFecha DATE;
	DEFINE cNomCteCoppel CHAR(107);
	
	DEFINE iIdRegistro INTEGER;
	DEFINE bEnTransaccion BOOLEAN;
	DEFINE iContador INTEGER;
	DEFINE iMaxCommit INTEGER;
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRet = 0;
	LET iSqlErr = 0;
	LET iNoRegsEncontrados = 0;
	LET iRegistros = 0;
	LET iRecuperacion = 0;
	
	LET cTicket = '';
	LET cCteCoppel = '';
	LET cCteBanco = '';
	LET cNombre1 = ''; 
	LET cNombre2 = '';
	LET cApell_paterno = '';
	LET cApell_materno = '';
	LET dFecha_nac = '';
	LET dFecha = '';
	LET cNomCteCoppel = '';
	
	LET iIdRegistro = 0;
	LET bEnTransaccion = 'f';
	LET iContador = 0;
	LET iMaxCommit = 1000;
	LET iNoRegistros = 0;
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			IF bEnTransaccion = 't' THEN
				ROLLBACK WORK;
			END IF;
			
			UPDATE "informix".statusctescoppel
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bEnTransaccion = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_consclientescoppel_totales.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- SE LIMPIA TABLA VERIFICA STATUS
		DELETE FROM "informix".statusctescoppel WHERE usuario_insert = pUsuario;
		INSERT INTO "informix".statusctescoppel(usuario_insert,status,num_registros,error_proceso,error) VALUES(pUsuario,'I',0,'',cCodRet);
		
		IF pUsuario = '' OR pIdFuncion = '' OR pCteBanco = '' THEN
			LET cCodRet = '00003';
			UPDATE "informix".statusctescoppel
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		-- VALIDACIÓN DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE "informix".statusctescoppel
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		-- SE LIMPIA TABLA PRINCIPAL
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		FOREACH WITH HOLD
			SELECT id_registro INTO iIdRegistro 
			FROM bdicnweb:"informix".sw_det_ctescoppel WHERE usuario_inserta = pUsuario
			
			DELETE FROM bdicnweb:"informix".sw_det_ctescoppel WHERE usuario_inserta = pUsuario AND id_registro = iIdRegistro;
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
		END FOREACH;		
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		SELECT ticket INTO cTicket
		FROM bdinteg:"informix".si_huella_linea WHERE numcte = pCteBanco;
		
		FOREACH WITH HOLD
			
			--NÚMERO CLIENTE COPPEL
			SELECT DISTINCT(cliente) INTO cCteCoppel
			FROM bdinteg:"informix".si_huella_linea_resultado WHERE ticket = cTicket
			
			FOREACH
				
				--FECHA CONSULTA COPPEL
				SELECT FIRST 1
				cliente, nombre, 
				TO_DATE(CASE
						WHEN fecha_nac = ''
						THEN '01/01/1990'
						ELSE 
						fecha_nac
						END,'%d/%m/%Y') fecha_nac
				, fecha
				INTO cCteCoppel, cNomCteCoppel, dFecha_nac, dFecha
				FROM bdinteg:"informix".si_huella_linea_resultado 
				WHERE ticket = cTicket AND cliente = cCteCoppel ORDER BY fecha,hora DESC
				
				IF dFecha_nac = '01/01/1990' THEN
					LET dFecha_nac = '';
				END IF;
				
				LET iNoRegistros = iNoRegistros + 1;
				INSERT INTO bdicnweb:"informix".sw_det_ctescoppel(numero_cte_coppel,nombre_cte_coppel,fecha_nac,fecha_consulta,usuario_inserta)
				VALUES(cCteCoppel,cNomCteCoppel,dFecha_nac,dFecha,pUsuario);
				
				LET iContador = iContador + 1;
				IF iContador = iMaxCommit THEN
					COMMIT WORK;
					BEGIN WORK;
					LET iContador = 0;
				END IF;
			
			END FOREACH;
		END FOREACH;
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		IF iNoRegistros = 0 THEN
			LET cCodRet = '01146'; --EL CLIENTE NO CUENTA CON COINCIDENCIAS COPPEL
			UPDATE "informix".statusctescoppel
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet,iNoRegistros;
		END IF;
		
		UPDATE "informix".statusctescoppel
		SET status = 'T', error_proceso = 'N', num_registros = iNoRegistros WHERE usuario_insert = pUsuario;
		
		RETURN cCodRet,iNoRegistros;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 20/03/2020',
'MODULO: Consultas',
'FUNCIONALIDAD: Consulta Detallada de Clientes',
'DESCRIPCION: SPL que consulta el número total de clientes Coppel.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_consclientescoppel(pUsuario CHAR(8), pIdFuncion CHAR(10), pCteBanco CHAR(20), pRegistros INTEGER, pRecuperacion INTEGER)
    RETURNING CHAR(5) AS cod_ret,
		CHAR(20) AS numero_cte_coppel,
		CHAR(107) AS nombre_cte_coppel,
		DATE AS fecha_nac,
		DATE AS fecha_consulta;
	
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRet INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegsEncontrados INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	
	DEFINE cNumCteCoppel CHAR(20);
	DEFINE cNomCteCoppel CHAR(107);
	DEFINE dFecha_nac DATE;
	DEFINE dFecha_consulta DATE;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRet = 0;
	LET iSqlErr = 0;
	LET iNoRegsEncontrados = 0;
	LET iNoRegistros = 0;
	LET iRecuperacion = 0;
	
	LET cNumCteCoppel = '';
	LET cNomCteCoppel = '';
	LET dFecha_nac = '';
	LET dFecha_consulta = '';
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNumCteCoppel, cNomCteCoppel, dFecha_nac, dFecha_consulta;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_consclientescoppel.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cNumCteCoppel, cNomCteCoppel, dFecha_nac, dFecha_consulta;
		END IF;
		
		-- VALIDACIÓN DEL PARAMETRO DE PAGINACION
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cNumCteCoppel, cNomCteCoppel, dFecha_nac, dFecha_consulta;
		END IF;
		
		-- VALIDACIÓN DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cNumCteCoppel, cNomCteCoppel, dFecha_nac, dFecha_consulta;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
	    FOREACH
		
			SELECT SKIP pRegistros FIRST pRecuperacion
			numero_cte_coppel, nombre_cte_coppel, fecha_nac, fecha_consulta
			INTO cNumCteCoppel, cNomCteCoppel, dFecha_nac, dFecha_consulta
			FROM bdicnweb:"informix".sw_det_ctescoppel 
			WHERE usuario_inserta = pUsuario ORDER BY cNomCteCoppel ASC
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet, cNumCteCoppel, cNomCteCoppel, dFecha_nac, dFecha_consulta WITH RESUME;
		
		END FOREACH;
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '01146'; --EL CLIENTE NO CUENTA CON COINCIDENCIAS COPPEL
			RETURN cCodRet, cNumCteCoppel, cNomCteCoppel, dFecha_nac, dFecha_consulta;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cNumCteCoppel, cNomCteCoppel, dFecha_nac, dFecha_consulta;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 20/03/2020',
'MODULO: Consultas',
'FUNCIONALIDAD: Consulta Detallada de Clientes',
'DESCRIPCION: SPL que consulta el detalle de clientes Coppel.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_consinfprospectos(pUsuario CHAR(8), pIdFuncion CHAR(10), pCteBanco CHAR(20), pRegistros INTEGER, pRecuperacion INTEGER)
    RETURNING CHAR(5) AS cod_ret,
		CHAR(20) AS tipo_prospecto,
		CHAR(2) AS rel_cliente,
		CHAR(20) AS rel_a_cliente,
		CHAR(107) AS nom_cliente_rel,
		CHAR(20) AS rel_registrada;
		
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRet INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegsEncontrados INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	
	DEFINE cTipo_prospecto CHAR(20);
	DEFINE cRel_cliente CHAR(2);
	DEFINE cRel_a_cliente CHAR(20);
	DEFINE cNom_cliente_rel CHAR(107);
	DEFINE cRel_registrada CHAR(20);
	DEFINE cNombre1 CHAR(26); 
	DEFINE cNombre2 CHAR(26);
	DEFINE cApell_paterno CHAR(26);
	DEFINE cApell_materno CHAR(26);
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRet = 0;
	LET iSqlErr = 0;
	LET iNoRegsEncontrados = 0;
	LET iNoRegistros = 0;
	LET iRecuperacion = 0;
	
	LET cTipo_prospecto = '';
	LET cRel_cliente = '';
	LET cRel_a_cliente = '';
	LET cNom_cliente_rel = '';
	LET cRel_registrada = '';
	LET cNombre1 = ''; 
	LET cNombre2 = '';
	LET cApell_paterno = '';
	LET cApell_materno = '';
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_consinfprospectos.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada;
		END IF;
		
		-- VALIDACIÃN DEL PARAMETRO DE PAGINACION
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada;
		END IF;
		
		-- VALIDACIÃN DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
	    FOREACH
		
			SELECT SKIP pRegistros FIRST pRecuperacion
			tipo_prospecto, rel_cliente, rel_a_cliente, nom_cliente_rel, rel_registrada
			INTO cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada
			FROM bdicnweb:"informix".sw_det_infprospectos 
			WHERE usuario_inserta = pUsuario ORDER BY nom_cliente_rel ASC
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet, cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada WITH RESUME;
		
		END FOREACH;
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat LeÃ³n Amador',
'FECHA: 23/03/2020',
'MODULO: Consultas',
'FUNCIONALIDAD: IdentificaciÃ³n de Prospectos',
'DESCRIPCION: SPL que consulta el detalle de prospectos.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_consinfprospectos_totales(pUsuario CHAR(8), pIdFuncion CHAR(10), pCteBanco CHAR(20))
	RETURNING CHAR(5) AS cod_ret,
		INTEGER AS no_registros;
		
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRet INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegsEncontrados INTEGER;
	DEFINE iRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	
	DEFINE cTipo_prospecto CHAR(20);
	DEFINE cRel_cliente CHAR(2);
	DEFINE cRel_a_cliente CHAR(20);
	DEFINE cNom_cliente_rel CHAR(107);
	DEFINE cRel_registrada CHAR(20);
	DEFINE cNombre1 CHAR(26); 
	DEFINE cNombre2 CHAR(26);
	DEFINE cApell_paterno CHAR(26);
	DEFINE cApell_materno CHAR(26);
	DEFINE cNumcteBanco CHAR(20); 
	DEFINE cNumcteRef CHAR(20);
	DEFINE cParentesco CHAR(2);
	
	DEFINE iIdRegistro INTEGER;
	DEFINE bEnTransaccion BOOLEAN;
	DEFINE iContador INTEGER;
	DEFINE iMaxCommit INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE iExiste INTEGER;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRet = 0;
	LET iSqlErr = 0;
	LET iNoRegsEncontrados = 0;
	LET iRegistros = 0;
	LET iRecuperacion = 0;
	
	LET cTipo_prospecto = '';
	LET cRel_cliente = '';
	LET cRel_a_cliente = '';
	LET cNom_cliente_rel = '';
	LET cRel_registrada = '';
	LET cNombre1 = ''; 
	LET cNombre2 = '';
	LET cApell_paterno = '';
	LET cApell_materno = '';
	LET cNumcteBanco = ''; 
	LET cNumcteRef = '';
	LET cParentesco = '';
	
	LET iIdRegistro = 0;
	LET bEnTransaccion = 'f';
	LET iContador = 0;
	LET iMaxCommit = 1000;
	LET iNoRegistros = 0;
	LET iExiste = 0;
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			IF bEnTransaccion = 't' THEN
				ROLLBACK WORK;
			END IF;
			
			UPDATE "informix".statusinfprospectos
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bEnTransaccion = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_consinfprospectos_totales.out';
		--TRACE ON;
		
		-- SE LIMPIA TABLA VERIFICA STATUS
		SET LOCK MODE TO WAIT 3;
		DELETE FROM "informix".statusinfprospectos WHERE usuario_insert = pUsuario;
		SET LOCK MODE TO WAIT 3;
		INSERT INTO "informix".statusinfprospectos(usuario_insert,status,num_registros,error_proceso,error) VALUES(pUsuario,'I',0,'',cCodRet);
		
		IF pUsuario = '' OR pIdFuncion = '' OR pCteBanco = '' THEN
			LET cCodRet = '00003';
			UPDATE "informix".statusinfprospectos
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		-- VALIDACIÓN DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo (pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE "informix".statusinfprospectos
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegistros;
		END IF;
		
		-- SE LIMPIA TABLA PRINCIPAL
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		FOREACH WITH HOLD
			SELECT {+AVOID_FULL (bdicnweb:"informix".sw_det_infprospectos )}id_registro INTO iIdRegistro 
			FROM bdicnweb:"informix".sw_det_infprospectos WHERE usuario_inserta = pUsuario
			
			DELETE {+AVOID_FULL (bdicnweb:"informix".sw_det_infprospectos )} FROM bdicnweb:"informix".sw_det_infprospectos WHERE usuario_inserta = pUsuario AND id_registro = iIdRegistro;
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
		END FOREACH;		
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		--PROSPECTO BENEFICIARIO
		FOREACH WITH HOLD
			
			SELECT {+INDEX (bdicheq:"informix".sc_maechq "informix".maecheques), AVOID_FULL (bdicheq:"informix".sc_beneficiario)}
			DISTINCT(BEN.numcte) AS rel_a_cliente,
			CTE2.tipo_cliente AS rel_cliente,
			CTE2.nombre1, CTE2.nombre2, CTE2.apell_paterno, CTE2.apell_materno,
			PAR.descripcion AS rel_registrada
			INTO cRel_a_cliente, cRel_cliente, cNombre1, cNombre2, cApell_paterno, cApell_materno, cRel_registrada
			FROM bdinteg:"informix".si_cliente CTE
			INNER JOIN bdicheq:"informix".sc_maechq CHEQ ON CHEQ.num_cte = CTE.numcte
			INNER JOIN bdicheq:"informix".sc_beneficiario BEN ON BEN.cuenta = CHEQ.cuenta
			INNER JOIN bdinteg:"informix".si_parentesco PAR ON PAR.parentesco = BEN.parentesco
			INNER JOIN bdinteg:"informix".si_cliente CTE2 ON CTE2.numcte = BEN.numcte
			WHERE --CTE.tipo_cliente IN (1,2) 
			CTE.numcte = pCteBanco
			
			IF cRel_cliente = '1' THEN
				LET cRel_cliente = 'SI';
			ELIF cRel_cliente = '2' THEN
				LET cRel_cliente = 'NO';
			END IF;
			
			LET cTipo_prospecto = 'BENEFICIARIO';
			LET cNom_cliente_rel = TRIM(TRIM(cNombre1)||' '||TRIM(cNombre2))||' '||TRIM(cApell_paterno)||' '||TRIM(cApell_materno);
			
			LET iNoRegistros = iNoRegistros + 1;
			INSERT INTO bdicnweb:"informix".sw_det_infprospectos(tipo_prospecto,rel_cliente,rel_a_cliente,nom_cliente_rel,rel_registrada,usuario_inserta)
			VALUES(cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada, pUsuario);
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
				
		END FOREACH;
		
		--PROSPECTO REFERENCIA
		FOREACH WITH HOLD
			
			SELECT 
			DISTINCT(RE.numcte_banco), RE.numcte_ref, RE.nombre1, RE.nombre2, RE.apell_paterno, RE.apell_materno, RE.parentesco
			INTO cNumcteBanco, cNumcteRef, cNombre1, cNombre2, cApell_paterno, cApell_materno, cParentesco
			FROM bdinteg:"informix".si_refclientes RE WHERE RE.numcte = pCteBanco
			
			IF NVL(cNumcteBanco, '') = '' AND NVL(cNumcteRef, '') = '' THEN
				
				LET cRel_cliente = '2';
				LET cRel_a_cliente = '';
				
				IF NVL(cParentesco, '') <> '' THEN
					SELECT PAR.descripcion INTO cRel_registrada FROM bdinteg:"informix".si_parentesco PAR WHERE PAR.parentesco = cParentesco;
				ELSE
					LET cRel_registrada = '';
				END IF;
				
				IF cRel_cliente = '1' THEN
					LET cRel_cliente = 'SI';
				ELIF cRel_cliente = '2' THEN
					LET cRel_cliente = 'NO';
				ELIF cRel_cliente = '' OR cRel_cliente IS NULL THEN
					LET cRel_cliente = 'NO';
				END IF;
				
				LET cTipo_prospecto = 'REFERENCIA';
				LET cNom_cliente_rel = TRIM(TRIM(cNombre1)||' '||TRIM(cNombre2))||' '||TRIM(cApell_paterno)||' '||TRIM(cApell_materno);
				
				SELECT {+AVOID_FULL (bdicnweb:"informix".sw_det_infprospectos )} COUNT(*) INTO iExiste FROM bdicnweb:"informix".sw_det_infprospectos 
				WHERE --rel_a_cliente = cRel_a_cliente AND 
				nom_cliente_rel = cNom_cliente_rel AND usuario_inserta = pUsuario;
				
				IF NVL(iExiste,0) = 0 THEN
				LET iNoRegistros = iNoRegistros + 1;
					INSERT INTO bdicnweb:"informix".sw_det_infprospectos(tipo_prospecto,rel_cliente,rel_a_cliente,nom_cliente_rel,rel_registrada,usuario_inserta)
					VALUES(cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada, pUsuario);
					
					LET cNumcteBanco = '';
					LET cNumcteRef = '';
					LET cRel_cliente = '';
					LET cRel_a_cliente = '';
					LET cNom_cliente_rel = '';
					LET cRel_registrada = '';
					LET cNombre1 = ''; 
					LET cNombre2 = '';
					LET cApell_paterno = '';
					LET cApell_materno = '';
					
					LET iContador = iContador + 1;
					IF iContador = iMaxCommit THEN
						COMMIT WORK;
						BEGIN WORK;
						LET iContador = 0;
					END IF;
				END IF;
				
			ELSE
				
				LET cRel_a_cliente = '';
				LET cRel_cliente = '';
				LET cNombre1 = ''; 
				LET cNombre2 = '';
				LET cApell_paterno = '';
				LET cApell_materno = '';
				LET cParentesco = '';
			
				IF NVL(cNumcteBanco, '') <> '' AND NVL(cNumcteRef, '') = '' THEN
				
					FOREACH
						
						SELECT
						DISTINCT(CTE.numcte), CTE.tipo_cliente,	RE.nombre1, RE.nombre2, RE.apell_paterno, RE.apell_materno, RE.parentesco
						INTO cRel_a_cliente, cRel_cliente, cNombre1, cNombre2, cApell_paterno, cApell_materno, cParentesco
						FROM bdinteg:"informix".si_refclientes RE 
						LEFT JOIN bdinteg:"informix".si_cliente CTE ON RE.numcte_banco = CTE.numcte
						WHERE RE.numcte = pCteBanco AND RE.numcte_banco = cNumcteBanco
						
						IF NVL(cParentesco, '') <> '' THEN
							SELECT PAR.descripcion INTO cRel_registrada FROM bdinteg:"informix".si_parentesco PAR WHERE PAR.parentesco = cParentesco;
						ELSE
							LET cRel_registrada = '';
						END IF;
						
						IF cRel_cliente = '1' THEN
							LET cRel_cliente = 'SI';
						ELIF cRel_cliente = '2' THEN
							LET cRel_cliente = 'NO';
						ELIF cRel_cliente = '' OR cRel_cliente IS NULL THEN
							LET cRel_cliente = 'NO';
						END IF;
						
						LET cTipo_prospecto = 'REFERENCIA';
						LET cNom_cliente_rel = TRIM(TRIM(cNombre1)||' '||TRIM(cNombre2))||' '||TRIM(cApell_paterno)||' '||TRIM(cApell_materno);
						
						SELECT {+AVOID_FULL (bdicnweb:"informix".sw_det_infprospectos )} COUNT(*) INTO iExiste FROM bdicnweb:"informix".sw_det_infprospectos 
						WHERE --rel_a_cliente = cRel_a_cliente AND 
						nom_cliente_rel = cNom_cliente_rel AND usuario_inserta = pUsuario;
						
						IF NVL(iExiste,0) = 0 THEN
							LET iNoRegistros = iNoRegistros + 1;
							INSERT INTO bdicnweb:"informix".sw_det_infprospectos(tipo_prospecto,rel_cliente,rel_a_cliente,nom_cliente_rel,rel_registrada,usuario_inserta)
							VALUES(cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada, pUsuario);
							
							LET cNumcteBanco = '';
							LET cNumcteRef = '';
							LET cRel_cliente = '';
							LET cRel_a_cliente = '';
							LET cNom_cliente_rel = '';
							LET cRel_registrada = '';
							LET cNombre1 = ''; 
							LET cNombre2 = '';
							LET cApell_paterno = '';
							LET cApell_materno = '';
							
							LET iContador = iContador + 1;
							IF iContador = iMaxCommit THEN
								COMMIT WORK;
								BEGIN WORK;
								LET iContador = 0;
							END IF;
						END IF;
						
					END FOREACH;
					
				ELIF NVL(cNumcteBanco, '') = '' AND NVL(cNumcteRef, '') <> '' THEN
					
					FOREACH
						
						SELECT
						DISTINCT(CTE.numcte), CTE.tipo_cliente,	RE.nombre1, RE.nombre2, RE.apell_paterno, RE.apell_materno, RE.parentesco
						INTO cRel_a_cliente, cRel_cliente, cNombre1, cNombre2, cApell_paterno, cApell_materno, cParentesco
						FROM bdinteg:"informix".si_refclientes RE
						LEFT JOIN bdinteg:"informix".si_cliente CTE ON RE.numcte_ref = CTE.numcte_ref
						WHERE RE.numcte = pCteBanco AND RE.numcte_ref = cNumcteRef
						
						IF NVL(cParentesco, '') <> '' THEN
							SELECT PAR.descripcion INTO cRel_registrada FROM bdinteg:"informix".si_parentesco PAR WHERE PAR.parentesco = cParentesco;
						ELSE
							LET cRel_registrada = '';
						END IF;
						
						IF cRel_cliente = '1' THEN
							LET cRel_cliente = 'SI';
						ELIF cRel_cliente = '2' THEN
							LET cRel_cliente = 'NO';
						ELIF cRel_cliente = '' OR cRel_cliente IS NULL THEN
							LET cRel_cliente = 'NO';
						END IF;
						
						LET cTipo_prospecto = 'REFERENCIA';
						LET cNom_cliente_rel = TRIM(TRIM(cNombre1)||' '||TRIM(cNombre2))||' '||TRIM(cApell_paterno)||' '||TRIM(cApell_materno);
						
						SELECT {+AVOID_FULL (bdicnweb:"informix".sw_det_infprospectos )} COUNT(*) INTO iExiste FROM bdicnweb:"informix".sw_det_infprospectos 
						WHERE --rel_a_cliente = cRel_a_cliente AND 
						nom_cliente_rel = cNom_cliente_rel AND usuario_inserta = pUsuario;
						
						IF NVL(iExiste,0) = 0 THEN
							LET iNoRegistros = iNoRegistros + 1;
							INSERT INTO bdicnweb:"informix".sw_det_infprospectos(tipo_prospecto,rel_cliente,rel_a_cliente,nom_cliente_rel,rel_registrada,usuario_inserta)
							VALUES(cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada, pUsuario);
							
							LET cNumcteBanco = '';
							LET cNumcteRef = '';
							LET cRel_cliente = '';
							LET cRel_a_cliente = '';
							LET cNom_cliente_rel = '';
							LET cRel_registrada = '';
							LET cNombre1 = ''; 
							LET cNombre2 = '';
							LET cApell_paterno = '';
							LET cApell_materno = '';
							
							LET iContador = iContador + 1;
							IF iContador = iMaxCommit THEN
								COMMIT WORK;
								BEGIN WORK;
								LET iContador = 0;
							END IF;
						END IF;
						
					END FOREACH;
				
				ELIF NVL(cNumcteBanco, '') <> '' AND NVL(cNumcteRef, '') <> '' THEN
					
					FOREACH
						
						SELECT
						DISTINCT(CTE.numcte), CTE.tipo_cliente,	RE.nombre1, RE.nombre2, RE.apell_paterno, RE.apell_materno, RE.parentesco
						INTO cRel_a_cliente, cRel_cliente, cNombre1, cNombre2, cApell_paterno, cApell_materno, cParentesco
						FROM bdinteg:"informix".si_refclientes RE
						LEFT JOIN bdinteg:"informix".si_cliente CTE ON RE.numcte_ref = CTE.numcte_ref
						WHERE RE.numcte = pCteBanco AND RE.numcte_ref = cNumcteRef AND RE.numcte_banco = cNumcteBanco
						
						IF NVL(cParentesco, '') <> '' THEN
							SELECT PAR.descripcion INTO cRel_registrada FROM bdinteg:"informix".si_parentesco PAR WHERE PAR.parentesco = cParentesco;
						ELSE
							LET cRel_registrada = '';
						END IF;
						
						IF cRel_cliente = '1' THEN
							LET cRel_cliente = 'SI';
						ELIF cRel_cliente = '2' THEN
							LET cRel_cliente = 'NO';
						ELIF cRel_cliente = '' OR cRel_cliente IS NULL THEN
							LET cRel_cliente = 'NO';
						END IF;
						
						LET cTipo_prospecto = 'REFERENCIA';
						LET cNom_cliente_rel = TRIM(TRIM(cNombre1)||' '||TRIM(cNombre2))||' '||TRIM(cApell_paterno)||' '||TRIM(cApell_materno);
						
						SELECT {+AVOID_FULL (bdicnweb:"informix".sw_det_infprospectos )} COUNT(*) INTO iExiste FROM bdicnweb:"informix".sw_det_infprospectos 
						WHERE --rel_a_cliente = cRel_a_cliente AND 
						nom_cliente_rel = cNom_cliente_rel AND usuario_inserta = pUsuario;
						
						IF NVL(iExiste,0) = 0 THEN
							LET iNoRegistros = iNoRegistros + 1;
							INSERT INTO bdicnweb:"informix".sw_det_infprospectos(tipo_prospecto,rel_cliente,rel_a_cliente,nom_cliente_rel,rel_registrada,usuario_inserta)
							VALUES(cTipo_prospecto, cRel_cliente, cRel_a_cliente, cNom_cliente_rel, cRel_registrada, pUsuario);
							
							LET cNumcteBanco = '';
							LET cNumcteRef = '';
							LET cRel_cliente = '';
							LET cRel_a_cliente = '';
							LET cNom_cliente_rel = '';
							LET cRel_registrada = '';
							LET cNombre1 = ''; 
							LET cNombre2 = '';
							LET cApell_paterno = '';
							LET cApell_materno = '';
							
							LET iContador = iContador + 1;
							IF iContador = iMaxCommit THEN
								COMMIT WORK;
								BEGIN WORK;
								LET iContador = 0;
							END IF;
