CREATE PROCEDURE "informix".sp_catalogotransaccioncargocap(pUsuario CHAR(10),pIdFuncion CHAR(10),pNaturaleza CHAR(1),pRegistros INTEGER,pRecuperacion INTEGER)
      RETURNING CHAR(5) AS codRet,
                CHAR(4) AS Clave_transaccion,
                CHAR(50) AS Desc_transaccion;

DEFINE cCodRet CHAR(5);
DEFINE cClave_transaccion CHAR(4);
DEFINE cDesc_transaccion CHAR(50);
DEFINE iSqlErr INT;
DEFINE cEmpresa CHAR(3);
DEFINE iRecuperacion INTEGER;

LET cCodRet = '00000';
LET iSqlErr = 0;
LET cEmpresa = '001';
LET cClave_transaccion = '';
LET cDesc_transaccion = '';
LET iRecuperacion = 0;


BEGIN

        ON EXCEPTION SET iSqlErr
                IF iSqlErr <> 0 THEN
                        LET cCodRet = iSqlErr;
                        RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
                END IF;
        END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_catalogotransaccioncargocap.out';
		--TRACE ON;
		
        IF  pUsuario = ''
         OR pIdFuncion = ''
         OR (pNaturaleza = '' OR pNaturaleza <> 'C')
        THEN
                LET cCodRet = '00003';
                RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
        END IF;
		
		-- VALIDACIÓN DE LOS DATOS DE PAGINACION
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
		END IF;
		
        -- VALIDACION DE ACCESO A LA FUNCIONALIDAD
        EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion)                            INTO cCodRet;
        IF cCodRet <> '00000' THEN
                RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
        END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
        FOREACH
			SELECT SKIP pRegistros FIRST pRecuperacion transacc,
					descripcion
			INTO    cClave_transaccion,
					cDesc_transaccion
			FROM bdicheq:"informix".sc_tranval tv, bdinteg:"informix".si_transacc tr
			WHERE tv.empresa = cEmpresa
			  AND tv.empresa = tr.empresa
			  AND transacc = numero
			  AND naturaleza = pNaturaleza
			ORDER BY 1
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet,cClave_transaccion,cDesc_transaccion WITH RESUME;
        END FOREACH;
		
		IF pRegistros = 0 AND iRecuperacion = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
		ELIF pRegistros > 0 AND iRecuperacion = 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
		END IF;
		
END;
END PROCEDURE
DOCUMENT 'AUTOR: M.D.S Sandra Cano',
'FECHA 20/09/2016',
'MODULO: DEBIITO',
'FUNCIONALIDAD: RETIRO A CUENTA OPERACION MANUAL',
'DESCRIPCION: SE MODIFICA PARA AGREGAR PARAMETROS DE PAGINACION Y DESPLEGAR TODAS LAS TRANSACCIONES EN LA FUNCIONALIDAD.',
