CREATE PROCEDURE "informix".sp_activardesactivarproductos(pUsuario CHAR(8), 
														  pIdFuncion CHAR(10), 
														  pProdActivaDesactiva CHAR(250), 
														  pTipo CHAR(1), 
														  pPlaza CHAR(3), 
														  pSucursal CHAR(4))
	RETURNING CHAR(5) AS cRetorno,
			  INTEGER AS iRegProcesados;

	DEFINE cCodRet					CHAR(5);
	DEFINE iSqlErr          		INTEGER;
	DEFINE cProducto			    CHAR(4);
	DEFINE cTieneProducto			CHAR(4);
	DEFINE cDescripcionProducto     CHAR(60);
	DEFINE cSistema					CHAR(2);
	DEFINE cTipoSistema				CHAR(2);
	DEFINE iNoRegistros 			INTEGER;
	DEFINE iTotSuc       			INTEGER;
	DEFINE iTotProdSuc       		INTEGER;
	DEFINE bInTransaction 			BOOLEAN;
	DEFINE cCadenaValores           CHAR(10);
	DEFINE cCadena                  CHAR(5);
	DEFINE iParams 					SMALLINT;
	DEFINE cActivarDesactivar       CHAR(1);
	DEFINE cSucursal 				CHAR(4);
	DEFINE iNoRegsProcesados 		INTEGER;

	LET cCodRet        			= "00000";
	LET iSqlErr          		= 0;
	LET cProducto             	= "";
	LET cDescripcionProducto	= "";
	LET cTieneProducto			= "";
	LET cSistema 				= "";
	LET cTipoSistema            = "06"; -- CREDITO
	LET iNoRegistros 			= 0;
	LET iTotSuc					= 0;
	LET iTotProdSuc				= 0;
	LET bInTransaction          = 'f';
	LET cCadenaValores          = '';
	LET cCadena					= '';
	LET iParams					= '';
	LET cActivarDesactivar      = '';
	LET cSucursal				= '';
	LET iNoRegsProcesados  		= 0;

	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,iNoRegsProcesados;
		END EXCEPTION;
		
		ON EXCEPTION IN (-535)
			LET bInTransaction = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
	   
		--SET DEBUG FILE TO "/tmp/mfinis/sp_activardesactivarproductos.out";
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pProdActivaDesactiva = '' OR pTipo = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,iNoRegsProcesados;
		END IF;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,iNoRegsProcesados;
		END IF;		

		BEGIN WORK;
					
			IF pTipo = "1" THEN -- ActivaciÃ³n/DesactivaciÃ³n por Gerencia Comercial
				
				FOREACH EXECUTE PROCEDURE bdicnweb:"informix".sp_split_cadena(pProdActivaDesactiva, '|')
						INTO cCadenaValores
						
						LET iParams = 0;
						FOREACH EXECUTE PROCEDURE bdicnweb:"informix".sp_split_cadena(cCadenaValores, ',')
							INTO cCadena
							
							IF iParams = 0 THEN
								LET cProducto = TRIM(cCadena);
								LET iParams = iParams + 1;
							ELIF iParams = 1 THEN
								LET cActivarDesactivar = TRIM(cCadena);
								LET iParams = iParams + 1;
							ELIF iParams = 2 THEN
								LET cSistema = TRIM(cCadena);
								EXIT FOREACH;
							END IF;
						END FOREACH;
						
						IF cActivarDesactivar = "1"  THEN -- ACTIVAR
						
					
							FOREACH
								SELECT sucursal INTO cSucursal
								FROM bdinteg:"informix".si_sucursales sc, bdinteg:"informix".si_plazas sp
								WHERE sc.plaza=sp.plaza
								AND sc.plaza= pPlaza
								
								DELETE FROM bdinteg:"informix".si_prod_sucursal WHERE empresa = '001' AND sucursal = cSucursal AND num_producto = cProducto;
									
								INSERT INTO bdinteg:"informix".si_prod_sucursal (empresa, sucursal, num_producto, sistema)
								VALUES ('001', cSucursal, cProducto, cSistema);
									
								LET iNoRegsProcesados = iNoRegsProcesados + DBINFO('sqlca.sqlerrd2');
									
								---
								IF cSistema = cTipoSistema THEN
									DELETE FROM bdisolic:"informix".ss_control_parametricos WHERE num_producto = cProducto AND sucursal = cSucursal AND num_parametrico='2';
											
									DELETE FROM bdinteg:"informix".si_control_tarj_suc WHERE empresa = '001' AND sucursal = cSucursal;
											
									INSERT INTO bdisolic:"informix".ss_control_parametricos(empresa, num_producto, sucursal, num_parametrico, descripcion, user_insert, fecha_insert)
									VALUES('001', cProducto, cSucursal, '2', ' Nuevo modelo paramÃ©trico CRIF', pUsuario, CURRENT);
								END IF;
								---
																
							END FOREACH;
						
						ELIF cActivarDesactivar = "0" THEN --DESACTIVAR
							FOREACH
								SELECT sucursal INTO cSucursal
								FROM bdinteg:"informix".si_sucursales sc, bdinteg:"informix".si_plazas sp
								WHERE sc.plaza=sp.plaza
								AND sc.plaza= pPlaza
								
								DELETE FROM bdinteg:"informix".si_prod_sucursal 
								WHERE empresa = '001' AND sucursal = cSucursal AND num_producto = cProducto; --AND sistema = cSistema;
								
								LET iNoRegsProcesados = iNoRegsProcesados + DBINFO('sqlca.sqlerrd2');
								
							END FOREACH;
						END IF;					
						
				END FOREACH;
				
			
			ELIF pTipo = "2" THEN -- ActivaciÃ³n/DesactivaciÃ³n por Nacional
				
				FOREACH EXECUTE PROCEDURE bdicnweb:"informix".sp_split_cadena(pProdActivaDesactiva, '|')
						INTO cCadenaValores
						
						LET iParams = 0;
						FOREACH EXECUTE PROCEDURE bdicnweb:"informix".sp_split_cadena(cCadenaValores, ',')
							INTO cCadena
							
							IF iParams = 0 THEN
								LET cProducto = TRIM(cCadena);
								LET iParams = iParams + 1;
							ELIF iParams = 1 THEN
								LET cActivarDesactivar = TRIM(cCadena);
								LET iParams = iParams + 1;
							ELIF iParams = 2 THEN
								LET cSistema = TRIM(cCadena);
								EXIT FOREACH;
							END IF;
						END FOREACH;
						
						IF cActivarDesactivar = "1"  THEN -- ACTIVAR
							FOREACH
								SELECT sucursal INTO cSucursal
								FROM bdinteg:"informix".si_sucursales
								
								DELETE FROM bdinteg:"informix".si_prod_sucursal WHERE empresa = '001' AND sucursal = cSucursal AND num_producto = cProducto;
								
								INSERT INTO bdinteg:"informix".si_prod_sucursal (empresa, sucursal, num_producto, sistema)
								VALUES ('001', cSucursal, cProducto, cSistema);
									
								LET iNoRegsProcesados = iNoRegsProcesados + DBINFO('sqlca.sqlerrd2');
									
								---
								IF cSistema = cTipoSistema THEN
										
									DELETE FROM bdisolic:"informix".ss_control_parametricos WHERE num_producto = cProducto AND sucursal = cSucursal AND num_parametrico='2';
											
									DELETE FROM bdinteg:"informix".si_control_tarj_suc WHERE empresa = '001' AND sucursal = cSucursal;
										
									INSERT INTO bdisolic:"informix".ss_control_parametricos(empresa, num_producto, sucursal, num_parametrico, descripcion, user_insert, fecha_insert)
									VALUES('001', cProducto, cSucursal, '2', ' Nuevo modelo paramÃ©trico CRIF', pUsuario, CURRENT);
									
								END IF;
								---
								
							END FOREACH;
						
						ELIF cActivarDesactivar = "0" THEN --DESACTIVAR
								
								DELETE FROM bdinteg:"informix".si_prod_sucursal 
								WHERE empresa = '001' AND num_producto = cProducto;
								
								LET iNoRegsProcesados = iNoRegsProcesados + DBINFO('sqlca.sqlerrd2');
								
						END IF;											
						
				END FOREACH;
				
			ELIF pTipo = "3" THEN -- ActivaciÃ³n/DesactivaciÃ³n por Sucursal
			
				FOREACH EXECUTE PROCEDURE bdicnweb:"informix".sp_split_cadena(pProdActivaDesactiva, '|')
						INTO cCadenaValores
						
						LET iParams = 0;
						FOREACH EXECUTE PROCEDURE bdicnweb:"informix".sp_split_cadena(cCadenaValores, ',')
							INTO cCadena
							
							IF iParams = 0 THEN
								LET cProducto = TRIM(cCadena);
								LET iParams = iParams + 1;
							ELIF iParams = 1 THEN
								LET cActivarDesactivar = TRIM(cCadena);
								LET iParams = iParams + 1;
							ELIF iParams = 2 THEN
								LET cSistema = TRIM(cCadena);
								EXIT FOREACH;
							END IF;
						END FOREACH;
						
						IF cActivarDesactivar = "1"  THEN -- ACTIVAR
							FOREACH
								SELECT sucursal INTO cSucursal
								FROM bdinteg:"informix".si_sucursales sc
								WHERE sc.sucursal = pSucursal
								
								DELETE FROM bdinteg:"informix".si_prod_sucursal 
								WHERE empresa = '001' AND sucursal = cSucursal AND num_producto = cProducto AND sistema = cSistema;
									
								DELETE FROM bdinteg:"informix".si_control_tarj_suc WHERE empresa = '001' AND sucursal = cSucursal;
									
								INSERT INTO bdinteg:"informix".si_prod_sucursal (empresa, sucursal, num_producto, sistema)
								VALUES ('001', cSucursal, cProducto, cSistema);
									
								LET iNoRegsProcesados = iNoRegsProcesados + DBINFO('sqlca.sqlerrd2');
									
								---
								IF cSistema = cTipoSistema THEN
									DELETE FROM bdisolic:"informix".ss_control_parametricos WHERE num_producto = cProducto AND sucursal = cSucursal AND num_parametrico='2';
										
									INSERT INTO bdisolic:"informix".ss_control_parametricos(empresa, num_producto, sucursal, num_parametrico, descripcion, user_insert, fecha_insert)
									VALUES('001', cProducto, cSucursal, '2', ' Nuevo modelo paramÃ©trico CRIF', pUsuario, CURRENT);
								END IF;
								---
									
							END FOREACH;
						
						ELIF cActivarDesactivar = "0" THEN --DESACTIVAR
							FOREACH
								SELECT sucursal INTO cSucursal
								FROM bdinteg:"informix".si_sucursales sc
								WHERE sc.sucursal = pSucursal
								
								DELETE FROM bdinteg:"informix".si_prod_sucursal 
								WHERE empresa = '001' AND sucursal = cSucursal AND num_producto = cProducto; --AND sistema = cSistema;
								
								LET iNoRegsProcesados = iNoRegsProcesados + DBINFO('sqlca.sqlerrd2');
								
							END FOREACH;
						END IF;					
						
				END FOREACH;
				
			END IF;

		COMMIT;
		
		IF bInTransaction = 't' THEN
			BEGIN WORK;
		END IF;
			
		RETURN cCodRet,iNoRegsProcesados;	
	   
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Rodolfo Conde Flores',
'FECHA: 08/08/2019',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: ActivaciÃ³n/DesactivaciÃ³n de Productos',
'DESCRIPCION: SPL que realiza ActivaciÃ³n/DesactivaciÃ³n de Productos a sucursal.',
'AUTOR: L. Montserrat LeÃ³n Amador',
'FECHA: 30/04/2020',
'DESCRIPCION: Se modifica SPL para eliminar llamado de la tabla si_ptf.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_consultaproductosactdesac(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipo CHAR(1), pPlaza CHAR(3), pSucursal CHAR(4))
	RETURNING CHAR(5)  AS cRetorno, 
			  CHAR(4)  AS codProducto,
			  CHAR(60) AS cDescripcionProd,
			  CHAR(2)  AS cSistema,
			  CHAR(4)  AS codTieneProducto;

	DEFINE cCodRet					CHAR(5);
	DEFINE iSqlErr          		INTEGER;
	DEFINE cProducto			    CHAR(4);
	DEFINE cTieneProducto			CHAR(4);
	DEFINE cDescripcionProducto     CHAR(60);
	DEFINE cSistema					CHAR(2);
	DEFINE iNoRegistros 			INTEGER;
	DEFINE iTotSuc       			INTEGER;
	DEFINE iTotProdSuc       		INTEGER;
	DEFINE cSucursal 				CHAR(4);

	LET cCodRet        			= "00000";
	LET iSqlErr          		= 0;
	LET cProducto             	= "";
	LET cDescripcionProducto	= "";
	LET cTieneProducto			= "";
	LET cSistema 				= "";
	LET iNoRegistros 			= 0;
	LET iTotSuc					= 0;
	LET iTotProdSuc				= 0;
	LET cSucursal				= '';

	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto;
		END EXCEPTION;
	   
		--SET DEBUG FILE TO "/tmp/mfinis/sp_consultaproductosactdesac.out";
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pTipo = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto;
		END IF;		

		IF pTipo = "1" THEN --Consulta por Gerencia Comercial
			IF pPlaza IS NOT NULL OR pPlaza <> '' THEN
				FOREACH
					SELECT {+AVOID_FULL(bdicheq:"informix".sc_producto)+AVOID_FULL(bdisolic:"informix".ss_tramite_productos_clasif)+AVOID_FULL(bdinteg:"informix".si_sucursales)} 
					DISTINCT(Prod.producto) AS numProd, Prod.nombre AS descProducto, tram.sistema AS sistema
					INTO cProducto, cDescripcionProducto, cSistema
					FROM bdicheq:"informix".sc_producto Prod, 
						 bdisolic:"informix".ss_tramite_productos_clasif tram,
						 bdinteg:"informix".si_sucursales sc, 
						 bdinteg:"informix".si_plazas sp
					WHERE Prod.empresa = '001'
					AND Prod.empresa = tram.empresa
					AND Prod.producto = tram.prod_ofrecer
					AND sc.plaza=sp.plaza
					AND sc.plaza= pPlaza
					UNION
					SELECT {+AVOID_FULL(bdicred:"informix".sd_definicion)+AVOID_FULL(bdisolic:"informix".ss_tramite_productos_clasif)}
					DISTINCT(Def.num_producto) AS numProd, Def.nombre_prod AS descProducto, tram.sistema AS sistema
					FROM bdicred:"informix".sd_definicion Def, 
						 bdisolic:"informix".ss_tramite_productos_clasif tram,
						 bdinteg:"informix".si_sucursales sc, 
						 bdinteg:"informix".si_plazas sp
					WHERE Def.empresa = '001'
					AND Def.empresa = tram.empresa
					AND Def.num_producto = tram.prod_ofrecer
					AND sc.plaza=sp.plaza
					AND sc.plaza= pPlaza
					UNION
					SELECT {+AVOID_FULL(bdinvers:"informix".sv_instrum)+AVOID_FULL(bdisolic:"informix".ss_tramite_productos_clasif)}
					DISTINCT(inst.cod_instrum) AS numProd, inst.nombre AS descProducto, tram.sistema AS sistema
					FROM bdinvers:"informix".sv_instrum inst, 
						 bdisolic:"informix".ss_tramite_productos_clasif tram,
						 bdinteg:"informix".si_sucursales sc, 
						 bdinteg:"informix".si_plazas sp
					WHERE inst.empresa = '001'
					AND inst.empresa = tram.empresa
					AND inst.cod_instrum = tram.prod_ofrecer
					AND sc.plaza=sp.plaza
					AND sc.plaza= pPlaza
					
					LET cTieneProducto = cProducto;
					
					FOREACH
						SELECT DISTINCT sc.sucursal INTO cSucursal
						FROM bdinteg:"informix".si_sucursales sc, 
							 bdinteg:"informix".si_plazas sp
						WHERE sc.plaza=sp.plaza
						AND sc.plaza= pPlaza
						
						SELECT COUNT(sucursal) INTO iTotProdSuc
						FROM bdinteg:"informix".si_prod_sucursal 
						WHERE sucursal = cSucursal AND num_producto = cProducto;
						
						IF iTotProdSuc = 0 THEN
							LET cTieneProducto = '';
							EXIT FOREACH;
						END IF;
							
					END FOREACH;
					
					LET iNoRegistros = iNoRegistros +1;
					
					RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto WITH resume;
				END FOREACH;
			ELSE
				LET cCodRet = '00003';
				RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto;
			END IF;
		
		ELIF pTipo = "2" THEN --Consulta por Nacional
			FOREACH
				SELECT {+AVOID_FULL(bdisolic:"informix".ss_tramite_productos_clasif)}
				DISTINCT(Prod.producto), Prod.nombre, tram.sistema
				INTO cProducto, cDescripcionProducto, cSistema
				FROM bdicheq:"informix".sc_producto Prod, 
					 bdisolic:"informix".ss_tramite_productos_clasif tram
				WHERE Prod.empresa = '001'
				AND Prod.empresa = tram.empresa
				AND Prod.producto = tram.prod_ofrecer
				UNION
				SELECT {+AVOID_FULL(bdisolic:"informix".ss_tramite_productos_clasif)}
				DISTINCT(Def.num_producto), Def.nombre_prod, tram.sistema
				FROM bdicred:"informix".sd_definicion Def, 
					 bdisolic:"informix".ss_tramite_productos_clasif tram
				WHERE Def.empresa = '001'
				AND Def.empresa = tram.empresa
				AND Def.num_producto = tram.prod_ofrecer
				UNION
				SELECT {+AVOID_FULL(bdinvers:"informix".sv_instrum)}
				DISTINCT(inst.cod_instrum), inst.nombre, tram.sistema 
				FROM bdinvers:"informix".sv_instrum inst, 
					 bdisolic:"informix".ss_tramite_productos_clasif tram
				WHERE inst.empresa = '001'
				AND inst.empresa = tram.empresa
				AND inst.cod_instrum = tram.prod_ofrecer
				
				SELECT COUNT(DISTINCT sc.sucursal) INTO iTotSuc
				FROM bdinteg:"informix".si_sucursales sc;


				SELECT {+AVOID_FULL(bdinteg:"informix".si_prod_sucursal)}
				COUNT(DISTINCT sc.sucursal) INTO iTotProdSuc
				FROM bdinteg:"informix".si_sucursales sc, 
					 bdinteg:"informix".si_prod_sucursal ps
				WHERE ps.sucursal = sc.sucursal
				AND ps.num_producto = cProducto;
				
				LET cTieneProducto = '';
				IF iTotProdSuc < iTotSuc THEN
					LET cTieneProducto = '';				
				ELSE
					LET cTieneProducto = cProducto;
				END IF;
				
				LET iNoRegistros = iNoRegistros +1;
				
				RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto WITH resume;
			END FOREACH;
			
		ELIF pTipo = "3" THEN --Consulta por Sucursal
			IF pSucursal IS NOT NULL OR pPlaza <> '' THEN
				FOREACH
					SELECT numProd, descProducto, sistema, prodSuc.num_producto
						INTO cProducto, cDescripcionProducto, cSistema, cTieneProducto
						FROM 
						(SELECT {+AVOID_FULL(bdicheq:"informix".sc_producto)+AVOID_FULL(bdisolic:"informix".ss_tramite_productos_clasif)}
						DISTINCT(Prod.producto) AS numProd, Prod.nombre AS descProducto, tram.sistema AS sistema
						FROM bdicheq:"informix".sc_producto Prod, 
							 bdisolic:"informix".ss_tramite_productos_clasif tram,
							 bdinteg:"informix".si_sucursales sc
						WHERE Prod.empresa = '001'
						AND Prod.empresa = tram.empresa
						AND Prod.producto = tram.prod_ofrecer
						AND sc.sucursal = pSucursal
						UNION
						SELECT {+AVOID_FULL(bdicred:"informix".sd_definicion)+AVOID_FULL(bdisolic:"informix".ss_tramite_productos_clasif)}
						DISTINCT(Def.num_producto) AS numProd, Def.nombre_prod AS descProducto, tram.sistema AS sistema
						FROM bdicred:"informix".sd_definicion Def, 
							 bdisolic:"informix".ss_tramite_productos_clasif tram,
							 bdinteg:"informix".si_sucursales sc
						WHERE Def.empresa = '001'
						AND Def.empresa = tram.empresa
						AND Def.num_producto = tram.prod_ofrecer
						AND sc.sucursal = pSucursal
						UNION
						SELECT {+AVOID_FULL(bdinvers:"informix".sv_instrum)}
						DISTINCT(inst.cod_instrum) AS numProd, inst.nombre AS descProducto, tram.sistema AS sistema
						FROM bdinvers:"informix".sv_instrum inst, 
							 bdisolic:"informix".ss_tramite_productos_clasif tram,
							 bdinteg:"informix".si_sucursales sc
						WHERE inst.empresa = '001'
						AND inst.empresa = tram.empresa
						AND inst.cod_instrum = tram.prod_ofrecer
						AND sc.sucursal = pSucursal) AS prodPlaza
						LEFT JOIN (SELECT {+AVOID_FULL(bdinteg:"informix".si_sucursales)}
									DISTINCT num_producto
									FROM bdinteg:"informix".si_sucursales sc, 
										 bdinteg:"informix".si_prod_sucursal ps
									WHERE ps.sucursal = sc.sucursal
									AND sc.sucursal = pSucursal) AS prodSuc
						ON prodPlaza.numProd = prodSuc.num_producto
					
					LET iNoRegistros = iNoRegistros +1;
					
					RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto WITH resume;
				END FOREACH;
			
			ELSE
				LET cCodRet = '00003';
				RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto;
			END IF;
		
		END IF;

	   IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, cProducto, cDescripcionProducto, cSistema, cTieneProducto;		
		END IF;
	   
	END;
END PROCEDURE
