CREATE PROCEDURE "informix".sp_ope_catgerenciascomerciales(pUsuario CHAR(8), pIdFuncion CHAR(10), pRegistros INTEGER, pRecuperacion INTEGER)
    RETURNING   CHAR(5) AS retorno,
				CHAR(3) AS empresa,
				CHAR(3) AS plaza,
				CHAR(40) AS nombre,
				CHAR(3) AS regional;

	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE iRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	DEFINE cEmpresa 	    CHAR(3);
    DEFINE cPlaza	        CHAR(3);
    DEFINE cNombre          CHAR(40);
    DEFINE cRegional        CHAR(3);
	

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	LET iRegistros = 0;
	LET iRecuperacion = 0;
	LET cEmpresa = '';
	LET cPlaza = '';
	LET cNombre = '';
	LET cRegional = '';

	BEGIN

		ON EXCEPTION SET iSqlErr
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional;
		END EXCEPTION;

		--SET DEBUG FILE TO '/tmp/mfinis/sp_ope_catgerenciascomerciales.out';
		--TRACE ON;

		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
				LET cCodRet = '00003';
				RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional;
		END IF;

		-- VALIDACION DE LA PAGINACION
		IF pRegistros < 0 OR pRecuperacion < 0 THEN
				LET cCodRet = '00098';
				RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional;
		END IF;

		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
				RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional;
		END IF;		


		FOREACH		
			SELECT {+AVOID_FULL(bdinteg:"informix".si_plazas)} SKIP pRegistros FIRST pRecuperacion
			--SELECT SKIP pRegistros FIRST pRecuperacion 
			--{+AVOID_FULL(bdinteg:"informix".si_sucursales idx_sucursal )}{+AVOID_FULL(bdinteg:"informix".si_plazas si_plazas_idx1 )}
			--{+INDEX(bdinteg:"informix".si_sucursales idx_sucursal )}{+INDEX(bdinteg:"informix".si_plazas si_plazas_idx1 )}
			DISTINCT B.empresa, B.plaza, C.nombre, C.regional
			INTO cEmpresa, cPlaza, cNombre, cRegional
			FROM bdinteg:"informix".si_plazas AS C
			INNER JOIN bdinteg:"informix".si_sucursales AS B 
			ON C.plaza = B.plaza
			ORDER BY C.nombre
			
			LET iNoRegistros = iNoRegistros +1;
			RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional WITH RESUME;
		END FOREACH;

		IF iNoRegistros = 0 AND pRegistros = 0 THEN
				LET cCodRet = '00017';
				RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional;
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
				LET cCodRet = '1001';
				RETURN cCodRet, cEmpresa, cPlaza, cNombre, cRegional;
		END IF;

	END;
END PROCEDURE
