CREATE PROCEDURE "informix".sp_cg_actualizastatusmasivo(pUsuario CHAR(8), pIdFuncion CHAR(10), pStatus CHAR(2), pIdRegistros VARCHAR(255))
	RETURNING
		CHAR(5) AS codret,
		INT AS exitosos, 
		INT AS fracasos
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE iExitosos INT;
	DEFINE iFracasos INT;
	DEFINE iCount INT;
	DEFINE iStart INT;
	DEFINE iLength INT;
	DEFINE iRow INT;
	DEFINE cBaseDatos CHAR(50);
	DEFINE cTablaDst CHAR(50);
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iExitosos = 0;
	LET iFracasos = 0;
	LET iLength = LENGTH(pIdRegistros);	
	LET iRow = 0;
	LET cBaseDatos = '';
	LET cTablaDst = '';
	
	BEGIN
		
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, iExitosos, iFracasos;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_cg_actualizastatusmasivo.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pStatus = '' OR pIdRegistros = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, iExitosos, iFracasos;
		END IF;
		
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, iExitosos, iFracasos;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		LET iStart = 1;
		
		SELECT base_datos, tabla
		INTO cBaseDatos, cTablaDst
		FROM sw_tr_info_tablas WHERE id_funcion = pIdFuncion;		
		
		IF cBaseDatos IS NULL OR cBaseDatos = '' THEN
			LET cCodRet = '00154';
			RETURN cCodRet, iExitosos, iFracasos;
		END IF;
		
		--ACTUALIZA TODA LA TABLA
		IF pIdRegistros = '0' THEN
			
			EXECUTE IMMEDIATE "UPDATE " || TRIM(cBaseDatos) || ":" || TRIM(cTablaDst) || " SET status='"|| TRIM(pStatus)||"';";
			LET iRow = dbinfo('sqlca.sqlerrd2');
			
			RETURN cCodRet, iExitosos, iFracasos;
			
		--ACTUALIZA REGISTROS SELECCIONADOS
		ELSE
			
			FOR iCount = 1 TO iLength
				IF SUBSTR(pIdRegistros, iCount, 1) = '|' THEN
					LET iRow = SUBSTR(pIdRegistros, iStart, iCount - iStart);
					EXECUTE IMMEDIATE "UPDATE " || TRIM(cBaseDatos) || ":" || TRIM(cTablaDst) || " SET status='"|| TRIM(pStatus) ||"' WHERE id_registro=" || iRow;
					LET iRow = dbinfo('sqlca.sqlerrd2');
					
					IF iRow > 0 THEN
						LET iExitosos = iExitosos + 1;
					ELSE
						LET iFracasos = iFracasos + 1;
					END IF;
					LET iStart = iCount + 1;
					
				ELIF iCount = iLength THEN
				
					LET iRow = SUBSTR(pIdRegistros, iStart);
					EXECUTE IMMEDIATE "UPDATE " || TRIM(cBaseDatos) || ":" || TRIM(cTablaDst) || " SET status='"|| TRIM(pStatus) ||"' WHERE id_registro=" || iRow;
					LET iRow = dbinfo('sqlca.sqlerrd2');
					
					IF iRow > 0 THEN
						LET iExitosos = iExitosos + 1;
					ELSE
						LET iFracasos = iFracasos + 1;
					END IF;
					LET iStart = iCount + 1;
				END IF;
			END FOR;
			
			RETURN cCodRet, iExitosos, iFracasos;
			
		END IF;
		
	END
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 30/03/2020',
'DESCRIPCION: Se realiza clonación de SPL sp_tr_actualizastatusmasivo para actualizar el status de forma masiva.',
'BD: bdicnweb';

