	LET dTotalBilletes = 0.0;
	LET dTotalMorralla = 0.0;
	LET dSaldoTotal = 0.0;
	LET dSumaIngreso = 0.0;
	LET dTotalBilletesEgr = 0.0;
	LET dTotalMorrallaEgr = 0.0;
	LET dSumaEgreso = 0.0;
	LET bSumasIguales = 'f';
	LET bSaldoIngresoMayor = 'f';

	LET dCantidadEgr1 = NULL;
	LET dCantidadEgr2 = NULL;
	LET dCantidadEgr3 = NULL;
	LET dCantidadEgr4 = NULL;
	LET dCantidadEgr5 = NULL;
	LET dCantidadEgr6 = NULL;
	LET dCantidadEgr7 = NULL;
	LET dCantidadEgr8 = NULL;
