	LET dCantidadEgr11 = NULL;
	LET dCantidadEgr12 = NULL;
	LET dCantidadEgr13 = NULL;
	LET dCantidadEgr14 = NULL;
	LET dCantidadEgr15 = NULL;
	LET iCodRetSp = 0;
	LET cCodRetSp = '';
	LET iNoRegsTotales = 0;
	
	LET iExisteFolio = 0;
	LET iIdRegistro = 0;
	LET cIdUsuarioSoc = '';
	LET cSucursal = '';
	LET cCajaGen = '';
	LET dFecha = '';
	LET cDescStatus = '';
	LET cFolioOperacion = '';
	LET dMonto = 0.00;
	LET cUsuario = '';
	LET cIdUsuario = '';
	LET cIdStatus = '';
	LET cCodTrans = '';
	LET cTpoSucursal = '';
	LET cCodProveedor = '';
	LET cIdSucursal = '';
	LET cStatus = '';
	LET iIdLote = 0;
	LET cCodRetorno = '';
	LET cMensaje = '';
	LET dFechaProceso = '';
	
	LET bEnTransaccion = 'f';
	LET iContador = 0;
	LET iMaxCommit = 1000;
	LET iNoRegistros = 0;
	LET iNumRegsNoProcesados = 0;
	
	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			
			IF bEnTransaccion = 't' THEN
				ROLLBACK WORK;
			END IF;
			
			UPDATE {+INDEX (bdicnweb:status_cg_dotaciones_masivo idx_status_cg_dotaciones_masivo)} "informix".status_cg_dotaciones_masivo
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegsProcesados;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bEnTransaccion = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_cg_enviodotacionmasivo.out';
		--TRACE ON;
		
		-- SE LIMPIA TABLA VERIFICA STATUS
		SET LOCK MODE TO WAIT 3;
		DELETE FROM "informix".status_cg_dotaciones_masivo WHERE usuario_insert = pUsuario;
		SET LOCK MODE TO WAIT 3;
		INSERT INTO "informix".status_cg_dotaciones_masivo(usuario_insert,status,num_registros,error_proceso,error) VALUES(pUsuario,'I',0,'',cCodRet);
		
		IF pUsuario = '' OR pIdFuncion = '' OR pLote IS NULL THEN
			LET cCodRet = '00003';
			UPDATE {+INDEX (bdicnweb:status_cg_dotaciones_masivo idx_status_cg_dotaciones_masivo)} "informix".status_cg_dotaciones_masivo
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegsProcesados;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE {+INDEX (bdicnweb:status_cg_dotaciones_masivo idx_status_cg_dotaciones_masivo)} "informix".status_cg_dotaciones_masivo
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iNoRegsProcesados;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		FOREACH WITH HOLD 
				
				SELECT {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} folio_operacion, id_registro 
				INTO cFolioOperacion, iIdRegistro
				FROM bdicnweb:"informix".sw_cg_enviodotaciones
				WHERE id_usuario_soc = pUsuario
				AND id_lote = pLote
				AND status = 'P'

			-- VALIDACION DE QUE EL FOLIO EXISTA
			SELECT COUNT(folio_oper) INTO iExisteFolio FROM bdisuc:"informix".ss_operaciones WHERE folio_oper = cFolioOperacion;
			
			IF NVL(iExisteFolio,0) > 0 THEN

				SELECT crs.cod_trans, rstablas.status,
					CASE WHEN TRIM(crs.denominacion_1) = '' THEN '0' ELSE crs.denominacion_1 END,
					CASE WHEN TRIM(crs.denominacion_2) = '' THEN '0' ELSE crs.denominacion_2 END,
					CASE WHEN TRIM(crs.denominacion_3) = '' THEN '0' ELSE crs.denominacion_3 END,
					CASE WHEN TRIM(crs.denominacion_4) = '' THEN '0' ELSE crs.denominacion_4 END,
					CASE WHEN TRIM(crs.denominacion_5) = '' THEN '0' ELSE crs.denominacion_5 END,
					CASE WHEN TRIM(crs.denominacion_6) = '' THEN '0' ELSE crs.denominacion_6 END,
					CASE WHEN TRIM(crs.denominacion_7) = '' THEN '0' ELSE crs.denominacion_7 END,
					CASE WHEN TRIM(crs.denominacion_8) = '' THEN '0' ELSE crs.denominacion_8 END,
					CASE WHEN TRIM(crs.denominacion_9) = '' THEN '0' ELSE crs.denominacion_9 END,
					CASE WHEN TRIM(crs.denominacion_10) = '' THEN '0' ELSE crs.denominacion_10 END,
					CASE WHEN TRIM(crs.denominacion_11) = '' THEN '0' ELSE crs.denominacion_11 END,
					CASE WHEN TRIM(crs.denominacion_12) = '' THEN '0' ELSE crs.denominacion_12 END,
					CASE WHEN TRIM(crs.denominacion_13) = '' THEN '0' ELSE crs.denominacion_13 END,
					CASE WHEN TRIM(crs.denominacion_14) = '' THEN '0' ELSE crs.denominacion_14 END,
					CASE WHEN TRIM(crs.denominacion_15) = '' THEN '0' ELSE crs.denominacion_15 END,
					crs.cantidad_1, crs.cantidad_2, crs.cantidad_3, crs.cantidad_4, crs.cantidad_5,
					crs.cantidad_6, crs.cantidad_7, crs.cantidad_8, crs.cantidad_9, crs.cantidad_10,
					crs.cantidad_11, crs.cantidad_12, crs.cantidad_13, crs.cantidad_14, crs.cantidad_15, 
					rs2.saldo_total,
					rs2.cantidad_1, rs2.cantidad_2, rs2.cantidad_3, rs2.cantidad_4, rs2.cantidad_5,
					rs2.cantidad_6, rs2.cantidad_7, rs2.cantidad_8, rs2.cantidad_9, rs2.cantidad_10,
					rs2.cantidad_11, rs2.cantidad_12, rs2.cantidad_13, rs2.cantidad_14, rs2.cantidad_15,
					rstablas.cod_proveedor
				INTO cCodTrans, cStatus, 
					cDenominacion1, cDenominacion2, cDenominacion3, cDenominacion4, cDenominacion5, 
					cDenominacion6, cDenominacion7, cDenominacion8, cDenominacion9, cDenominacion10,
					cDenominacion11, cDenominacion12, cDenominacion13, cDenominacion14, cDenominacion15,
					dCantidadIng1, dCantidadIng2, dCantidadIng3, dCantidadIng4, dCantidadIng5,
					dCantidadIng6, dCantidadIng7, dCantidadIng8, dCantidadIng9, dCantidadIng10,
					dCantidadIng11, dCantidadIng12, dCantidadIng13, dCantidadIng14, dCantidadIng15,
					dSaldoTotal,
					dCantidadEgr1, dCantidadEgr2, dCantidadEgr3, dCantidadEgr4, dCantidadEgr5,
					dCantidadEgr6, dCantidadEgr7, dCantidadEgr8, dCantidadEgr9, dCantidadEgr10,
					dCantidadEgr11, dCantidadEgr12, dCantidadEgr13, dCantidadEgr14, dCantidadEgr15,
					cCodProveedor
				FROM bdisuc:"informix".ss_operaciones crs LEFT JOIN bdisuc:"informix".ss_mae_entradasalida rstablas ON rstablas.folio_oper = crs.folio_oper
				LEFT JOIN bdisuc:"informix".ss_cajageneral rs2 ON rs2.cod_proveedor = rstablas.cod_proveedor
				WHERE crs.folio_oper = cFolioOperacion;

				IF (cCodTrans = '0001' AND cStatus = '01') OR (cCodTrans = '0010' AND cStatus = '01') OR (cCodTrans = '0036' AND cStatus IN ('12','01')) THEN
					LET dTotalBilletes = 0.0;
					LET dTotalMorralla = 0.0;

					IF NVL(cDenominacion1, '') <> '' THEN
						IF dCantidadIng1 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng1 * cDenominacion1);
						END IF;
					END IF;

					IF NVL(cDenominacion2, '') <> '' THEN
						IF dCantidadIng2 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng2 * cDenominacion2);
						END IF;
					END IF;

					IF NVL(cDenominacion3, '') <> '' THEN
						IF dCantidadIng3 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng3 * cDenominacion3);
						END IF;
					END IF;

					IF NVL(cDenominacion4, '') <> '' THEN
						IF dCantidadIng4 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng4 * cDenominacion4);
						END IF;
					END IF;

					IF NVL(cDenominacion5, '') <> '' THEN
						IF dCantidadIng5 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng5 * cDenominacion5);
						END IF;
					END IF;

					IF NVL(cDenominacion6, '') <> '' THEN
						IF dCantidadIng6 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng6 * cDenominacion6);
						END IF;
					END IF;

					IF NVL(cDenominacion7, '') <> '' THEN
						IF dCantidadIng7 IS NOT NULL THEN
							LET dTotalBilletes = dTotalBilletes + (dCantidadIng7 * cDenominacion7);
						END IF;
					END IF;

					IF NVL(cDenominacion8, '') <> '' THEN
						IF dCantidadIng8 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng8 * cDenominacion8);
						END IF; 
					END IF;

					IF NVL(cDenominacion9, '') <> '' THEN
						IF dCantidadIng9 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng9 * cDenominacion9);
						END IF;
					END IF;

					IF NVL(cDenominacion10, '') <> '' THEN
						IF dCantidadIng10 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng10 * cDenominacion10);
						END IF;
					END IF;

					IF NVL(cDenominacion11, '') <> '' THEN
						IF dCantidadIng11 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng11 * cDenominacion11);
						END IF;
					END IF;

					IF NVL(cDenominacion12, '') <> '' THEN
						IF dCantidadIng12 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng12 * cDenominacion12);
						END IF;
					END IF;

					IF NVL(cDenominacion13, '') <> '' THEN
						IF dCantidadIng13 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng13 * cDenominacion13);
						END IF;
					END IF;

					IF NVL(cDenominacion14, '') <> '' THEN
						IF dCantidadIng14 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng14 * cDenominacion14);
						END IF;
					END IF;

					IF NVL(cDenominacion15, '') <> '' THEN
						IF dCantidadIng15 IS NOT NULL THEN
							LET dTotalMorralla = dTotalMorralla + (dCantidadIng15 * cDenominacion15);
						END IF;
					END IF;

					-- COMPARACION DEL MONTO TOTAL
					LET dSumaIngreso = dTotalBilletes + dTotalMorralla;
					IF dSumaIngreso > dSaldoTotal THEN
						LET cMensaje = 'LA DOTACION SOLICITADA '||TRIM(cFolioOperacion)||' ES MAYOR AL SALDO DISPONIBLE EN CAJA GENERAL';
						LET cCodRetorno = '00001';
						LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
					ELSE
						
						LET dTotalBilletesEgr = dTotalBilletes;
						LET dTotalMorrallaEgr = dTotalMorralla;
						LET dSumaEgreso = dTotalBilletesEgr + dTotalMorrallaEgr;
                        
						-- VALIDACION DE LAS SUMAS
						IF (dSumaEgreso = dSumaIngreso) AND (dSumaIngreso <= dSaldoTotal) THEN
							
							IF cStatus IN ('01', '12') THEN
							
								IF dCantidadIng1 > dCantidadEgr1 THEN
									LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
									LET cCodRetorno = '00003';
									LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
								ELIF dCantidadIng2 > dCantidadEgr2 THEN
									LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
									LET cCodRetorno = '00003';
									LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
								ELIF dCantidadIng3 > dCantidadEgr3 THEN
									LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
									LET cCodRetorno = '00003';
									LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
								ELIF dCantidadIng4 > dCantidadEgr4 THEN
									LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
									LET cCodRetorno = '00003';
									LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
								ELIF dCantidadIng5 > dCantidadEgr5 THEN
									LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
									LET cCodRetorno = '00003';
									LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
								ELIF dCantidadIng6 > dCantidadEgr6 THEN
									LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
									LET cCodRetorno = '00003';
									LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
								ELIF dCantidadIng7 > dCantidadEgr7 THEN
									LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
									LET cCodRetorno = '00003';
									LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
								ELSE
									-- ACTUALIZACION DEL FOLIO DE OPERACION
									UPDATE {+INDEX (bdisuc:ss_mae_entradasalida idx01ss_mae_entradasalida)} bdisuc:"informix".ss_mae_entradasalida
									SET status = '03',
										hora_envio = TO_CHAR(CURRENT, '%H:%m'),
										fecha_envio = CURRENT,
										usuario_envio = pUsuario
									WHERE folio_oper = cFolioOperacion;

									-- ACTUALIZACION DE LA DOTACION
									UPDATE {+INDEX (bdisuc:ss_cajageneral idx_ss_cajageneral)} bdisuc:"informix".ss_cajageneral
									SET cantidad_1 = cantidad_1 - dCantidadIng1,
										cantidad_2 = cantidad_2 - dCantidadIng2,
										cantidad_3 = cantidad_3 - dCantidadIng3,
										cantidad_4 = cantidad_4 - dCantidadIng4,
										cantidad_5 = cantidad_5 - dCantidadIng5,
										cantidad_6 = cantidad_6 - dCantidadIng6,
										cantidad_7 = cantidad_7 - dTotalMorralla,
										saldo_total = saldo_total - dSumaEgreso,
										saldo_asignado = saldo_asignado + dSumaEgreso
									WHERE cod_proveedor = cCodProveedor;
									
									IF DBINFO('sqlca.sqlerrd2') > 0 THEN
										LET iNoRegsProcesados = iNoRegsProcesados + 1;
									END IF;
									
									LET cMensaje = 'OPERACION EXITOSA';
									LET cCodRetorno = '00000';
									
								END IF;	
								
							ELSE    
								LET cMensaje = 'LA OPERACION NO CUENTA CON EL ESTATUS REQUERIDO DE SOLICITUD DOTACION SUCURSAL';
								LET cCodRetorno = '00004';
								LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
							END IF;
						ELSE
							LET cMensaje = 'NO HAY SUFICIENTE CANTIDAD DE ALGUNA DENOMINACION, TENDRA QUE ENVIARLA DE FORMA DETALLADA';
							LET cCodRetorno = '00003';
							LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
						END IF;

					END IF;
				ELSE
					LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
				END IF;

			ELSE
				LET cMensaje = 'EL FOLIO DE OPERACION '||TRIM(cFolioOperacion)||' NO EXISTE';
				LET cCodRetorno = '00002';
				LET iNumRegsNoProcesados = iNumRegsNoProcesados + 1;
			END IF;
			
			-- ACTUALIZACION DEL MENSAJE
			UPDATE {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} bdicnweb:"informix".sw_cg_enviodotaciones
			SET mensaje = cMensaje,
				fecha_proceso = CURRENT,
				cod_retorno = cCodRetorno
			WHERE id_registro = iIdRegistro;

			LET iNoRegsTotales = iNoRegsTotales + 1;
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
			
		END FOREACH;
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		-- ACTUALIZACION DEL ESTATUS A TERMINADO
		UPDATE {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} bdicnweb:"informix".sw_cg_enviodotaciones
		SET status = 'T'
		WHERE id_lote = pLote
		AND fecha_proceso IS NOT NULL;
		
		LET iIdRegistro = 0;
		LET cCodRetorno = '';
		LET cMensaje = '';
		
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		-- SE MUEVE TODO EL LOTE AL HISTORICO
		FOREACH WITH HOLD
			SELECT {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} id_registro,id_usuario_soc,sucursal,caja_general,fecha,desc_status,folio_operacion,monto,usuario,id_usuario,
			id_status,cod_trans,tpo_sucursal,cod_proveedor,id_sucursal,status,id_lote,cod_retorno,mensaje,fecha_proceso 
			INTO iIdRegistro, cIdUsuarioSoc, cSucursal, cCajaGen, dFecha, cDescStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, 
			cIdStatus, cCodTrans, cTpoSucursal, cCodProveedor, cIdSucursal, cStatus, iIdLote, cCodRetorno, cMensaje, dFechaProceso
			FROM bdicnweb:"informix".sw_cg_enviodotaciones
			WHERE id_lote = pLote
			AND fecha_proceso IS NOT NULL
			
			LET iNoRegistros = iNoRegistros + 1;
			INSERT INTO bdicnweb:"informix".sw_cg_enviodotaciones_hist(id_registro,id_usuario_soc,sucursal,caja_general,fecha,desc_status,folio_operacion,monto,usuario,id_usuario,
			id_status,cod_trans,tpo_sucursal,cod_proveedor,id_sucursal,status,id_lote,cod_retorno,mensaje,fecha_proceso)
			VALUES(iIdRegistro, cIdUsuarioSoc, cSucursal, cCajaGen, dFecha, cDescStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, 
			cIdStatus, cCodTrans, cTpoSucursal, cCodProveedor, cIdSucursal, cStatus, iIdLote, cCodRetorno, cMensaje, dFechaProceso);
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
			
		END FOREACH;
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		UPDATE {+INDEX (bdicnweb:status_cg_dotaciones_masivo idx_status_cg_dotaciones_masivo)} "informix".status_cg_dotaciones_masivo
		SET status = 'T',
		error_proceso = 'N',
		num_registros = iNoRegsProcesados,
		registros_totales = iNoRegsTotales,
		registros_no_procesados = iNumRegsNoProcesados
		WHERE usuario_insert = pUsuario;
		
		RETURN cCodRet, iNoRegsProcesados;

	END;

END PROCEDURE
DOCUMENT 'AUTOR: Oscar Flores Conde',
'FECHA: 11/02/2015',
'DESCRIPCION: Ejecuta en envio masivo de dotacion de caja general',
'AUTOR: L. Montserrat León Amador',
'FECHA: 30/03/2020',
'DESCRIPCION: Se modifica SPL eliminar notificación de correo electronico y obtener el número de dotaciones enviadas satisfactoriamente.',
'AUTOR: L. Montserrat León Amador',
'FECHA: 02/04/2020',
'DESCRIPCION: Se modifica SPL para corregir validación en denominaciones y aplicar commit cada 1000 registros procesados.',
'AUTOR: Rodolfo Conde Flores',
'FECHA: 13/04/2020',
'DESCRIPCION: Se modifica SPL para contabilizar de registros a procesar, de los proceados y no procesados.',
'AUTOR: L. Montserrat León Amador',
'FECHA: 16/04/2020',
'DESCRIPCION: Se modifica SPL para modificar validación en cantidades de la posición 8 a la 15 (morralla corresponde a la cantidad_7).',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_cg_reversodotacionmasivo(pUsuario CHAR(8), pIdFuncion CHAR(10), pLote INTEGER)
		RETURNING CHAR(5) AS codret,
			INTEGER AS registros_procesados;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iRegsProcesados INTEGER;
	DEFINE iNoRegsAfectados INTEGER;
	DEFINE iCodRetSp INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iNoRegsTotales INTEGER;
	
	DEFINE iIdRegistro INTEGER;
	DEFINE cIdUsuarioSoc CHAR(8);
	DEFINE cSucursal CHAR(50);
	DEFINE cCajaGen CHAR(50);
	DEFINE dFecha DATE;
	DEFINE cDescStatus CHAR(50);
	DEFINE cFolioOperacion CHAR(8);
	DEFINE dMonto DECIMAL(14,2);
	DEFINE cUsuario CHAR(50);    
	DEFINE cIdUsuario CHAR(8);
	DEFINE cIdStatus CHAR(2);
	DEFINE cCodTrans CHAR(4);
	DEFINE cTpoSucursal CHAR(2);
	DEFINE cCodProveedor CHAR(4);
	DEFINE cIdSucursal CHAR(4);
	DEFINE cStatus CHAR(2);
	DEFINE iIdLote INTEGER;
	DEFINE cCodRetorno CHAR(5);
	DEFINE cMensaje CHAR(150);
	DEFINE dFechaProceso DATETIME YEAR to FRACTION(3);
	
	DEFINE bEnTransaccion BOOLEAN;
	DEFINE iContador INTEGER;
	DEFINE iMaxCommit INTEGER;
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iRegsProcesados = 0;
	LET iNoRegsAfectados = 0;
	LET iCodRetSp = 0;
	LET cCodRetSp = '';
	LET iNoRegsTotales = 0;
	
	LET iIdRegistro = 0;
	LET cIdUsuarioSoc = '';
	LET cSucursal = '';
	LET cCajaGen = '';
	LET dFecha = '';
	LET cDescStatus = '';
	LET cFolioOperacion = '';
	LET dMonto = 0.00;
	LET cUsuario = '';
	LET cIdUsuario = '';
	LET cIdStatus = '';
	LET cCodTrans = '';
	LET cTpoSucursal = '';
	LET cCodProveedor = '';
	LET cIdSucursal = '';
	LET cStatus = '';
	LET iIdLote = 0;
	LET cCodRetorno = '';
	LET cMensaje = '';
	LET dFechaProceso = '';
	
	LET bEnTransaccion = 'f';
	LET iContador = 0;
	LET iMaxCommit = 1000;
	LET iNoRegistros = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			
			IF bEnTransaccion = 't' THEN
				ROLLBACK WORK;
			END IF;
			
			UPDATE {+INDEX (bdicnweb:status_cg_dotaciones_masivo idx_status_cg_dotaciones_masivo)} "informix".status_cg_dotaciones_masivo
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iRegsProcesados;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bEnTransaccion = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_cg_reversodotacionmasivo.out';
		--TRACE ON;
		
		-- SE LIMPIA TABLA VERIFICA STATUS
		SET LOCK MODE TO WAIT 3;
		DELETE FROM {+INDEX (bdicnweb:status_cg_dotaciones_masivo idx_status_cg_dotaciones_masivo)} "informix".status_cg_dotaciones_masivo WHERE usuario_insert = pUsuario;
		SET LOCK MODE TO WAIT 3;
		INSERT INTO "informix".status_cg_dotaciones_masivo(usuario_insert,status,num_registros,error_proceso,error) VALUES(pUsuario,'I',0,'',cCodRet);
		
		IF pUsuario = '' OR pIdFuncion = '' OR pLote IS NULL THEN
			LET cCodRet = '00003';
			UPDATE {+INDEX (bdicnweb:status_cg_dotaciones_masivo idx_status_cg_dotaciones_masivo)} "informix".status_cg_dotaciones_masivo
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iRegsProcesados;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			UPDATE "informix".status_cg_dotaciones_masivo
			SET status = 'E', error_proceso = 'S', error = cCodRet WHERE usuario_insert = pUsuario;
			RETURN cCodRet, iRegsProcesados;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		FOREACH WITH HOLD
				
				SELECT {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} folio_operacion, id_registro
				INTO cFolioOperacion, iIdRegistro
				FROM bdicnweb:"informix".sw_cg_enviodotaciones
				WHERE id_lote = pLote
				AND status = 'P'
				
			LET cCodRetorno = '00000';
			LET cMensaje = 'OPERACION EXITOSA';
			
			UPDATE {+INDEX (bdisuc:ss_operaciones idx02ss_operaciones)} bdisuc:"informix".ss_operaciones
			SET reversado = '1'
			WHERE folio_oper = cFolioOperacion;
			
			LET iNoRegsAfectados = DBINFO('sqlca.sqlerrd2');
			
			IF iNoRegsAfectados = 0 THEN
				LET cCodRetorno = '00001';
				LET cMensaje = 'NO SE ENCONTRO EL FOLIO EN LA TABLA ss_operaciones';
			ELIF iNoRegsAfectados > 1 THEN
				LET cCodRetorno = '00000';
				LET cMensaje = 'SE ACTUALIZO MAS DE UN REGISTRO CON ESE FOLIO EN LA TABLA ss_operaciones';
			ELSE
				UPDATE {+INDEX (bdisuc:ss_mae_entradasalida idx01ss_mae_entradasalida)} bdisuc:"informix".ss_mae_entradasalida
				SET hora_reversion = TO_CHAR(CURRENT, '%H:%m'),
					fecha_reversion = CURRENT,
					usuario_reversion = pUsuario,
					status = '08'
				WHERE folio_oper = cFolioOperacion;
				
				LET iNoRegsAfectados = DBINFO('sqlca.sqlerrd2');
				IF iNoRegsAfectados = 0 THEN
					LET cCodRetorno = '00002';
					LET cMensaje = 'NO SE ENCONTRO EL FOLIO EN LA TABLA ss_mae_entradasalida';
				ELIF iNoRegsAfectados > 1 THEN
					LET cCodRetorno = '00000';
					LET cMensaje = 'SE ACTUALIZO MAS DE UN REGISTRO CON ESE FOLIO EN LA TABLA ss_mae_entradasalida';
				ELSE
					LET iRegsProcesados = iRegsProcesados + 1;
				END IF;
				
			END IF;
			
			UPDATE {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} bdicnweb:"informix".sw_cg_enviodotaciones
			SET mensaje = cMensaje,
				fecha_proceso = CURRENT,
				cod_retorno = cCodRetorno
			WHERE id_registro = iIdRegistro;
			
			LET iNoRegsTotales = iNoRegsTotales + 1;
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
			
		END FOREACH;
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		-- ACTUALIZACION DEL ESTATUS A REVERSADO
		UPDATE {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} bdicnweb:"informix".sw_cg_enviodotaciones
		SET status = 'R'
		WHERE id_lote = pLote
		AND fecha_proceso IS NOT NULL;
		
		LET iIdRegistro = 0;
		LET cCodRetorno = '';
		LET cMensaje = '';
		
		BEGIN WORK;
		LET bEnTransaccion = 't';
		
		-- SE MUEVE TODO EL LOTE AL HISTORICO
		FOREACH WITH HOLD
			SELECT {+INDEX (bdicnweb:sw_cg_enviodotaciones idx_cg_enviodotaciones1)} id_registro,id_usuario_soc,sucursal,caja_general,fecha,desc_status,folio_operacion,monto,usuario,id_usuario,
			id_status,cod_trans,tpo_sucursal,cod_proveedor,id_sucursal,status,id_lote,cod_retorno,mensaje,fecha_proceso 
			INTO iIdRegistro, cIdUsuarioSoc, cSucursal, cCajaGen, dFecha, cDescStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, 
			cIdStatus, cCodTrans, cTpoSucursal, cCodProveedor, cIdSucursal, cStatus, iIdLote, cCodRetorno, cMensaje, dFechaProceso
			FROM bdicnweb:"informix".sw_cg_enviodotaciones
			WHERE id_lote = pLote
			AND fecha_proceso IS NOT NULL
			
			LET iNoRegistros = iNoRegistros + 1;
			INSERT INTO bdicnweb:"informix".sw_cg_enviodotaciones_hist(id_registro,id_usuario_soc,sucursal,caja_general,fecha,desc_status,folio_operacion,monto,usuario,id_usuario,
			id_status,cod_trans,tpo_sucursal,cod_proveedor,id_sucursal,status,id_lote,cod_retorno,mensaje,fecha_proceso)
			VALUES(iIdRegistro, cIdUsuarioSoc, cSucursal, cCajaGen, dFecha, cDescStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, 
			cIdStatus, cCodTrans, cTpoSucursal, cCodProveedor, cIdSucursal, cStatus, iIdLote, cCodRetorno, cMensaje, dFechaProceso);
			
			LET iContador = iContador + 1;
			IF iContador = iMaxCommit THEN
				COMMIT WORK;
				BEGIN WORK;
				LET iContador = 0;
			END IF;
			
		END FOREACH;
		
		COMMIT WORK;
		IF bEnTransaccion = 't' THEN
			BEGIN WORK;
			LET bEnTransaccion = 'f';
			LET iContador = 0;
		END IF;
		
		UPDATE "informix".status_cg_dotaciones_masivo
		SET status = 'T', error_proceso = 'N', num_registros = iRegsProcesados WHERE usuario_insert = pUsuario;
		
		RETURN cCodRet, iRegsProcesados;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: Oscar Flores Conde',
'FECHA: 11/02/2015',
'DESCRIPCION: Reversa las dotaciones solicitadas a enviar en un lote',
'MODULO: Caja general',
'AUTOR: L. Montserrat León Amador',
'FECHA: 30/03/2020',
'DESCRIPCION: Se modifica SPL eliminar notificación de correo electronico y obtener el número de reverso enviados satisfactoriamente.',
'AUTOR: L. Montserrat León Amador',
'FECHA: 02/04/2020',
'DESCRIPCION: Se modifica SPL para aplicar commit cada 1000 registros procesados.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_consultainfdotacionescaja(pUsuario CHAR(8), pIdFuncion CHAR(10), pTipoSucursal CHAR(2), pIdProvCaja CHAR(4), pIdSucursal CHAR(4), pFechaInic DATE, pFechaFin DATE, pIdLote INTEGER, 
pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(50) AS sucursal,
			CHAR(50) AS caja_gen,
			DATE AS fecha,
			CHAR(50) AS status,
			CHAR(8) AS folio_operacion, 
			DECIMAL(14,2) AS monto,
			CHAR(50) AS usuario,
			CHAR(8) AS id_usuario,
			CHAR(2) AS id_status,
			CHAR(4) AS cod_trans,
			INTEGER AS id_registro; 
    
	DEFINE cCodRet CHAR(5);
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE iSqlErr INTEGER;
	DEFINE cSucursal CHAR(50);
	DEFINE cCajaGen CHAR(50);
	DEFINE dFecha DATE;
	DEFINE cStatus CHAR(50);
	DEFINE cFolioOperacion CHAR(8);
	DEFINE dMonto DECIMAL(14,2);
	DEFINE cUsuario CHAR(50);    
	DEFINE cIdUsuario CHAR(8);
	DEFINE cIdStatus CHAR(2);
	DEFINE cCodTrans CHAR(4);
	DEFINE iIdRegistro INTEGER;
	
	DEFINE cEmpresa CHAR(3);
	DEFINE iNoRegistros INTEGER; 
	DEFINE iRecuperacion INTEGER;
	DEFINE iRegistros INTEGER;
	DEFINE iIdLote INTEGER;
	
	LET cCodRet = '00000';
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET iSqlErr = 0;
	LET cSucursal = '';
	LET cCajaGen = '';
	LET dFecha = NULL;
	LET cStatus = '';
	LET cFolioOperacion = '';
	LET dMonto = NULL;
	LET cUsuario = '';
	LET cIdUsuario = '';
	LET cIdStatus = '';
	LET cCodTrans = '';
	LET iIdRegistro = 0;
	
	LET cEmpresa = '001';
	LET iNoRegistros = 0; 
	LET iRecuperacion = 0;
	LET iRegistros = 0;
	LET iIdLote = 0;
	
	BEGIN
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cSucursal, cCajaGen, dFecha, cStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, cIdStatus, cCodTrans, iIdRegistro;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_consultainfdotacionescaja.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pTipoSucursal = '' OR pRegistros IS NULL OR pRecuperacion IS NULL 
			OR pIdLote IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cSucursal, cCajaGen, dFecha, cStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, cIdStatus, cCodTrans, iIdRegistro;
		END IF;
		
		-- VALIDACON DE LOS DATOS DE PAGINACIÓN
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cSucursal, cCajaGen, dFecha, cStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, cIdStatus, cCodTrans, iIdRegistro;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:'informix'.sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
			IF cCodRet <> '00000' THEN
			RETURN cCodRet, cSucursal, cCajaGen, dFecha, cStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, cIdStatus, cCodTrans, iIdRegistro;
		END IF;
		
		--IF pTipoSucursal = 'S' THEN
		--	LET cIdStatus = '01';
		--ELIF pTipoSucursal = 'C' THEN
		--	LET cIdStatus = '12';
		--END IF;
		--
		--IF NVL(pFechaInic, '') = '' THEN
		--	LET pFechaInic = MDY(1,1,2007);
		--END IF
		--
		--IF NVL(pFechaFin, '') = '' THEN
		--	LET pFechaFin = DATE(CURRENT);
		--END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH 
			SELECT SKIP pRegistros FIRST pRecuperacion sucursal, caja_general, fecha, desc_status, folio_operacion, monto, usuario, id_usuario, id_status, cod_trans, id_registro
			INTO cSucursal, cCajaGen, dFecha, cStatus, cFolioOperacion, dMonto, cUsuario, cIdUsuario, cIdStatus, cCodTrans, iIdRegistro
			FROM bdicnweb:"informix".sw_cg_enviodotaciones
			WHERE id_usuario_soc = pUsuario
			AND id_lote = pIdLote
			ORDER BY id_registro ASC
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet, UPPER(cSucursal), UPPER(cCajaGen), dFecha, UPPER(cStatus), cFolioOperacion, dMonto, UPPER(cUsuario), cIdUsuario, cIdStatus, cCodTrans, iIdRegistro WITH RESUME;
		END FOREACH;
		
		IF iNoRegistros = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, '', '', '', '', '', '', '', '', '', '', 0; 
		ELIF iNoRegistros = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet, '', '', '', '', '', '', '', '', '', '', 0;
		END IF;
		
	END;
END PROCEDURE 
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA: 04/02/2015',
'DESCRIPCION: SPL que realiza la consulta para el llenado del grid Dotaciones, Envío de Dotaciones Caja General',
'FECHA: 25/05/2015',
'DESCRIPCION: Se modifico la evaluacion de fechas nulas.',
'AUTOR: L. Montserrat León Amador',
'FECHA: 30/03/2020',
'DESCRIPCION: Se modifica SPL para implementar tabla de paso que almacene el detalle de la consulta y agregar tratado de volumetría en segundo plano.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_enviardotacioncaja(pUsuario CHAR(8), pIdFuncion CHAR(10), pFolioOperacion CHAR(8), pStatus CHAR(2),
				pCantidadEnviada1 DECIMAL(10,2), pTotalEnviada1 MONEY(14,2), pCantidadEnviada2 DECIMAL(10,2), pTotalEnviada2 MONEY(14,2), 
				pCantidadEnviada3 DECIMAL(10,2), pTotalEnviada3 MONEY(14,2), pCantidadEnviada4 DECIMAL(10,2), pTotalEnviada4 MONEY(14,2), 
				pCantidadEnviada5 DECIMAL(10,2), pTotalEnviada5 MONEY(14,2), pCantidadEnviada6 DECIMAL(10,2), pTotalEnviada6 MONEY(14,2),
				pMontoMorrallaEnv MONEY(14,2), pTotalDotEnviada MONEY(14,2))
				
		RETURNING CHAR(5) AS codret;
			
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;	
	DEFINE fCant1 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenominacion1 CHAR(18); 
	DEFINE mTotal1 MONEY(14,2);
	DEFINE fCant2 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenominacion2 CHAR(18);
	DEFINE mTotal2 MONEY(14,2);
	DEFINE fCant3 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenominacion3 CHAR(18); 
	DEFINE mTotal3 MONEY(14,2);
	DEFINE fCant4 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenominacion4 CHAR(18);
	DEFINE mTotal4 MONEY(14,2);
	DEFINE fCant5 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenominacion5 CHAR(18); 
	DEFINE mTotal5 MONEY(14,2);
	DEFINE fCant6 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenominacion6 CHAR(18); 
	DEFINE mTotal6 MONEY(14,2);
	DEFINE cDenMorralla CHAR(2);	      
	DEFINE mTotalMorralla MONEY(14,2); 
	DEFINE mTotalDotSolicitada MONEY(14,2);
	DEFINE fCantEnv_1 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_1 CHAR(18);
	DEFINE fCantEnv_2 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_2 CHAR(18);
	DEFINE fCantEnv_3 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_3 CHAR(18);
	DEFINE fCantEnv_4 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_4 CHAR(18);
	DEFINE fCantEnv_5 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_5 CHAR(18);
	DEFINE fCantEnv_6 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_6 CHAR(18);
	DEFINE fCantEnv_7 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_7 CHAR(18);
	DEFINE fCantEnv_8 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_8 CHAR(18);
	DEFINE fCantEnv_9 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_9 CHAR(18);
	DEFINE fCantEnv_10 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_10 CHAR(18);
	DEFINE fCantEnv_11 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_11 CHAR(18);
	DEFINE fCantEnv_12 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_12 CHAR(18);
	DEFINE fCantEnv_13 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_13 CHAR(18);
	DEFINE fCantEnv_14 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_14 CHAR(18);
	DEFINE fCantEnv_15 FLOAT(8); --DECIMAL(10,2); 
	DEFINE cDenEnv_15 CHAR(18);
	DEFINE mTotalMorrallaEnv MONEY(14,2);
	DEFINE cDenMorrallaEnv CHAR(8);
	DEFINE mSaldoDisponible MONEY(14,2);
	DEFINE cCodTrans CHAR(4);
	DEFINE cReversado CHAR(1);
	DEFINE cUsuario CHAR(8);
	DEFINE cCodProvedor CHAR(4);
	DEFINE cStatus CHAR(2);
	DEFINE dFechReversion DATE;
	DEFINE dHoReversion CHAR(5);
	DEFINE cUsReversion CHAR(8);
	DEFINE iRegistrosAfectados INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET fCant1 = 0; 
	LET cDenominacion1 = ''; 
	LET mTotal1 = NULL;
	LET fCant2 = 0; 
	LET cDenominacion2 = ''; 
	LET mTotal2 = NULL;
	LET fCant3 = 0; 
	LET cDenominacion3 = '';
	LET mTotal3 = NULL;
	LET fCant4 = 0; 
	LET cDenominacion4 = '';
	LET mTotal4 = NULL;
	LET fCant5 = 0; 
	LET cDenominacion5 = '';
	LET mTotal5 = NULL;
	LET fCant6 = 0; 
	LET cDenominacion6 = ''; 
	LET mTotal6 = NULL; 
	LET cDenMorralla = '1';  			
	LET mTotalMorralla = NULL;  
	LET mTotalDotSolicitada = NULL;
	LET fCantEnv_1 = 0; 
	LET cDenEnv_1 = '';
	LET fCantEnv_2 = 0; 
	LET cDenEnv_2 = '';
	LET fCantEnv_3 = 0; 
	LET cDenEnv_3 = '';
	LET fCantEnv_4 = 0; 
	LET cDenEnv_4 = '';
	LET fCantEnv_5 = 0; 
	LET cDenEnv_5 = '';
	LET fCantEnv_6 = 0; 
	LET cDenEnv_6 = '';
	LET fCantEnv_7 = 0; 
	LET cDenEnv_7 = '';
	LET fCantEnv_8 = 0; 
	LET cDenEnv_8 = '';
	LET fCantEnv_9 = 0; 
	LET cDenEnv_9 = '';
	LET fCantEnv_10 = 0; 
	LET cDenEnv_10 = '';
	LET fCantEnv_11 = 0; 
	LET cDenEnv_11 = '';
	LET fCantEnv_12 = 0; 
	LET cDenEnv_12 = '';
	LET fCantEnv_13 = 0; 
	LET cDenEnv_13 = '';
	LET fCantEnv_14 = 0; 
	LET cDenEnv_14 = '';
	LET fCantEnv_15 = 0; 
	LET cDenEnv_15 = '';
	LET mTotalMorrallaEnv = NULL;
	LET cDenMorrallaEnv = 'MORRALLA';
	LET mSaldoDisponible = NULL;
	LET cCodTrans = '';
	LET cReversado = '';
	LET cUsuario = '';
	LET cCodProvedor = '';
	LET cStatus = '';
	LET dFechReversion = '';
	LET dHoReversion = '';
	LET cUsReversion = '';
	LET iRegistrosAfectados = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr; 
			RETURN cCodRet;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_enviardotacioncaja.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFolioOperacion = '' OR pStatus = '' OR pStatus IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet; 
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet; 
		END IF;
		
		SET LOCK MODE TO WAIT 3;
		SET ISOLATION TO DIRTY READ;
		
		-- Dotación Solicitada 	
		SELECT {+INDEX (bdisuc:ss_operaciones idx02ss_operaciones)} cod_trans, reversado, usuario, monto,
			NVL(cantidad_1,0), NVL(denominacion_1,''), NVL((cantidad_1 * NVL(NVL((denominacion_1::DECIMAL(16,2)),0),0)),0) AS total_1,
		    NVL(cantidad_2,0), NVL(denominacion_2,''), NVL((cantidad_2 * NVL(NVL((denominacion_2::DECIMAL(16,2)),0),0)),0) AS total_2,
		    NVL(cantidad_3,0), NVL(denominacion_3,''), NVL((cantidad_3 * NVL(NVL((denominacion_3::DECIMAL(16,2)),0),0)),0) AS total_3,
		    NVL(cantidad_4,0), NVL(denominacion_4,''), NVL((cantidad_4 * NVL(NVL((denominacion_4::DECIMAL(16,2)),0),0)),0) AS total_4,
		    NVL(cantidad_5,0), NVL(denominacion_5,''), NVL((cantidad_5 * NVL(NVL((denominacion_5::DECIMAL(16,2)),0),0)),0) AS total_5,
		    NVL(cantidad_6,0), NVL(denominacion_6,''), NVL((cantidad_6 * NVL(NVL((denominacion_6::DECIMAL(16,2)),0),0)),0) AS total_6,	
			
			(NVL((cantidad_7 * NVL(NVL((denominacion_7::DECIMAL(16,2)),0),0)),0) + NVL((cantidad_8 * NVL(NVL((denominacion_8::DECIMAL(16,2)),0),0)),0) + NVL((cantidad_9 * NVL(NVL((denominacion_9::DECIMAL(16,2)),0),0)),0) +
			 NVL((cantidad_10 * NVL(NVL((denominacion_10::DECIMAL(16,2)),0),0)),0) + NVL((cantidad_11 * NVL(NVL((denominacion_11::DECIMAL(16,2)),0),0)),0) + NVL((cantidad_12 * NVL(NVL((denominacion_12::DECIMAL(16,2)),0),0)),0) +
			 NVL((cantidad_13 * NVL(NVL((denominacion_13::DECIMAL(16,2)),0),0)),0) + NVL((cantidad_14 * NVL(NVL((denominacion_14::DECIMAL(16,2)),0),0)),0) + NVL((cantidad_15 * NVL(NVL((denominacion_15::DECIMAL(16,2)),0),0)),0)
			 ) AS suma_totalMorralla
		
		INTO cCodTrans, cReversado, cUsuario, mTotalDotSolicitada,
			fCant1, cDenominacion1, mTotal1,
			fCant2, cDenominacion2, mTotal2,
			fCant3, cDenominacion3, mTotal3,
			fCant4, cDenominacion4, mTotal4,
			fCant5, cDenominacion5, mTotal5,
			fCant6, cDenominacion6, mTotal6,  
			mTotalMorralla

		FROM bdisuc:"informix".ss_operaciones WHERE folio_oper = pFolioOperacion;	
		
		--SET LOCK MODE TO WAIT 3;
		--SET ISOLATION TO DIRTY READ;
		
		-- Obtiene Codigo Proveedor
		SELECT {+INDEX (bdisuc:ss_mae_entradasalida idx01ss_mae_entradasalida)} cod_proveedor, status, fecha_reversion, hora_reversion, usuario_reversion
		INTO cCodProvedor, cStatus, dFechReversion, dHoReversion, cUsReversion
		FROM bdisuc:"informix".ss_mae_entradasalida WHERE folio_oper = pFolioOperacion;
		
		SET LOCK MODE TO WAIT 3;
		
		-- Dotación Enviada
		SELECT {+INDEX (bdisuc:ss_cajageneral idx_ss_cajageneral)} saldo_total,
			NVL(cantidad_1,0), NVL(denominacion_1,''), 
			NVL(cantidad_2,0), NVL(denominacion_2,''), 
			NVL(cantidad_3,0), NVL(denominacion_3,''), 
			NVL(cantidad_4,0), NVL(denominacion_4,''), 
			NVL(cantidad_5,0), NVL(denominacion_5,''), 
			NVL(cantidad_6,0), NVL(denominacion_6,''), 			
			NVL(cantidad_7,0), NVL(denominacion_7,''), 
			NVL(cantidad_8,0), NVL(denominacion_8,''), 
			NVL(cantidad_9,0), NVL(denominacion_9,''), 
			NVL(cantidad_10,0), NVL(denominacion_10,''),
			NVL(cantidad_11,0), NVL(denominacion_11,''),
			NVL(cantidad_12,0), NVL(denominacion_12,''),
			NVL(cantidad_13,0), NVL(denominacion_13,''),
			NVL(cantidad_14,0), NVL(denominacion_14,''),
			NVL(cantidad_15,0), NVL(denominacion_15,'')
		
		INTO mSaldoDisponible,
			fCantEnv_1, cDenEnv_1, 
			fCantEnv_2, cDenEnv_2, 
			fCantEnv_3, cDenEnv_3, 
			fCantEnv_4, cDenEnv_4, 
			fCantEnv_5, cDenEnv_5, 
			fCantEnv_6, cDenEnv_6,
			fCantEnv_7, cDenEnv_7,
			fCantEnv_8, cDenEnv_8,
			fCantEnv_9, cDenEnv_9,
			fCantEnv_10, cDenEnv_10,
			fCantEnv_11, cDenEnv_11,
			fCantEnv_12, cDenEnv_12,
			fCantEnv_13, cDenEnv_13,
			fCantEnv_14, cDenEnv_14,
			fCantEnv_15, cDenEnv_15
			
		FROM bdisuc:"informix".ss_cajageneral WHERE cod_proveedor = cCodProvedor;
	
		-- Valida Dotación Solicitada
		IF mTotalDotSolicitada > mSaldoDisponible THEN
			LET cCodRet = '90000'; -- La Dotación solicitada <folio operación> es mayor al saldo disponible en caja. Por favor verifique.
			RETURN cCodRet;
		END IF;
		
		
		IF (pTotalDotEnviada = mTotalDotSolicitada) AND ((mTotalDotSolicitada < mSaldoDisponible) OR (mTotalDotSolicitada = mSaldoDisponible)) THEN
		
			-- Valida 'Status'
			IF pStatus = '01' OR pStatus = '12' THEN
				-- Actualiza Foliio Operación
				UPDATE {+INDEX (bdisuc:ss_mae_entradasalida idx01ss_mae_entradasalida)} bdisuc:"informix".ss_mae_entradasalida SET status = '03', hora_envio = to_char(CURRENT, '%H:%m'), fecha_envio = date(CURRENT), usuario_envio = pUsuario 
				WHERE folio_oper = pFolioOperacion; 
			
				IF cDenEnv_1 = '-1' OR cDenEnv_1 = 'M' THEN
					LET fCantEnv_1 = fCantEnv_1 - NVL(pTotalEnviada1,0);
				ELSE 	
					LET fCantEnv_1 = fCantEnv_1 - NVL(pCantidadEnviada1,0);
				END IF;	
				IF cDenEnv_2 = '-1' OR cDenEnv_2 = 'M' THEN
					LET fCantEnv_2 = fCantEnv_2 - NVL(pTotalEnviada2,0);
				ELSE 	
					LET fCantEnv_2 = fCantEnv_2 - NVL(pCantidadEnviada2,0);
				END IF;
				IF cDenEnv_3 = '-1' OR cDenEnv_3 = 'M' THEN
					LET fCantEnv_3 = fCantEnv_3 - NVL(pTotalEnviada3,0);
				ELSE 	
					LET fCantEnv_3 = fCantEnv_3 - NVL(pCantidadEnviada3,0);
				END IF;
				IF cDenEnv_4 = '-1' OR cDenEnv_4 = 'M' THEN
					LET fCantEnv_4 = fCantEnv_4 - NVL(pTotalEnviada4,0);
				ELSE 	
					LET fCantEnv_4 = fCantEnv_4 - NVL(pCantidadEnviada4,0);
				END IF;
				IF cDenEnv_5 = '-1' OR cDenEnv_5 = 'M' THEN
					LET fCantEnv_5 = fCantEnv_5 - NVL(pTotalEnviada5,0);
				ELSE 	
					LET fCantEnv_5 = fCantEnv_5 - NVL(pCantidadEnviada5,0);
				END IF;
				IF cDenEnv_6 = '-1' OR cDenEnv_6 = 'M' THEN
					LET fCantEnv_6 = fCantEnv_6 - NVL(pTotalEnviada6,0);
				ELSE 	
					LET fCantEnv_6 = fCantEnv_6 - NVL(pCantidadEnviada6,0);
				END IF;							
				IF cDenEnv_7 = '-1' OR cDenEnv_7 = 'M' THEN
					LET fCantEnv_7 = fCantEnv_7 - NVL(pMontoMorrallaEnv,0);
				END IF;
				--
				IF cDenEnv_8 = '-1' OR cDenEnv_8 = 'M' THEN
					LET fCantEnv_8 = fCantEnv_8 - NVL(pMontoMorrallaEnv,0);
				END IF;
				IF cDenEnv_9 = '-1' OR cDenEnv_9 = 'M' THEN
					LET fCantEnv_9 = fCantEnv_9 - NVL(pMontoMorrallaEnv,0);
				END IF;
				IF cDenEnv_10 = '-1' OR cDenEnv_10 = 'M' THEN
					LET fCantEnv_10 = fCantEnv_10 - NVL(pMontoMorrallaEnv,0);
				END IF;
				IF cDenEnv_11 = '-1' OR cDenEnv_11 = 'M' THEN
					LET fCantEnv_11 = fCantEnv_11 - NVL(pMontoMorrallaEnv,0);
				END IF;	
				IF cDenEnv_12 = '-1' OR cDenEnv_12 = 'M' THEN
					LET fCantEnv_12 = fCantEnv_12 - NVL(pMontoMorrallaEnv,0);
				END IF;
				IF cDenEnv_13 = '-1' OR cDenEnv_13 = 'M' THEN
					LET fCantEnv_13 = fCantEnv_13 - NVL(pMontoMorrallaEnv,0);
				END IF;
				IF cDenEnv_14 = '-1' OR cDenEnv_14 = 'M' THEN
					LET fCantEnv_14 = fCantEnv_14 - NVL(pMontoMorrallaEnv,0);
				END IF;
				IF cDenEnv_15 = '-1' OR cDenEnv_15 = 'M' THEN
					LET fCantEnv_15 = fCantEnv_15 - NVL(pMontoMorrallaEnv,0);
				END IF;		

				-- Actualiza tabla
				UPDATE {+INDEX (bdisuc:ss_cajageneral idx_ss_cajageneral)} bdisuc:"informix".ss_cajageneral SET cantidad_1 = fCantEnv_1, cantidad_2 = fCantEnv_2, cantidad_3 = fCantEnv_3, cantidad_4 = fCantEnv_4, cantidad_5 = fCantEnv_5,
					cantidad_6 = fCantEnv_6, cantidad_7 = fCantEnv_7, cantidad_8 = fCantEnv_8, cantidad_9 = fCantEnv_9, cantidad_10 = fCantEnv_10,
					cantidad_11 = fCantEnv_11, cantidad_12 = fCantEnv_12, cantidad_13 = fCantEnv_13, cantidad_14 = fCantEnv_14, cantidad_15 = fCantEnv_15,
					saldo_total = saldo_total - pTotalDotEnviada, saldo_asignado = saldo_asignado + pTotalDotEnviada
				WHERE cod_proveedor = cCodProvedor;
				
				LET iRegistrosAfectados = DBINFO('sqlca.sqlerrd2');
			
			ELSE
				LET cCodRet = '00428'; -- La operación no cuenta con el estatus requerido  de solicitud dotación sucursal
				RETURN cCodRet;
				
			END IF;
			
		END IF;
		
		-- ERROR AL ACTUALIZAR EL REGISTRO
		IF iRegistrosAfectados = 0 THEN
			LET cCodRet = '00283'; 
		END IF;

		RETURN cCodRet;
		
	END;
	
END PROCEDURE
