CREATE PROCEDURE "informix".sp_sc_ctasproductomesiversario(pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaConsulta DATE, pProducto CHAR(4), pCtasConsulta INTEGER)
    RETURNING CHAR(5) AS codRet,
		DATE AS fechaFin,
		CHAR(4) AS producto,
		CHAR(20) AS cuenta,
		MONEY(18,2) AS acumSdoPos,
		SMALLINT AS diasSdoPos,
		MONEY(18,2) AS sdoProm,
		MONEY(18,2) AS tasaBruta,
		MONEY(18,2) AS totIntPag,
		MONEY(18,2) AS totIsrCobrado,
		INTEGER AS iTotal;
	
	DEFINE cCodRet 			CHAR(5);
	DEFINE iSqlErr 			INT;
	DEFINE cCodRetSp 		CHAR(5);
	DEFINE cDescCodRet 		CHAR(80);
	DEFINE cEmpresa 		CHAR(3);
	DEFINE iRecuperacion 	INTEGER;
	DEFINE dFechaFin		DATE;
	DEFINE cProducto		CHAR(4);
	DEFINE cCuenta			CHAR(20);
	DEFINE mAcumSdoPos		MONEY(18,2);
	DEFINE sDiasSdoPos		SMALLINT;
	DEFINE mSdoProm			MONEY(18,2);
	DEFINE dTasaBruta		MONEY(18,2);
	DEFINE mTotIntPag		MONEY(18,2);
	DEFINE mTotIsrCobrado	MONEY(18,2);
	DEFINE iTotal		 	INTEGER;
	DEFINE iTotalCta 		INTEGER;
	DEFINE cCuentaAux		CHAR(20);

	LET cCodRet 		    = '00000';
	LET iSqlErr 		    = 0;
	LET cCodRetSp 		    = '';
	LET cDescCodRet 	    = '';
	LET cEmpresa 		    = '001';
	LET iRecuperacion 	    = 0;
	LET dFechaFin		    = '';
	LET cProducto		    = '';
	LET cCuenta			    = '';
	LET mAcumSdoPos		    = 0;
	LET sDiasSdoPos		    = 0;
	LET mSdoProm		    = 0;	
	LET dTasaBruta		    = 0;
	LET mTotIntPag		    = 0;
	LET mTotIsrCobrado	    = 0;
	LET iTotal			    =0;
	LET iTotalCta 		    =0;
	LET cCuentaAux		    = '';

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet, dFechaFin, cProducto, cCuenta, mAcumSdoPos, sDiasSdoPos,
         		mSdoProm, dTasaBruta,mTotIntPag, mTotIsrCobrado, iTotal;  
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_sc_ctasproductomesiversario.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pFechaConsulta IS NULL OR pProducto = '' OR pCtasConsulta IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, dFechaFin, cProducto, cCuenta, mAcumSdoPos, sDiasSdoPos,
         	mSdoProm, dTasaBruta,mTotIntPag, mTotIsrCobrado, iTotal;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, dFechaFin, cProducto, cCuenta, mAcumSdoPos, sDiasSdoPos,
         	mSdoProm, dTasaBruta,mTotIntPag, mTotIsrCobrado, iTotal;
		END IF;	
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- Obtener el numero de cuentas distitntas
		SELECT COUNT(DISTINCT cuenta) AS Total
		INTO iTotalCta
		FROM bdicheq:"informix".sc_ctas_mesiversario
		WHERE producto = pProducto
		AND fecha_mov = pFechaConsulta;
		
		FOREACH	
			SELECT FIRST pCtasConsulta
			fecha_mov, producto, cuenta, sdo_acum, dias_periodo, sdo_prom, tasa_interes, monto_interes, isr_cobrado
			INTO dFechaFin, cProducto, cCuenta, mAcumSdoPos, sDiasSdoPos, mSdoProm, dTasaBruta,mTotIntPag, mTotIsrCobrado
			FROM bdicheq:"informix".sc_ctas_mesiversario
			WHERE producto = pProducto
			AND fecha_mov = pFechaConsulta		
			ORDER BY sdo_actual DESC
				
			RETURN cCodRet, dFechaFin, cProducto, cCuenta, mAcumSdoPos, sDiasSdoPos,
			mSdoProm, dTasaBruta,mTotIntPag, mTotIsrCobrado, iTotalCta WITH RESUME;				
			
			LET iRecuperacion = iRecuperacion + 1;
			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, dFechaFin, cProducto, cCuenta, mAcumSdoPos, sDiasSdoPos,
            mSdoProm, dTasaBruta,mTotIntPag, mTotIsrCobrado, iTotalCta;
		END IF;
	
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Rodolfo Conde Flores',
'FECHA: 06/09/2019',
'MODULO: OPERACIONES',
'FUNCIONALIDAD: Muestreo de Estados de Cuenta por Mesiversario', 
'DESCRIPCION: Spl encargado de consultar registros de cuentas mesiversario.',
