CREATE PROCEDURE "informix".sp_cg_consbitusuario(pUsuario CHAR(8), pIdFuncion CHAR(10), pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
			CHAR(8) AS usuario,
			CHAR(45) AS nombre_usuario;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cUsuario CHAR(8);
	DEFINE cNombreUsuario CHAR(45);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cUsuario = '';
	LET cNombreUsuario = '';
	LET iRecuperacion = 0;	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cUsuario,cNombreUsuario;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_cg_consbitusuario.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cUsuario,cNombreUsuario;
		END IF;
		
		-- VALIDACIÓN DE LOS DATOS DE PAGINACION
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet,cUsuario,cNombreUsuario;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cUsuario,cNombreUsuario;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT {+INDEX (bdisuc:ss_bitacora_reversoscg idx_ss_bitacora_reversoscg)} SKIP pRegistros FIRST pRecuperacion 
			DISTINCT(a.usuario),b.nombre 
			INTO cUsuario,cNombreUsuario
			FROM bdisuc:"informix".ss_bitacora_reversoscg AS a, bdinteg:"informix".si_ejecut AS b
			WHERE a.usuario = b.ejecutivo
			ORDER BY b.nombre ASC
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet,cUsuario,cNombreUsuario WITH RESUME;
		END FOREACH;
		
		IF pRegistros = 0 AND iRecuperacion = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cUsuario,cNombreUsuario;
		ELIF pRegistros > 0 AND iRecuperacion = 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet,cUsuario,cNombreUsuario;
		END IF;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 29/04/2020',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: REVERSO DE OPERACIONES CAJA GENERAL',
'DESCRIPCION: SPL encargado de consultar el detalle del catálogo Usuario.',
