CREATE PROCEDURE "informix".sp_cg_consbitoperacion(pUsuario CHAR(8), pIdFuncion CHAR(10))
		RETURNING CHAR(5) AS codret,
			CHAR(20) AS desc_operacion;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cDesc_operacion CHAR(20);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cDesc_operacion = '';
	LET iRecuperacion = 0;	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cDesc_operacion;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_cg_consbitoperacion.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cDesc_operacion;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cDesc_operacion;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT {+INDEX (bdicnweb:sw_cg_operacion idx_sw_cg_operacion)} desc_operacion
			INTO cDesc_operacion
			FROM bdicnweb:"informix".sw_cg_operacion
			ORDER BY desc_operacion ASC
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet,cDesc_operacion WITH RESUME;
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cDesc_operacion;
		END IF;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 29/04/2020',
'MODULO: CAJA GENERAL',
'FUNCIONALIDAD: REVERSO DE OPERACIONES CAJA GENERAL',
'DESCRIPCION: SPL encargado de consultar el detalle del catálogo Operación.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_monitorconsultatotsolicitudxmc_error_mc(pUsuario CHAR(8), pIdFuncion CHAR(10), pNumSolicitud CHAR(20), pEjecutivoAtiende CHAR(8), pStatus CHAR(2), pCausa CHAR(3), pObservaciones CHAR(100), pTipo SMALLINT)
	RETURNING CHAR(5) AS codret,
		INTEGER AS total_regs;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE iRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE cNumSolicitud CHAR(20);
	DEFINE cNumCliente CHAR(20);
	DEFINE cNombreCliente CHAR(100);
	DEFINE cRfc CHAR(13);
	DEFINE cSucursal CHAR(4);
	DEFINE dFechaInsert DATE;
	DEFINE dFechaModificacion DATE;
	DEFINE mMontoSolicitado DECIMAL(18,2);
	DEFINE mEficiencia DECIMAL(18,2);
	DEFINE iHistorial SMALLINT;
	DEFINE cStatusInicial CHAR(2);
	DEFINE mSeccion1 DECIMAL(18,2);
	DEFINE mSeccion2 DECIMAL(18,2);
	DEFINE cCausaSolic CHAR(3);
	DEFINE cObservaciones CHAR(300);
	DEFINE cNumProducto CHAR(4);
	DEFINE cStatusFin CHAR(2);
	DEFINE cEjecutivoAtiende CHAR(8);
	DEFINE cEjcutivoAutoriza CHAR(8);
	DEFINE dHoraInsert DATETIME HOUR TO SECOND;
	DEFINE dFechaDeterminacion DATE;
	DEFINE cRevisado CHAR(1);
	DEFINE cEmpresa CHAR(3);
	DEFINE iTotalRegs INTEGER;
	DEFINE iNoRegs INTEGER;

	-- InicializaciÃ³n de variables
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET iNoRegistros = 0;
	LET iRegistros = 0;
	LET iRecuperacion = 0;
	LET cCodRetSp = '';
	LET cNumSolicitud = '';
	LET cNumCliente = '';
	LET cNombreCliente = '';
	LET cRfc = '';
	LET cSucursal = '';
	LET dFechaInsert = NULL;
	LET dFechaModificacion = NULL;
	LET mMontoSolicitado = NULL;
	LET mEficiencia = NULL;
	LET iHistorial = 0;
	LET cStatusInicial = '';
	LET mSeccion1 = NULL;
	LET mSeccion2 = NULL;
	LET cCausaSolic = '';
	LET cObservaciones = '';
	LET cNumProducto = '';
	LET cStatusFin = '';
	LET cEjecutivoAtiende = '';
	LET cEjcutivoAutoriza = '';
	LET dHoraInsert = NULL;
	LET dFechaDeterminacion = NULL;
	LET cRevisado = '';
	LET cEmpresa = '001';
	LET iTotalRegs = 0;
	LET iNoRegs = 0;
	
	BEGIN
		
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, iTotalRegs;
		END EXCEPTION;
		
		ON EXCEPTION IN (-239)
			LET cCodRet = '00017';
		END EXCEPTION WITH RESUME;
		
		SET DEBUG FILE TO '/tmp/mfinis/sp_monitorconsultatotsolicitudxmc.out';
		TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pStatus = '' OR pTipo IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, iTotalRegs;
		END IF;
		
		-- ValidaciÃ³n del tipo de busqueda
		IF pTipo NOT IN (1,2,3) THEN
			LET cCodRet = '00108';
			RETURN cCodRet, iTotalRegs;
		END IF;
		
		IF pTipo = 3 THEN
			IF pEjecutivoAtiende = '' OR pNumSolicitud = '' THEN
				LET cCodRet = '00003';
				RETURN cCodRet, iTotalRegs;
			ENd IF;
			
			IF pStatus IN ('CM', 'RT') AND pCausa = '' THEN
				LET cCodRet = '00003';
				RETURN cCodRet, iTotalRegs;
			END IF;
		END IF;
		
		-- ValidacciÃ³n de acceso a la funcionalidad
		EXECUTE FUNCTION bdinteg:sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) into cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, iTotalRegs;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		
		-- Conteo del numero de registros
		FOREACH EXECUTE PROCEDURE bdisolic:'informix'.sp_consultaactualizasolicmc(cEmpresa, pNumSolicitud, pEjecutivoAtiende, pStatus, pCausa, pObservaciones, pTipo)
			INTO cCodRetSp, cNumSolicitud, cNumCliente, cNombreCliente, cRfc, cSucursal, dFechaInsert, dFechaModificacion, mMontoSolicitado, 
				mEficiencia, iHistorial, cStatusInicial, mSeccion1, mSeccion2, cCausaSolic, cObservaciones, cNumProducto, cStatusFin,
				cEjecutivoAtiende, cEjcutivoAutoriza, dHoraInsert, dFechaDeterminacion, cRevisado
				
				IF cCodRetSp::INTEGER < 0 THEN
					RAISE EXCEPTION cCodRetSp::INTEGER, 0 , 'ERROR EN LA EJECUCION DEL SP PRODUCTIVO bdisolic:sp_consultaactualizasolicmc';
				ELIF cCodRetSp::INTEGER = 0 THEN
					LET iTotalRegs = iTotalRegs + 1;
				ELIF cCodRetSp = '00001' THEN -- Parametros incorrectos
					LET cCodRet = '00003';
					RETURN cCodRet, iTotalRegs;
				ELIF cCodRetSp = '00002' THEN -- OCURRIO UN ERROR AL REALIZAR LA ACTUALIZACION DE LA SOLICITUD
					LET cCodRet = '00219';
					RETURN cCodRet, iTotalRegs;
				ELIF cCodRetSp IN ('00003', '00004', '00005') THEN -- NO SE ENCUENTRAN SOLICITUDES MC PARA SER ATENDIDAS
					LET cCodRet = '00220';
					RETURN cCodRet, iTotalRegs;
				END IF;
				
		END FOREACH;
		
		IF iTotalRegs = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet, iTotalRegs;
		END IF;
		
		RETURN cCodRet, iTotalRegs;

	END;
END PROCEDURE
DOCUMENT "AUTOR: Johnattan Esquivel Sanchez",
"FECHA: 12/03/2020",
"MODIFICACION: Se se modifica procedimiento por control de excepcion",
"BD    : bdicnweb";

CREATE PROCEDURE "informix".sp_seg_consfunusapass(pUsuario CHAR(8), pIdFuncion CHAR(10))
		RETURNING CHAR(5) AS codret,
			CHAR(10) AS id_funcion,
			CHAR(100) AS desc_funcion;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cIdFuncion CHAR(10);
	DEFINE cDescFuncion CHAR(100);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cIdFuncion = '';
	LET cDescFuncion = '';
	LET iNoRegistros = 0;	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cIdFuncion,cDescFuncion;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_seg_consfunusapass.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cIdFuncion,cDescFuncion;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cIdFuncion,cDescFuncion;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT {+INDEX (bdinteg"informix".si_seg_funciones idx_pass)} 
			id_funcion,d_funcion INTO cIdFuncion,cDescFuncion
			FROM bdinteg:"informix".si_seg_funciones 
			WHERE usa_pass = '1'
			ORdER BY id_funcion,d_funcion ASC
			
			LET iNoRegistros = iNoRegistros + 1;
			RETURN cCodRet,cIdFuncion,cDescFuncion WITH RESUME;
		END FOREACH;
		
		IF iNoRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cIdFuncion,cDescFuncion;
		END IF;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 27/04/2020',
