'FUNCIONALIDAD: ENCRIPTACIÓN DE CONTRASEÑAS',
'DESCRIPCION: SPL encargado de consultar el nombre de las funcionalidades que hacen uso de contraseñas.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_dic_modactualizastatusalerta(pUsuario CHAR(8),pIdFuncion CHAR(10),pNumcte CHAR(20),pSucursal CHAR(4),pStatus CHAR(1),pFechaInsert DATE)
	RETURNING CHAR(5) AS codret;
	
