CREATE PROCEDURE "informix".sp_seg_consswsegvalidausuarios(pUsuario CHAR(8), pIdFuncion CHAR(10), pNumUsuario CHAR(10))
		RETURNING CHAR(5) AS codret,
			CHAR(10) AS id_usuario,
			CHAR(50) AS password,
			CHAR(1) AS pass_encrip;
			
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE cId_usuario CHAR(10);
	DEFINE cPassword CHAR(50);
	DEFINE cPass_encrip CHAR(1);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cId_usuario = '';
	LET cPassword = '';
	LET cPass_encrip = '';
	LET iNoRegistros = 0;	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cId_usuario,cPassword,cPass_encrip;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_seg_consswsegvalidausuarios.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pNumUsuario = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cId_usuario,cPassword,cPass_encrip;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cId_usuario,cPassword,cPass_encrip;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT FIRST 1 id_usuario,password_usuario,pass_encrip 
		INTO cId_usuario,cPassword,cPass_encrip
		FROM bdicnweb:"informix".sw_seg_valida_usuarios
		WHERE id_usuario = pNumUsuario;
		
		IF cId_usuario = '' THEN
			LET cCodRet = '00017';
		END IF;
		
		RETURN cCodRet,cId_usuario,cPassword,cPass_encrip;
		
	END;
	
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 27/04/2020',
'MODULO: SEGURIDAD',
'FUNCIONALIDAD: ENCRIPTACIÓN DE CONTRASEÑAS',
'DESCRIPCION: SPL encargado de consultar si el usuario existe en tabla sw_seg_valida_usuarios.',
