CREATE PROCEDURE "informix".sp_seg_validacoordinador(pUsuario CHAR(8), pIdFuncion CHAR(10), pIdEjecucion CHAR(1), pIdCoordinador CHAR(10), pPassword CHAR(50))
    RETURNING CHAR(5) AS codRet;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cDescCodRet CHAR(80);
	DEFINE cEmpresa CHAR(3);
	DEFINE cIdCoordinador CHAR(10);
	DEFINE cNombreCoordinador CHAR(45);
	DEFINE iExiste INTEGER;

	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cDescCodRet = '';
	LET cEmpresa = '001';
	LET cIdCoordinador = '';
	LET cNombreCoordinador = '';
	LET iExiste = 0;

	BEGIN
		ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet;
			END IF;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_seg_validacoordinador.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pIdEjecucion = '' OR pIdCoordinador = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pIdEjecucion = '1' THEN
		
			IF (SELECT COUNT(id_usuario) FROM bdicnweb:"informix".sw_seg_valida_usuarios WHERE id_usuario = pIdCoordinador) = 0 THEN 
				LET cCodRet = '00002'; --EL REGISTRO QUE DESEA CONSULTAR NO EXISTE
			END IF;
			
			IF (SELECT COUNT(id_usuario) FROM bdicnweb:"informix".sw_seg_valida_usuarios WHERE id_usuario = pIdCoordinador AND pass_encrip = '0') = 1 THEN 
				LET cCodRet = '01148'; --PARA AUTENTICARSE POR CONTRASEÑA, ES NECESARIO SOLICITE AL ÁREA DE SEGURIDAD SU ENCRIPTACIÓN
				RETURN cCodRet;
			END IF;
			
		ELIF pIdEjecucion = '2' THEN
		
			IF pPassword = '' THEN
				LET cCodRet = '00003';
				RETURN cCodRet;
			END IF;
		
			IF (SELECT COUNT(id_usuario) FROM bdicnweb:"informix".sw_seg_valida_usuarios WHERE id_usuario = pIdCoordinador) = 0 THEN 
				LET cCodRet = '00002'; --EL REGISTRO QUE DESEA CONSULTAR NO EXISTE
				RETURN cCodRet;
			END IF;
			
			IF (SELECT COUNT(id_usuario) FROM bdicnweb:"informix".sw_seg_valida_usuarios WHERE id_usuario = pIdCoordinador AND pass_encrip = '0') = 1 THEN 
				LET cCodRet = '01148'; --PARA AUTENTICARSE POR CONTRASEÑA, ES NECESARIO SOLICITE AL ÁREA DE SEGURIDAD SU ENCRIPTACIÓN
				RETURN cCodRet;
			END IF;
			
			IF (SELECT COUNT(id_usuario) FROM bdicnweb:"informix".sw_seg_valida_usuarios WHERE id_usuario = pIdCoordinador) = 1 THEN 	
				SELECT NVL(COUNT(id_usuario),0) INTO iExiste 
				FROM bdicnweb:"informix".sw_seg_valida_usuarios WHERE id_usuario = pIdCoordinador AND password_usuario = pPassword;
				IF iExiste = 0 OR iExiste IS NULL THEN
					LET cCodRet = '00920'; --EL PASSWORD INGRESADO ES INCORRECTO. VERIFIQUE.
				END IF;	
			END IF;
			
		END IF;
		
		RETURN cCodRet;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat León Amador',
'FECHA 02/01/2017',
'MODULO: ',
'FUNCIONALIDAD: ',
'DESCRIPCION: Spl encargado de hacer la validación para consultar que el coordinador esté dado de alta y que el password corresponda al Coordinador de CC consultado.',
'AUTOR: L. Montserrat Leon Amador',
'FECHA: 06/05/2020',
'DESCRIPCION: SPL clon del procedimiento sp_sw_validacoordinador para la implementación en la funcionalidad Encriptación de Contraseñas.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_consultareportepagoscre (pUsuario CHAR(8), pIdFuncion CHAR(10), pFechaIni CHAR(10), pFechaFin CHAR(10), pStatus CHAR(1), pFolio CHAR(16), 
								pAplicacion SMALLINT, pConsulta SMALLINT, pProducto CHAR (4), pRegistros INTEGER, pRecuperacion INTEGER)
		RETURNING CHAR(5) AS codret,
				CHAR(3)     As reg,
				CHAR(1)     As Secuencia,
				CHAR(30)    As DescrSecuencia,
				CHAR(20)    AS numCredito,
				CHAR(104)   AS nomcte,
				MONEY(18,2) AS importe,
				MONEY(18,2) AS capVigente,
				MONEY(18,2) AS capTransitorio,
				MONEY(18,2) AS capVencido,
				MONEY(18,2) AS capVdoNoexigible,
				MONEY(18,2) AS CapitalTotal,
				MONEY(18,2) AS intiVgente,
				MONEY(18,2) AS ivaIntvigente,
				MONEY(18,2) AS interesVencido,
				MONEY(18,2) AS ivaInteresvencido,
				MONEY(18,2) AS interesMoraBase,
				MONEY(18,2) AS interesMoraCopete,
				MONEY(18,2) AS ivaIntmoratorio,
				DATE        AS fechaMovimiento,
				CHAR(2)     AS codigoPago,
				CHAR(50)    AS descripCod_pago,
				CHAR(16)    AS folioGrupo,
				CHAR(16)    AS folio,
				CHAR(8)     AS usuario,
				CHAR(4)     AS sucursal,
				CHAR(50)    AS descripReverso,
				CHAR(4)     AS codigoProducto,
				CHAR(50)    AS descripcionPago,
				CHAR(4)     AS transaccion,
				MONEY(18,2) AS interesMoratorio,
				MONEY(18,2) AS ivaIntMorabase,
				MONEY(18,2) AS ivaIntMoracopete;
		
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE iNoRegistros INTEGER;
	DEFINE iRegistros INTEGER;
	DEFINE iRecuperacion INTEGER;
	DEFINE iNoRegs INTEGER;
	
	DEFINE cReg              CHAR(3);
	DEFINE cSecuencia        CHAR(1);
	DEFINE cConcepto         CHAR(30);
	DEFINE cNumCredito       CHAR(20); 
	DEFINE cNombreCte        CHAR(104);
	DEFINE m_ImportePago     MONEY(18,2);
	DEFINE mCapVigente       MONEY(18,2);
	DEFINE mCapTransitorio   MONEY(18,2);
	DEFINE mCapVencido       MONEY(18,2);
	DEFINE mCapVdoNoExigible MONEY(18,2);
	DEFINE mCapitalTotal     MONEY(18,2);
	DEFINE mIntVigente       MONEY(18,2);
	DEFINE mIvaIntVigente    MONEY(18,2);
	DEFINE mInteresVencido   MONEY(18,2);
	DEFINE mIvaIntVencido    MONEY(18,2);
	DEFINE mIntMoraCopete    MONEY(18,2);
	DEFINE mIvaIntMoratorio  MONEY(18,2); 
	DEFINE dt_FechaMov       DATE;
	DEFINE cCodigo           CHAR(2);
	DEFINE cDescripcionpag   CHAR(50);
	DEFINE cFolioGrupo       CHAR(16);
	DEFINE cFolio            CHAR(16);
	DEFINE cUsuario          CHAR(8);
	DEFINE cSucursal         CHAR(4);
	DEFINE cDescRev          CHAR(50);
	DEFINE cCodProducto      CHAR(4);
	DEFINE c_DescriPago      CHAR(50);
	DEFINE cTransaccion      CHAR(4);
	DEFINE mIntMoratorio     MONEY(18,2);
	DEFINE mIntMoraBase      MONEY(18,2);
	DEFINE mIvaIntMoraBase   MONEY(18,2);
	DEFINE mIvaIntMoraCopete MONEY(18,2);
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET iNoRegistros = 0;
	LET iRegistros = 0;
	LET iRecuperacion = 0;
	LET iNoRegs = 0;
	
	LET cReg              = '000';
	LET cSecuencia        = '';
	LET cConcepto         = '';
	LET cNumCredito       = '';
	LET cNombreCte        = '';
	LET m_ImportePago     = 0.0;
	LET mCapVigente       = 0.0;
	LET mCapTransitorio   = 0.0;
	LET mCapVencido       = 0.0;
	LET mCapVdoNoExigible = 0.0;
	LET mCapitalTotal     = 0.0;
	LET mIntVigente       = 0.0;
	LET mIvaIntVigente    = 0.0;
	LET mInteresVencido   = 0.0;
	LET mIvaIntVencido    = 0.0;
	LET mIntMoraCopete    = 0.0;
	LET mIvaIntMoratorio  = 0.0;
	LET dt_FechaMov       = '';
	LET cCodigo           = '';
	LET cDescripcionpag   = '';
	LET cFolioGrupo       = '';
	LET cFolio            = '';
	LET cUsuario          = '';
	LET cSucursal         = '';
	LET cDescRev          = '';
	LET cCodProducto      = '';
	LET c_DescriPago      = '';
	LET cTransaccion      = '';
	LET mIntMoratorio     = 0.0;
	LET mIntMoraBase      = 0.0; 
	LET mIvaIntMoraBase   = 0.0;
	LET mIvaIntMoraCopete = 0.0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cReg, cSecuencia,cConcepto,cNumCredito, cNombreCte, m_ImportePago, mCapVigente, mCapTransitorio, mCapVencido, mCapVdoNoExigible, mCapitalTotal,
				mIntVigente, mIvaIntVigente, mInteresVencido, mIvaIntVencido, mIntMoraBase, mIntMoraCopete, mIvaIntMoratorio, dt_FechaMov, cCodigo, cDescripcionpag, 
				cfoliogrupo, cFolio, cUsuario, cSucursal, cDescRev, cCodProducto, c_DescriPago, cTransaccion, mIntMoratorio, mIvaIntMoraBase,mIvaIntMoraCopete;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/sp_consultareportepagoscre.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pStatus = ''  OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cReg, cSecuencia,cConcepto,cNumCredito, cNombreCte, m_ImportePago, mCapVigente, mCapTransitorio, mCapVencido, mCapVdoNoExigible, mCapitalTotal,
				mIntVigente, mIvaIntVigente, mInteresVencido, mIvaIntVencido, mIntMoraBase, mIntMoraCopete, mIvaIntMoratorio, dt_FechaMov, cCodigo, cDescripcionpag, 
				cfoliogrupo, cFolio, cUsuario, cSucursal, cDescRev, cCodProducto, c_DescriPago, cTransaccion, mIntMoratorio, mIvaIntMoraBase,mIvaIntMoraCopete;
		END IF;
		
		-- VALIDACION DE LA PAGINACION
		IF pRegistros < 0 OR pRecuperacion < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet, cReg, cSecuencia,cConcepto,cNumCredito, cNombreCte, m_ImportePago, mCapVigente, mCapTransitorio, mCapVencido, mCapVdoNoExigible, mCapitalTotal,
				mIntVigente, mIvaIntVigente, mInteresVencido, mIvaIntVencido, mIntMoraBase, mIntMoraCopete, mIvaIntMoratorio, dt_FechaMov, cCodigo, cDescripcionpag, 
				cfoliogrupo, cFolio, cUsuario, cSucursal, cDescRev, cCodProducto, c_DescriPago, cTransaccion, mIntMoratorio, mIvaIntMoraBase,mIvaIntMoraCopete;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:'informix'.sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cReg, cSecuencia,cConcepto,cNumCredito, cNombreCte, m_ImportePago, mCapVigente, mCapTransitorio, mCapVencido, mCapVdoNoExigible, mCapitalTotal,
				mIntVigente, mIvaIntVigente, mInteresVencido, mIvaIntVencido, mIntMoraBase, mIntMoraCopete, mIvaIntMoratorio, dt_FechaMov, cCodigo, cDescripcionpag, 
				cfoliogrupo, cFolio, cUsuario, cSucursal, cDescRev, cCodProducto, c_DescriPago, cTransaccion, mIntMoratorio, mIvaIntMoraBase,mIvaIntMoraCopete;
		END IF;
		
		FOREACH	EXECUTE PROCEDURE bdicred:'informix'.sp_consultarreportepagosspl(pFechaIni, pFechaFin, pStatus, pFolio, pAplicacion, pConsulta, pProducto)
			INTO cCodRetSp, cReg, cSecuencia,cConcepto,cNumCredito, cNombreCte, m_ImportePago, mCapVigente, mCapTransitorio, mCapVencido, mCapVdoNoExigible, mCapitalTotal,
					mIntVigente, mIvaIntVigente, mInteresVencido, mIvaIntVencido, mIntMoraBase, mIntMoraCopete, mIvaIntMoratorio, dt_FechaMov, cCodigo, cDescripcionpag, 
					cfoliogrupo, cFolio, cUsuario, cSucursal, cDescRev, cCodProducto, c_DescriPago, cTransaccion, mIntMoratorio, mIvaIntMoraBase,mIvaIntMoraCopete
			
			LET iCodRetSp = cCodRetSp::INTEGER;
			IF iCodRetSp < 0 THEN
				RAISE EXCEPTION iCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP ';
			ELIF iCodRetSp = 000001 THEN
				LET cCodRet = '00003';
			ELIF iCodRetSp = 000002 THEN
				LET cCodRet = '00154';			--LA FECHA INICIAL ES MAYOR A LA FECHA FINAL
			ELIF iCodRetSp = 000003 THEN
				LET cCodRet = '00155';			--LA FECHA FINAL ES MAYOR A LA FECHA ACTUAL
			ELIF iCodRetSp = 000004 THEN
				LET cCodRet = '00017';
			ELIF iCodRetSp = 000005 THEN
				LET cCodRet = '00003';
			ELSE
				IF iCodRetSp = 0 THEN
					IF iRegistros >= pRegistros THEN
						IF iRecuperacion < pRecuperacion THEN
							LET iRecuperacion = iRecuperacion + 1;
							RETURN cCodret, cReg, cSecuencia,cConcepto,cNumCredito, cNombreCte, m_ImportePago, mCapVigente, mCapTransitorio, mCapVencido, mCapVdoNoExigible, 
								mCapitalTotal, mIntVigente, mIvaIntVigente, mInteresVencido, mIvaIntVencido, mIntMoraBase, mIntMoraCopete, mIvaIntMoratorio, dt_FechaMov, cCodigo,
								cDescripcionpag, cfoliogrupo, cFolio, cUsuario, cSucursal, cDescRev, cCodProducto, c_DescriPago, cTransaccion, mIntMoratorio, mIvaIntMoraBase,
								mIvaIntMoraCopete WITH RESUME;
							LET iNoRegs = iNoRegs + 1;
						END IF;
					END IF;
						LET iRegistros = iRegistros + 1;
				ELSE
					LET cCodRet = cCodRetSp;
					RETURN cCodret, cReg, cSecuencia,cConcepto,cNumCredito, cNombreCte, m_ImportePago, mCapVigente, mCapTransitorio, mCapVencido, mCapVdoNoExigible, 
						mCapitalTotal, mIntVigente, mIvaIntVigente, mInteresVencido, mIvaIntVencido, mIntMoraBase, mIntMoraCopete, mIvaIntMoratorio, dt_FechaMov, cCodigo,
						cDescripcionpag, cfoliogrupo, cFolio, cUsuario, cSucursal, cDescRev, cCodProducto, c_DescriPago, cTransaccion, mIntMoratorio, mIvaIntMoraBase,
						mIvaIntMoraCopete;
				END IF;
			END IF;
		END FOREACH;
		
		IF iNoRegs = 0 AND pRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodret, cReg, cSecuencia,cConcepto,cNumCredito, cNombreCte, m_ImportePago, mCapVigente, mCapTransitorio, mCapVencido, mCapVdoNoExigible, mCapitalTotal, 
				mIntVigente, mIvaIntVigente, mInteresVencido, mIvaIntVencido, mIntMoraBase, mIntMoraCopete, mIvaIntMoratorio, dt_FechaMov, cCodigo,	cDescripcionpag, cfoliogrupo,
				cFolio, cUsuario, cSucursal, cDescRev, cCodProducto, c_DescriPago, cTransaccion, mIntMoratorio, mIvaIntMoraBase, mIvaIntMoraCopete;
		ELIF iNoRegs = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodret, '', '','','', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '';
		END IF;
	END;
END PROCEDURE
DOCUMENT 'AUTOR: Esparza Brenis Fernando Martin',
'FECHA: 01/08/2014',
'DESCRIPCION: Genera Reporte de Pago a Cuenta.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_catalogotransaccionabonocap(pUsuario CHAR(10),pIdFuncion CHAR(10),pNaturaleza CHAR(1),pRegistros INTEGER, pRecuperacion INTEGER)
      RETURNING CHAR(5) AS codRet,
                CHAR(4) AS Clave_transaccion,
                CHAR(50) AS Desc_transaccion;

	DEFINE cCodRet CHAR(5);
	DEFINE cClave_transaccion CHAR(4);
	DEFINE cDesc_transaccion CHAR(50);
	DEFINE iSqlErr INT;
	DEFINE cEmpresa CHAR(3);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cEmpresa = '001';
	LET cClave_transaccion = '';
	LET cDesc_transaccion = '';
	LET iRecuperacion = 0;

	BEGIN

        ON EXCEPTION SET iSqlErr
			IF iSqlErr <> 0 THEN
				LET cCodRet = iSqlErr;
				RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
			END IF;
        END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_catalogotransaccionabonocap.out';   
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;

        IF  pUsuario = '' OR pIdFuncion = '' OR (pNaturaleza = '' OR pNaturaleza <> 'A') THEN
			LET cCodRet = '00003';
			RETURN  cCodRet,cClave_transaccion,cDesc_transaccion;
        END IF;

        -- VALIDACION DE ACCESO A LA FUNCIONALIDAD
        EXECUTE FUNCTION bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion)
		INTO cCodRet;
		
        IF cCodRet <> '00000' THEN
			RETURN cCodRet,	cClave_transaccion,	cDesc_transaccion;
        END IF;

        FOREACH
                SELECT SKIP pRegistros FIRST pRecuperacion transacc, descripcion
                INTO cClave_transaccion, cDesc_transaccion
                FROM bdicheq:"informix".sc_tranval tv, bdinteg:"informix".si_transacc tr
                WHERE tv.empresa = cEmpresa
                AND tv.empresa = tr.empresa
                AND transacc = numero
                AND naturaleza = pNaturaleza
                ORDER BY 1
				
				LET iRecuperacion = iRecuperacion + 1;

                RETURN cCodRet,cClave_transaccion,cDesc_transaccion with resume;
				
        END FOREACH;

		IF iRecuperacion = 0 AND pRegistros = 0 THEN
			LET cCodRet = '01096'; --NO EXISTE INFORMACIÃâN PARA EL TIPO DE REPORTE SELECCIONADO, VERIFIQUE
			RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
		ELIF iRecuperacion = 0 AND pRegistros > 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet,cClave_transaccion,cDesc_transaccion;
		END IF;
		
	END;
END PROCEDURE
