CREATE PROCEDURE "informix".sp_mc_eliminasolicatenusuariomc_prueba(pUsuario CHAR(8), pIdFuncion CHAR(10))
RETURNING
        CHAR(5) AS COD_RET,
        CHAR(80) AS DESCRIPCION; 
    
	---DECLARACIONES
    DEFINE iSqlErr      INTEGER;
    DEFINE iIsamErr     INTEGER;
    DEFINE cErrorInfo   CHAR(80);
    DEFINE cCodRet      CHAR(6);
    DEFINE cMensajeRet  CHAR(80);
    ---INICIALIZACIONES
    LET iSqlErr       = 0;
    LET iIsamErr      = 0;
    LET cErrorInfo    = '';
    LET cCodRet       = '00000';
    LET cMensajeRet   = '';
	
BEGIN

   ON EXCEPTION SET iSqlErr
		LET cCodRet = iSqlErr;
		RETURN cCodRet, cMensajeRet;
	END EXCEPTION;
	
	SET ISOLATION TO DIRTY READ;
    SET LOCK MODE TO WAIT 3;
    
	SET DEBUG FILE TO "/tmp/mfinis/sp_mc_eliminasolicatenusuariomc.out";
	TRACE ON;
	
    IF pUsuario = '' OR pIdFuncion = '' THEN
		LET cCodRet = '00003';
		RETURN cCodRet, cMensajeRet;
	END IF;   
	
	EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
	IF cCodRet <> '00000' THEN
		RETURN cCodRet, cMensajeRet;
	END IF;
	
	
	
	DELETE FROM bdisolic:"informix".ss_cte_procesando WHERE usuario = pUsuario;
	
    UPDATE bdisolic:"informix".ss_solicitudes_mc SET ejecutivo_atiende ='' WHERE ejecutivo_atiende = pUsuario AND status_fin = '' AND revisado <> 'S';
	 
	LET cMensajeRet = 'Proceso Exitoso';					
	RETURN cCodRet, cMensajeRet;
	
END
END PROCEDURE
