CREATE PROCEDURE "informix".sp_dic_registrositespcte(pUsuario CHAR(8), pIdFuncion CHAR(10), pCteNvo CHAR(20),   --CLIENTE NUEVO
																		pSitNvo CHAR(1),						--SITUACION CTENUEVO
																		pCausaNvo SMALLINT,						--CAUSA CTENUEVO
																		pCteMat CHAR(20),						--CLIENTE MATCH
																		pSitMat CHAR(1),						--SITUACION CTEMATCH
																		pCausaMat SMALLINT,						--CAUSA CTE MATCH
																		pOrigMat CHAR(4),						--EMPRESA CON QUIEN SE HIZO MATCH EMPLEADOS, EXEMPLEADO,COPPEL, BANCOPPEL 
																		pSucursal CHAR(4),						--DONDE SE ORIGINO LA ALERTA
																		pOperador CHAR(8),						--USUARIO
																		pOrigen CHAR(1),						--CENTRAL O SUCURSAL
																		pActivo SMALLINT,						--BANDERA SI ES EMPLEADO O EXEMPLEADO.
																		pBandera INTEGER, 						--1 MISMA PERSONA,2 DISTINTA PERSONA, 3 FRAUDE.															
																		pFechaDictaINI DATETIME YEAR TO SECOND,	--* FECHA DE INICIO DICTAMEN
																		pFechaDictaFIN DATETIME YEAR TO SECOND,	--* FECHA DE FINALIZACION DICTAMEN
																		--DATOS PARA CONSULTA A TABLA SI_HUELLA_LINEA_RESULTADO
																		pNombreCoincidencia CHAR(104),			--* NOMBRE CTE MATCH
																		pFechaNacimiento CHAR(10))
		RETURNING CHAR(5) AS codret,
			 CHAR (100) AS Mensaje;
		
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cMensaje CHAR(100);  
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cMensaje = '';
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cMensaje;
		END EXCEPTION;
		
		-- SET DEBUG FILE TO "/tmp/mfinis/sp_dic_registrositespcte.out";
		-- TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pCteNvo = '' OR pSitNvo = '' OR pCausaNvo IS NULL OR pCteMat = '' OR pOrigMat = '' OR pSucursal = '' OR pOperador = '' OR pFechaDictaINI = '' OR pFechaDictaFIN = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cMensaje;
		END IF;
		
		IF NVL(pBandera,0) NOT IN(1,2,3,4) OR NVL(pActivo,0) NOT IN (0,1) THEN
			LET cCodRet = '00003';
			LET cMensaje = 'Parametro BANDERA y/o ACTIVO incorrectos.';
			RETURN TRIM(cCodRet),TRIM(cMensaje);
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD	
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) 
		INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cMensaje;
		END IF;
		
		EXECUTE PROCEDURE bdinteg:"informix".sp_dicta_registrositespcte(pCteNvo,pSitNvo,pCausaNvo,pCteMat,pSitMat,pCausaMat,pOrigMat,pSucursal,pOperador,pOrigen,pActivo,pBandera,pFechaDictaINI,pFechaDictaFIN,pNombreCoincidencia,pFechaNacimiento)
		INTO cCodRetSp, cMensaje;
		
		LET iCodRetSp = cCodRetSp::INTEGER;
		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION iCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP bdinteg:"informix".sp_dicta_registrositespcte';
		ELIF iCodRetSp = 1 OR iCodRetSp = 2 THEN
			LET cCodRet = '00003';
		ELIF iCodRetSp > 0 THEN
			LET cCodRet = CAST (iCodRetSp AS CHAR(5));
		END IF;
		
		RETURN cCodRet, cMensaje;
	END;
END PROCEDURE
