CREATE PROCEDURE "informix".sp_cnsif_consultasaldoapoyo(pUsuario CHAR(8),pIdFuncion CHAR(10),pNumCredito CHAR(20),pNumCte CHAR(20))
	RETURNING CHAR(5) AS codret,
		DECIMAL(14,2) AS saldo_apoyo;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cMensaje CHAR(100);
	DEFINE cEmpresa CHAR(3);
	DEFINE dSaldoApoyo DECIMAL(14,2);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cMensaje = '';
	LET cEmpresa = '001';
	LET dSaldoApoyo = 0.00;
	LET iNoRegistros = 0;	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,dSaldoApoyo;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_cnsif_consultasaldoapoyo.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,dSaldoApoyo;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,dSaldoApoyo;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		EXECUTE PROCEDURE bdicred:"informix".sp_consulta_sdo_apoyo(pNumCredito,pNumCte) 
		INTO cCodRetSp,dSaldoApoyo,cMensaje;
		
		LET iCodRetSp = cCodRetSp::INTEGER;
		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION cCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP bdicred:sp_consulta_sdo_apoyo';
		ELIF iCodRetSp = 1 THEN
			LET cCodRet = '01202'; --EL CREDITO NO EXISTE
		ELIF iCodRetSp = 2 THEN
			LET cCodRet = '01203'; --EL CREDITO NO ESTA EN EL PROGRAMA DE APOYO
		ELIF iCodRetSp = 3 THEN
			LET cCodRet = '01204'; --EL PRODUCTO NO ESTA EN EL PROGRAMA DE APOYO
		ELIF iCodRetSp = 4 THEN
			LET cCodRet = '01205'; --EL CLIENTE NO ESTA EN EL PROGRAMA DE APOYO
		ELIF iCodRetSp = 5 THEN
			LET cCodRet = '00003';
		END IF;
		
		RETURN cCodRet,dSaldoApoyo;
		
	END;
END PROCEDURE
