CREATE PROCEDURE "informix".sp_cnsif_validaplanapoyo(pUsuario CHAR(8),pIdFuncion CHAR(10),pNumCte CHAR(20))
	RETURNING CHAR(5) AS codret,
		CHAR(1) AS plan_apoyo;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cEmpresa CHAR(3);
	DEFINE iExiste INTEGER;
	DEFINE cPlanApoyo CHAR(1);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cEmpresa = '001';
	LET iExiste = 0;
	LET cPlanApoyo = 'f';
	LET iNoRegistros = 0;	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cPlanApoyo;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_cnsif_validaplanapoyo.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pNumCte = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cPlanApoyo;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cPlanApoyo;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		SELECT COUNT(*) INTO iExiste
		FROM bdicred:"informix".sd_diferir
		WHERE numcte = pNumCte 
		AND canal_baja IS NULL OR canal_baja = '';
		
		IF NVL(iExiste,0) > 0 THEN
			LET cPlanApoyo = 't';
		END IF;
		
		RETURN cCodRet,cPlanApoyo;
		
	END;
END PROCEDURE
