CREATE PROCEDURE "informix".sp_seg_comboperfilappmovil (pUsuario CHAR(8), pIdFuncion CHAR(10))
	RETURNING CHAR(5)		AS codigo_retorno,
			  SMALLINT		AS codParam,
			  CHAR(480)		AS descripcion;

	---DECLARACIONES   
	DEFINE cCodRet			CHAR(5); 
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cCodParam		SMALLINT;
	DEFINE cDescripcion		CHAR(480);
	DEFINE iRecuperacion 	INTEGER;

	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET cCodParam		= 0;
	LET cDescripcion	= '';
	LET iRecuperacion	= 0;

	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cCodParam, cDescripcion;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_seg_comboperfilappmovil.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cCodParam, cDescripcion;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cCodParam, cDescripcion;
		END IF;
		
		FOREACH
		
			SELECT cod_param, descripcion
			INTO cCodParam, cDescripcion
			FROM bdinteg:"informix".si_param_movil
			WHERE valor = 'amov'
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, cCodParam, cDescripcion WITH RESUME;
			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cCodParam, cDescripcion;
		END IF;	 
		
	END
END PROCEDURE
