			  CHAR(1)		AS clave_reporte,
			  CHAR(20)		AS descripcion;

	---DECLARACIONES   
	DEFINE cCodRet			CHAR(5); 
	DEFINE iSqlErr			INTEGER;
	DEFINE iIsamErr			INTEGER;
	DEFINE cErrorInfo		CHAR(80);
	DEFINE cClaveReporte	CHAR(1);
	DEFINE cDescripcion		CHAR(20);
	DEFINE iRecuperacion 	INTEGER;

	---INICIALIZACIONES
	LET iSqlErr			= 0;
	LET iIsamErr		= 0;
	LET cErrorInfo		= '';
	LET cCodRet			= '00000';
	LET cClaveReporte	= '';
	LET cDescripcion	= '';
	LET iRecuperacion	= 0;

	BEGIN

		ON EXCEPTION SET iSqlErr, iIsamErr, cErrorInfo
				LET cCodRet = iSqlErr;
				RETURN cCodRet, cClaveReporte, cDescripcion;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_seg_comboreporteappmovil.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet, cClaveReporte, cDescripcion;
		END IF;

		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet, cClaveReporte, cDescripcion;
		END IF;
		
		
		FOREACH
		
			SELECT clave_reporte, descripcion 
			INTO cClaveReporte, cDescripcion
			FROM bdicnweb:"informix".sw_rptappmovil
			WHERE status = '1'
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet, cClaveReporte, cDescripcion WITH RESUME;
			
		END FOREACH;
		
		IF iRecuperacion = 0 THEN
			LET cCodRet = '00017'; 
			RETURN cCodRet, cClaveReporte, cDescripcion;
		END IF;
		
	END
END PROCEDURE
