CREATE PROCEDURE "informix".sp_seg_generareportesappmovil(pUsuario CHAR(8), pIdFuncion CHAR(10), pReporte CHAR(1), pInicio DATE, pFin DATE, pEjecutivo CHAR(20), pRuta CHAR(100))
	RETURNING CHAR(5)	AS codigo_retorno,
		CHAR(100) AS archivo_generado;

	---DECLARACIONES   
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INT;
	DEFINE cCodRetSp CHAR(5);
	DEFINE iCodRetSp INTEGER;
	DEFINE cDescCodRet CHAR(80);
	DEFINE cEmpresa CHAR(3);
	DEFINE iIdRegistro INTEGER;
	DEFINE iTotal INTEGER;
	
	DEFINE iSerial INTEGER;
	DEFINE cRespMensaje CHAR(45);
	DEFINE iRegistros INTEGER;
	DEFINE cQuery CHAR(255);
	DEFINE cCmd1 CHAR(2000);
	DEFINE cSql CHAR(2500);
	DEFINE cRutaGral CHAR(150);
	DEFINE cRutaInformix CHAR(100);
	DEFINE cUsrBin CHAR(100);
	DEFINE iCountRep INTEGER;
	DEFINE iProcesaRep INT;
	DEFINE iArmaReporte INT;
	DEFINE cArchivoCP CHAR(45);
	DEFINE cCmdQuery CHAR(2500);
	DEFINE bInTransaction BOOLEAN;
	DEFINE ven_transacc SMALLINT;
	DEFINE dFechaHora DATETIME YEAR TO FRACTION(5);
	DEFINE cReporte CHAR(100);
	DEFINE cNombreArchivo CHAR(100);
	DEFINE iRecuperacion INTEGER;
	
	-- Variables de Reportes
	DEFINE cEjecutivo CHAR(8);
	DEFINE cNombre CHAR(60);
	DEFINE cPerfil CHAR(20);
	DEFINE cIp CHAR(15);
	DEFINE cFecha_alta CHAR(10);
	DEFINE cUltimo_acceso CHAR(10);
	DEFINE cDescripcion 	CHAR(50);
	DEFINE cHora CHAR(8);
	DEFINE cAccion CHAR(50);
	DEFINE cUsuario_insert CHAR(8);
	DEFINE iTotalRegistros  INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cDescCodRet = '';
	LET cEmpresa = '001';
	LET iIdRegistro = 0;
	
	LET iSerial = 0;
	LET cRespMensaje = '';
	LET iRegistros = 0;
	LET cQuery = '';
	LET cCmd1 = '';
	LET cSql = '';
	LET cRutaGral = '';
	LET cRutaInformix = '/informix/bin/';
	LET cUsrBin = '/usr/bin/';
	LET iCountRep = 0;
	LET iProcesaRep = 0;
	LET iArmaReporte = 0;
	LET cArchivoCP = '';
	LET cCmdQuery = '';
	LET bInTransaction = 'f';
	LET ven_transacc = 0;
	LET dFechaHora = CURRENT YEAR TO FRACTION(5);
	LET cReporte = '';
	LET cNombreArchivo = '';
	LET iRecuperacion = 0;
	LET iTotal = 0;
	
	-- Variables de Reportes
	LET cEjecutivo = '';
	LET cNombre = '';
	LET cPerfil = '';
	LET cIp = '';
	LET cFecha_alta = '';
	LET cUltimo_acceso = '';
	LET cDescripcion = '';
	LET cHora = '';
	LET cAccion = '';
	LET cUsuario_insert = '';
	LET iTotalRegistros  = 0;

	BEGIN

		ON EXCEPTION SET iSqlErr
				LET cCodRet = iSqlErr;
				
				IF ven_transacc = 1 THEN
					ROLLBACK WORK; --		
				END IF;
				
				RETURN cCodRet,cNombreArchivo;
		END EXCEPTION;
		
		ON EXCEPTION IN (-668, -535, -255)
			LET bInTransaction = 't';
			COMMIT WORK;
			BEGIN WORK;
		END EXCEPTION WITH RESUME;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_seg_generareportesappmovil.out';
		--TRACE ON;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		-- Se validan los parametros de entrada.
		IF NVL(pUsuario,'') = '' OR NVL(pIdFuncion,'') = '' OR NVL(pReporte,'') = '' OR NVL(pRuta,'') = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		-- Se validan los parametros de entrada.
		IF pReporte = 1 AND (pInicio IS NULL OR pFin IS NULL ) THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		DELETE FROM bdicnweb:"informix".sw_rpt_consultappmovil
		WHERE usuario_insert = TRIM(pUsuario);
		
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		IF pReporte = 1 THEN
			-- SE DEFINE NOMENCLATURA DEL REPORTE POR ACCIONES
			LET pRuta = TRIM(pRuta) || '/';
			LET cReporte = 'REPORTE_MOVIL_ACCIONES_' || TO_CHAR(CURRENT, '%Y%m%d');
			LET cRutaGral = TRIM(pRuta)||TRIM(cReporte)||'.txt';
			LET cNombreArchivo = TRIM(cReporte)||'.txt';
			FOREACH
				EXECUTE PROCEDURE bdinteg:"informix".sp_reporte_accesos_amov(pEjecutivo, pInicio, pFin)
				INTO cCodRetSp, cEjecutivo, cNombre, cFecha_alta, cHora,  cIp, cAccion
				
				IF cCodRetSp = '00001' THEN
					LET cCodRet = '00017';
					RETURN cCodRet,cNombreArchivo;
					
				ELIF cCodRetSp = '00000' THEN
				
					INSERT INTO bdicnweb:"informix".sw_rpt_consultappmovil(consecutivo, ejecutivo, nombre, ip, fecha_alta, hora, accion, usuario_insert) 
					VALUES(iTotalRegistros, cEjecutivo, cNombre, cIp, cFecha_alta, cHora, cAccion, pUsuario);
					
					LET iTotalRegistros = iTotalRegistros + 1;
				END IF
			
			 END FOREACH;
		ELIF pReporte = 3 THEN
			-- SE DEFINE NOMENCLATURA DEL REPORTE POR USUARIOS
			LET pRuta = TRIM(pRuta) || '/';
			LET cReporte = 'REPORTE_MOVIL_USUARIOS_' || TO_CHAR(CURRENT, '%Y%m%d');
			LET cRutaGral = TRIM(pRuta)||TRIM(cReporte)||'.txt';
			LET cNombreArchivo = TRIM(cReporte)||'.txt';
			FOREACH
				EXECUTE PROCEDURE bdinteg:"informix".sp_reporte_usuarios_amov(pEjecutivo)
				INTO cCodRetSp, cEjecutivo, cNombre, cPerfil, cIp, cFecha_alta, cUltimo_acceso
				
				
				IF cCodRetSp = '00001' THEN
					LET cCodRet = '00017';
					RETURN cCodRet,cNombreArchivo;
					
				ELIF cCodRetSp = '00000' THEN
				
					INSERT INTO bdicnweb:"informix".sw_rpt_consultappmovil(consecutivo, ejecutivo, nombre, perfil, ip, fecha_alta, ultimo_acceso, usuario_insert) 
					VALUES(iTotalRegistros, cEjecutivo, cNombre, cPerfil, cIp, cFecha_alta, cUltimo_acceso, pUsuario);
				
					LET iTotalRegistros = iTotalRegistros + 1;
				END IF
				
			 END FOREACH;
		ELIF pReporte = 2 THEN
			-- SE DEFINE NOMENCLATURA DEL REPORTE POR PERFILES
			LET pRuta = TRIM(pRuta) || '/';
			LET cReporte = 'REPORTE_MOVIL_PERFILES_' || TO_CHAR(CURRENT, '%Y%m%d');
			LET cRutaGral = TRIM(pRuta)||TRIM(cReporte)||'.txt';
			LET cNombreArchivo = TRIM(cReporte)||'.txt';
			FOREACH
				EXECUTE PROCEDURE bdinteg:"informix".sp_perfiles_amov()
				INTO cCodRetSp, cPerfil, cDescripcion, cFecha_alta
				
				INSERT INTO bdicnweb:"informix".sw_rpt_consultappmovil(consecutivo, perfil, fecha_alta, descripcion, usuario_insert) 
				VALUES(iTotalRegistros, cPerfil, cFecha_alta, cDescripcion, pUsuario);
				
				LET iTotalRegistros = iTotalRegistros + 1;
			 END FOREACH;
		END IF;
		
		IF iTotalRegistros = 0 THEN
			LET cCodRet = '00017';
			RETURN cCodRet,cNombreArchivo;
		END IF;
		
		BEGIN WORK;
			LET ven_transacc = 1;
			
			LET cCmd1 = "";
			
			IF pReporte = 1 THEN
				-- SE DEFINE NOMENCLATURA DEL REPORTE POR ACCIONES
				LET cCmd1 = "SELECT 'NO_EMPLEADO','NOMBRE','FECHA','HORA','IP','ACCION' FROM systables WHERE tabid = 1";
				
				IF pEjecutivo <> '' THEN
					LET cCmd1 = "" || TRIM(cCmd1)|| " UNION ALL SELECT ejecutivo, nombre, fecha_alta, hora, ip, accion FROM bdicnweb:""informix"".sw_rpt_consultappmovil ";
					LET cCmd1 = "" || TRIM(cCmd1)|| " WHERE usuario_insert = '"|| pUsuario ||"' AND ejecutivo = '"|| pEjecutivo ||"' AND fecha_alta BETWEEN '"||pInicio||"' AND '"||pFin||"' ";
				ELSE
					LET cCmd1 = "" || TRIM(cCmd1)|| " UNION ALL SELECT ejecutivo, nombre, fecha_alta, hora, ip, accion FROM bdicnweb:""informix"".sw_rpt_consultappmovil ";
					LET cCmd1 = "" || TRIM(cCmd1)|| " WHERE usuario_insert = '"|| pUsuario ||"' AND fecha_alta BETWEEN '"||pInicio||"' AND '"||pFin||"' ";
				END IF;
					
			ELIF pReporte = 3 THEN
				-- SE DEFINE NOMENCLATURA DEL REPORTE POR USUARIOS
				LET cCmd1 = "SELECT 'NO_EMPLEADO','NOMBRE','PERFIL','IP','FECHA_ALTA','ULTIMO_ACCESO' FROM systables WHERE tabid = 1";
				IF pEjecutivo <> '' THEN
					LET cCmd1 = "" || TRIM(cCmd1)|| " UNION ALL SELECT ejecutivo, nombre, perfil, ip, fecha_alta, ultimo_acceso FROM bdicnweb:""informix"".sw_rpt_consultappmovil ";
					LET cCmd1 = "" || TRIM(cCmd1)|| " WHERE usuario_insert = '"|| pUsuario ||"' AND ejecutivo = '"|| pEjecutivo ||"' ";
				ELSE
					LET cCmd1 = "" || TRIM(cCmd1)|| " UNION ALL SELECT ejecutivo, nombre, perfil, ip, fecha_alta, ultimo_acceso FROM bdicnweb:""informix"".sw_rpt_consultappmovil ";
					LET cCmd1 = "" || TRIM(cCmd1)|| " WHERE usuario_insert = '"|| pUsuario ||"' ";
				END IF;
			ELIF pReporte = 2 THEN
				LET cCmd1 = "SELECT 'PERFIL','FUNCIONALIDAD','FECHA_ALTA' FROM systables WHERE tabid = 1";
				LET cCmd1 = "" || TRIM(cCmd1)|| " UNION ALL SELECT perfil, descripcion, fecha_alta FROM bdicnweb:""informix"".sw_rpt_consultappmovil ";
				LET cCmd1 = "" || TRIM(cCmd1)|| " WHERE usuario_insert = '"|| pUsuario ||"' ";
			END IF;
			
			
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'echo "SET ISOLATION TO DIRTY READ; UNLOAD TO '||TRIM(cRutaGral)|| ' DELIMITER ''|'' '||TRIM(cCmd1)||' " > '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cRutaInformix)||'dbaccess bdicnweb '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el archivo query.sql
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(pRuta)||'query.sql';
			SYSTEM TRIM(cSql);
			
			-- Se manipula el archivo para agregar el salto de lÃ­nea
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGral)||" > "||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el archivo original
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			-- Eliminamos el caracter delimitador ';' al final de la lÃ­nea
			LET cSql = '';
			LET cSql =  "sed 's/..$//g' "||TRIM(cRutaGral)||".tmp > "||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			-- Se manipula el archivo para agregar el salto de lÃ­nea
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
								
			LET cSql = '';
			LET cSql = "sed "||"'s/$'""/`echo \\\r`/"" "||TRIM(cRutaGral)||" > "||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
							
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral)||".tmp";
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'rm -rf '||TRIM(cRutaGral)||'; /usr/bin/mv '||TRIM(cRutaGral)||'.tmp '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
			LET cSql = '';
			LET cSql = TRIM(cUsrBin)||'chmod 777 '||TRIM(cRutaGral);
			SYSTEM TRIM(cSql);
			
		COMMIT WORK;
		
		LET ven_transacc = 0;
		IF bInTransaction = 't' THEN
			BEGIN WORK;
		END IF;
		
		RETURN cCodRet,cNombreArchivo;
		
	END
END PROCEDURE
