CREATE PROCEDURE "informix".sp_fc_conscliente(pUsuario CHAR(8),pIdFuncion CHAR(10),pNumCte CHAR(20))
	RETURNING CHAR(5) AS codret,
		CHAR(26) AS apell_paterno, 
		CHAR(26) AS apell_materno, 
		CHAR(26) AS nombre, 
		CHAR(26) AS nombre2, 
		CHAR(4) AS sucursal, 
		CHAR(13) AS rfc, 
		CHAR(2) AS status_cte, 
		DATE AS fecha_alta,  
		DATE AS fecha_nac, 
		CHAR(1) AS sexo;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cDescCodRetSp CHAR(100);
	DEFINE cEmpresa CHAR(3);
	DEFINE cApellPaterno CHAR(26);
	DEFINE cApellMaterno CHAR(26);
	DEFINE cNombre CHAR(26);
	DEFINE cNombre2 CHAR(26);
	DEFINE cSucursal CHAR(4);
	DEFINE cRFC CHAR(13);
	DEFINE cStatusCte CHAR(2);
	DEFINE dFechaAlta DATE;
	DEFINE dFechaNac DATE;
	DEFINE cSexo CHAR(1);
	DEFINE iNoRegistros INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cDescCodRetSp = '';
	LET cEmpresa = '001';
	LET cApellPaterno = '';
	LET cApellMaterno = '';
	LET cNombre = '';
	LET cNombre2 = '';
	LET cSucursal = '';
	LET cRFC = '';
	LET cStatusCte = '';
	LET dFechaAlta = '';
	LET dFechaNac = '';
	LET cSexo = '';
	LET iNoRegistros = 0;	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_fc_conscliente.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		EXECUTE PROCEDURE bdinteg:"informix".sp_fuscte_conscte(pNumCte) 
		INTO cCodRetSp,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo;
		
		LET iCodRetSp = cCodRetSp::INTEGER;
		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION cCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP bdinteg:sp_fuscte_conscte';
		ELIF iCodRetSp = 100 THEN
			LET cCodRet = '01150'; --NO. DE CLIENTE INVÃLIDO
		ELIF iCodRetSp = 200 THEN
			LET cCodRet = '01151'; --LONGITUD INVÃLIDA, CORRESPONDIENTE AL NO. DE CLIENTE
		ELIF iCodRetSp = 300 THEN
			LET cCodRet = '01152'; --NO. DE CLIENTE NO EXISTE
		ELIF iCodRetSp = 400 THEN
			LET cCodRet = '01153'; --NO. DE CLIENTE CANCELADO
		ELIF iCodRetSp = 500 THEN
			LET cCodRet = '01154'; --SIN DATOS PERSONALES DEL CLIENTE []
		ELIF iCodRetSp = 600 THEN
			LET cCodRet = '01155'; --CLIENTE FUSIONADO []
		ELIF iCodRetSp = 700 THEN
			LET cCodRet = '01156'; --CLIENTE [] ES UN CLIENTE MORAL
		END IF;
		
		RETURN cCodRet,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo;
		
	END;
END PROCEDURE
