	LET dFechaAlta = '';
	LET dFechaNac = '';
	LET cSexo = '';
	LET cApellPaterno_CteI = '';
	LET cApellMaterno_CteI = '';
	LET cNombre_CteI = '';
	LET cNombre2_CteI = '';
	LET cSucursal_CteI = '';
	LET cRFC_CteI = '';
	LET cStatusCte_CteI = '';
	LET dFechaAlta_CteI = '';
	LET dFechaNac_CteI = '';
	LET cSexo_CteI = '';
	LET cNumCte_CteI = '';
	LET iNoRegistros = 0;	
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo,
			cApellPaterno_CteI,cApellMaterno_CteI,cNombre_CteI,cNombre2_CteI,cSucursal_CteI,cRFC_CteI,cStatusCte_CteI,dFechaAlta_CteI,dFechaNac_CteI,cSexo_CteI,cNumCte_CteI;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_fc_consctesdesb.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo,
			cApellPaterno_CteI,cApellMaterno_CteI,cNombre_CteI,cNombre2_CteI,cSucursal_CteI,cRFC_CteI,cStatusCte_CteI,dFechaAlta_CteI,dFechaNac_CteI,cSexo_CteI,cNumCte_CteI;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo,
			cApellPaterno_CteI,cApellMaterno_CteI,cNombre_CteI,cNombre2_CteI,cSucursal_CteI,cRFC_CteI,cStatusCte_CteI,dFechaAlta_CteI,dFechaNac_CteI,cSexo_CteI,cNumCte_CteI;
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		EXECUTE PROCEDURE bdinteg:"informix".sp_desbctasfus_conscte(pNumCte,pAnalista) 
		INTO cCodRetSp,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo,
		cApellPaterno_CteI,cApellMaterno_CteI,cNombre_CteI,cNombre2_CteI,cSucursal_CteI,cRFC_CteI,cStatusCte_CteI,dFechaAlta_CteI,dFechaNac_CteI,cSexo_CteI,cNumCte_CteI;
		
		LET iCodRetSp = cCodRetSp::INTEGER;
		IF iCodRetSp < 0 THEN
			RAISE EXCEPTION cCodRetSp, 0, 'ERROR EN LA EJECUCION DEL SP bdinteg:sp_desbctasfus_conscte';
		ELIF iCodRetSp = 1 THEN
			LET cCodRet = '01180'; --NO SE ENCUENTRAN DATOS CON EL NO. DE ANALISTA A CONSULTAR
		ELIF iCodRetSp = 100 THEN
			LET cCodRet = '01150'; --NO. DE CLIENTE INVÃLIDO
		ELIF iCodRetSp = 200 THEN
			LET cCodRet = '01151'; --LONGITUD INVÃLIDA, CORRESPONDIENTE AL NO. DE CLIENTE
		ELIF iCodRetSp = 300 THEN
			LET cCodRet = '01181'; --NO SE ENCUENTRAN DATOS CON EL NO. CLIENTE A LOCALIZAR
		ELIF iCodRetSp = 400 THEN
			LET cCodRet = '01182'; --NO. DE CLIENTE CANCELADO
		ELIF iCodRetSp = 500 THEN
			LET cCodRet = '01183'; --SIN DATOS PERSONALES DEL CLIENTE
		ELIF iCodRetSp = 700 THEN
			LET cCodRet = '01184'; --EL NO. DE CLIENTE ES UN CLIENTE MORAL
		ELIF iCodRetSp <> 0 THEN
			LET cCodRet = '01185'; --EL NO. DE CLIENTE NO EXISTE
		END IF;
		
		RETURN cCodRet,cApellPaterno,cApellMaterno,cNombre,cNombre2,cSucursal,cRFC,cStatusCte,dFechaAlta,dFechaNac,cSexo,
		cApellPaterno_CteI,cApellMaterno_CteI,cNombre_CteI,cNombre2_CteI,cSucursal_CteI,cRFC_CteI,cStatusCte_CteI,dFechaAlta_CteI,dFechaNac_CteI,cSexo_CteI,cNumCte_CteI;
		
	END;
END PROCEDURE
