CREATE PROCEDURE "informix".sp_fc_conslocalctesnom(pUsuario CHAR(8),pIdFuncion CHAR(10),
pNombre1 CHAR(26),pNombre2 CHAR(26),pApPaterno CHAR(26),pApMaterno CHAR(26),pFecha DATE,
pRegistros INTEGER,pRecuperacion INTEGER)
	RETURNING CHAR(5) AS codret,
		CHAR(20) AS numcte, 
		CHAR(26) AS nombre1, 
		CHAR(26) AS nombre2,
		CHAR(26) AS apell_paterno,
		CHAR(26) AS apell_materno,
		CHAR(13) AS rfc,
		DATE AS fecha_nac;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cDescCodRetSp CHAR(100);
	DEFINE cEmpresa CHAR(3);
	DEFINE cNumCte CHAR(20);
	DEFINE cNombre1 CHAR(26);
	DEFINE cNombre2 CHAR(26);
	DEFINE cApell_paterno CHAR(26);
	DEFINE cApell_materno CHAR(26);
	DEFINE cRfc CHAR(13);
	DEFINE dFecha_nac DATE;
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cDescCodRetSp = '';
	LET cEmpresa = '001';
	LET cNumCte = '';
	LET cNombre1 = '';
	LET cNombre2 = '';
	LET cApell_paterno = '';
	LET cApell_materno = '';
	LET cRfc = '';
	LET dFecha_nac = '';
	LET iRecuperacion = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cNumcte,cNombre1,cNombre2,cApell_paterno,cApell_materno,cRfc,dFecha_nac;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_fc_conslocalctesnom.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cNumcte,cNombre1,cNombre2,cApell_paterno,cApell_materno,cRfc,dFecha_nac;
		END IF;
		
		-- VALIDACIÃN DE LOS DATOS DE PAGINACION
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet,cNumcte,cNombre1,cNombre2,cApell_paterno,cApell_materno,cRfc,dFecha_nac;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cNumcte,cNombre1,cNombre2,cApell_paterno,cApell_materno,cRfc,dFecha_nac;
		END IF;
		
		-- SE INICIALIZAN VARIABLES
		LET pNombre1 = TRIM(pNombre1)||'%';
		IF pNombre2 <> '' THEN
			LET pNombre2 = TRIM(pNombre2)||'%';
		END IF;
		LET pApPaterno = TRIM(pApPaterno)||'%';
		IF pApMaterno <> '' THEN
			LET pApMaterno = TRIM(pApMaterno)||'%';
		END IF;
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT {+INDEX (bdinteg:si_cliente inx_si_cliente3)} {+INDEX (bdinteg:si_ctepf 221_466)} --LIMIT 100 
			SKIP pRegistros FIRST pRecuperacion
			cte.numcte,cte.nombre1,cte.nombre2,cte.apell_paterno,cte.apell_materno,cte.rfc,ctepf.fecha_nac 
			INTO cNumcte,cNombre1,cNombre2,cApell_paterno,cApell_materno,cRfc,dFecha_nac
			FROM bdinteg:"informix".si_cliente cte INNER JOIN bdinteg:"informix".si_ctepf ctepf ON cte.numcte = ctepf.numcte
			WHERE cte.nombre1 LIKE pNombre1
			AND cte.nombre2 LIKE (CASE WHEN pNombre2 <> '' THEN pNombre2 ELSE cte.nombre2 END)
			AND cte.apell_paterno LIKE pApPaterno
			AND cte.apell_materno LIKE (CASE WHEN pApMaterno <> '' THEN pApMaterno ELSE cte.apell_materno END)
			AND ctepf.fecha_nac = (CASE WHEN pFecha IS NOT NULL THEN pFecha ELSE ctepf.fecha_nac END)
			ORDER BY cte.apell_paterno ASC
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet,cNumcte,cNombre1,cNombre2,cApell_paterno,cApell_materno,cRfc,dFecha_nac WITH RESUME;
		END FOREACH;
		
		IF pRegistros = 0 AND iRecuperacion = 0 THEN
			LET cCodRet = '01176'; --NO SE ENCONTRÃ NINGÃN CLIENTE CON LOS DATOS CAPTURADOS
			RETURN cCodRet,cNumcte,cNombre1,cNombre2,cApell_paterno,cApell_materno,cRfc,dFecha_nac;
		ELIF pRegistros > 0 AND iRecuperacion = 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet,cNumcte,cNombre1,cNombre2,cApell_paterno,cApell_materno,cRfc,dFecha_nac;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 08/05/2020',
'MODULO: CLIENTES',
'FUNCIONALIDAD: FUSION MANUAL DE CLIENTES',
'DESCRIPCION: SPL encargado de realizar la busqueda por nombre y obtener el detalle de la consulta local de clientes.',
'BD: bdicnweb';

CREATE PROCEDURE "informix".sp_fc_conslocalctesrs(pUsuario CHAR(8),pIdFuncion CHAR(10),
pRazonSoc CHAR(60),pRegistros INTEGER,pRecuperacion INTEGER)
	RETURNING CHAR(5) AS codret,
		CHAR(20) AS numcte, 
		CHAR(60) AS razon_social,
		CHAR(13) AS rfc;
	
	DEFINE cCodRet CHAR(5);
	DEFINE iSqlErr INTEGER;
	DEFINE cCodRetSp CHAR(6);
	DEFINE iCodRetSp INTEGER;
	DEFINE cDescCodRetSp CHAR(100);
	DEFINE cEmpresa CHAR(3);
	DEFINE cNumCte CHAR(20);
	DEFINE cRazon_social CHAR(60);
	DEFINE cRfc CHAR(13);
	DEFINE iRecuperacion INTEGER;
	
	LET cCodRet = '00000';
	LET iSqlErr = 0;
	LET cCodRetSp = '';
	LET iCodRetSp = 0;
	LET cDescCodRetSp = '';
	LET cEmpresa = '001';
	LET cNumCte = '';
	LET cRazon_social = '';
	LET cRfc = '';
	LET iRecuperacion = 0;
	
	BEGIN
	
		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet,cNumcte,cRazon_social,cRfc;
		END EXCEPTION;
		
		--SET DEBUG FILE TO '/tmp/mfinis/sp_fc_conslocalctesrs.out';
		--TRACE ON;
		
		IF pUsuario = '' OR pIdFuncion = '' OR pRegistros IS NULL OR pRecuperacion IS NULL THEN
			LET cCodRet = '00003';
			RETURN cCodRet,cNumcte,cRazon_social,cRfc;
		END IF;
		
		-- VALIDACIÃN DE LOS DATOS DE PAGINACION
		IF pRegistros < 0 THEN
			LET cCodRet = '00098';
			RETURN cCodRet,cNumcte,cRazon_social,cRfc;
		END IF;
		
		-- VALIDACION DE ACCESO A LA FUNCIONALIDAD
		EXECUTE PROCEDURE bdinteg:"informix".sp_cnsif_confirmaejecutivo(pUsuario, pIdFuncion) INTO cCodRet;
		IF cCodRet <> '00000' THEN
			RETURN cCodRet,cNumcte,cRazon_social,cRfc;
		END IF;
		
		-- SE INICIALIZAN VARIABLES
		LET pRazonSoc = TRIM(pRazonSoc)||'%';
		
		SET ISOLATION TO DIRTY READ;
		SET LOCK MODE TO WAIT 3;
		
		FOREACH
			SELECT  
			SKIP pRegistros FIRST pRecuperacion
			numcte,razon_social,rfc 
			INTO cNumcte,cRazon_social,cRfc
			FROM bdinteg:"informix".si_cliente
			WHERE razon_social LIKE pRazonSoc
			ORDER BY razon_social ASC
			
			LET iRecuperacion = iRecuperacion + 1;
			RETURN cCodRet,cNumcte,cRazon_social,cRfc WITH RESUME;
		END FOREACH;
		
		IF pRegistros = 0 AND iRecuperacion = 0 THEN
			LET cCodRet = '01176'; --NO SE ENCONTRÃ NINGÃN CLIENTE CON LOS DATOS CAPTURADOS
			RETURN cCodRet,cNumcte,cRazon_social,cRfc;
		ELIF pRegistros > 0 AND iRecuperacion = 0 THEN
			LET cCodRet = '1001';
			RETURN cCodRet,cNumcte,cRazon_social,cRfc;
		END IF;
		
	END;
END PROCEDURE
DOCUMENT 'AUTOR: L. Montserrat Leon Amador',
'FECHA: 08/05/2020',
'MODULO: CLIENTES',
'FUNCIONALIDAD: FUSION MANUAL DE CLIENTES',
'DESCRIPCION: SPL encargado de realizar la busqueda por razon social y obtener el detalle de la consulta local de clientes.',
