CREATE PROCEDURE "informix".sp_fc_historicodoctosfusionados(pUsuario CHAR(8),pIdFuncion CHAR(10),pNumCteTrasp CHAR(20),pRegistros INTEGER,pRecuperacion INTEGER)
    RETURNING CHAR(5) AS codret,
		CHAR(20) AS cliente,
