CREATE PROCEDURE "informix".sp_fc_respaldacargaimg(pUsuario CHAR(8),pIdFuncion CHAR(10),pCteTitular CHAR(20),pCteTraspasa CHAR(20),pUsEjecuta CHAR(8))
