		UPDATE "informix".sw_verificastatusrep
		SET status = 'T', error_proceso = 'N', num_registros = iNumRegistros WHERE usuario_insert = pUsuario;
		RETURN cCodRet, iNumRegistros;
		
    END;
END PROCEDURE
