	LET cEmpresa 				= '001';
	LET cEmpresaSp 				= '';
	LET cNum_Producto 			= '';
	LET cNomb_Producto 			= '';

	BEGIN

		ON EXCEPTION SET iSqlErr
			LET cCodRet = iSqlErr;
			RETURN cCodRet, cNum_Producto, cNomb_Producto, cEmpresaSp;
