			ELIF iCodRetSp = 1 THEN
				LET cCodRet = '00003';
				RETURN cCodRet, cNum_Producto, cNomb_Producto, cEmpresaSp;
			ELIF iCodRetSp = 2 THEN
				LET cCodRet = '00017';
				RETURN cCodRet, cNum_Producto, cNomb_Producto, cEmpresaSp;
			END IF;

			RETURN cCodRet, cNum_Producto, cNomb_Producto, cEmpresaSp WITH RESUME;

