		IF pMonto_minimo <> '' THEN
			SELECT COUNT(par_id) INTO iExiste FROM bdirst:"informix".parametro_sistema WHERE par_status = 'A' AND par_nombre = 'MONTO_MINIMO';
			
			IF NVL(iexiste,0) > 0 THEN
