CREATE PROCEDURE "informix".sp_ris_consultatransaccion(pUsuario CHAR(8), pIdFuncion CHAR(10), pSistema CHAR(10), pSecuencia CHAR(10), pTransaccion CHAR(10), pProducto CHAR(10))
		RETURNING CHAR(5) AS codret,
